  function startupDurationLabel(duration) {
    return (Math.max(100, Math.round(duration)) / 1000).toLocaleString('pt-BR', { minimumFractionDigits: 1, maximumFractionDigits: 1 }) + ' s';
  }

  function normalizeStartupDuration(value) {
    let duration = Number(value);
    if (!Number.isFinite(duration)) return 0;
    // A versão anterior podia salvar décimos de segundo. Mantemos essa
    // compatibilidade ao migrar para o histórico em milissegundos.
    if (duration >= 300 && duration < 3000) duration *= 10;
    return duration >= 300 && duration <= 30000 ? Math.round(duration) : 0;
  }

  function readStartupDurationHistory() {
    const values = [];
    try {
      const rawHistory = window.localStorage.getItem(STARTUP_DURATION_HISTORY_STORAGE_KEY);
      const history = rawHistory ? JSON.parse(rawHistory) : [];
      if (Array.isArray(history)) history.forEach(value => {
        const duration = normalizeStartupDuration(value);
        if (duration) values.push(duration);
      });
      if (!values.length) {
        const legacy = normalizeStartupDuration(window.localStorage.getItem(STARTUP_DURATION_STORAGE_KEY));
        if (legacy) values.push(legacy);
      }
    } catch (error) { /* Sem armazenamento local, usamos a estimativa padrão. */ }
    return values.slice(-8);
  }

  function recordStartupDuration(duration) {
    const normalized = normalizeStartupDuration(duration);
    if (!normalized) return;
    try {
      const history = readStartupDurationHistory();
      history.push(normalized);
      const recent = history.slice(-8);
      window.localStorage.setItem(STARTUP_DURATION_HISTORY_STORAGE_KEY, JSON.stringify(recent));
      window.localStorage.setItem(STARTUP_DURATION_STORAGE_KEY, String(normalized));
    } catch (error) { /* Sem armazenamento local, não há estimativa na próxima abertura. */ }
  }

  function cancelStartupProgressTimer() {
    if (!startupProgressFrame) return;
    window.clearTimeout(startupProgressFrame);
    if (typeof window.cancelAnimationFrame === 'function') window.cancelAnimationFrame(startupProgressFrame);
    startupProgressFrame = 0;
  }

  function renderStartupProgress(value) {
    const safeValue = Math.max(0, Math.min(100, Math.floor(Number(value) || 0)));
    startupProgressValue = safeValue;
    startupProgressFloor = safeValue;
    const fill = $('#pw-startup-progress-fill');
    const percent = $('#pw-startup-progress-percent');
    const track = $('.pw-startup-progress-track');
    if (fill) fill.style.width = safeValue + '%';
    if (percent) percent.textContent = safeValue + '%';
    if (track) track.setAttribute('aria-valuenow', String(safeValue));
  }

  function startStartupProgress() {
    const detail = $('#pw-startup-progress-detail');
    const track = $('.pw-startup-progress-track');
    if (!detail || !track) return;
    startupReadyToOpen = false;
    const recentDurations = readStartupDurationHistory();
    startupEstimatedDuration = recentDurations.length ? Math.round(recentDurations.reduce((sum, duration) => sum + duration, 0) / recentDurations.length) : 3000;
    startupProgressValue = 0;
    startupProgressFloor = 0;
    track.classList.remove('pw-startup-priming');
    renderStartupProgress(0);
    const estimateText = 'Média das últimas ' + Math.max(1, recentDurations.length) + ' abertura' + (recentDurations.length === 1 ? '' : 's') + ' válida' + (recentDurations.length === 1 ? '' : 's') + ': cerca de ' + startupDurationLabel(startupEstimatedDuration) + '.';
    detail.textContent = startupTipText ? '💡 Dica: ' + startupTipText + ' · ' + estimateText : estimateText;
    const interval = Math.max(8, Math.round(startupEstimatedDuration / 100));
    const tick = () => {
      if (startupReadyToOpen) return;
      if (startupProgressValue < 99) renderStartupProgress(startupProgressValue + 1);
      // Até 97% acompanhamos a média; os dois últimos pontos ficam reservados
      // para a confirmação final dos dados, sem saltos ou animação travada.
      const nextDelay = startupProgressValue >= 97 ? Math.max(interval, 250) : interval;
      startupProgressFrame = window.setTimeout(tick, nextDelay);
    };
    cancelStartupProgressTimer();
    startupProgressFrame = window.setTimeout(tick, interval);
  }

  function setStartupProgress(value, message) {
    const detail = $('#pw-startup-progress-detail');
    if (detail && message) detail.textContent = message;
  }

  function finishStartupProgress() {
    const detail = $('#pw-startup-progress-detail');
    const panel = $('#pw-access-panel');
    if (!detail || startupReadyToOpen) return;
    startupReadyToOpen = true;
    cancelStartupProgressTimer();
    const complete = () => {
      if (startupProgressValue < 100) {
        renderStartupProgress(startupProgressValue + 1);
        startupProgressFrame = window.setTimeout(complete, 12);
        return;
      }
      const completedElapsed = Math.max(300, Math.round(performance.now() - startupStartedAt));
      detail.textContent = 'Sistema pronto em ' + startupDurationLabel(completedElapsed) + '.';
      recordStartupDuration(completedElapsed);
      window.setTimeout(() => {
        if (panel) panel.classList.remove('pw-visible');
        const shell = $('#pw-personalizados-shell');
        if (shell) shell.classList.remove('pw-auth-pending', 'pw-auth-denied');
        /* Deep-link: abre view indicada via ?pw_view=nome */
        try {
          const deepView = new URLSearchParams(window.location.search).get('pw_view');
          if (deepView) window.setTimeout(() => showSystemView(deepView), 300);
        } catch(e) {}
      }, 180);
    };
    complete();
  }

  async function runStartupTask(task, label, timeoutMs = 5000) {
    let timer = 0;
    const work = Promise.resolve().then(task).catch(error => {
      console.warn('Etapa opcional da abertura não foi concluída: ' + label, error);
      return null;
    });
    const timeout = new Promise(resolve => {
      timer = window.setTimeout(() => {
        console.warn('Etapa da abertura excedeu o tempo e seguirá em segundo plano: ' + label);
        resolve(null);
      }, timeoutMs);
    });
    const result = await Promise.race([work, timeout]);
    window.clearTimeout(timer);
    return result;
  }

