  function themeStorageKey() {
    const identity = currentUser && (currentUser.id || currentUser.login) || 'guest';
    return 'pw_personalizados_theme_' + String(identity);
  }

  function readUserTheme() {
    try { return JSON.parse(window.localStorage.getItem(themeStorageKey()) || 'null'); } catch (error) { return null; }
  }

  function applyVisualTheme(theme, persist) {
    const selected = theme || visualThemes.default;
    root.style.setProperty('--pw-primary', selected.primary);
    root.style.setProperty('--pw-primary-dark', selected.primaryDark || selected.primary);
    root.style.setProperty('--pw-blue', selected.accent);
    root.style.setProperty('--pw-soft', selected.soft || '#f5f8fc');
    root.style.setProperty('--pw-text', selected.text || '#202936');
    root.style.setProperty('--pw-font-family', selected.font || 'inherit');
    root.dataset.theme = selected.id || 'custom';
    if (persist) window.localStorage.setItem(themeStorageKey(), JSON.stringify(selected));
    $$('.pw-theme-option').forEach(button => button.classList.toggle('pw-selected', button.dataset.themeId === root.dataset.theme));
  }

  function normalizedTheme(theme) {
    return theme ? { ...theme } : { ...visualThemes.default, id: 'default' };
  }

  function renderThemeOptions(selectedTheme) {
    const selected = selectedTheme || themeDraft || readUserTheme() || { ...visualThemes.default, id: 'default' };
    $('#pw-theme-grid').innerHTML = Object.entries(visualThemes).map(([id, theme]) => {
      const active = selected.id === id;
      return '<button class="pw-theme-option' + (active ? ' pw-selected' : '') + '" type="button" role="radio" aria-checked="' + (active ? 'true' : 'false') + '" data-theme-id="' + id + '" style="--theme-primary:' + theme.primary + ';--theme-primary-dark:' + theme.primaryDark + ';--theme-accent:' + theme.accent + ';--theme-soft:' + theme.soft + ';--theme-text:' + theme.text + ';--theme-font:' + theme.font + '">' +
        '<span class="pw-theme-card-preview" aria-hidden="true"><span class="pw-theme-card-top"></span><span class="pw-theme-card-layout"><span class="pw-theme-card-sidebar"><i></i><i></i><i></i></span><span class="pw-theme-card-content"><b></b><i></i><i></i><em></em></span></span></span>' +
        '<span class="pw-theme-card-copy"><strong>' + escapeHtml(theme.name) + '</strong><small>' + escapeHtml(theme.description) + '</small></span><span class="pw-theme-check" aria-hidden="true">✓</span></button>';
    }).join('');
  }

  function renderFontOptions(selectedValue) {
    const selected = selectedValue || $('#pw-theme-font').value || visualFonts[0].value;
    $('#pw-font-options').innerHTML = visualFonts.map(font => '<button type="button" class="pw-font-option' + (font.value === selected ? ' pw-selected' : '') + '" role="option" aria-selected="' + (font.value === selected ? 'true' : 'false') + '" data-font-value="' + escapeHtml(font.value) + '" style="font-family:' + font.value + '"><span>' + escapeHtml(font.name) + '</span><small>Aa Bb Cc 123</small></button>').join('');
    const current = visualFonts.find(font => font.value === selected) || visualFonts[0];
    $('#pw-font-picker-label').textContent = current.name;
    $('#pw-font-picker-label').style.fontFamily = current.value;
  }

  function darkerThemeColor(hex) {
    const clean = String(hex || '').replace('#', '');
    if (!/^[0-9a-f]{6}$/i.test(clean)) return hex;
    const channels = [0, 2, 4].map(index => Math.max(0, Math.round(parseInt(clean.slice(index, index + 2), 16) * 0.74)));
    return '#' + channels.map(value => value.toString(16).padStart(2, '0')).join('');
  }

  function syncThemeControls(theme) {
    const selected = theme || readUserTheme() || { ...visualThemes.default, id: 'default' };
    $('#pw-theme-primary').value = selected.primary || visualThemes.default.primary;
    $('#pw-theme-accent').value = selected.accent || visualThemes.default.accent;
    $('#pw-theme-font').value = selected.font === 'inherit' ? 'system-ui, sans-serif' : (selected.font || 'system-ui, sans-serif');
    renderFontOptions($('#pw-theme-font').value);
  }

