  function syncActualDeliveryAvailability() {
    syncCurrentStatusDate();
    updateDeadlineStatus();
  }

  function syncCurrentStatusDate(orderOverride) {
    const field = $('#pw-current-status-date');
    if (!field) return;
    const selectedStatus = $('#pw-status').value || 'Criação da arte';
    const order = orderOverride || getOrders().find(record => record.orderNumber === $('#pw-order-number').value);
    let recordedAt = '';
    if (formStatusChangeAt && (!order || selectedStatus !== order.status)) recordedAt = formStatusChangeAt;
    else if (order) recordedAt = orderStatusDate(order, selectedStatus);
    else if (selectedStatus === 'Criação da arte' && $('#pw-created-date').value) recordedAt = $('#pw-created-date').value + 'T' + ($('#pw-order-time').value || '00:00');
    field.value = formatStatusDate(recordedAt);
  }

  function syncDateConstraints() {
    const today = localDateValue(new Date());
    const requestedField = $('#pw-requested-delivery');
    const savedOrder = editingOrderNumber && getOrders().find(order => String(order.orderNumber) === String(editingOrderNumber));
    const savedRequestedDelivery = String(savedOrder && savedOrder.requestedDelivery || '');
    const requestedDeliveryLocked = Boolean(savedRequestedDelivery);
    // Uma previsão já gravada é um dado histórico: não pode ser reescrita,
    // nem torna impossível salvar o restante de um pedido antigo.
    requestedField.readOnly = requestedDeliveryLocked;
    requestedField.setAttribute('aria-readonly', requestedDeliveryLocked ? 'true' : 'false');
    requestedField.title = requestedDeliveryLocked ? 'A previsão de entrega já foi registrada e não pode ser alterada.' : '';
    requestedField.min = requestedDeliveryLocked ? '' : today;

    let requestedError = '';
    if (!requestedDeliveryLocked && requestedField.value && requestedField.value < today) {
      requestedError = 'A previsão de entrega não pode ser anterior à data atual.';
    }
    requestedField.setCustomValidity(requestedError);
  }

  function initializeOrder() {
    const now = new Date();
    const number = nextOrderNumber();
    editingOrderNumber = '';
    aiOrderPaymentPending = false;
    loadedOrderCreator = null;
    $('#pw-order-number').value = number;
    $('#pw-order-number-view').textContent = number;
    $('#pw-created-date').value = localDateValue(now);
    $('#pw-order-time').value = localTimeValue(now);
    $('#pw-last-change').value = 'Ainda não alterado';
    $('#pw-created-by').value = currentUser ? userSummary(currentUser) : '';
    syncOrderStatusSelect('Criação da arte');
    formStatusChangeAt = null;
    $('#pw-requested-delivery').value = '';
    $('#pw-actual-delivery').value = '';
    $('#pw-personalization-notes').value = '';
    setDetailsSection(false);
    $('#pw-payment-method').value = '';
    $('#pw-payment-status').value = 'Pendente';
    $('#pw-discount-value').value = '0,00';
    $('#pw-surcharge-value').value = '0,00';
    $('#pw-paid-value').value = '0,00';
    clearClient();
    syncOrderOriginOptions('Normal');
    missingApprovedArtRowIds = new Set();
    items = [];
    renderItems();
    syncCurrentStatusDate();
    syncDateConstraints();
    updateDeadlineStatus();
    $('#pw-editing-note').classList.remove('pw-visible');
    syncOrderEditLock(null);
    captureOrderSavedState(false);
  }

  function orderIsLockedForCollaborator(order) {
    return !userIsAdministrator(currentUser) && !!(order && order.status && order.status !== 'Criação da arte');
  }

  function syncOrderEditLock(order) {
    const form = $('#pw-order-form');
    if (!form) return;
    const finalized = isOrderFinalized(order);
    const collaboratorLocked = orderIsLockedForCollaborator(order);
    const locked = finalized || collaboratorLocked;
    const allowedButtons = new Set(['pw-new-order', 'pw-order-history', 'pw-order-payments', 'pw-print-order']);
    $$('input,select,textarea,button', form).forEach(control => {
      if (locked) {
        if (allowedButtons.has(control.id)) return;
        if (!control.disabled) {
          control.disabled = true;
          control.dataset.statusLocked = '1';
        }
      } else if (control.dataset.statusLocked === '1') {
        control.disabled = false;
        delete control.dataset.statusLocked;
      }
    });
    form.classList.toggle('pw-order-collaborator-locked', locked);
    if (locked) {
      const note = $('#pw-editing-note');
      note.textContent = finalized
        ? 'Pedido ' + order.orderNumber + ' finalizado: foi entregue e está totalmente pago, portanto não pode mais ser alterado.'
        : 'Pedido ' + order.orderNumber + ' bloqueado para alterações após a mudança de situação. Como Colaborador, você ainda pode consultar, imprimir e registrar pagamentos.';
      note.classList.add('pw-visible', 'pw-order-lock-note');
    } else {
      $('#pw-editing-note').classList.remove('pw-order-lock-note');
    }
    syncOrderAiImageButton();
  }

  function syncOrderAiImageButton() {
    const button = $('#pw-order-ai-image');
    if (!button) return;
    const editing = Boolean(editingOrderNumber);
    button.hidden = editing;
    button.disabled = editing;
    button.setAttribute('aria-disabled', editing ? 'true' : 'false');
    button.dataset.tooltip = editing ? 'Disponível somente ao incluir um novo pedido' : 'IA - cadastro por print marketplaces';
    button.setAttribute('aria-label', editing ? 'Disponível somente ao incluir um novo pedido' : 'IA - cadastro por print marketplaces');
  }

  function getClients() {
    return orderedRecords(readStorage(STORAGE.clients, []));
  }

  function getProducts() {
    return orderedRecords(readStorage(STORAGE.products, []));
  }

  function getCategories() { return orderedRecords(readStorage(STORAGE.categories, [])); }
  function getUnits() { return orderedRecords(readStorage(STORAGE.units, [])); }
  function getSuppliers() { return orderedRecords(readStorage(STORAGE.suppliers, [])); }
  function getPaymentMethods() { return orderedRecords(readStorage(STORAGE.paymentMethods, [])); }

  function getOrderOrigins() {
    const saved = readStorage(STORAGE.orderOrigins, null);
    const defaults = [
      { id: 'order-origin-normal', code: '0001', name: 'Normal', marketplace: false, active: true, protected: true, position: 0 },
      { id: 'order-origin-mercado-livre', code: '0002', name: 'Mercado Livre', marketplace: true, active: true, protected: true, position: 1 },
      { id: 'order-origin-shopee', code: '0003', name: 'Shopee', marketplace: true, active: true, protected: true, position: 2 }
    ];
    const records = Array.isArray(saved) && saved.length ? saved : defaults;
    return orderedRecords(records.map((entry, index) => {
      const record = typeof entry === 'string' ? { name: entry } : entry;
      const name = String(record.name || '').trim();
      const legacyMarketplace = ['mercadolivre', 'shopee', 'marketplace'].includes(normalize(name).replace(/[^a-z0-9]/g, ''));
      return {
        ...record,
        id: String(record.id || 'order-origin-' + index),
        code: String(record.code || String(index + 1).padStart(4, '0')),
        name,
        marketplace: Object.prototype.hasOwnProperty.call(record, 'marketplace')
          ? (record.marketplace === true || ['1', 'true', 'yes', 'sim'].includes(String(record.marketplace || '').trim().toLowerCase()))
          : legacyMarketplace,
        active: record.active !== false,
        position: record.position == null ? index : record.position
      };
    }).filter(record => record.name));
  }

  function ensureDefaultOrderOrigins() {
    const defaults = [
      { id: 'order-origin-normal', code: '0001', name: 'Normal', marketplace: false, active: true, protected: true, position: 0 },
      { id: 'order-origin-mercado-livre', code: '0002', name: 'Mercado Livre', marketplace: true, active: true, protected: true, position: 1 },
      { id: 'order-origin-shopee', code: '0003', name: 'Shopee', marketplace: true, active: true, protected: true, position: 2 }
    ];
    const saved = readStorage(STORAGE.orderOrigins, null);
    const records = Array.isArray(saved) ? saved.slice() : [];
    let changed = false;
    defaults.forEach(defaultRecord => {
      const found = records.find(record => normalize(record && record.name) === normalize(defaultRecord.name));
      if (!found) { records.push(defaultRecord); changed = true; }
      else {
        if (found.marketplace == null) { found.marketplace = defaultRecord.marketplace; changed = true; }
        if (found.protected !== true) { found.protected = true; changed = true; }
        if (found.active === false) { found.active = true; changed = true; }
      }
    });
    if (changed || !Array.isArray(saved)) {
      writeStorage(STORAGE.orderOrigins, records);
      writeStorage(STORAGE.orderOriginSequence, Math.max(4, records.reduce((max, record) => Math.max(max, Number(record.code) || 0), 0) + 1));
    }
  }

  function orderOriginName(value) {
    const normalized = normalize(value);
    const record = getOrderOrigins().find(item => normalize(item.name) === normalized || (item.aliases || []).some(alias => normalize(alias) === normalized));
    return record ? record.name : String(value || 'Normal');
  }

  function orderOriginRecord(value) {
    const normalized = normalize(value);
    return getOrderOrigins().find(item => normalize(item.name) === normalized || (item.aliases || []).some(alias => normalize(alias) === normalized)) || null;
  }

  function orderOriginIsMarketplace(value) {
    const record = orderOriginRecord(value);
    if (record) return record.marketplace === true || normalize(record.name).replace(/[^a-z0-9]/g, '') === 'marketplace';
    const compact = normalize(value).replace(/[^a-z0-9]/g, '');
    return compact === 'ml' || compact.includes('mercadolivre') || compact.includes('shopee') || compact === 'marketplace';
  }

  function syncOrderOriginOptions(selected = '') {
    const select = $('#pw-order-client-origin');
    if (!select) return;
    const current = orderOriginName(selected || select.value || 'Normal');
    const options = getOrderOrigins().filter(record => record.active !== false || normalize(record.name) === normalize(current));
    if (!options.some(record => normalize(record.name) === normalize(current))) options.push({ name: current, active: true });
    select.innerHTML = options.map(record => '<option value="' + escapeHtml(record.name) + '">' + escapeHtml(record.name) + '</option>').join('');
    select.value = current;
    if (!select.value) select.value = 'Normal';
  }

  function getCaseCorrectionIgnored() {
    const stored = readStorage(STORAGE.caseCorrectionIgnored, []);
    return Array.isArray(stored) ? stored.filter(item => typeof item === 'string') : [];
  }

  function caseCorrectionSources() {
    return [
      { kind: 'clients', list: true, storageKey: STORAGE.clients, sourceLabel: 'Cliente', getRecords: getClients, getRecordId: r => r.id,
        identify: r => (r.code ? r.code + ' — ' : '') + (r.name || '—'),
        fields: [
          { path: 'name', label: 'Nome' },
          { path: 'address.street', label: 'Endereço — Rua' },
          { path: 'address.neighborhood', label: 'Endereço — Bairro' },
          { path: 'address.city', label: 'Endereço — Cidade' }
        ] },
      { kind: 'suppliers', list: true, storageKey: STORAGE.suppliers, sourceLabel: 'Fornecedor', getRecords: getSuppliers, getRecordId: r => r.id,
        identify: r => (r.code ? r.code + ' — ' : '') + (r.name || '—'),
        fields: [ { path: 'name', label: 'Nome' }, { path: 'contact', label: 'Pessoa de contato' } ] },
      { kind: 'categories', list: true, storageKey: STORAGE.categories, sourceLabel: 'Categoria', getRecords: getCategories, getRecordId: r => r.id,
        identify: r => r.name || '—', fields: [ { path: 'name', label: 'Nome' } ] },
      { kind: 'units', list: true, storageKey: STORAGE.units, sourceLabel: 'Unidade', getRecords: getUnits, getRecordId: r => r.id,
        identify: r => r.name || '—', fields: [ { path: 'name', label: 'Nome' } ] },
      { kind: 'paymentMethods', list: true, storageKey: STORAGE.paymentMethods, sourceLabel: 'Forma de pagamento', getRecords: getPaymentMethods, getRecordId: r => r.id,
        identify: r => r.name || '—', fields: [ { path: 'name', label: 'Nome' } ] },
      { kind: 'products', list: true, storageKey: STORAGE.products, sourceLabel: 'Produto', getRecords: getProducts, getRecordId: r => r.id,
        identify: r => (r.code ? r.code + ' — ' : '') + (r.description || '—'), fields: [ { path: 'description', label: 'Descrição' } ] },
      { kind: 'orders', list: true, storageKey: STORAGE.orders, sourceLabel: 'Pedido', getRecords: getOrders, getRecordId: r => r.orderNumber,
        identify: r => (r.orderNumber ? r.orderNumber + ' — ' : '') + (r.client && r.client.name || '—'),
        fields: [
          { path: 'client.name', label: 'Nome do cliente (no pedido)' },
          { path: 'client.address.street', label: 'Endereço — Rua (no pedido)' },
          { path: 'client.address.neighborhood', label: 'Endereço — Bairro (no pedido)' },
          { path: 'client.address.city', label: 'Endereço — Cidade (no pedido)' }
        ] },
      { kind: 'nfeSettings', list: false, storageKey: STORAGE.nfeSettings, sourceLabel: 'Configuração fiscal (NF-e)', getRecords: () => [getNfeSettings()], getRecordId: () => 'single',
        identify: () => 'Responsável técnico', fields: [ { path: 'techName', label: 'Contato técnico' } ] }
    ];
  }

  function scanCaseCorrections() {
    const issues = [];
    caseCorrectionSources().forEach(source => {
      (source.getRecords() || []).forEach(record => {
        const recordId = source.getRecordId(record) || 'single';
        source.fields.forEach(field => {
          const original = getByPath(record, field.path);
          if (typeof original !== 'string' || !original.trim()) return;
          const suggestion = suggestCaseFix(original);
          if (suggestion && suggestion !== original) {
            issues.push({
              id: source.kind + '::' + recordId + '::' + field.path,
              kind: source.kind,
              storageKey: source.storageKey,
              list: source.list,
              recordId: recordId,
              fieldPath: field.path,
              fieldLabel: field.label,
              sourceLabel: source.sourceLabel,
              recordLabel: source.identify(record),
              original,
              suggestion
            });
          }
        });
      });
    });
    return issues;
  }

  function resolveCaseCorrectionIssueByKey(key) {
    const parts = String(key).split('::');
    if (parts.length !== 3) return null;
    const [kind, recordId, fieldPath] = parts;
    const source = caseCorrectionSources().find(item => item.kind === kind);
    if (!source) return null;
    const field = source.fields.find(item => item.path === fieldPath);
    if (!field) return null;
    const record = (source.getRecords() || []).find(item => String(source.getRecordId(item) || 'single') === recordId);
    if (!record) return null;
    const original = getByPath(record, fieldPath);
    if (typeof original !== 'string' || !original.trim()) return null;
    return {
      id: key, kind, storageKey: source.storageKey, list: source.list, recordId,
      fieldPath, fieldLabel: field.label, sourceLabel: source.sourceLabel,
      recordLabel: source.identify(record), original, suggestion: suggestCaseFix(original) || original
    };
  }

  async function loadCaseCorrectionSchedule() {
    const status = $('#pw-case-correction-schedule-status');
    const enabledInput = $('#pw-case-correction-schedule-enabled');
    const valueInput = $('#pw-case-correction-schedule-value');
    const unitInput = $('#pw-case-correction-schedule-unit');
    if (!enabledInput || !valueInput || !unitInput) return;
    try {
      const payload = await postForm({ action: 'pw_personalizados_case_correction_schedule_fetch', nonce: SERVER.nonce || '' });
      if (!payload || !payload.success || !payload.data) throw new Error((payload && payload.data && payload.data.message) || 'Não foi possível carregar o agendamento.');
      const { schedule, last, next } = payload.data;
      enabledInput.checked = Boolean(schedule && schedule.enabled);
      valueInput.value = schedule && schedule.interval_value ? schedule.interval_value : 30;
      unitInput.value = schedule && schedule.interval_unit ? schedule.interval_unit : 'days';
      if (!status) return;
      const lastLine = last
        ? 'Última correção automática: ' + formatCleanupDate(last.time) + ' (' + (last.fields || 0) + ' campo(s) em ' + (last.records || 0) + ' registro(s))'
        : 'Ainda não rodou automaticamente.';
      const nextLine = schedule && schedule.enabled && next ? ' · Próxima: ' + formatCleanupDate(next) : ' · Desabilitado (não roda sozinho).';
      status.textContent = lastLine + nextLine;
    } catch (error) {
      if (status) status.textContent = error && error.message ? error.message : 'Não foi possível carregar o agendamento.';
    }
  }

  async function saveCaseCorrectionSchedule() {
    const button = $('#pw-case-correction-schedule-save');
    const enabledInput = $('#pw-case-correction-schedule-enabled');
    const valueInput = $('#pw-case-correction-schedule-value');
    const unitInput = $('#pw-case-correction-schedule-unit');
    if (!enabledInput || !valueInput || !unitInput) return;
    if (button) button.disabled = true;
    try {
      const payload = await postForm({
        action: 'pw_personalizados_case_correction_schedule_save',
        nonce: SERVER.nonce || '',
        enabled: enabledInput.checked ? '1' : '',
        interval_value: valueInput.value || '30',
        interval_unit: unitInput.value || 'days'
      });
      if (!payload || !payload.success) throw new Error((payload && payload.data && payload.data.message) || 'Não foi possível salvar o agendamento.');
      recordAudit('settings', 'case-correction-schedule', 'Agendamento da correção automática de textos', enabledInput.checked ? ('habilitado, a cada ' + valueInput.value + ' ' + unitInput.options[unitInput.selectedIndex].text.toLowerCase()) : 'desabilitado');
      showMessage('Agendamento salvo.', 'success');
      loadCaseCorrectionSchedule();
    } catch (error) {
      showMessage(error && error.message ? error.message : 'Não foi possível salvar o agendamento.', 'error');
    } finally {
      if (button) button.disabled = false;
    }
  }

  function renderCaseCorrectionModal() {
    caseCorrectionAllIssues = scanCaseCorrections();
    caseCorrectionIgnoredKeys = new Set(getCaseCorrectionIgnored());
    $('#pw-case-correction-subtitle').textContent = 'Varredura em clientes, fornecedores, categorias, unidades, formas de pagamento, produtos, pedidos e configuração fiscal.';
    activateCaseCorrectionTab('pending');
    openModal('pw-case-correction-modal', true);
  }

  function activateCaseCorrectionTab(tabName) {
    caseCorrectionActiveTab = tabName;
    $$('[data-case-correction-tab]').forEach(button => {
      const active = button.dataset.caseCorrectionTab === tabName;
      button.classList.toggle('pw-active', active);
      button.classList.toggle('is-active', active);
      button.setAttribute('aria-selected', active ? 'true' : 'false');
    });
    $('#pw-case-correction-ignore').hidden = tabName !== 'pending';
    $('#pw-case-correction-apply').hidden = tabName !== 'pending';
    $('#pw-case-correction-restore').hidden = tabName !== 'ignored';
    renderCaseCorrectionTable();
  }

  function currentCaseCorrectionIssues() {
    if (caseCorrectionActiveTab === 'ignored') {
      return Array.from(caseCorrectionIgnoredKeys).map(resolveCaseCorrectionIssueByKey).filter(Boolean);
    }
    return caseCorrectionAllIssues.filter(issue => !caseCorrectionIgnoredKeys.has(issue.id));
  }

  function highlightCaseCorrectionOriginal(original, suggestion) {
    const originalWords = String(original == null ? '' : original).split(' ');
    const suggestionWords = String(suggestion == null ? '' : suggestion).split(' ');
    return originalWords.map((word, index) => {
      const safeWord = escapeHtml(word);
      const changed = suggestionWords[index] !== undefined && suggestionWords[index] !== word;
      return changed ? '<strong class="pw-case-correction-diff">' + safeWord + '</strong>' : safeWord;
    }).join(' ');
  }

  function renderCaseCorrectionTable() {
    const issues = currentCaseCorrectionIssues();
    caseCorrectionIssues = issues;
    const body = $('#pw-case-correction-body');
    const table = $('#pw-case-correction-table');
    const empty = $('#pw-case-correction-empty');
    const selectAll = $('#pw-case-correction-select-all');
    if (!issues.length) {
      table.hidden = true;
      empty.hidden = false;
      empty.textContent = caseCorrectionActiveTab === 'ignored'
        ? 'Nenhum campo ignorado no momento.'
        : 'Nenhum campo fora do padrão foi encontrado. Seus cadastros já estão certinhos.';
      $('#pw-case-correction-count').textContent = '';
      selectAll.checked = false;
      $('#pw-case-correction-apply').disabled = true;
      $('#pw-case-correction-ignore').disabled = true;
      $('#pw-case-correction-restore').disabled = true;
    } else {
      table.hidden = false;
      empty.hidden = true;
      const editable = caseCorrectionActiveTab === 'pending';
      body.innerHTML = issues.map(issue => '<tr><td><input type="checkbox" data-case-correction-item="' + escapeHtml(issue.id) + '" checked></td><td>' + escapeHtml(issue.sourceLabel) + '</td><td>' + escapeHtml(issue.recordLabel) + '</td><td>' + escapeHtml(issue.fieldLabel) + '</td><td class="pw-case-correction-current">' + highlightCaseCorrectionOriginal(issue.original, issue.suggestion) + '</td><td>' + (editable
        ? '<input type="text" class="pw-case-correction-suggestion-input" data-case-correction-suggestion="' + escapeHtml(issue.id) + '" value="' + escapeHtml(issue.suggestion) + '">'
        : '<span class="pw-case-correction-suggestion">' + escapeHtml(issue.suggestion) + '</span>') + '</td></tr>').join('');
      selectAll.checked = true;
      $('#pw-case-correction-apply').disabled = false;
      $('#pw-case-correction-ignore').disabled = false;
      $('#pw-case-correction-restore').disabled = false;
      updateCaseCorrectionCount();
    }
  }

  function updateCaseCorrectionCount() {
    const total = $$('[data-case-correction-item]').length;
    const checked = $$('[data-case-correction-item]:checked').length;
    $('#pw-case-correction-count').textContent = checked + ' de ' + total + ' selecionado(s)';
  }

  async function saveCaseCorrectionIgnored(keys) {
    return writeStorage(STORAGE.caseCorrectionIgnored, Array.from(keys), { immediate: true });
  }

  async function ignoreSelectedCaseCorrections() {
    const selectedIds = $$('[data-case-correction-item]:checked').map(input => input.dataset.caseCorrectionItem);
    if (!selectedIds.length) return showMessage('Selecione ao menos um campo para ignorar.', 'error');
    const button = $('#pw-case-correction-ignore');
    button.disabled = true;
    try {
      selectedIds.forEach(id => caseCorrectionIgnoredKeys.add(id));
      const saved = await saveCaseCorrectionIgnored(caseCorrectionIgnoredKeys);
      if (!saved) { selectedIds.forEach(id => caseCorrectionIgnoredKeys.delete(id)); return showMessage('Não foi possível salvar os itens ignorados.', 'error'); }
      showMessage(selectedIds.length + ' campo(s) movido(s) para "Ignorados".', 'success');
      renderCaseCorrectionTable();
    } finally {
      button.disabled = false;
    }
  }

  async function restoreSelectedCaseCorrections() {
    const selectedIds = $$('[data-case-correction-item]:checked').map(input => input.dataset.caseCorrectionItem);
    if (!selectedIds.length) return showMessage('Selecione ao menos um campo para restaurar.', 'error');
    const button = $('#pw-case-correction-restore');
    button.disabled = true;
    try {
      selectedIds.forEach(id => caseCorrectionIgnoredKeys.delete(id));
      const saved = await saveCaseCorrectionIgnored(caseCorrectionIgnoredKeys);
      if (!saved) { selectedIds.forEach(id => caseCorrectionIgnoredKeys.add(id)); return showMessage('Não foi possível restaurar os itens selecionados.', 'error'); }
      showMessage(selectedIds.length + ' campo(s) devolvido(s) para a lista de pendentes.', 'success');
      renderCaseCorrectionTable();
    } finally {
      button.disabled = false;
    }
  }

  function renderPdfRulesSettings() {
    const body = $('#pw-pdf-rules-body');
    if (!body) return;
    const rules = getPdfRules();
    const categories = getCategories();
    if (!categories.length) { body.innerHTML = '<p class="pw-field-hint">Nenhuma categoria cadastrada ainda.</p>'; return; }
    body.innerHTML = categories.map(category => {
      const id = String(category.id || category.name);
      const rule = rules[id] || {};
      const num = value => (value === null || value === undefined ? '' : value);
      return '<div class="pw-pdf-rule-row" data-pdf-rule="' + escapeHtml(id) + '">' +
        '<strong>' + escapeHtml(category.name) + '</strong>' +
        '<label><input type="checkbox" data-field="enabled"' + (rule.enabled !== false ? ' checked' : '') + '> Habilitar PDF</label>' +
        '<label><input type="checkbox" data-field="required"' + (rule.required !== false ? ' checked' : '') + '> Obrigatório</label>' +
        '<label>Larg. mín (mm) <input type="number" min="0" step="0.1" data-field="minWidth" value="' + escapeHtml(String(num(rule.minWidth))) + '"></label>' +
        '<label>Larg. máx (mm) <input type="number" min="0" step="0.1" data-field="maxWidth" value="' + escapeHtml(String(num(rule.maxWidth))) + '"></label>' +
        '<label>Alt. mín (mm) <input type="number" min="0" step="0.1" data-field="minHeight" value="' + escapeHtml(String(num(rule.minHeight))) + '"></label>' +
        '<label>Alt. máx (mm) <input type="number" min="0" step="0.1" data-field="maxHeight" value="' + escapeHtml(String(num(rule.maxHeight))) + '"></label>' +
        '<label>Tam. máx (MB) <input type="number" min="0" step="0.1" data-field="maxSizeMb" value="' + escapeHtml(String(num(rule.maxSizeMb))) + '"></label>' +
      '</div>';
    }).join('');
  }

  async function savePdfRulesSettings() {
    const rules = {};
    $$('[data-pdf-rule]').forEach(row => {
      const id = row.dataset.pdfRule;
      const get = field => row.querySelector('[data-field="' + field + '"]');
      const num = field => { const value = get(field).value; return value === '' ? null : Number(value); };
      rules[id] = {
        enabled: get('enabled').checked,
        required: get('required').checked,
        minWidth: num('minWidth'), maxWidth: num('maxWidth'),
        minHeight: num('minHeight'), maxHeight: num('maxHeight'),
        maxSizeMb: num('maxSizeMb')
      };
    });
    const saved = await writeStorage(STORAGE.pdfRules, rules, { immediate: true });
    if (!saved) return showMessage('Não foi possível salvar as regras de PDF.', 'error');
    showMessage('Regras de PDF por categoria salvas.', 'success');
  }

  async function applySelectedCaseCorrections() {
    const selectedIds = new Set($$('[data-case-correction-item]:checked').map(input => input.dataset.caseCorrectionItem));
    const selected = caseCorrectionIssues.filter(issue => selectedIds.has(issue.id)).map(issue => {
      const input = $('[data-case-correction-suggestion="' + issue.id + '"]');
      const value = input ? input.value : issue.suggestion;
      return { ...issue, suggestion: value };
    });
    if (!selected.length) return showMessage('Selecione ao menos um campo para corrigir.', 'error');
    if (selected.some(issue => !issue.suggestion.trim())) return showMessage('O campo "Ficará assim" não pode ficar vazio.', 'error');
    const sources = caseCorrectionSources();
    const byStorageKey = new Map();
    selected.forEach(issue => {
      if (!byStorageKey.has(issue.storageKey)) byStorageKey.set(issue.storageKey, []);
      byStorageKey.get(issue.storageKey).push(issue);
    });
    const applyButton = $('#pw-case-correction-apply');
    applyButton.disabled = true;
    let totalFields = 0;
    try {
      for (const [storageKey, issuesForKey] of byStorageKey) {
        const source = sources.find(item => item.storageKey === storageKey);
        if (!source) continue;
        if (source.list) {
          const records = JSON.parse(JSON.stringify(source.getRecords()));
          issuesForKey.forEach(issue => {
            const record = records.find(item => String(source.getRecordId(item) || 'single') === String(issue.recordId));
            if (record) { setByPath(record, issue.fieldPath, issue.suggestion); totalFields += 1; }
          });
          const saved = await writeStorage(storageKey, records, { immediate: true });
          if (!saved) { showMessage('Não foi possível salvar as correções de ' + source.sourceLabel.toLowerCase() + '.', 'error'); return; }
        } else {
          const settings = { ...source.getRecords()[0] };
          issuesForKey.forEach(issue => { setByPath(settings, issue.fieldPath, issue.suggestion); totalFields += 1; });
          const saved = await writeStorage(storageKey, settings, { immediate: true });
          if (!saved) { showMessage('Não foi possível salvar as correções de ' + source.sourceLabel.toLowerCase() + '.', 'error'); return; }
        }
      }
      const appliedIds = new Set(selected.map(issue => issue.id));
      if (appliedIds.size) {
        appliedIds.forEach(id => caseCorrectionIgnoredKeys.delete(id));
        await saveCaseCorrectionIgnored(caseCorrectionIgnoredKeys);
      }
      recordAudit('settings', 'case-correction', 'Correção automática de textos', totalFields + ' campo(s) corrigido(s).');
      closeModal('pw-case-correction-modal', true);
      refreshAllViews();
      showMessage(totalFields + ' campo(s) corrigido(s) com sucesso.', 'success');
    } finally {
      applyButton.disabled = false;
    }
  }

  function ensureDefaultPaymentMethods() {
    if (getPaymentMethods().length) return;
    const names = ['Pix', 'Dinheiro', 'Cartão de crédito', 'Cartão de débito', 'Transferência bancária', 'Boleto', 'Outro'];
    const records = names.map((name, index) => ({ id: 'payment-method-default-' + (index + 1), code: String(index + 1).padStart(4, '0'), name, active: true }));
    writeStorage(STORAGE.paymentMethods, records);
    writeStorage(STORAGE.paymentMethodSequence, records.length + 1);
  }

  function populatePaymentMethodSelects(selectedOrder, selectedFinal) {
    const options = getPaymentMethods().filter(record => record.active !== false || record.name === selectedOrder || record.name === selectedFinal)
      .map(record => '<option value="' + escapeHtml(record.name) + '">' + escapeHtml(record.name) + '</option>').join('');
    const orderSelect = $('#pw-payment-method');
    const finalSelect = $('#pw-final-payment-method');
    const entrySelect = $('#pw-payment-entry-method');
    orderSelect.innerHTML = '<option value="">Não informada</option>' + options;
    if (finalSelect) finalSelect.innerHTML = '<option value="">Selecione</option>' + options;
    if (entrySelect) entrySelect.innerHTML = '<option value="">Selecione</option>' + options;
    orderSelect.value = selectedOrder || '';
    if (finalSelect) finalSelect.value = selectedFinal || '';
  }

  function paymentStatusFor(order, paidValue) {
    const payments = Array.isArray(order && order.payments) ? order.payments : [];
    if (payments.some(payment => payment.type === 'Cortesia')) return 'Cortesia';
    const paid = Math.max(0, Number(paidValue || 0));
    if (paid <= 0) return 'Pendente';
    return paid + 0.005 >= adjustedOrderTotal(order || {}) ? 'Pago' : 'Parcial';
  }

  function orderHasNoPendingBalance(order) {
    return Math.max(0, adjustedOrderTotal(order || {}) - Number(order && order.paid || 0)) <= 0.005;
  }

  function isOrderFinalized(order) {
    return Boolean(order && order.finalized === true) || Boolean(order && order.status === 'Entregue' && orderHasNoPendingBalance(order));
  }

  function isOrderActive(order) {
    return Boolean(order) && order.status !== 'Entregue' && !isOrderFinalized(order);
  }

  function syncOrderFinalization(order) {
    if (!order) return false;
    const finalized = order.status === 'Entregue' && orderHasNoPendingBalance(order);
    const changed = Boolean(order.finalized) !== finalized;
    order.finalized = finalized;
    if (finalized && !order.finalizedAt) order.finalizedAt = new Date().toISOString();
    if (!finalized) delete order.finalizedAt;
    return changed;
  }

  function finalizationLabel(order) {
    return isOrderFinalized(order) ? 'Finalizado' : 'Em aberto';
  }

  function finalizationIndicatorHtml(order) {
    const finalized = isOrderFinalized(order);
    const delivered = order && order.status === 'Entregue';
    const balance = Math.max(0, adjustedOrderTotal(order || {}) - Number(order && order.paid || 0));
    const deliveryInfo = delivered
      ? 'Entrega: registrada' + (order && order.actualDelivery ? ' em ' + String(order.actualDelivery).split('-').reverse().join('/') : '')
      : 'Entrega: ainda não registrada';
    const paymentInfo = balance <= 0.005
      ? 'Pagamento: Nenhum saldo pendente'
      : 'Pagamento: Saldo pendente: ' + money.format(balance);
    const label = deliveryInfo + '\n' + paymentInfo;
    return '<span class="pw-order-finalization-icon ' + (finalized ? 'pw-order-finalization-icon-success' : 'pw-order-finalization-icon-open') + ' pw-tooltip" data-tooltip="' + escapeHtml(label) + '" title="' + escapeHtml(label) + '" aria-label="' + escapeHtml(label) + '">' + (finalized ? '✓' : '×') + '</span>';
  }

  function clientForOrder(order) {
    const id = order && order.client && order.client.id;
    return getClients().find(client => String(client.id) === String(id)) || (order && order.client) || {};
  }

  function marketplaceOrigin(value) {
    const origin = normalize(value).replace(/[^a-z0-9]/g, '');
    if (origin === 'ml' || origin.includes('mercadolivre')) return 'Mercado Livre';
    if (origin.includes('shopee')) return 'Shopee';
    return '';
  }

  function clientHasMarketplaceOrder(clientId) {
    if (!clientId) return false;
    return getOrders().some(order => {
      const orderClient = order && order.client || {};
      if (String(orderClient.id || '') !== String(clientId)) return false;
      return [orderClient.origin, order.origin, order.platform, order.channel].some(value => !!marketplaceOrigin(value));
    });
  }

  function clientHasPendingMonthlyBilling(clientId) {
    if (!clientId) return false;
    return monthlyOpenOrders().some(order => String(order.client && order.client.id || '') === String(clientId));
  }

  function clientIdentityText(value) {
    return normalize(value).replace(/[^a-z0-9]/g, '');
  }

  function clientIdentityNameTokens(value) {
    return normalize(value).replace(/[^a-z0-9 ]/g, ' ').split(/\s+/).filter(token => token.length >= 2);
  }

  function clientAddressValue(address, key) {
    const value = address && address[key] || '';
    return key === 'cep' || key === 'cityCode' ? digits(value) : clientIdentityText(value);
  }

  function clientAddressFieldEquivalent(left, right, key) {
    const first = clientAddressValue(left, key), second = clientAddressValue(right, key);
    if (!first || !second) return false;
    if (first === second) return true;
    if (key === 'street' || key === 'neighborhood' || key === 'city') return first.includes(second) || second.includes(first);
    return false;
  }

  function clientIdentityMatch(record, candidate) {
    const source = record || {}, target = candidate || {};
    const targetDocument = digits(target.document), sourceDocument = digits(source.document);
    const targetPhone = digits(target.phone), sourcePhone = digits(source.phone);
    const targetEmail = normalize(target.email), sourceEmail = normalize(source.email);
    const targetName = clientIdentityText(target.name), sourceName = clientIdentityText(source.name);
    const targetAddress = target.address || {}, sourceAddress = source.address || {};
    const targetDocumentValid = targetDocument.length === 11 || targetDocument.length === 14;
    const targetPhoneValid = isValidPhone(target.phone);
    const targetEmailValid = isValidEmail(target.email);
    const matches = [];
    let score = 0;
    // Um documento, telefone ou e-mail diferentes são conflitos fortes: não
    // associe automaticamente apenas porque o nome parece igual.
    if (targetDocumentValid && sourceDocument && sourceDocument !== targetDocument) return { score: 0, hardConflict: true, matches: [] };
    if (targetPhoneValid && sourcePhone && sourcePhone !== targetPhone) return { score: 0, hardConflict: true, matches: [] };
    if (targetEmailValid && sourceEmail && sourceEmail !== targetEmail) return { score: 0, hardConflict: true, matches: [] };
    if (targetDocumentValid && sourceDocument === targetDocument) { score += 110; matches.push({ field: 'document', label: 'CPF/CNPJ', value: formatDocument(target.document) }); }
    if (targetPhoneValid && sourcePhone === targetPhone) { score += 90; matches.push({ field: 'phone', label: 'Telefone/WhatsApp', value: formatPhone(target.phone) }); }
    if (targetEmailValid && sourceEmail === targetEmail) { score += 80; matches.push({ field: 'email', label: 'E-mail', value: target.email }); }
    if (targetName && sourceName && targetName === sourceName) { score += 60; matches.push({ field: 'name', label: 'Nome completo', value: String(target.name || '').trim() }); }
    const targetTokens = clientIdentityNameTokens(target.name), sourceTokens = new Set(clientIdentityNameTokens(source.name));
    const commonNameTokens = targetTokens.filter(token => sourceTokens.has(token));
    if (targetName !== sourceName && targetTokens.length >= 2 && commonNameTokens.length >= Math.max(2, Math.ceil(targetTokens.length * 0.75))) {
      score += 25;
      matches.push({ field: 'name-similar', label: 'Nome semelhante', value: String(target.name || '').trim() });
    }
    const addressKeys = ['cep', 'street', 'number', 'neighborhood', 'city', 'state'];
    const addressMatches = addressKeys.filter(key => clientAddressFieldEquivalent(targetAddress, sourceAddress, key));
    if (addressMatches.includes('cep')) { score += 45; matches.push({ field: 'address-cep', label: 'CEP do endereço', value: targetAddress.cep }); }
    if (addressMatches.includes('street') && addressMatches.includes('number')) { score += 30; matches.push({ field: 'address', label: 'Endereço', value: [targetAddress.street, targetAddress.number].filter(Boolean).join(', ') }); }
    if (addressMatches.includes('city') && addressMatches.includes('state')) score += 10;
    return { score, hardConflict: false, matches };
  }

  function findBestMatchingClient(clients, candidate) {
    const ranked = (Array.isArray(clients) ? clients : [])
      .map(record => ({ record, identity: clientIdentityMatch(record, candidate) }))
      .filter(entry => !entry.identity.hardConflict && entry.identity.score > 0)
      .sort((left, right) => right.identity.score - left.identity.score);
    if (!ranked.length) return null;
    const top = ranked[0], tied = ranked.filter(entry => entry.identity.score === top.identity.score);
    return {
      record: top.record,
      score: top.identity.score,
      matches: top.identity.matches,
      ambiguous: tied.length > 1,
      candidates: ranked.slice(0, 3).map(entry => ({ record: entry.record, score: entry.identity.score, matches: entry.identity.matches }))
    };
  }

  function findPossibleDuplicateClient(clients, editingClientId, candidate) {
    const ranked = (Array.isArray(clients) ? clients : [])
      .filter(record => record.id !== editingClientId)
      .map(record => ({ record, identity: clientIdentityMatch(record, candidate) }))
      .filter(entry => !entry.identity.hardConflict && entry.identity.score >= 60)
      .sort((left, right) => right.identity.score - left.identity.score);
    if (!ranked.length) return null;
    const top = ranked[0], tied = ranked.filter(entry => entry.identity.score === top.identity.score);
    if (tied.length > 1) return null;
    const primary = top.identity.matches[0] || { field: 'name', label: 'Nome completo', value: candidate.name };
    return { record: top.record, field: primary.field, label: primary.label, value: primary.value, score: top.identity.score, matches: top.identity.matches };
  }

  function confirmPossibleDuplicateClient(match) {
    $('#pw-duplicate-client-reason').textContent = 'O ' + match.label.toLowerCase() + ' informado já está cadastrado em outro cliente:';
    $('#pw-duplicate-client-info').innerHTML = '<strong>' + escapeHtml(match.record.code || '—') + ' — ' + escapeHtml(match.record.name || '—') + '</strong><span>' + escapeHtml(match.label) + ': ' + escapeHtml(match.value) + '</span>';
    openModal('pw-duplicate-client-modal', true);
    return new Promise(resolve => {
      duplicateClientResolve = resolve;
    });
  }

  function syncClientPhoneRequirement() {
    const input = $('#pw-new-client-phone'), label = $('#pw-new-client-phone-label');
    if (!input || !label) return;
    const orderOrigin = $('#pw-order-client-origin') ? $('#pw-order-client-origin').value : '';
    const orderViewActive = !!$('#pw-order-form') && $('#pw-order-form').classList.contains('pw-active');
    const marketplaceOrder = orderViewActive && orderOriginIsMarketplace(orderOrigin);
    const optional = marketplaceOrder || (!!editingClientId && clientHasMarketplaceOrder(editingClientId));
    input.required = !optional;
    input.title = optional ? 'Opcional: pedidos de Mercado Livre ou Shopee podem não informar WhatsApp.' : '';
    input.placeholder = optional ? 'Não informado para pedidos de marketplace' : '(00) 00000-0000';
    label.classList.toggle('pw-required', !optional);
    label.textContent = optional ? 'Telefone / WhatsApp (opcional para marketplace)' : 'Telefone / WhatsApp';
  }

  function orderUsesMonthlyClosing(order) {
    const client = clientForOrder(order);
    const day = Number(client.closingDay || 0);
    return client.monthlyClosing === true && day >= 1 && day <= 31;
  }

  function monthlyDueDate(order) {
    const client = clientForOrder(order);
    const closingDay = Math.max(1, Math.min(31, Number(client.closingDay || 1)));
    const created = orderDate(order) || new Date();
    let year = created.getFullYear(), month = created.getMonth();
    const makeDate = () => new Date(year, month, Math.min(closingDay, new Date(year, month + 1, 0).getDate()), 12);
    let due = makeDate();
    if (created > due) { month += 1; if (month > 11) { month = 0; year += 1; } due = makeDate(); }
    return due;
  }

  function nextClientClosingDate(client) {
    const day = Math.max(1, Math.min(31, Number(client && client.closingDay || 1)));
    const now = new Date(), today = new Date(now.getFullYear(), now.getMonth(), now.getDate(), 12);
    let year = today.getFullYear(), month = today.getMonth();
    const make = () => new Date(year, month, Math.min(day, new Date(year, month + 1, 0).getDate()), 12);
    let result = make();
    if (result < today) { month += 1; if (month > 11) { month = 0; year += 1; } result = make(); }
    return result;
  }

  function clientOriginIndicatorHtml(client) {
    const origin = client && client.origin || 'Normal';
    if (origin === 'Mercado Livre') return '<span class="pw-client-origin-dot pw-origin-mercado-livre pw-tooltip" data-tooltip="Origem: Mercado Livre · Pedido ' + escapeHtml(client.marketplaceOrderNumber || 'não informado') + '" aria-label="Cliente do Mercado Livre">🤝</span>';
    if (origin === 'Shopee') return '<span class="pw-client-origin-dot pw-origin-shopee pw-tooltip" data-tooltip="Origem: Shopee · Pedido ' + escapeHtml(client.marketplaceOrderNumber || 'não informado') + '" aria-label="Cliente da Shopee"><span class="pw-shopee-bag">S</span></span>';
    return '<span class="pw-client-origin-dot pw-origin-normal pw-tooltip" data-tooltip="Origem: Cliente normal" aria-label="Cliente normal">☺</span>';
  }

  function customerTypeIndicatorHtml(customerType) {
    const isReseller = customerType === 'revenda';
    const icon = isReseller
      ? '🏬'
      : '<svg viewBox="0 0 24 24" width="1em" height="1em" fill="currentColor" aria-hidden="true" focusable="false"><circle cx="12" cy="8" r="4"></circle><path d="M4 20.2C4 15.9 7.6 13 12 13s8 2.9 8 7.2V21H4v-.8z"></path></svg>';
    return '<span class="pw-client-info-dot pw-customer-type-' + (isReseller ? 'reseller' : 'direct') + ' pw-tooltip" data-tooltip="' + (isReseller ? 'Revenda' : 'Cliente direto') + '" aria-label="' + (isReseller ? 'Revenda' : 'Cliente direto') + '">' + icon + '</span>';
  }

  function orderRegistrationSourceIndicatorHtml(order) {
    if (!order) return '';
    const isClientSelf = order.registrationSource === 'client_dtf';
    const creator = order.createdBy || {};
    const creatorName = String(creator.name || creator.login || creator.summary || '').trim();
    if (isClientSelf) {
      const displayName = creatorName || (order.client && order.client.name ? String(order.client.name) : '');
      const tooltip = 'Cadastrado pelo próprio cliente' + (displayName ? ': ' + displayName : '');
      return '<span class="pw-status-dot pw-reg-source-dot pw-reg-source-client pw-tooltip" data-tooltip="' + escapeHtml(tooltip) + '" aria-label="Cadastrado pelo cliente">●</span>';
    }
    if (!order.registrationSource && !creator.id && !creatorName) return '';
    const role = String(creator.role || '').trim();
    const displayRole = role && role !== 'Cliente' ? role.toLowerCase() : 'colaborador';
    const tooltip = 'Cadastrado por ' + displayRole + (creatorName ? ': ' + creatorName : '');
    return '<span class="pw-status-dot pw-reg-source-dot pw-reg-source-system pw-tooltip" data-tooltip="' + escapeHtml(tooltip) + '" aria-label="' + escapeHtml('Cadastrado por ' + (creatorName || 'colaborador')) + '">●</span>';
  }

  function orderInfoLegendHtml() {
    return '<span><b class="pw-order-finalization-icon pw-order-finalization-icon-success">✓</b>Pedido finalizado</span>' +
      '<span><b class="pw-order-finalization-icon pw-order-finalization-icon-open">×</b>Pedido em aberto</span>' +
      '<span>' + clientOriginIndicatorHtml({ origin:'Normal' }) + 'Cliente normal</span>' +
      '<span>' + clientOriginIndicatorHtml({ origin:'Mercado Livre', marketplaceOrderNumber:'—' }) + 'Mercado Livre</span>' +
      '<span>' + clientOriginIndicatorHtml({ origin:'Shopee', marketplaceOrderNumber:'—' }) + 'Shopee</span>' +
      '<span>' + customerTypeIndicatorHtml('direto') + 'Cliente direto</span>' +
      '<span>' + customerTypeIndicatorHtml('revenda') + 'Revenda</span>' +
      '<span>' + orderRegistrationSourceIndicatorHtml({ registrationSource: 'system', createdBy: { role: 'colaborador', name: '' } }) + 'Cadastrado por colaborador/adm</span>' +
      '<span>' + orderRegistrationSourceIndicatorHtml({ registrationSource: 'client_dtf', createdBy: {} }) + 'Cadastrado pelo próprio cliente</span>';
  }

  function orderInfoIndicatorsHtml(order) {
    const client = getClients().find(record => String(record.id) === String(order && order.client && order.client.id)) || (order && order.client);
    return '<div class="pw-order-info-indicators">' + finalizationIndicatorHtml(order) + clientOriginIndicatorHtml(order && order.client) + customerTypeIndicatorHtml(client && client.customerType) + orderRegistrationSourceIndicatorHtml(order) + '</div>';
  }

  function orderFinancialValidation(order) {
    if (!order) return { valid: false, message: 'Salve o pedido antes de registrar e conferir os pagamentos.' };
    const total = adjustedOrderTotal(order);
    const payments = Array.isArray(order.payments) ? order.payments : [];
    if (!(total > 0)) return { valid: false, message: 'O pedido precisa possuir um valor total válido antes da finalização.' };
    if (orderUsesMonthlyClosing(order) && !payments.length) return { valid: true, paid: 0, total, monthlyClosing: true };
    if (!payments.length) return { valid: false, message: 'Nenhum pagamento foi registrado para este pedido.' };
    const invalid = payments.find(payment => !payment || !payment.method || !payment.date || !['Total', 'Parcial'].includes(payment.type) || !(Number(payment.value) > 0));
    if (invalid) return { valid: false, message: 'Existe um pagamento incompleto ou inválido. Confira forma, tipo, data e valor.' };
    const paid = payments.reduce((sum, payment) => sum + Number(payment.value || 0), 0);
    if (orderUsesMonthlyClosing(order) && paid <= total + 0.005) return { valid: true, paid, total, monthlyClosing: true };
    if (Math.abs(paid - total) > 0.005) return { valid: false, message: 'Os pagamentos somam ' + money.format(paid) + ', mas o total do pedido é ' + money.format(total) + '. Saldo pendente: ' + money.format(Math.max(0, total - paid)) + '.' };
    if (Math.abs(Number(order.paid || 0) - paid) > 0.005) return { valid: false, message: 'O total recebido não corresponde ao histórico financeiro. Revise os pagamentos.' };
    return { valid: true, paid, total };
  }

  function renderPaymentModal(order) {
    if (!order) return;
    const total = adjustedOrderTotal(order);
    const paid = Math.max(0, Number(order.paid || 0));
    const balance = Math.max(0, total - paid);
    $('#pw-payment-order-number').textContent = order.orderNumber + ' · ' + (order.client && order.client.name || 'Cliente não informado');
    $('#pw-payment-order-total').textContent = money.format(total);
    $('#pw-payment-order-paid').textContent = money.format(paid);
    $('#pw-payment-order-balance').textContent = money.format(balance);
    $('#pw-payment-order-status').textContent = paymentStatusFor(order, paid);
    $('#pw-payment-adjustment-discount').value = Number(order.discount || 0).toFixed(2).replace('.', ',');
    $('#pw-payment-adjustment-surcharge').value = Number(order.surcharge || 0).toFixed(2).replace('.', ',');
    const canAdjustPayment = userIsAdministrator(currentUser);
    ['#pw-payment-adjustment-discount', '#pw-payment-adjustment-surcharge'].forEach(selector => {
      const field = $(selector);
      field.disabled = !canAdjustPayment;
      field.title = canAdjustPayment ? 'Administrador: ajuste permitido' : 'Somente Administradores podem alterar este valor';
    });
    const payments = Array.isArray(order.payments) ? order.payments : [];
    const history = payments.map((payment, index) => ({ payment, index })).reverse();
    const historyTab = $('[data-payment-tab="history"]');
    const adjustmentsTab = $('[data-payment-tab="adjustments"]');
    const fullyPaid = history.length > 0 && balance <= 0.005;
    if (historyTab) {
      historyTab.disabled = history.length === 0;
      historyTab.setAttribute('aria-disabled', history.length === 0 ? 'true' : 'false');
      historyTab.title = history.length === 0 ? 'Nenhuma movimentação financeira registrada' : 'Consultar histórico financeiro';
    }
    if (adjustmentsTab) {
      adjustmentsTab.disabled = fullyPaid && paymentEditingIndex < 0;
      adjustmentsTab.setAttribute('aria-disabled', adjustmentsTab.disabled ? 'true' : 'false');
      adjustmentsTab.title = adjustmentsTab.disabled ? 'O pedido já está totalmente pago' : 'Registrar ou ajustar pagamento';
    }
    $('#pw-payment-history-body').innerHTML = history.length ? history.map(entry => {
      const payment = entry.payment;
      const amount = Number(payment.value || 0);
      const amountClass = amount < 0 || payment.type === 'Estorno' ? ' class="pw-payment-negative"' : '';
      const actions = userIsAdministrator(currentUser) ? '<div class="pw-inline-actions"><button class="pw-btn pw-btn-soft pw-btn-icon" type="button" data-edit-payment="' + entry.index + '" title="Editar pagamento" aria-label="Editar pagamento">✎</button><button class="pw-btn pw-btn-danger pw-btn-icon" type="button" data-delete-payment="' + entry.index + '" title="Apagar pagamento" aria-label="Apagar pagamento">×</button></div>' : '—';
      return '<tr><td>' + escapeHtml(payment.date ? payment.date.split('-').reverse().join('/') : '—') + '</td><td>' + escapeHtml(payment.type || 'Pagamento') + '</td><td>' + escapeHtml(payment.method || '—') + '</td><td' + amountClass + '>' + escapeHtml(money.format(amount)) + '</td><td>' + escapeHtml(payment.actor || '—') + '</td><td>' + escapeHtml(payment.note || '—') + '</td><td>' + actions + '</td></tr>';
    }).join('') : '<tr><td colspan="7" class="pw-empty">Nenhuma movimentação financeira registrada.</td></tr>';
  }

  function activatePaymentTab(name) {
    const requested = $('[data-payment-tab="' + name + '"]');
    if (requested && requested.disabled) name = 'adjustments';
    $$('[data-payment-tab]').forEach(button => {
      const active = button.dataset.paymentTab === name;
      button.classList.toggle('pw-active', active);
      button.classList.toggle('is-active', active);
      button.setAttribute('aria-selected', active ? 'true' : 'false');
    });
    $$('[data-payment-panel]').forEach(panel => panel.classList.toggle('pw-active', panel.dataset.paymentPanel === name));
  }

  function refreshPaymentDraftTotals(options) {
    const order = getOrders().find(record => record.orderNumber === paymentModalOrderNumber);
    if (!order) return;
    const canAdjustPayment = userIsAdministrator(currentUser);
    const discount = canAdjustPayment ? Math.max(0, parseMoney($('#pw-payment-adjustment-discount').value)) : Number(order.discount || 0);
    const surcharge = canAdjustPayment ? Math.max(0, parseMoney($('#pw-payment-adjustment-surcharge').value)) : Number(order.surcharge || 0);
    const draftOrder = Object.assign({}, order, { discount, surcharge });
    const total = adjustedOrderTotal(draftOrder);
    const paid = Math.max(0, Number(order.paid || 0));
    const balance = Math.max(0, total - paid);
    $('#pw-payment-order-total').textContent = money.format(total);
    $('#pw-payment-order-paid').textContent = money.format(paid);
    $('#pw-payment-order-balance').textContent = money.format(balance);
    $('#pw-payment-order-status').textContent = paymentStatusFor(draftOrder, paid);
    const type = $('#pw-payment-entry-type').value;
    if (type === 'Total') $('#pw-payment-entry-value').value = balance.toFixed(2).replace('.', ',');
    if (type === 'Parcial' && options && options.clearPartial) $('#pw-payment-entry-value').value = '';
  }

  function openPaymentModal(orderNumber) {
    const order = getOrders().find(record => record.orderNumber === orderNumber);
    if (!order) return showMessage('Salve o pedido antes de registrar pagamentos.', 'error');

    // Se o cliente é de fechamento mensal, alerta antes de abrir o modal de pagamento avulso
    if (orderUsesMonthlyClosing(order)) {
      const clientName = order.client && order.client.name ? order.client.name : 'este cliente';
      promptConfirm(
        'Atenção: ' + clientName + ' está cadastrado como fechamento mensal e pagará automaticamente no dia do vencimento. Deseja mesmo registrar um pagamento avulso agora?',
        'Sim, registrar pagamento',
        'Cancelar',
        () => openPaymentModalDirect(order), // prossegue se confirmado
        null                                  // cancela sem fazer nada
      );
      return;
    }

    openPaymentModalDirect(order);
  }

  // Abre o modal de pagamento diretamente, sem verificações extras.
  // Chamado por openPaymentModal após confirmação quando necessário.
  function openPaymentModalDirect(order) {
    const orderNumber = order.orderNumber;
    paymentModalOrderNumber = order.orderNumber;
    paymentEditingIndex = -1;
    $('#pw-payment-entry-save').textContent = 'Registrar pagamento';
    populatePaymentMethodSelects(order.paymentMethod || 'Pix', '');
    $('#pw-payment-entry-method').value = order.paymentMethod || 'Pix';
    const balance = Math.max(0, adjustedOrderTotal(order) - Number(order.paid || 0));
    $('#pw-payment-entry-type').value = 'Total';
    $('#pw-payment-entry-value').value = balance.toFixed(2).replace('.', ',');
    $('#pw-payment-entry-date').value = localDateValue(new Date());
    const noteField = $('#pw-payment-entry-note');
    if (noteField) noteField.value = '';
    renderPaymentModal(order);
    refreshPaymentDraftTotals();
    activatePaymentTab(balance <= 0.005 && Array.isArray(order.payments) && order.payments.length ? 'history' : 'adjustments');
    openModal('pw-payment-modal', true);
  }

  function ensureDefaultUnits() {
    if (getUnits().length) return;
    const names = [['Unidade', 'un.'], ['Metro', 'm'], ['Centímetro', 'cm'], ['Folha', 'fl.'], ['Kit', 'kit'], ['Pacote', 'pct.'], ['Par', 'par']];
    const units = names.map((entry, index) => ({ id: 'unit-default-' + (index + 1), code: String(index + 1).padStart(4, '0'), name: entry[0], symbol: entry[1], active: true }));
    writeStorage(STORAGE.units, units);
    writeStorage(STORAGE.unitSequence, units.length + 1);
  }

  function getOrders() {
    return readStorage(STORAGE.orders, []);
  }

  function migrateClientOriginToOrders() {
    const clients = getClients();
    const legacy = new Map(clients.filter(client => client && (client.origin === 'Mercado Livre' || client.origin === 'Shopee')).map(client => [String(client.id), client]));
    if (!legacy.size) return;
    const orders = getOrders();
    let changed = false;
    orders.forEach(order => {
      const clientId = order && order.client && order.client.id;
      const source = legacy.get(String(clientId));
      if (!source) return;
      if (!order.client) order.client = {};
      if (!order.client.origin || order.client.origin === 'Normal') {
        order.client.origin = source.origin;
        order.client.marketplaceOrderNumber = order.client.marketplaceOrderNumber || source.marketplaceOrderNumber || '';
        changed = true;
      }
    });
    if (changed) writeStorage(STORAGE.orders, orders, { immediate: true });
    const cleanedClients = clients.map(client => {
      const copy = { ...client };
      delete copy.origin;
      delete copy.marketplaceOrderNumber;
      return copy;
    });
    writeStorage(STORAGE.clients, cleanedClients, { immediate: true });
  }

  function migrateFinalizedOrdersToDelivered() {
    const orders = getOrders();
    let changed = false;
    orders.forEach(order => {
      if (order.status === 'Finalizado') {
        order.status = 'Entregue';
        order.timeline = Array.isArray(order.timeline) ? order.timeline : [];
        order.timeline.forEach(entry => {
          if (entry && entry.status === 'Finalizado') entry.status = 'Entregue';
          if (entry && entry.previous === 'Finalizado') entry.previous = 'Entregue';
        });
        changed = true;
      }
      if (syncOrderFinalization(order)) changed = true;
    });
    if (changed) writeStorage(STORAGE.orders, orders, { immediate: true });
  }

  function getDtfCosts() { return readStorage(STORAGE.dtfCosts, []); }

  async function linkMecolourExpensesToSupplier() {
    if (!userIsAdministrator(currentUser)) return;
    if (readStorage(STORAGE.mecolourExpensesLinked, false)) return;
    let suppliers = getSuppliers();
    let supplier = suppliers.find(record => [record.name, ...(record.aliases || [])].some(name => normalize(name) === 'mecolour'));
    if (!supplier) {
      supplier = {
        id: 'supplier-mecolour',
        code: nextRegistryCode('supplier'),
        name: 'Mecolour',
        active: true,
        position: nextRecordPosition(suppliers),
        aliases: [],
        contact: '',
        phone: '',
        email: '',
        document: '',
        notes: ''
      };
      suppliers = [...suppliers, supplier];
      if (!await saveExpenseCollection(STORAGE.suppliers, suppliers)) return;
    }
    const costs = getDtfCosts();
    let changed = false;
    const linked = costs.map(entry => {
      const matchesMecolour = normalize(entry && entry.supplier) === 'mecolour';
      if (!matchesMecolour || entry.supplierId === supplier.id) return entry;
      changed = true;
      return { ...entry, supplierId:supplier.id, supplier:supplier.name };
    });
    if (!changed) return;
    if (changed && !await saveExpenseCollection(STORAGE.dtfCosts, linked)) return;
    await persistStorage(STORAGE.mecolourExpensesLinked, true);
  }

  function orderedRecords(records) {
    return (records || []).map((record, index) => ({ record, index })).sort((a, b) => {
      const aPosition = Number.isFinite(Number(a.record.position)) ? Number(a.record.position) : a.index;
      const bPosition = Number.isFinite(Number(b.record.position)) ? Number(b.record.position) : b.index;
      return aPosition - bPosition || a.index - b.index;
    }).map(entry => entry.record);
  }

  function nextRecordPosition(records) {
    return (records || []).reduce((highest, record, index) => Math.max(highest, Number.isFinite(Number(record.position)) ? Number(record.position) : index), -1) + 1;
  }

  const DEFAULT_DTF_CATALOG = [
    ['TVR', 'Tinta', 'Verniz', 'ml'], ['TBR', 'Tinta', 'Branca', 'ml'], ['TPR', 'Tinta', 'Preta', 'ml'],
    ['TAM', 'Tinta', 'Amarela', 'ml'], ['TCY', 'Tinta', 'Cyan', 'ml'], ['TMG', 'Tinta', 'Magenta', 'ml'],
    ['FLA', 'Filme', 'Filme A', 'metro'], ['FLB', 'Filme', 'Filme B', 'metro'],
    ['MNP', 'Manutenção', 'Limpeza preventiva', 'serviço'], ['MNC', 'Manutenção', 'Limpeza corretiva', 'serviço'], ['VTC', 'Manutenção', 'Visita técnica', 'serviço'],
    ['CAB', 'Peça', 'Cabeça de impressão', 'unidade'], ['BOM', 'Peça', 'Bomba', 'unidade'], ['DAM', 'Peça', 'Damper', 'unidade'],
    ['FIL', 'Peça', 'Filtro', 'unidade'], ['LUV', 'Peça', 'Lâmpada UV', 'unidade'], ['PLA', 'Peça', 'Placa', 'unidade'], ['MAN', 'Peça', 'Mangueira', 'unidade']
  ].map((item, index) => ({ id: 'dtf-item-' + (index + 1), code: item[0], category: item[1], name: item[2], unit: item[3], position: index }));

  function getDtfCatalog() {
    const saved = readStorage(STORAGE.dtfCatalog, null);
    return (Array.isArray(saved) ? saved : DEFAULT_DTF_CATALOG).map(item => ({ ...item })).sort((a, b) => Number(a.position || 0) - Number(b.position || 0));
  }

  function ensureDefaultDtfCatalog() {
    if (!userIsAdministrator(currentUser)) return;
    if (!Array.isArray(readStorage(STORAGE.dtfCatalog, null))) writeStorage(STORAGE.dtfCatalog, DEFAULT_DTF_CATALOG.map(item => ({ ...item })));
  }

  function dtfCostItemCode(entry) {
    const current = getDtfCatalog().find(item => item.id === entry.itemId || (dtfCategoryName(item.category) === dtfCategoryName(entry.category) && [item.name, ...(item.aliases || [])].some(name => normalize(name) === normalize(entry.item))));
    return current && current.code || entry.itemCode || '';
  }

  function expenseDisplayRecord(entry) {
    const item = getDtfCatalog().find(record => record.id === entry.itemId || (dtfCategoryName(record.category) === dtfCategoryName(entry.category) && [record.name, ...(record.aliases || [])].some(name => normalize(name) === normalize(entry.item))));
    const supplier = getSuppliers().find(record => record.id === entry.supplierId || [record.name, ...(record.aliases || [])].some(name => normalize(name) === normalize(entry.supplier)));
    return { ...entry, category:dtfCategoryName(entry.category), item:item ? item.name : entry.item, action:dtfMovementName(entry.action), unit:dtfUnitValue(entry.unit), supplier:supplier ? supplier.name : entry.supplier };
  }

  function syncDtfCostItemOptions() {
    const categorySelect = $('#pw-dtf-cost-category');
    const previousCategory = dtfCategoryName(categorySelect.value || '');
    const categories = getDtfExpenseCategories().filter(category => dtfCostFormMode === 'ads' || normalize(category) !== normalize('Anúncio'));
    if (editingDtfCostId && previousCategory && !categories.includes(previousCategory)) categories.push(previousCategory);
    categorySelect.innerHTML = categories.map(category => '<option value="' + escapeHtml(category) + '">' + escapeHtml(category) + '</option>').join('');
    categorySelect.value = categories.includes(previousCategory) ? previousCategory : (categories[0] || '');
    const category = categorySelect.value;
    const previousItem = $('#pw-dtf-cost-item').value;
    const previousUnit = $('#pw-dtf-cost-unit').value;
    const options = getDtfCatalog().filter(item => (item.active !== false || (editingDtfCostId && item.id === previousItem)) && dtfCategoryName(item.category) === category);
    $('#pw-dtf-cost-item').innerHTML = options.map(item => '<option value="' + escapeHtml(item.id) + '" data-unit="' + escapeHtml(item.unit) + '">' + escapeHtml(item.code + ' — ' + item.name) + '</option>').join('') + '<option value="__custom__">Outro insumo, peça ou serviço — descrever</option>';
    const retainedItem = options.find(item => item.id === previousItem);
    if (retainedItem || previousItem === '__custom__') $('#pw-dtf-cost-item').value = previousItem;
    const selected = getDtfCatalog().find(item => item.id === $('#pw-dtf-cost-item').value);
    $('#pw-dtf-custom-item-wrap').hidden = Boolean(selected);
    populateDtfUnitSelect($('#pw-dtf-cost-unit'), retainedItem ? previousUnit : (selected && selected.unit || (category === dtfCategoryName('Manutenção') ? 'serviço' : 'unidade')));
    $('#pw-dtf-cost-quantity-label').textContent = category === dtfCategoryName('Filme') ? 'Metragem inserida na máquina' : (category === dtfCategoryName('Tinta') ? 'Quantidade abastecida' : (category === dtfCategoryName('Anúncio') ? 'Quantidade de anúncios/campanhas' : 'Quantidade'));
  }

  async function ensureAnnouncementCategory() {
    const existing = getDtfExpenseCategoryRecords().find(record => normalize(record.name) === normalize('Anúncio'));
    if (existing) return existing.name;
    const created = await saveDtfExpenseCategory({ id:'dtf-category-' + Date.now(), code:nextRegistryCode('dtfCategory'), name:'Anúncio', active:true });
    return created ? 'Anúncio' : '';
  }

  function setDtfCostFormTab(mode) {
    dtfCostFormMode = mode === 'ads' ? 'ads' : 'materials';
    const form = $('#pw-dtf-cost-form');
    if (form) form.dataset.expenseMode = dtfCostFormMode;
    $$('.pw-expense-tab', form || root).forEach(button => {
      const active = button.dataset.expenseTab === dtfCostFormMode;
      button.classList.toggle('is-active', active);
      button.setAttribute('aria-selected', active ? 'true' : 'false');
    });
    const fields = {
      category: $('#pw-dtf-cost-category'), item: $('#pw-dtf-cost-item'), customItem: $('#pw-dtf-custom-item-wrap'), action: $('#pw-dtf-cost-action'), quantity: $('#pw-dtf-cost-quantity'), unit: $('#pw-dtf-cost-unit')
    };
    ['category','item','action','quantity','unit'].forEach(key => { const field = fields[key]; if (field) field.closest('.pw-field').hidden = dtfCostFormMode === 'ads'; });
    if (fields.customItem) fields.customItem.hidden = true;
    if (dtfCostFormMode === 'ads') {
      if (fields.category) fields.category.value = 'Anúncio';
      ensureAnnouncementCategory().then(name => { if (name && fields.category) fields.category.value = name; });
    } else {
      fields.customItem.hidden = true;
      syncDtfCostItemOptions();
    }
    syncDtfSupplierOptions($('#pw-dtf-cost-supplier') ? $('#pw-dtf-cost-supplier').value : '');
  }

  function setDtfListTab(tab) {
    dtfListTab = tab === 'ads' ? 'ads' : 'materials';
    const section = $('[data-view="dtf-list"]');
    if (section) section.dataset.listTab = dtfListTab;
    $$('.pw-expense-tab[data-list-tab]').forEach(button => {
      const active = button.dataset.listTab === dtfListTab;
      button.classList.toggle('is-active', active);
      button.setAttribute('aria-selected', active ? 'true' : 'false');
    });
    ['pw-dtf-list-category','pw-dtf-list-action','pw-dtf-list-item','pw-dtf-list-supplier'].forEach(id => { const el = $('#' + id); if (el) el.value = ''; });
    renderDtfExpenseReport('cost');
  }

  function getDtfExpenseCategoryRecords() {
    const defaults = ['Tinta', 'Filme', 'Manutenção', 'Peça', 'Anúncio', 'Outro'];
    const saved = readStorage(STORAGE.dtfExpenseCategories, null);
    // Aceita as listas antigas de nomes, mantendo os registros e seus códigos.
    const source = Array.isArray(saved) ? saved : defaults;
    return source.map((value, index) => {
      const record = typeof value === 'string' ? { name: value } : value;
      if (!record || !String(record.name || '').trim()) return null;
      return { ...record, id: String(record.id || 'dtf-category-' + index), code: String(record.code || String(index + 1).padStart(4, '0')),
        name: String(record.name).trim(), active: record.active !== false, position: record.position == null ? index : record.position,
        aliases: Array.isArray(record.aliases) ? record.aliases : [] };
    }).filter(Boolean);
  }
  function getDtfExpenseCategories() {
    return getDtfExpenseCategoryRecords().filter(record => record.active !== false).map(record => record.name);
  }
  function dtfCategoryMatches(record, name) {
    return [record.name, ...record.aliases].some(value => normalize(value) === normalize(name));
  }
  function dtfCategoryName(name) {
    const record = getDtfExpenseCategoryRecords().find(category => dtfCategoryMatches(category, name));
    return record ? record.name : name;
  }
  async function saveDtfExpenseCategory(record) {
    if (!userIsAdministrator(currentUser)) return showMessage('Apenas administradores podem alterar categorias de despesas.', 'error');
    const records = getDtfExpenseCategoryRecords();
    if (records.some(item => item.id !== record.id && (normalize(item.code) === normalize(record.code) || dtfCategoryMatches(item, record.name)))) {
      showMessage('Já existe uma categoria com esse nome ou código.', 'error'); return false;
    }
    const existing = records.find(item => item.id === record.id);
    const updated = { ...existing, ...record, aliases: existing ? existing.aliases.slice() : [], position: existing ? existing.position : nextRecordPosition(records) };
    if (existing && existing.name !== record.name) updated.aliases = [...new Set([...updated.aliases, existing.name])];
    const next = existing ? records.map(item => item.id === updated.id ? updated : item) : [...records, updated];
    // Só troca a lista compartilhada na tela depois da confirmação do servidor.
    const saved = await persistStorage(STORAGE.dtfExpenseCategories, next);
    if (!saved) return false;
    SERVER_STORAGE[STORAGE.dtfExpenseCategories] = next;
    recordAudit('dtfCategory', updated.id, existing ? 'Categoria de despesa alterada' : 'Categoria de despesa cadastrada', updated.name);
    refreshExpenseViews(); renderDtfCategories();
    return true;
  }
  function renderDtfCategories() {
    const body = $('#pw-dtf-category-body');
    if (body) body.innerHTML = getDtfExpenseCategories().map(category => '<tr><td>' + escapeHtml(category) + '</td></tr>').join('');
  }
  function getDtfExpenseUnits() {
    // Despesas e estoque consultam o mesmo cadastro de unidades de venda.
    return getUnits().map(record => ({ ...record, aliases:Array.isArray(record.aliases) ? record.aliases : [] }));
  }

  async function migrateExpenseUnitsToSharedRegistry() {
    if (!userIsAdministrator(currentUser) || readStorage(STORAGE.expenseUnitsMigrated, false)) return;
    const legacy = readStorage(STORAGE.dtfExpenseUnits, []);
    const sources = [
      ...(Array.isArray(legacy) ? legacy : []).map(entry => typeof entry === 'string' ? { name:entry, symbol:entry } : entry),
      ...[...getDtfCatalog(), ...getDtfCosts()].filter(record => record.unit).map(record => ({ name:record.unit, symbol:record.unit }))
    ];
    const units = getDtfExpenseUnits().map(record => ({ ...record, aliases:record.aliases.slice() }));
    let code = Math.max(0, ...units.map(record => Number(record.code) || 0), ...getTrash().filter(entry => entry.kind === 'unit').map(entry => Number(entry.record && entry.record.code) || 0));
    let changed = false;
    sources.forEach(source => {
      if (!source || !source.name) return;
      const match = units.find(record => dtfUnitMatches(record, source.symbol || source.name) || dtfUnitMatches(record, source.name));
      if (match) {
        const aliases = [...new Set([...match.aliases, source.name, source.symbol, ...(source.aliases || [])].filter(Boolean))];
        if (JSON.stringify(aliases) !== JSON.stringify(match.aliases)) { match.aliases = aliases; changed = true; }
      } else {
        code += 1;
        units.push({ ...source, id:'unit-expense-migrated-' + code, code:String(code).padStart(4, '0'), symbol:source.symbol || source.name,
          active:source.active !== false, aliases:Array.isArray(source.aliases) ? source.aliases : [], position:nextRecordPosition(units) });
        changed = true;
      }
    });
    if (changed && !await saveExpenseCollection(STORAGE.units, units)) throw new Error('Não foi possível preservar as unidades de despesas no cadastro compartilhado. Tente novamente.');
    if (!await saveExpenseCollection(STORAGE.expenseUnitsMigrated, true)) throw new Error('Não foi possível concluir a integração das unidades.');
    writeStorage(STORAGE.unitSequence, Math.max(Number(readStorage(STORAGE.unitSequence, 1)), code + 1));
  }

  function dtfUnitMatches(record, value) {
    return [record.name, record.symbol, ...record.aliases].some(name => normalize(name) === normalize(value));
  }

  function dtfUnitValue(value) {
    const record = getDtfExpenseUnits().find(unit => dtfUnitMatches(unit, value));
    return record ? record.symbol : value;
  }

  function populateDtfUnitSelect(select, selected = '', includeInactive = false) {
    const units = getDtfExpenseUnits().filter(unit => includeInactive || unit.active !== false || dtfUnitMatches(unit, selected));
    const value = dtfUnitValue(selected);
    const options = units.map(unit => ({ value: unit.symbol, text: unit.name === unit.symbol ? unit.name : unit.name + ' (' + unit.symbol + ')' }));
    if (value && !options.some(option => option.value === value)) options.push({ value, text: value });
    select.innerHTML = '<option value="">Selecione</option>' + options.map(option => '<option value="' + escapeHtml(option.value) + '">' + escapeHtml(option.text) + '</option>').join('');
    select.value = value || '';
  }

  function getDtfExpenseMovements() {
    const saved = readStorage(STORAGE.dtfExpenseMovements, null);
    const defaults = [...new Set(['Abastecimento', 'Troca', 'Compra', 'Manutenção', 'Reparo', ...getDtfCosts().map(entry => entry.action)].filter(Boolean))];
    return orderedRecords((Array.isArray(saved) ? saved : defaults).map((entry, index) => {
      const record = typeof entry === 'string' ? { name:entry } : entry;
      return { ...record, id:String(record.id || 'dtf-movement-' + index), code:String(record.code || String(index + 1).padStart(4, '0')),
        active:record.active !== false, aliases:Array.isArray(record.aliases) ? record.aliases : [], position:record.position == null ? index : record.position };
    }));
  }

  function dtfMovementMatches(record, value) {
    return [record.name, ...record.aliases].some(name => normalize(name) === normalize(value));
  }

  function dtfMovementName(value) {
    const record = getDtfExpenseMovements().find(item => dtfMovementMatches(item, value));
    return record ? record.name : value;
  }

  function syncDtfMovementOptions(selected = $('#pw-dtf-cost-action').value) {
    const value = dtfMovementName(selected);
    const options = getDtfExpenseMovements().filter(record => record.active !== false || (editingDtfCostId && dtfMovementMatches(record, selected))).map(record => record.name);
    if (editingDtfCostId && value && !options.includes(value)) options.push(value);
    $('#pw-dtf-cost-action').innerHTML = '<option value="">Selecione</option>' + options.map(name => '<option value="' + escapeHtml(name) + '">' + escapeHtml(name) + '</option>').join('');
    $('#pw-dtf-cost-action').value = options.includes(value) ? value : '';
  }

  function dtfExpenseRecordTimestamp(entry) {
    // Atualizações e novos lançamentos têm timestamp; os registros antigos
    // ainda podem ter apenas a data da movimentação.
    const values = [entry && entry.updatedAt, entry && entry.createdAt, entry && entry.registeredAt, entry && entry.savedAt, entry && entry.date];
    for (const value of values) {
      const time = Date.parse(String(value || ''));
      if (Number.isFinite(time)) return time;
    }
    return 0;
  }

  function latestDtfCostForSelection(category, itemId, itemName, itemCode) {
    const selectedCategory = normalize(dtfCategoryName(category));
    const selectedItem = getDtfCatalog().find(item => String(item.id) === String(itemId || ''));
    const selectedNames = [itemName, selectedItem && selectedItem.name, ...(selectedItem && selectedItem.aliases || [])]
      .map(value => normalize(value)).filter(Boolean);
    const selectedCodes = [itemCode, selectedItem && selectedItem.code].map(value => normalize(value)).filter(Boolean);
    return getDtfCosts()
      .filter(entry => String(entry && entry.id || '') !== String(editingDtfCostId || ''))
      .filter(entry => normalize(dtfCategoryName(entry && entry.category)) === selectedCategory)
      .filter(entry => {
        if (selectedItem && entry && entry.itemId && String(entry.itemId) === String(selectedItem.id)) return true;
        const entryNames = [entry && entry.item, entry && entry.itemName, entry && entry.description].map(value => normalize(value)).filter(Boolean);
        const entryCodes = [entry && entry.itemCode, entry && entry.code].map(value => normalize(value)).filter(Boolean);
        return entryNames.some(value => selectedNames.includes(value)) || entryCodes.some(value => selectedCodes.includes(value));
      })
      .sort((a, b) => dtfExpenseRecordTimestamp(b) - dtfExpenseRecordTimestamp(a) || String(b && b.id || '').localeCompare(String(a && a.id || '')))[0] || null;
  }

  function fillDtfCostFromLatest() {
    if (dtfCostFormMode === 'ads') return showMessage('A Lembrança inteligente está disponível na aba Materiais.', 'info');
    const categoryField = $('#pw-dtf-cost-category');
    const itemField = $('#pw-dtf-cost-item');
    if (!categoryField || !itemField || !categoryField.value || !itemField.value) return showMessage('Selecione a Categoria e o Insumo, peça ou serviço antes de usar a Lembrança inteligente.', 'info');
    const catalogItem = getDtfCatalog().find(record => String(record.id) === String(itemField.value));
    const itemName = catalogItem ? catalogItem.name : $('#pw-dtf-custom-item').value.trim();
    const itemCode = catalogItem ? catalogItem.code : '';
    const latest = latestDtfCostForSelection(categoryField.value, itemField.value, itemName, itemCode);
    if (!latest) return showMessage('Nenhum lançamento anterior encontrado para esta categoria e insumo.', 'info');

    const setField = (id, value, type = 'input') => {
      const field = $('#' + id);
      if (!field || value == null) return;
      field.value = String(value);
      field.dispatchEvent(new Event(type, { bubbles: true }));
    };
    setField('pw-dtf-cost-date', latest.date || '');
    syncDtfMovementOptions(latest.action || '');
    populateDtfUnitSelect($('#pw-dtf-cost-unit'), latest.unit || '');
    setField('pw-dtf-cost-quantity', latest.quantity == null ? '' : latest.quantity);
    setField('pw-dtf-cost-value', Number(latest.value || 0).toFixed(2).replace('.', ','));
    const supplierRecord = getSuppliers().find(record => String(record.id) === String(latest.supplierId || '') || normalize(record.name) === normalize(latest.supplier));
    syncDtfSupplierOptions(supplierRecord ? supplierRecord.name : (latest.supplier || ''));
    setField('pw-dtf-cost-notes', latest.notes || '');
    if (itemField.value === '__custom__') setField('pw-dtf-custom-item', latest.item || '');
    showMessage('Lembrança inteligente aplicada com o lançamento mais recente de ' + (latest.date ? dateLabel(latest.date) : 'data não informada') + '.', 'success');
  }

  function expenseReportModel(type) {
    const configs = {
      category: { kind:'dtfCategory', view:'dtf-category-report', body:'pw-dtf-category-report-body', search:'pw-dtf-category-report-search', title:'Categorias de despesas', records:getDtfExpenseCategoryRecords,
        headers:['Código','Categoria','Situação'], cells:r => [r.code, r.name, r.active === false ? 'Inativo' : 'Ativo'] },
      movement: { kind:'dtfMovement', view:'dtf-movement-report', body:'pw-dtf-movement-report-body', search:'pw-dtf-movement-report-search', title:'Movimentações de despesas', records:getDtfExpenseMovements,
        headers:['Código','Movimentação','Situação'], cells:r => [r.code, r.name, r.active === false ? 'Inativo' : 'Ativo'] },
      unit: { kind:'unit', view:'units', body:'pw-units-consult-body', search:'pw-units-consult-search', title:'Unidades de venda', records:getUnits,
        headers:['Código','Unidade','Sigla','Situação'], cells:r => [r.code, r.name, r.symbol, r.active === false ? 'Inativo' : 'Ativo'] },
      item: { kind:'dtfItem', view:'dtf-items', body:'pw-dtf-catalog-body', search:'pw-dtf-catalog-search', title:'Itens de despesas', records:getDtfCatalog,
        headers:['Código','Categoria','Item','Unidade sugerida','Situação'], cells:r => [r.code, dtfCategoryName(r.category), r.name, dtfUnitValue(r.unit), r.active === false ? 'Inativo' : 'Ativo'] },
      supplier: { kind:'supplier', view:'suppliers', body:'pw-suppliers-consult-body', search:'pw-suppliers-consult-search', title:'Fornecedores', records:getSuppliers,
        headers:['Código','Fornecedor','Tipo','Contato','Telefone','E-mail','CPF / CNPJ','Situação'], cells:r => [r.code,r.name,r.supplierType === 'materials' ? 'Materiais' : r.supplierType === 'ads' ? 'Anúncios' : r.supplierType === 'both' ? 'Materiais e Anúncios' : '—',r.contact || '—',r.phone || '—',r.email || '—',r.document || '—',r.active === false ? 'Inativo' : 'Ativo'] },
      orderOrigin: { kind:'orderOrigin', view:'order-origins', body:'pw-order-origins-consult-body', search:'pw-order-origins-consult-search', title:'Origens do pedido', records:getOrderOrigins,
        headers:['Código','Origem do pedido','Marketplace','Situação'], cells:r => [r.code, r.name, r.marketplace ? 'Sim' : 'Não', r.active === false ? 'Inativo' : 'Ativo'] },
      cost: { kind:'dtfCost', view:'dtf-list', body:'pw-dtf-cost-recent', search:'pw-dtf-list-search', title:'Listagem de despesas',
        records:() => getDtfCosts().map(expenseDisplayRecord).filter(r => dtfListTab === 'ads' ? normalize(dtfCategoryName(r.category)) === normalize('Anúncio') : normalize(dtfCategoryName(r.category)) !== normalize('Anúncio')),
        headers: dtfListTab === 'ads' ? ['Data','Valor','Fornecedor','Observações','Responsável'] : ['Data','Categoria','Item','Movimentação','Quantidade','Unidade','Valor','Fornecedor','Observações','Responsável'],
        cells: dtfListTab === 'ads'
          ? r => [dateLabel(r.date), money.format(Number(r.value || 0)), r.supplier || '—', r.notes || '—', r.updatedBy || r.actor || '—']
          : r => [dateLabel(r.date), dtfCategoryName(r.category), (dtfCostItemCode(r) ? dtfCostItemCode(r) + ' — ' : '') + r.item, dtfMovementName(r.action), Number(r.quantity).toLocaleString('pt-BR'), r.unit, money.format(Number(r.value || 0)), r.supplier || '—', r.notes || '—', r.updatedBy || r.actor || '—'] }
    };
    const model = configs[type];
    const all = model.records().slice();
    if (type === 'cost') all.sort((a,b) => String(b.date).localeCompare(String(a.date)) || String(b.createdAt).localeCompare(String(a.createdAt)));
    else all.sort((a,b) => Number(a.position || 0) - Number(b.position || 0));
    if (type === 'cost') syncDtfCostListFilters(all);
    const query = normalize($('#' + model.search).value);
    const start = type === 'cost' ? $('#pw-dtf-list-start').value : '';
    const end = type === 'cost' ? $('#pw-dtf-list-end').value : '';
    const category = type === 'cost' && $('#pw-dtf-list-category') ? $('#pw-dtf-list-category').value : '';
    const action = type === 'cost' && $('#pw-dtf-list-action') ? $('#pw-dtf-list-action').value : '';
    const item = type === 'cost' && $('#pw-dtf-list-item') ? $('#pw-dtf-list-item').value : '';
    const supplier = type === 'cost' && $('#pw-dtf-list-supplier') ? $('#pw-dtf-list-supplier').value : '';
    const rows = all.filter(record => (!query || normalize(model.cells(record).join(' ')).includes(query)) && (!start || record.date >= start) && (!end || record.date <= end) && (!category || dtfCategoryName(record.category) === category) && (!action || dtfMovementName(record.action) === action) && (!item || normalize(record.item) === normalize(item)) && (!supplier || normalize(record.supplier) === normalize(supplier)));
    return { ...model, all, rows, query, start, end };
  }

  function syncDtfCostListFilters(records) {
    const definitions = [
      ...(dtfListTab !== 'ads' ? [
        ['pw-dtf-list-category', records.map(record => dtfCategoryName(record.category)), 'Todas'],
        ['pw-dtf-list-action', records.map(record => dtfMovementName(record.action)), 'Todas'],
        ['pw-dtf-list-item', records.map(record => record.item), 'Todos']
      ] : []),
      ['pw-dtf-list-supplier', records.map(record => record.supplier), 'Todos']
    ];
    definitions.forEach(([id, values, emptyLabel]) => {
      const select = $('#' + id);
      if (!select) return;
      const current = select.value;
      const options = [...new Set(values.map(value => String(value || '').trim()).filter(Boolean))].sort((a,b) => a.localeCompare(b, 'pt-BR'));
      select.innerHTML = '<option value="">' + emptyLabel + '</option>' + options.map(value => '<option value="' + escapeHtml(value) + '">' + escapeHtml(value) + '</option>').join('');
      if (options.includes(current)) select.value = current;
    });
  }

  function renderDtfExpenseReport(type) {
    const model = expenseReportModel(type);
    const { kind, view, rows, all } = model;
    filteredRecordIds[kind] = rows.map(record => String(record.id));
    paginationState[view] = Math.max(1, Math.min(paginationState[view] || 1, Math.ceil(rows.length / PAGE_SIZE) || 1));
    const pageRows = rows.slice((paginationState[view] - 1) * PAGE_SIZE, paginationState[view] * PAGE_SIZE);
    const body = $('#' + model.body);
    body.innerHTML = pageRows.length ? pageRows.map(record => '<tr draggable="' + (type !== 'cost' && userIsAdministrator(currentUser) ? 'true' : 'false') + '" data-record-kind="' + kind + '" data-record-id="' + escapeHtml(record.id) + '">' + selectionCell(kind, record.id) +
      model.cells(record).map(value => '<td>' + escapeHtml(String(value == null ? '—' : value)) + '</td>').join('') + '</tr>').join('') :
      '<tr><td colspan="' + (model.headers.length + 1) + '" class="pw-empty-table">Nenhum registro encontrado.</td></tr>';
    pruneBulkSelection(kind, rows.map(record => record.id));
    reportFooter(body, pageRows, rows, all, type === 'cost' ? { [dtfListTab === 'ads' ? 2 : 7]:{ label:'Total filtrado', value:rows.reduce((sum,record) => sum + Number(record.value || 0), 0) } } : null);
    renderPagination(view, rows.length);
  }

  const expenseWrites = new Set();
  async function saveExpenseCollection(key, records) {
    if (!userIsAdministrator(currentUser)) { showMessage('Apenas administradores podem alterar despesas.', 'error'); return false; }
    if (expenseWrites.has(key)) { showMessage('Aguarde a gravação em andamento.', 'info'); return false; }
    expenseWrites.add(key);
    try {
      // Evita que uma gravação adiada antiga substitua os dados recém-confirmados.
      window.clearTimeout(serverSaveTimers[key]); delete serverSaveTimers[key];
      if (!await persistStorage(key, records)) return false;
      SERVER_STORAGE[key] = records;
      return true;
    } finally { expenseWrites.delete(key); }
  }

  /**
   * Pergunta uma vez (resumindo todos os lugares afetados) e propaga um
   * nome/campo alterado num cadastro pra todos os registros que guardam
   * uma cópia dele — nunca mexe em nada sem confirmar antes.
   */
  async function confirmAndPropagateRename(oldLabel, newLabel, groups) {
    const affected = groups.filter(group => group.items.length > 0);
    if (!affected.length) return;
    const summary = affected.map(group => group.items.length + ' em ' + group.label).join(', ');
    if (!window.confirm('O nome mudou de "' + oldLabel + '" para "' + newLabel + '".\n\n' + summary + ' usam esse nome e seriam atualizados também.\n\nAtualizar agora?')) return;
    for (const group of affected) {
      const updatedList = group.apply();
      await writeStorage(group.storageKey, updatedList, { immediate: true });
    }
    refreshAllViews();
    showMessage('Atualizado: ' + summary + '.', 'success');
  }

  async function saveExpenseMaster(kind, record) {
    const config = registryConfig(kind);
    const records = config.records();
    const existing = records.find(item => item.id === record.id);
    const duplicate = records.some(item => item.id !== record.id && (
      normalize(item.code) === normalize(record.code) ||
      (kind === 'dtfMovement' && dtfMovementMatches(item, record.name))
    ));
    if (duplicate) { showMessage('Já existe um cadastro com esse código, nome ou sigla.', 'error'); return false; }
    const aliases = existing && Array.isArray(existing.aliases) ? existing.aliases.slice() : [];
    if (existing && kind === 'dtfMovement') aliases.push(existing.name);
    if (existing && kind === 'dtfItem') aliases.push(existing.name);
    const updated = { ...existing, ...record, aliases:[...new Set(aliases.filter(Boolean))], position:existing ? existing.position : nextRecordPosition(records), updatedAt:new Date().toISOString(), updatedBy:currentActor() };
    const next = existing ? records.map(item => item.id === record.id ? updated : item) : [...records, updated];
    if (!await saveExpenseCollection(config.storage, next)) return false;
    recordAudit(kind, record.id, existing ? 'Cadastro de despesa alterado' : 'Cadastro de despesa criado', record.name);
    refreshExpenseViews();
    if (existing && normalize(existing.name) !== normalize(updated.name)) {
      const dtfCosts = getDtfCosts();
      if (kind === 'dtfCategory') {
        const affected = dtfCosts.filter(expense => normalize(expense.category || '') === normalize(existing.name));
        await confirmAndPropagateRename(existing.name, updated.name, [{ label: 'Despesas', items: affected, storageKey: STORAGE.dtfCosts, apply: () => getDtfCosts().map(expense => affected.includes(expense) ? { ...expense, category: updated.name } : expense) }]);
      } else if (kind === 'dtfMovement') {
        const affected = dtfCosts.filter(expense => normalize(expense.action || '') === normalize(existing.name));
        await confirmAndPropagateRename(existing.name, updated.name, [{ label: 'Despesas', items: affected, storageKey: STORAGE.dtfCosts, apply: () => getDtfCosts().map(expense => affected.includes(expense) ? { ...expense, action: updated.name } : expense) }]);
      } else if (kind === 'dtfItem') {
        const affected = dtfCosts.filter(expense => (expense.itemId && expense.itemId === updated.id) || (!expense.itemId && normalize(expense.item || '') === normalize(existing.name)));
        await confirmAndPropagateRename(existing.name, updated.name, [{ label: 'Despesas', items: affected, storageKey: STORAGE.dtfCosts, apply: () => getDtfCosts().map(expense => affected.includes(expense) ? { ...expense, item: updated.name, itemCode: updated.code || expense.itemCode, itemId: updated.id } : expense) }]);
      }
    }
    return updated;
  }

  function refreshExpenseViews() {
    syncDtfCostItemOptions();
    syncDtfMovementOptions();
    ['category','unit','movement','item','cost'].forEach(renderDtfExpenseReport);
    renderDtfCostReport();
  }

  function syncDtfSupplierOptions(selected = '') {
    const records = getSuppliers();
    const known = records.find(record => [record.name, ...(record.aliases || [])].some(name => normalize(name) === normalize(selected)));
    const value = known ? known.name : selected;
    const names = records.filter(record => (record.active !== false || record === known) && (!record.supplierType || record.supplierType === dtfCostFormMode)).map(record => record.name);
    if (value && !names.includes(value)) names.push(value);
    $('#pw-dtf-cost-supplier').innerHTML = '<option value="">Não informado</option>' + names.map(name => '<option value="' + escapeHtml(name) + '">' + escapeHtml(name) + '</option>').join('');
    $('#pw-dtf-cost-supplier').value = value;
    $('#pw-dtf-custom-supplier').value = '';
    $('#pw-dtf-custom-supplier-wrap').hidden = true;
  }

  function selectNewExpenseRegistry(kind, record) {
    if (!quickExpenseRegistry || quickExpenseRegistry.kind !== kind) return;
    const target = quickExpenseRegistry.target;
    quickExpenseRegistry = null;
    if (target === 'category' || target === 'item') {
      const name = target === 'category' ? record.name : dtfCategoryName(record.category);
      const select = $('#pw-dtf-cost-category');
      if (!Array.from(select.options).some(option => option.value === name)) select.add(new Option(name, name));
      select.value = name;
      syncDtfCostItemOptions();
      if (target === 'item') {
        $('#pw-dtf-cost-item').value = record.id;
        $('#pw-dtf-custom-item-wrap').hidden = true;
        populateDtfUnitSelect($('#pw-dtf-cost-unit'), record.unit);
      }
    } else if (target === 'unit') populateDtfUnitSelect($('#pw-dtf-cost-unit'), record.symbol);
    else if (target === 'action') syncDtfMovementOptions(record.name);
    else if (target === 'supplier') syncDtfSupplierOptions(record.name);
  }

  function renderDtfCatalog() {
    renderDtfExpenseReport('item');
  }

  function renderDtfCostRegistry() {
    if (!userIsAdministrator(currentUser)) return;
    if (!$('#pw-dtf-cost-date').value) $('#pw-dtf-cost-date').value = localDateValue(new Date());
    if (!$('#pw-dtf-cost-item').options.length) syncDtfCostItemOptions();
    if (!$('#pw-dtf-cost-supplier').options.length) syncDtfSupplierOptions();
    renderDtfCatalog(); renderDtfExpenseReport('cost');
  }

  function resetDtfCostForm(mode = 'materials') {
    editingDtfCostId = '';
    $$('.pw-expense-tab[data-expense-tab]').forEach(btn => { btn.hidden = false; });
    $('#pw-dtf-cost-form').reset();
    setDtfCostFormTab(mode);
    $('#pw-dtf-cost-date').value = localDateValue(new Date());
    $('#pw-dtf-cost-category').value = mode === 'ads' ? 'Anúncio' : 'Tinta';
    syncDtfCostItemOptions();
    syncDtfSupplierOptions();
    syncDtfMovementOptions('Abastecimento');
    // A sincronização dos itens pode reexibir o campo personalizado quando não há
    // item selecionado. Reaplica a aba ao final para preservar exatamente seu layout.
    setDtfCostFormTab(mode);
    $('#pw-save-dtf-cost').textContent = '✓ Registrar despesa';
    $('#pw-cancel-dtf-cost-edit').hidden = true;
  }

  function editDtfCost(entry) {
    if (!entry || !userIsAdministrator(currentUser)) return;
    $('#pw-dtf-cost-modal-body').appendChild($('#pw-dtf-cost-form'));
    editingDtfCostId = entry.id;
    setDtfCostFormTab(normalize(entry.category) === normalize('Anúncio') ? 'ads' : 'materials');
    $$('.pw-expense-tab[data-expense-tab]').forEach(btn => { btn.hidden = btn.dataset.expenseTab !== dtfCostFormMode; });
    $('#pw-dtf-cost-date').value = entry.date || '';
    const categoryName = dtfCategoryName(entry.category || 'Outro');
    const isAd = normalize(categoryName) === normalize('Anúncio');
    const categorySelect = $('#pw-dtf-cost-category');
    if (!Array.from(categorySelect.options).some(option => option.value === categoryName)) categorySelect.add(new Option(categoryName, categoryName));
    categorySelect.value = categoryName;
    syncDtfCostItemOptions();
    const catalogItem = getDtfCatalog().find(item => item.id === entry.itemId || (dtfCategoryName(item.category) === categoryName && [item.name, ...(item.aliases || [])].some(name => normalize(name) === normalize(entry.item))));
    if (catalogItem) $('#pw-dtf-cost-item').value = catalogItem.id;
    if (!catalogItem && !isAd) {
      $('#pw-dtf-cost-item').value = '__custom__';
      $('#pw-dtf-custom-item-wrap').hidden = false; $('#pw-dtf-custom-item').value = entry.item || '';
    } else if (!isAd) {
      if (!Array.from($('#pw-dtf-cost-item').options).some(option => option.value === catalogItem.id)) $('#pw-dtf-cost-item').add(new Option(catalogItem.code + ' — ' + catalogItem.name, catalogItem.id));
      $('#pw-dtf-cost-item').value = catalogItem.id;
      $('#pw-dtf-custom-item-wrap').hidden = true;
    }
    syncDtfMovementOptions(entry.action || 'Abastecimento');
    $('#pw-dtf-cost-quantity').value = entry.quantity || '';
    populateDtfUnitSelect($('#pw-dtf-cost-unit'), entry.unit || 'unidade');
    $('#pw-dtf-cost-value').value = Number(entry.value || 0).toFixed(2).replace('.', ',');
    syncDtfSupplierOptions(entry.supplier || '');
    $('#pw-dtf-cost-notes').value = entry.notes || '';
    // Mantém na alteração o mesmo conjunto de campos da aba correspondente ao cadastro.
    setDtfCostFormTab(isAd ? 'ads' : 'materials');
    $('#pw-save-dtf-cost').textContent = '✓ Salvar alterações';
    $('#pw-cancel-dtf-cost-edit').hidden = false;
    openModal('pw-dtf-cost-modal', true);
    renderBulkNavigation();
  }

  function dtfCostReportPeriod() {
    return { start: $('#pw-dtf-report-start').value, end: $('#pw-dtf-report-end').value, category: $('#pw-dtf-report-category').value };
  }

  function renderDtfCostReport() {
    if (!userIsAdministrator(currentUser)) return;
    const categorySelect = $('#pw-dtf-report-category');
    const selectedCategory = dtfCategoryName(categorySelect.value);
    const categories = [...new Set([...getDtfExpenseCategoryRecords().map(record => record.name), ...getDtfCosts().map(entry => dtfCategoryName(entry.category))])];
    categorySelect.innerHTML = '<option value="">Todas</option>' + categories.map(name => '<option value="' + escapeHtml(name) + '">' + escapeHtml(name) + '</option>').join('');
    categorySelect.value = categories.includes(selectedCategory) ? selectedCategory : '';
    const filters = dtfCostReportPeriod();
    const inPeriod = date => (!filters.start || date >= filters.start) && (!filters.end || date <= filters.end);
    const costs = getDtfCosts().map(expenseDisplayRecord).filter(entry => inPeriod(entry.date || '') && (!filters.category || dtfCategoryName(entry.category) === filters.category)).sort((a, b) => String(b.date || '').localeCompare(String(a.date || '')));
    const dtfOrders = getOrders().map(order => {
      const dtfItems = (order.items || []).filter(item => item && item.dtfUv);
      return { order, items: dtfItems };
    }).filter(record => record.items.length && inPeriod(record.order.createdDate || ''));
    const totalCost = costs.reduce((sum, entry) => sum + Number(entry.value || 0), 0);
    const allPeriodCosts = getDtfCosts().map(expenseDisplayRecord).filter(entry => inPeriod(entry.date || ''));
    const totalCostAll = allPeriodCosts.reduce((sum, entry) => sum + Number(entry.value || 0), 0);
    const revenue = dtfOrders.reduce((sum, record) => sum + record.items.reduce((itemSum, item) => itemSum + itemFinancialBreakdown(item, record.order.origin || record.order.client && record.order.client.origin || 'Normal').net, 0), 0);
    const lengthCm = dtfOrders.reduce((sum, record) => sum + record.items.reduce((itemSum, item) => itemSum + Number(item.dtfUv && item.dtfUv.height != null ? item.dtfUv.height : 0), 0), 0);
    const lengthMeters = lengthCm / 100;
    const area = lengthMeters * 0.28;
    const comparison = revenue - totalCost;
    const filmAMeters = costs.filter(entry => dtfCategoryName(entry.category) === dtfCategoryName('Filme') && normalize(entry.item) === normalize('Filme A')).reduce((sum, entry) => sum + Number(entry.quantity || 0), 0);
    const filmBMeters = costs.filter(entry => dtfCategoryName(entry.category) === dtfCategoryName('Filme') && normalize(entry.item) === normalize('Filme B')).reduce((sum, entry) => sum + Number(entry.quantity || 0), 0);
    const inkMl = costs.filter(entry => dtfCategoryName(entry.category) === dtfCategoryName('Tinta') && normalize(entry.unit) === normalize(dtfUnitValue('ml'))).reduce((sum, entry) => sum + Number(entry.quantity || 0), 0);
    const card = (label, value, detail, state) => '<div class="pw-dtf-report-card ' + (state || '') + '"><small>' + escapeHtml(label) + '</small><strong>' + escapeHtml(value) + '</strong><span>' + escapeHtml(detail) + '</span></div>';
    $('#pw-dtf-report-cards').innerHTML = [
      card('Custos registrados', money.format(totalCost), costs.length + ' movimentação(ões)', 'pw-cost'),
      card('Vendas DTF UV', money.format(revenue), dtfOrders.length + ' pedido(s) com DTF UV', 'pw-revenue'),
      card('Resultado comparativo', money.format(comparison), 'Vendas menos custos lançados no período', comparison >= 0 ? 'pw-positive' : 'pw-negative'),
      card('Comprimento produzido', lengthMeters.toFixed(2).replace('.', ',') + ' m', area.toFixed(2).replace('.', ',') + ' m² em largura fixa de 28 cm'),
      card('Custo por metro', lengthMeters > 0 ? money.format(totalCostAll / lengthMeters) : '—', 'Todos os custos do período ÷ metros produzidos'),
      card('Venda média por pedido', dtfOrders.length ? money.format(revenue / dtfOrders.length) : '—', 'Somente itens DTF UV'),
      card('Filme A informado', filmAMeters.toFixed(2).replace('.', ',') + ' m', 'Saldo estimado após vendas: ' + (filmAMeters - lengthMeters).toFixed(2).replace('.', ',') + ' m'),
      card('Filme B informado', filmBMeters.toFixed(2).replace('.', ',') + ' m', 'Saldo estimado após vendas: ' + (filmBMeters - lengthMeters).toFixed(2).replace('.', ',') + ' m'),
      card('Tintas abastecidas', inkMl.toFixed(2).replace('.', ',') + ' ml', 'Soma dos abastecimentos registrados no período')
    ].join('');
    // cm linear analysis — mecolour costs only
    const mecolourCosts = costs.filter(e => normalize(String(e.supplier || '')) === 'mecolour');
    const mecolourTotal = mecolourCosts.reduce((s, e) => s + Number(e.value || 0), 0);
    const costPerCm = lengthCm > 0 ? mecolourTotal / lengthCm : 0;
    const revenuePerCm = lengthCm > 0 ? revenue / lengthCm : 0;
    const profitPerCm = revenuePerCm - costPerCm;
    const fmtCmVal = v => (v < 0 ? '−' : '') + 'R$ ' + Math.abs(v).toFixed(4).replace('.', ',') + '/cm';
    const cmCardsEl = $('#pw-dtf-cm-cards');
    if (cmCardsEl) cmCardsEl.innerHTML = [
      card('Custo Mecolour/cm linear', lengthCm > 0 ? fmtCmVal(costPerCm) : '—', mecolourCosts.length + ' despesa(s) Mecolour ÷ ' + Math.round(lengthCm) + ' cm produzidos', 'pw-cost'),
      card('Receita/cm linear', lengthCm > 0 ? fmtCmVal(revenuePerCm) : '—', 'Vendas DTF UV ÷ cm linear do período', 'pw-revenue'),
      card('Margem/cm (vs Mecolour)', lengthCm > 0 ? fmtCmVal(profitPerCm) : '—', 'Receita DTF UV menos custos Mecolour por cm — não inclui outras despesas', profitPerCm >= 0 ? 'pw-positive' : 'pw-negative'),
    ].join('');
    // monthly breakdown for chart
    const monthlyMap = {};
    mecolourCosts.forEach(e => {
      const m = String(e.date || '').slice(0, 7); if (!m) return;
      if (!monthlyMap[m]) monthlyMap[m] = { cost: 0, revenue: 0, cm: 0 };
      monthlyMap[m].cost += Number(e.value || 0);
    });
    dtfOrders.forEach(({ order, items }) => {
      const m = String(order.createdDate || '').slice(0, 7); if (!m) return;
      if (!monthlyMap[m]) monthlyMap[m] = { cost: 0, revenue: 0, cm: 0 };
      items.forEach(item => {
        monthlyMap[m].cm += Number(item.dtfUv && item.dtfUv.height != null ? item.dtfUv.height : 0);
        monthlyMap[m].revenue += itemFinancialBreakdown(item, order.origin || (order.client && order.client.origin) || 'Normal').net;
      });
    });
    const months = Object.keys(monthlyMap).sort();
    const chartWrap = $('#pw-dtf-cm-chart-wrap');
    if (chartWrap) {
      if (!months.length) { chartWrap.innerHTML = ''; } else {
        const pts = months.map(m => { const d = monthlyMap[m]; return { m, costCm: d.cm > 0 ? d.cost / d.cm : 0, revCm: d.cm > 0 ? d.revenue / d.cm : 0, profCm: d.cm > 0 ? (d.revenue - d.cost) / d.cm : 0, cm: d.cm }; });
        const W = 700, H = 240, PL = 72, PR = 16, PT = 18, PB = 48, pw2 = W - PL - PR, ph2 = H - PT - PB;
        const allV = pts.flatMap(p => [p.costCm, p.revCm, p.profCm]);
        const maxV = Math.max(...allV, 0.001), minV = Math.min(...allV, 0), rng = maxV - minV || 1;
        const xi = i => PL + (i + 0.5) * (pw2 / pts.length);
        const yi = v => PT + ph2 - ((v - minV) / rng) * ph2;
        const polyline = (key, col) => '<polyline fill="none" stroke="' + col + '" stroke-width="2.5" stroke-linejoin="round" stroke-linecap="round" points="' + pts.map((p, i) => xi(i).toFixed(1) + ',' + yi(p[key]).toFixed(1)).join(' ') + '"/>' + pts.map((p, i) => '<circle cx="' + xi(i).toFixed(1) + '" cy="' + yi(p[key]).toFixed(1) + '" r="4" fill="' + col + '"><title>' + escapeHtml(p.m + ': R$ ' + p[key].toFixed(4).replace('.', ',') + '/cm (' + Math.round(p.cm) + ' cm)') + '</title></circle>').join('');
        const MNAMES = ['Jan','Fev','Mar','Abr','Mai','Jun','Jul','Ago','Set','Out','Nov','Dez'];
        const mLabel = m => { const parts = m.split('-'); return (MNAMES[Number(parts[1]) - 1] || parts[1]) + '/' + parts[0].slice(2); };
        const ticks = Array.from({ length: 5 }, (_, i) => minV + (rng / 4) * i);
        chartWrap.innerHTML =
          '<div class="pw-dtf-cm-legend"><span style="color:#b91c1c">▬ Custo Mecolour/cm</span><span style="color:#16a34a">▬ Receita/cm</span><span style="color:#2563eb">▬ Margem vs Mecolour/cm</span></div>' +
          '<div class="pw-dtf-cm-scroll"><svg viewBox="0 0 ' + W + ' ' + H + '" xmlns="http://www.w3.org/2000/svg" class="pw-dtf-cm-svg">' +
          ticks.map(v => '<line x1="' + PL + '" y1="' + yi(v).toFixed(1) + '" x2="' + (W - PR) + '" y2="' + yi(v).toFixed(1) + '" stroke="#e2e8f0" stroke-width="1"/><text x="' + (PL - 5) + '" y="' + (yi(v) + 4).toFixed(1) + '" text-anchor="end" font-size="10" fill="#64748b">R$' + v.toFixed(3).replace('.', ',') + '</text>').join('') +
          (minV < 0 ? '<line x1="' + PL + '" y1="' + yi(0).toFixed(1) + '" x2="' + (W - PR) + '" y2="' + yi(0).toFixed(1) + '" stroke="#94a3b8" stroke-width="1" stroke-dasharray="4,3"/>' : '') +
          polyline('costCm', '#b91c1c') + polyline('revCm', '#16a34a') + polyline('profCm', '#2563eb') +
          pts.map((p, i) => '<text x="' + xi(i).toFixed(1) + '" y="' + (H - 8) + '" text-anchor="middle" font-size="10" fill="#64748b">' + escapeHtml(mLabel(p.m)) + '</text>').join('') +
          '</svg></div>';
      }
    }

    const categoryMap = {}, itemMap = {};
    costs.forEach(entry => {
      categoryMap[entry.category] = (categoryMap[entry.category] || 0) + Number(entry.value || 0);
      const key = entry.category + '|' + entry.item + '|' + entry.unit;
      if (!itemMap[key]) itemMap[key] = { category: entry.category, item: entry.item, itemCode: dtfCostItemCode(entry), unit: entry.unit, quantity: 0, value: 0, latest: '' };
      itemMap[key].quantity += Number(entry.quantity || 0); itemMap[key].value += Number(entry.value || 0); itemMap[key].latest = String(entry.date || '') > itemMap[key].latest ? entry.date : itemMap[key].latest;
    });
    $('#pw-dtf-category-breakdown').innerHTML = Object.keys(categoryMap).length ? Object.entries(categoryMap).sort((a, b) => b[1] - a[1]).map(entry => '<div class="pw-dtf-breakdown-row"><span>' + escapeHtml(entry[0]) + '</span><b>' + escapeHtml(money.format(entry[1])) + '</b><small>' + escapeHtml(totalCost ? (entry[1] / totalCost * 100).toFixed(1).replace('.', ',') + '%' : '0%') + '</small></div>').join('') : '<p>Nenhum custo no período.</p>';
    $('#pw-dtf-item-breakdown').innerHTML = Object.values(itemMap).length ? Object.values(itemMap).sort((a, b) => b.value - a.value).map(entry => '<div class="pw-dtf-breakdown-row"><span><strong>' + escapeHtml((entry.itemCode ? entry.itemCode + ' — ' : '') + entry.item) + '</strong><small>' + escapeHtml(entry.category + ' · última em ' + dateLabel(entry.latest)) + '</small></span><b>' + escapeHtml(money.format(entry.value)) + '</b><small>' + escapeHtml(String(Number(entry.quantity.toFixed(2))).replace('.', ',') + ' ' + entry.unit) + '</small></div>').join('') : '<p>Nenhum item no período.</p>';
  }

  function artOrderPrefix(orderNumber) {
    return digits(orderNumber).slice(-5).padStart(5, '0');
  }

  function nextArtCode(orderNumber, orderItems) {
    const prefix = artOrderPrefix(orderNumber);
    const used = new Set((orderItems || []).map(item => String(item.art && item.art.code || '').toUpperCase()));
    for (let index = 0; index < 26; index += 1) {
      const code = prefix + '-' + String.fromCharCode(65 + index);
      if (!used.has(code)) return code;
    }
    return '';
  }

  function normalizeExistingArtCodes() {
    const orders = getOrders();
    let changed = false;
    orders.forEach(order => {
      const prefix = artOrderPrefix(order.orderNumber);
      const used = new Set();
      (order.items || []).forEach(item => {
        if (!item.art || !item.art.id || !item.art.url) return;
        let code = String(item.art.code || '').toUpperCase();
        if (!new RegExp('^' + prefix + '-[A-Z]$').test(code) || used.has(code)) {
          code = '';
          for (let index = 0; index < 26; index += 1) {
            const candidate = prefix + '-' + String.fromCharCode(65 + index);
            if (!used.has(candidate)) { code = candidate; break; }
          }
          if (!code) return;
          item.art.code = code;
          changed = true;
        }
        used.add(code);
      });
    });
    if (changed) writeStorage(STORAGE.orders, orders);
  }

  function analyticsChartPreferenceKey() {
    const user = currentUser || {};
    const identity = String(user.id || user.login || user.user_login || user.email || 'usuario').replace(/[^A-Za-z0-9_-]/g, '_');
    return 'pw_personalizados_analytics_chart_models_' + identity;
  }

  function ensureAnalyticsChartPreferences() {
    const key = analyticsChartPreferenceKey();
    if (analyticsChartPreferencesLoadedFor === key) return;
    Object.keys(analyticsChartTypes).forEach(targetId => delete analyticsChartTypes[targetId]);
    try {
      const saved = JSON.parse(localStorage.getItem(key) || '{}');
      if (saved && typeof saved === 'object' && !Array.isArray(saved)) {
        Object.entries(saved).forEach(([targetId, type]) => {
          if (typeof type === 'string') analyticsChartTypes[targetId] = type;
        });
      }
    } catch (error) {
      console.warn('Não foi possível recuperar os modelos de gráficos salvos.', error);
    }
    analyticsChartPreferencesLoadedFor = key;
  }

  function saveAnalyticsChartPreferences(useSystemDefaults = false, notify = true) {
    const key = analyticsChartPreferenceKey();
    if (useSystemDefaults) Object.keys(analyticsChartTypes).forEach(targetId => delete analyticsChartTypes[targetId]);
    try {
      localStorage.setItem(key, JSON.stringify(analyticsChartTypes));
      analyticsChartPreferencesLoadedFor = key;
      if (notify) showMessage(useSystemDefaults ? 'Modelos padrão restaurados e salvos para este usuário.' : 'Modelos de gráficos salvos para este usuário.', 'success');
    } catch (error) {
      console.error('Não foi possível salvar os modelos de gráficos.', error);
      showMessage('Não foi possível salvar seus modelos de gráficos neste navegador.', 'error');
    }
  }

  function analyticsChartMode(targetId, fallback = 'horizontal') { return analyticsChartTypes[targetId] || fallback; }

  function analyticsDonutRows(entries, formatter, empty = 'Nenhum dado para os filtros selecionados.') {
    const positive = entries.filter(entry => Number(entry.value || 0) > 0.005);
    const total = positive.reduce((sum, entry) => sum + Number(entry.value || 0), 0);
    if (!total) return '<div class="pw-analytics-empty">' + empty + '</div>';
    let angle = 0;
    const palette = ['#2563eb','#0f766e','#7c3aed','#ea580c','#0891b2','#ca8a04','#db2777','#475569'];
    const slices = positive.map((entry, index) => { const start = angle; angle += entry.value / total * 360; return (entry.color || palette[index % palette.length]) + ' ' + start + 'deg ' + angle + 'deg'; });
    return '<div class="pw-analytics-donut-layout"><div class="pw-analytics-donut" style="background:conic-gradient(' + slices.join(',') + ')" role="img" aria-label="Distribuição proporcional"><span>' + escapeHtml(money.format(total)) + '<small>total</small></span></div><div class="pw-analytics-legend">' + positive.map((entry, index) => '<div><i style="background:' + (entry.color || palette[index % palette.length]) + '"></i><span>' + escapeHtml(entry.label) + '<small>' + (entry.value / total * 100).toFixed(1).replace('.', ',') + '% do total</small></span><strong>' + escapeHtml(formatter(entry.value, entry)) + '</strong></div>').join('') + '</div></div>';
  }

  function analyticsVerticalRows(entries, formatter, color, empty = 'Nenhum dado para os filtros selecionados.') {
    if (!entries.length) return '<div class="pw-analytics-empty">' + empty + '</div>';
    const max = Math.max(1, ...entries.map(entry => Number(entry.value || 0)));
    return '<div class="pw-analytics-columns pw-analytics-switch-vertical">' + entries.map(entry => '<div title="' + escapeHtml(entry.label + ' · ' + formatter(entry.value, entry)) + '"><span>' + escapeHtml(formatter(entry.value, entry)) + '</span><i style="height:' + Math.max(5, Number(entry.value || 0) / max * 100).toFixed(1) + '%;background:' + (entry.color || color || 'var(--pw-blue)') + '"></i><small>' + escapeHtml(entry.label) + '</small></div>').join('') + '</div>';
  }

  function analyticsLineRows(entries, formatter, color = '#2563eb', empty = 'Nenhum dado para os filtros selecionados.') {
    if (!entries.length) return '<div class="pw-analytics-empty">' + empty + '</div>';
    if (entries.length === 1) return analyticsVerticalRows(entries, formatter, color, empty);
    const max = Math.max(1, ...entries.map(entry => Number(entry.value || 0)));
    const points = entries.map((entry, index) => ((entries.length === 1 ? 300 : index / (entries.length - 1) * 560 + 20).toFixed(1) + ',' + (190 - Number(entry.value || 0) / max * 155).toFixed(1))).join(' ');
    return '<div class="pw-analytics-line-chart"><svg viewBox="0 0 600 220" preserveAspectRatio="none" role="img" aria-label="Evolução ao longo do tempo"><polyline points="' + points + '" fill="none" stroke="' + color + '" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"></polyline>' + entries.map((entry, index) => { const x = entries.length === 1 ? 300 : index / (entries.length - 1) * 560 + 20; const y = 190 - Number(entry.value || 0) / max * 155; return '<circle cx="' + x.toFixed(1) + '" cy="' + y.toFixed(1) + '" r="5" fill="' + color + '" data-label="' + escapeHtml(entry.label) + '" />'; }).join('') + '</svg><div class="pw-analytics-line-labels">' + entries.map(entry => '<span title="' + escapeHtml(entry.label + ' · ' + formatter(entry.value, entry)) + '">' + escapeHtml(entry.label) + '</span>').join('') + '</div></div>';
  }

  function ensureAnalyticsChartTools() {
    const definitions = {
      'pw-analytics-trend':['vertical','line'],
      'pw-analytics-forecast':['line','vertical'],
      'pw-analytics-products-chart':['horizontal','vertical','donut'],
      'pw-analytics-clients-chart':['horizontal','vertical','donut'],
      'pw-analytics-platform-share-chart':['horizontal','vertical','donut'],
      'pw-analytics-payments-chart':['donut','horizontal','vertical'],
      'pw-analytics-receivables-chart':['horizontal','vertical','donut'],
      'pw-analytics-expense-category-chart':['horizontal','vertical','donut'],
      'pw-analytics-expense-supplier-chart':['horizontal','vertical','donut'],
      'pw-analytics-ad-date-chart':['vertical','horizontal','line'],
      'pw-analytics-material-comparison-chart':['horizontal','vertical'],
      'pw-analytics-profit-chart':['horizontal','vertical','donut'],
      'pw-analytics-status-chart':['horizontal','vertical','donut'],
      'pw-analytics-finalization-chart':['horizontal','vertical','donut'],
      'pw-analytics-pending-chart':['horizontal','vertical','donut'],
      'pw-analytics-delivery-chart':['horizontal','vertical','donut'],
      'pw-analytics-commission-share-chart':['donut','horizontal','vertical'],
      'pw-analytics-operation-chart':['radial']
    };
    const icons = { horizontal:'▬', vertical:'▥', donut:'◉', line:'⌁', radial:'◌' };
    const labels = { horizontal:'Barras horizontais', vertical:'Barras verticais', donut:'Gráfico de pizza', line:'Linhas', radial:'Indicadores radiais' };
    Object.entries(definitions).forEach(([targetId, types]) => {
      const chart = $('#' + targetId); const header = chart && chart.closest('.pw-analytics-card') && chart.closest('.pw-analytics-card').querySelector('header');
      if (!chart || !header) return;
      const existing = header.querySelector('[data-analytics-chart-tools="' + targetId + '"]');
      if (existing) { $$('.pw-analytics-chart-tool', existing).forEach(button => button.classList.toggle('is-active', analyticsChartMode(targetId, types[0]) === button.dataset.analyticsChartType)); return; }
      if (types.length < 2) return;
      const tools = document.createElement('div'); tools.className = 'pw-analytics-chart-tools'; tools.dataset.analyticsChartTools = targetId; tools.setAttribute('aria-label', 'Tipo de gráfico');
      types.forEach(type => { const button = document.createElement('button'); button.type = 'button'; button.className = 'pw-analytics-chart-tool'; button.dataset.analyticsChartTarget = targetId; button.dataset.analyticsChartType = type; button.textContent = icons[type]; button.title = labels[type]; button.setAttribute('aria-label', labels[type]); if (analyticsChartMode(targetId, types[0]) === type) button.classList.add('is-active'); if (type === 'radial') button.disabled = true; tools.appendChild(button); });
      header.appendChild(tools);
    });
  }

  function analyticsBarRows(entries, formatter, color, targetId = '') {
    const mode = targetId ? analyticsChartMode(targetId) : 'horizontal';
    if (mode === 'donut') return analyticsDonutRows(entries, formatter);
    if (mode === 'vertical') return analyticsVerticalRows(entries, formatter, color);
    if (mode === 'line') return analyticsLineRows(entries, formatter, color);
    const max = Math.max(1, ...entries.map(entry => Number(entry.value || 0)));
    return entries.length ? entries.map((entry, index) => '<div class="pw-analytics-bar-row"><div><strong>' + escapeHtml(entry.label) + '</strong><span>' + escapeHtml(formatter(entry.value, entry)) + '</span></div><i><b style="width:' + Math.max(3, Number(entry.value || 0) / max * 100).toFixed(1) + '%;background:' + (entry.color || color || 'var(--pw-blue)') + '"></b></i></div>').join('') : '<div class="pw-analytics-empty">Nenhum dado para os filtros selecionados.</div>';
  }

  function analyticsSupplierDonut(expenses, categoryType, targetId = '') {
    const values = {};
    expenses.forEach(expense => {
      const isAd = normalize(dtfCategoryName(expense.category || 'Outro')) === normalize('Anúncio');
      if ((categoryType === 'ads') !== isAd) return;
      const supplier = String(expense.supplier || 'Não informado').trim() || 'Não informado';
      values[supplier] = (values[supplier] || 0) + Number(expense.value || 0);
    });
    const entries = Object.entries(values).map(([label, value], index) => ({
      label, value,
      color: ['#2563eb','#0f766e','#7c3aed','#ea580c','#0891b2','#ca8a04','#db2777','#475569'][index % 8]
    })).filter(entry => entry.value > 0.005).sort((a,b) => b.value - a.value);
    if (targetId && analyticsChartMode(targetId, 'donut') !== 'donut') return analyticsBarRows(entries, value => money.format(value), '#7c3aed', targetId);
    const total = entries.reduce((sum, entry) => sum + entry.value, 0);
    if (!total) return '<div class="pw-analytics-empty">Nenhuma despesa encontrada para esta categoria.</div>';
    let angle = 0;
    const slices = entries.map(entry => { const start = angle; angle += entry.value / total * 360; return entry.color + ' ' + start + 'deg ' + angle + 'deg'; });
    return '<div class="pw-analytics-donut-layout pw-analytics-supplier-donut-layout"><div class="pw-analytics-donut" style="background:conic-gradient(' + slices.join(',') + ')" role="img" aria-label="Distribuição por fornecedor"><span>' + escapeHtml(money.format(total)) + '<small>total</small></span></div><div class="pw-analytics-legend">' + entries.map(entry => '<div><i style="background:' + entry.color + '"></i><span>' + escapeHtml(entry.label) + '<small>' + (entry.value / total * 100).toFixed(1).replace('.', ',') + '% do total</small></span><strong>' + escapeHtml(money.format(entry.value)) + '</strong></div>').join('') + '</div></div>';
  }

  function analyticsAdDateBars(expenses, range) {
    const granularity = $('#pw-analytics-ad-date-granularity') ? $('#pw-analytics-ad-date-granularity').value : 'month';
    const grouped = {};
    expenses.forEach(expense => {
      if (normalize(dtfCategoryName(expense.category || 'Outro')) !== normalize('Anúncio')) return;
      const date = String(expense.date || '').slice(0, 10);
      let key = 'Sem data';
      if (date) key = granularity === 'year' ? date.slice(0, 4) : (granularity === 'month' ? date.slice(0, 7) : date);
      grouped[key] = (grouped[key] || 0) + Number(expense.value || 0);
    });
    const labelFor = key => {
      if (key === 'Sem data') return key;
      if (granularity === 'year') return key;
      if (granularity === 'month') {
        const [year, month] = key.split('-');
        return new Date(Number(year), Number(month) - 1, 1).toLocaleDateString('pt-BR', { month:'short', year:'numeric' });
      }
      return dateLabel(key);
    };
    const entries = Object.entries(grouped).map(([key, value]) => ({ key, label:labelFor(key), value })).sort((a,b) => (a.key === 'Sem data' ? 1 : b.key === 'Sem data' ? -1 : a.key.localeCompare(b.key)));
    const rangeLabel = range.start || range.end ? 'Filtro master: ' + (range.start ? dateLabel(range.start) : 'início') + ' até ' + (range.end ? dateLabel(range.end) : 'hoje') : 'Filtro master: todo o histórico';
    const rangeNode = $('#pw-analytics-ad-date-range');
    if (rangeNode) rangeNode.textContent = rangeLabel;
    if (!entries.length) return '<div class="pw-analytics-empty">Nenhum gasto com anúncios encontrado para os filtros selecionados.</div>';
    const mode = analyticsChartMode('pw-analytics-ad-date-chart', 'vertical');
    if (mode === 'horizontal') return analyticsBarRows(entries, value => money.format(value), '#ea580c', 'pw-analytics-ad-date-chart');
    if (mode === 'line') return analyticsLineRows(entries, value => money.format(value), '#ea580c');
    const max = Math.max(1, ...entries.map(entry => entry.value));
    return '<div class="pw-analytics-columns pw-analytics-ad-date-columns">' + entries.map(entry => '<div title="' + escapeHtml(entry.label + ' · ' + money.format(entry.value)) + '"><span>' + escapeHtml(money.format(entry.value)) + '</span><i style="height:' + Math.max(5, entry.value / max * 100).toFixed(1) + '%;background:#ea580c"></i><small>' + escapeHtml(entry.label) + '</small></div>').join('') + '</div>';
  }

  function analyticsMaterialKey(expense) {
    if (!expense) return 'material-sem-identificacao';
    return normalize(expense.category || 'Outro') + '|' + normalize(expense.item || expense.itemId || 'material-sem-identificacao');
  }

  function analyticsIsDtfUvItem(item) {
    const description = normalize(item && (item.description || item.name || item.code));
    return !!(item && item.dtfUv) || description.includes('dtfuv') || description.includes('dtf');
  }

  function analyticsMaterialComparisonData(allExpenses, orders, range, selectedKey) {
    const materials = (allExpenses || []).filter(expense => normalize(expense.category) !== normalize('Anúncio') && expense.date && Number(expense.value || 0) >= 0);
    const selected = materials.filter(expense => analyticsMaterialKey(expense) === selectedKey).sort((a, b) => String(a.date).localeCompare(String(b.date)));
    if (!selected.length) return [];
    const masterStart = range.start || '';
    const masterEnd = range.end || localDateValue(new Date());
    const rows = [];
    selected.forEach((expense, index) => {
      const next = selected[index + 1];
      const nextDate = next && String(next.date).slice(0, 10);
      let end = masterEnd;
      if (nextDate) {
        const date = new Date(nextDate + 'T12:00:00');
        date.setDate(date.getDate() - 1);
        end = localDateValue(date);
      }
      const start = String(expense.date).slice(0, 10);
      const effectiveStart = masterStart && masterStart > start ? masterStart : start;
      const effectiveEnd = masterEnd && masterEnd < end ? masterEnd : end;
      if (effectiveStart > effectiveEnd) return;
      const row = {
        start: effectiveStart,
        end: effectiveEnd,
        label: dateLabel(effectiveStart) + ' → ' + dateLabel(effectiveEnd),
        material: expense.item || expense.category || 'Material',
        unit: expense.unit || 'unidade',
        quantity: Number(expense.quantity || 0),
        cost: Number(expense.value || 0),
        sold: 0,
        received: 0,
        orders: new Set()
      };
      (orders || []).forEach(order => {
        const orderDateValue = String(order.createdDate || '').slice(0, 10);
        if (!orderDateValue || orderDateValue < row.start || orderDateValue > row.end) return;
        const lineItems = (order.items || []).filter(analyticsIsDtfUvItem);
        if (!lineItems.length) return;
        const orderGross = Math.max(0, Number(order.total || 0));
        const orderNet = adjustedOrderTotal(order);
        const paidNet = Math.min(orderNet, Math.max(0, Number(order.paid || 0)));
        const discount = Math.max(0, Number(order.discount || 0));
        const lineGrossTotal = (order.items || []).reduce((sum, item) => sum + itemFinancialBreakdown(item, order.origin || order.client && order.client.origin || 'Normal').net, 0) || orderGross;
        lineItems.forEach(item => {
          const gross = itemFinancialBreakdown(item, order.origin || order.client && order.client.origin || 'Normal').net;
          const base = gross || (lineGrossTotal ? orderGross * (Number(item.quantity || 0) / Math.max(1, lineItems.reduce((sum, current) => sum + Number(current.quantity || 0), 0))) : 0);
          const itemNet = Math.max(0, base - (lineGrossTotal ? discount * base / lineGrossTotal : 0));
          row.sold += itemNet;
          row.received += orderNet > 0 ? Math.min(itemNet, paidNet * itemNet / orderNet) : 0;
          row.orders.add(String(order.orderNumber || order.id || orderDateValue));
        });
      });
      rows.push({ ...row, orders: row.orders.size, unitCost: row.quantity > 0 ? row.cost / row.quantity : 0, realProfit: row.received - row.cost });
    });
    return rows;
  }

  function analyticsMaterialComparisonRows(rows, targetId = '') {
    if (!rows.length) return '<div class="pw-analytics-empty">Cadastre compras de um material para comparar com as vendas de DTF UV.</div>';
    const totalCost = rows.reduce((sum, row) => sum + row.cost, 0);
    const totalSold = rows.reduce((sum, row) => sum + row.sold, 0);
    const totalReceived = rows.reduce((sum, row) => sum + row.received, 0);
    const totalProfit = totalReceived - totalCost;
    const summary = '<div class="pw-material-comparison-summary"><div><small>Custo dos materiais</small><strong>' + escapeHtml(money.format(totalCost)) + '</strong></div><div><small>Vendas DTF UV líquidas</small><strong>' + escapeHtml(money.format(totalSold)) + '</strong></div><div><small>Recebido líquido</small><strong>' + escapeHtml(money.format(totalReceived)) + '</strong></div><div><small>Lucro real</small><strong class="' + (totalProfit >= 0 ? 'pw-profit-positive' : 'pw-profit-negative') + '">' + escapeHtml(money.format(totalProfit)) + '</strong></div></div>';
    const mode = analyticsChartMode(targetId, 'horizontal');
    if (mode === 'vertical') {
      const max = Math.max(1, ...rows.flatMap(row => [row.cost, row.received]));
      return summary + '<div class="pw-material-comparison-legend"><span><i class="pw-material-cost-key"></i>Custo do material</span><span><i class="pw-material-sales-key"></i>Recebido líquido</span></div><div class="pw-material-comparison-columns">' + rows.map(row => '<div class="pw-material-comparison-column" title="' + escapeHtml(row.label + ' · custo ' + money.format(row.cost) + ' · recebido ' + money.format(row.received)) + '"><div class="pw-material-comparison-bars"><i class="pw-material-cost-bar" style="height:' + Math.max(5, row.cost / max * 100).toFixed(1) + '%"></i><i class="pw-material-sales-bar" style="height:' + Math.max(5, row.received / max * 100).toFixed(1) + '%"></i></div><small>' + escapeHtml(row.label) + '</small></div>').join('') + '</div>';
    }
    const max = Math.max(1, ...rows.flatMap(row => [row.cost, row.received]));
    return summary + '<div class="pw-material-comparison-rows">' + rows.map(row => '<div class="pw-material-comparison-row"><div class="pw-material-comparison-row-title"><strong>' + escapeHtml(row.label) + '</strong><span>' + escapeHtml(String(row.quantity).replace('.', ',') + ' ' + row.unit + ' · ' + row.orders + ' pedido(s) DTF UV · custo unitário ' + money.format(row.unitCost)) + '</span></div><div class="pw-material-comparison-metric"><div><span>Custo do material</span><b>' + escapeHtml(money.format(row.cost)) + '</b></div><i><em class="pw-material-cost-bar" style="width:' + Math.max(2, row.cost / max * 100).toFixed(1) + '%"></em></i></div><div class="pw-material-comparison-metric"><div><span>Recebido líquido (− descontos)</span><b>' + escapeHtml(money.format(row.received)) + '</b></div><i><em class="pw-material-sales-bar" style="width:' + Math.max(2, row.received / max * 100).toFixed(1) + '%"></em></i></div><div class="pw-material-comparison-profit">Lucro real do intervalo: <strong class="' + (row.realProfit >= 0 ? 'pw-profit-positive' : 'pw-profit-negative') + '">' + escapeHtml(money.format(row.realProfit)) + '</strong></div></div>').join('') + '</div>';
  }

  function analyticsDateRange() {
    const period = $('#pw-analytics-period').value;
    const today = new Date();
    let start = $('#pw-analytics-start').value;
    let end = $('#pw-analytics-end').value;
    if (period !== 'custom') {
      end = localDateValue(today);
      if (period === '30' || period === '90') {
        const date = new Date(today); date.setDate(date.getDate() - Number(period) + 1); start = localDateValue(date);
      } else if (period === 'year') start = today.getFullYear() + '-01-01';
      else { start = ''; end = ''; }
    }
    return { start, end };
  }

  function populateAnalyticsFilters(orders) {
    const fill = (selector, entries, first) => {
      const select = $(selector); const selected = select.value;
      const uniqueEntries = uniqueFilterEntries(entries);
      select.innerHTML = '<option value="">' + escapeHtml(first) + '</option>' + uniqueEntries.map(entry => '<option value="' + escapeHtml(entry.value) + '">' + escapeHtml(entry.label) + '</option>').join('');
      const selectedEntry = entries.find(entry => entry.value === selected);
      const selectedLabelKey = normalize(selectedEntry && selectedEntry.label).replace(/\s+/g, ' ');
      const restored = uniqueEntries.find(entry => entry.value === selected || (selectedLabelKey && normalize(entry.label).replace(/\s+/g, ' ') === selectedLabelKey));
      if (restored) select.value = restored.value;
    };
    const statuses = Array.from(new Set(orders.map(order => order.status).filter(Boolean))).sort().map(value => ({ value, label:value }));
    const clients = new Map(); const users = new Map();
    orders.forEach(order => {
      const clientValue = String(order.client && (order.client.id || order.client.name) || '');
      if (clientValue) clients.set(clientValue, order.client.name || clientValue);
      const userValue = createdByFilterValue(order);
      const userLabel = createdByFilterLabel(order);
      if (userValue && userLabel) users.set(userValue, userLabel);
    });
    fill('#pw-analytics-status', statuses, 'Todas');
    fill('#pw-analytics-client', Array.from(clients, ([value,label]) => ({ value,label })).sort((a,b) => a.label.localeCompare(b.label)), 'Todos');
    fill('#pw-analytics-user', Array.from(users, ([value,label]) => ({ value,label })).sort((a,b) => a.label.localeCompare(b.label)), 'Todos');
    fill('#pw-analytics-category', getCategories().filter(item => item.active !== false).map(item => ({ value:item.id || item.name, label:item.name })).sort((a,b) => a.label.localeCompare(b.label)), 'Todas');
  }

  function renderAnalytics() {
    ensureAnalyticsChartPreferences();
    ensureAnalyticsChartTools();
    const allOrders = getOrders();
    populateAnalyticsFilters(allOrders);
    const range = analyticsDateRange();
    const status = $('#pw-analytics-status').value;
    const client = $('#pw-analytics-client').value;
    const user = $('#pw-analytics-user').value;
    const category = $('#pw-analytics-category').value;
    const origin = $('#pw-analytics-origin').value;
    const finalization = $('#pw-analytics-finalization').value;
    const productMap = new Map(getProducts().map(product => [String(product.id || product.code), product]));
    const itemCategory = item => {
      const product = productMap.get(String(item.productId || item.code)) || {};
      return String(item.categoryId || item.category || product.categoryId || product.category || '');
    };
    const orders = allOrders.filter(order => {
      const date = String(order.createdDate || '').slice(0,10);
      const clientValue = String(order.client && (order.client.id || order.client.name) || '');
      const userValue = createdByFilterValue(order);
      const orderOrigin = order.origin || order.client && order.client.origin || 'Normal';
      const matchesFinalization = !finalization || (finalization === 'finalized' ? isOrderFinalized(order) : !isOrderFinalized(order));
      return (!range.start || date >= range.start) && (!range.end || date <= range.end) && (!status || order.status === status) && (!client || clientValue === client) && (!user || userValue === user) && (!origin || orderOrigin === origin) && matchesFinalization && (!category || (order.items || []).some(item => itemCategory(item) === category));
    });
    const revenue = orders.reduce((sum, order) => sum + adjustedOrderTotal(order), 0);
    const received = orders.reduce((sum, order) => sum + Math.min(adjustedOrderTotal(order), Number(order.paid || 0)), 0);
    const pending = Math.max(0, revenue - received);
    const finalized = orders.filter(isOrderFinalized).length;
    const withArt = orders.filter(order => (order.items || []).some(item => item.art && item.art.url)).length;
    const allExpenses = getDtfCosts().map(expenseDisplayRecord);
    const expenses = allExpenses.filter(expense => {
      const date = String(expense.date || '').slice(0, 10);
      return (!range.start || date >= range.start) && (!range.end || date <= range.end);
    });
    const expenseTotal = expenses.reduce((sum, expense) => sum + Number(expense.value || 0), 0);
    const estimatedProfit = revenue - expenseTotal;
    const materialChoices = new Map();
    allExpenses.filter(expense => normalize(expense.category) !== normalize('Anúncio')).forEach(expense => {
      const key = analyticsMaterialKey(expense);
      if (!materialChoices.has(key)) materialChoices.set(key, (expense.item || expense.category || 'Material') + (expense.unit ? ' (' + expense.unit + ')' : ''));
    });
    const materialSelect = $('#pw-analytics-material-comparison');
    let selectedMaterialKey = materialSelect ? materialSelect.value : '';
    if (!materialChoices.has(selectedMaterialKey)) selectedMaterialKey = materialChoices.keys().next().value || '';
    if (materialSelect) {
      materialSelect.innerHTML = materialChoices.size ? Array.from(materialChoices, ([value, label]) => '<option value="' + escapeHtml(value) + '">' + escapeHtml(label) + '</option>').join('') : '<option value="">Nenhum material lançado</option>';
      materialSelect.value = selectedMaterialKey;
    }
    const materialRangeNode = $('#pw-analytics-material-comparison-range');
    if (materialRangeNode) materialRangeNode.textContent = range.start || range.end ? 'Filtro master: ' + (range.start ? dateLabel(range.start) : 'início') + ' até ' + (range.end ? dateLabel(range.end) : 'hoje') : 'Filtro master: todo o histórico';
    const materialComparisonRows = analyticsMaterialComparisonData(allExpenses, orders, range, selectedMaterialKey);
    $('#pw-analytics-summary').textContent = orders.length + ' pedido(s) analisado(s)' + (range.start || range.end ? ' · período de ' + (range.start ? dateLabel(range.start) : 'início') + ' até ' + (range.end ? dateLabel(range.end) : 'hoje') : ' · todo o histórico');
    const kpis = [
      ['Faturamento líquido', money.format(revenue), 'Após tarifas de marketplace e ajustes', '↗'],
      ['Pedidos', String(orders.length), 'Quantidade no período', '▤'],
      ['Ticket médio', money.format(orders.length ? revenue / orders.length : 0), 'Média por pedido', '◇'],
      ['Recebido', money.format(received), revenue ? (received / revenue * 100).toFixed(1).replace('.', ',') + '% do faturamento' : 'Sem movimento', '✓'],
      ['A receber', money.format(pending), pending > 0 ? 'Saldo financeiro pendente' : 'Tudo recebido', '$'],
      ['Despesas', money.format(expenseTotal), expenses.length + ' lançamento(s) no período', '◉'],
      ['Resultado estimado', money.format(estimatedProfit), 'Faturamento líquido menos despesas', estimatedProfit >= 0 ? '↗' : '↘']
    ];
    $('#pw-analytics-kpis').innerHTML = kpis.map((item, index) => '<article class="pw-analytics-kpi pw-kpi-' + index + '"><span>' + item[3] + '</span><small>' + item[0] + '</small><strong>' + escapeHtml(item[1]) + '</strong><p>' + escapeHtml(item[2]) + '</p></article>').join('');
    const salesTypeValues = {};
    orders.forEach(order => {
      const type = order.origin || order.client && order.client.origin || 'Normal';
      const itemTotals = orderItemTotals(order, type);
      if (!salesTypeValues[type]) salesTypeValues[type] = { gross:0, fees:0, discounts:0, net:0, count:0 };
      salesTypeValues[type].gross += itemTotals.gross || Math.max(0, Number(order.total || 0));
      salesTypeValues[type].fees += itemTotals.fees;
      salesTypeValues[type].discounts += Math.max(0, Number(order.discount || 0));
      salesTypeValues[type].net += adjustedOrderTotal(order);
      salesTypeValues[type].count += 1;
    });
    const salesTypeEntries = Object.entries(salesTypeValues).map(([label, values]) => ({ label, value:values.gross, ...values, color:label === 'Mercado Livre' ? '#f59e0b' : (label === 'Shopee' ? '#ee4d2d' : '#475569') })).sort((a,b) => b.value-a.value);
    $('#pw-analytics-platform-share-chart').innerHTML = analyticsBarRows(salesTypeEntries, (value, entry) => 'Bruto: ' + money.format(entry.gross) + ' · Tarifas: ' + money.format(entry.fees) + ' · Descontos: ' + money.format(entry.discounts) + ' · Sua parcela: ' + money.format(entry.net), '#15803d', 'pw-analytics-platform-share-chart');
    const commissionsByOrigin = { 'Mercado Livre':0, 'Shopee':0, other:0 };
    salesTypeEntries.forEach(entry => {
      if (entry.label === 'Mercado Livre' || entry.label === 'Shopee') commissionsByOrigin[entry.label] += entry.fees;
      else commissionsByOrigin.other += entry.fees;
    });
    const commissionShareEntries = [
      { label:'Você (valor líquido)', value:Math.max(0, salesTypeEntries.reduce((sum, entry) => sum + entry.net, 0)), color:'#15803d' },
      { label:'Mercado Livre (tarifas)', value:commissionsByOrigin['Mercado Livre'], color:'#f59e0b' },
      { label:'Shopee (tarifas)', value:commissionsByOrigin.Shopee, color:'#ee4d2d' }
    ];
    if (commissionsByOrigin.other > 0.005) commissionShareEntries.push({ label:'Outros marketplaces (tarifas)', value:commissionsByOrigin.other, color:'#64748b' });
    const customerDiscounts = salesTypeEntries.reduce((sum, entry) => sum + entry.discounts, 0);
    if (customerDiscounts > 0.005) commissionShareEntries.push({ label:'Descontos concedidos', value:customerDiscounts, color:'#be123c' });
    const commissionShareTotal = commissionShareEntries.reduce((sum, item) => sum + item.value, 0);
    let commissionAngle = 0;
    const commissionSlices = commissionShareEntries.filter(item => item.value > 0.005).map(item => { const start = commissionAngle; commissionAngle += commissionShareTotal ? item.value / commissionShareTotal * 360 : 0; return item.color + ' ' + start + 'deg ' + commissionAngle + 'deg'; });
    const commissionMode = analyticsChartMode('pw-analytics-commission-share-chart', 'donut');
    $('#pw-analytics-commission-share-chart').innerHTML = commissionShareTotal > 0.005 ? (commissionMode === 'donut' ? '<div class="pw-analytics-donut-layout pw-analytics-commission-layout"><div class="pw-analytics-donut" style="background:conic-gradient(' + commissionSlices.join(',') + ')"><span>' + escapeHtml(money.format(commissionShareTotal)) + '<small>composição</small></span></div><div class="pw-analytics-legend">' + commissionShareEntries.map(item => { const percentage = commissionShareTotal ? item.value / commissionShareTotal * 100 : 0; return '<div><i style="background:' + item.color + '"></i><span>' + escapeHtml(item.label) + '<small>' + percentage.toFixed(1).replace('.', ',') + '% da composição</small></span><strong>' + escapeHtml(money.format(item.value)) + '</strong></div>'; }).join('') + '</div></div>' : analyticsBarRows(commissionShareEntries, value => money.format(value), '#15803d', 'pw-analytics-commission-share-chart')) : '<div class="pw-analytics-empty">Nenhuma venda encontrada para calcular a divisão.</div>';
    const revenueGranularity = $('#pw-analytics-revenue-granularity') ? $('#pw-analytics-revenue-granularity').value : 'month';
    const trendValues = {};
    orders.forEach(order => {
      const date = String(order.createdDate || '').slice(0, 10);
      const key = date ? (revenueGranularity === 'year' ? date.slice(0, 4) : (revenueGranularity === 'month' ? date.slice(0, 7) : date)) : 'Sem data';
      if (!trendValues[key]) trendValues[key] = { value:0, count:0 };
      trendValues[key].value += adjustedOrderTotal(order); trendValues[key].count += 1;
    });
    const trendLabel = key => {
      if (key === 'Sem data' || revenueGranularity === 'year') return key;
      if (revenueGranularity === 'month') { const [year, month] = key.split('-'); return new Date(Number(year), Number(month) - 1, 1).toLocaleDateString('pt-BR', { month:'short', year:'numeric' }); }
      return dateLabel(key);
    };
    const trendEntries = Object.entries(trendValues).map(([key, data]) => ({ key, ...data, label:trendLabel(key) })).sort((a,b) => a.key === 'Sem data' ? 1 : b.key === 'Sem data' ? -1 : a.key.localeCompare(b.key));
    const maxTrend = Math.max(1, ...trendEntries.map(entry => entry.value));
    const trendMode = analyticsChartMode('pw-analytics-trend', 'vertical');
    $('#pw-analytics-trend').innerHTML = trendEntries.length ? (trendMode === 'line' ? analyticsLineRows(trendEntries, value => money.format(value), '#2563eb') : '<div class="pw-analytics-columns pw-analytics-revenue-columns">' + trendEntries.map(entry => '<div title="' + escapeHtml(entry.label + ' · ' + money.format(entry.value) + ' · ' + entry.count + ' pedido(s)') + '"><span>' + escapeHtml(money.format(entry.value)) + '</span><i style="height:' + Math.max(5, entry.value / maxTrend * 100).toFixed(1) + '%"></i><small>' + escapeHtml(entry.label) + '</small></div>').join('') + '</div>') : '<div class="pw-analytics-empty">Sem vendas no período.</div>';
    $('#pw-analytics-trend-label').textContent = trendEntries.length ? trendEntries.length + ' período(s)' : '';
    const trendRangeNode = $('#pw-analytics-trend-range');
    if (trendRangeNode) trendRangeNode.textContent = range.start || range.end ? 'Filtro master: ' + (range.start ? dateLabel(range.start) : 'início') + ' até ' + (range.end ? dateLabel(range.end) : 'hoje') : 'Filtro master: todo o histórico';

    // Gráfico de perspectiva: vendas reais do mês atual dia a dia + projeção linear para os dias restantes.
    // Sempre usa o mês de hoje, independente do filtro master — mostra onde o mês vai chegar.
    const forecastEl = $('#pw-analytics-forecast');
    if (forecastEl) {
      const nowFc = new Date();
      const yearFc = nowFc.getFullYear();
      const monthFc = nowFc.getMonth(); // 0-indexed
      const todayFc = nowFc.getDate();
      const lastDayFc = new Date(yearFc, monthFc + 1, 0).getDate();
      const monthPrefix = String(yearFc) + '-' + String(monthFc + 1).padStart(2, '0') + '-';
      // Acumula vendas por dia (considera TODOS os pedidos, sem filtro master, pois queremos o mês atual sempre)
      const allOrdersFc = getOrders();
      const dailySales = {};
      allOrdersFc.forEach(order => {
        const date = String(order.createdDate || '').slice(0, 10);
        if (!date.startsWith(monthPrefix.slice(0, 7))) return;
        const day = parseInt(date.slice(8, 10), 10);
        if (!day) return;
        dailySales[day] = (dailySales[day] || 0) + adjustedOrderTotal(order);
      });
      // Média diária com base nos dias que já passaram (inclusive hoje)
      const totalSoFar = Object.values(dailySales).reduce((s, v) => s + v, 0);
      const avgPerDay = todayFc > 0 ? totalSoFar / todayFc : 0;
      // Monta os pontos: dias reais (até hoje) + projeção (a partir de amanhã)
      const realPoints = [];
      const projPoints = [];
      for (let d = 1; d <= lastDayFc; d++) {
        const label = String(d) + '/' + String(monthFc + 1).padStart(2, '0');
        if (d <= todayFc) {
          realPoints.push({ label, value: dailySales[d] || 0 });
          projPoints.push(null); // sem projeção nos dias reais
        } else {
          realPoints.push(null); // sem real nos dias futuros
          projPoints.push({ label, value: Math.round(avgPerDay * 100) / 100 });
        }
      }
      // Todos os dias pra calcular o domínio do SVG
      const allValues = [...realPoints, ...projPoints].filter(Boolean).map(p => p.value);
      const maxFc = Math.max(1, ...allValues);
      const totalDays = lastDayFc;
      const svgW = 600; const svgH = 260; const padL = 20; const padR = 20; const padT = 18; const padB = 30;
      const xFor = (d) => padL + (d - 1) / (totalDays - 1) * (svgW - padL - padR);
      const yFor = (v) => padT + (1 - v / maxFc) * (svgH - padT - padB);
      // Linha real
      const realSegs = realPoints.map((p, i) => p ? (xFor(i + 1).toFixed(1) + ',' + yFor(p.value).toFixed(1)) : null).filter(Boolean);
      const realLine = realSegs.length > 1 ? '<polyline points="' + realSegs.join(' ') + '" fill="none" stroke="#2563eb" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/>' : '';
      // Linha de projeção começa do último ponto real, se existir
      const lastRealIdx = realPoints.reduce((last, p, i) => p !== null ? i : last, -1);
      const projStart = lastRealIdx >= 0 ? (xFor(lastRealIdx + 1).toFixed(1) + ',' + yFor(realPoints[lastRealIdx].value).toFixed(1)) : '';
      const projSegs = projPoints.map((p, i) => p ? (xFor(i + 1).toFixed(1) + ',' + yFor(p.value).toFixed(1)) : null).filter(Boolean);
      const projLine = projSegs.length > 0 ? '<polyline points="' + (projStart ? projStart + ' ' : '') + projSegs.join(' ') + '" fill="none" stroke="#f97316" stroke-width="2" stroke-dasharray="6 4" stroke-linecap="round" stroke-linejoin="round"/>' : '';
      // Linha vertical marcando "hoje"
      const todayX = xFor(todayFc);
      const todayLine = '<line x1="' + todayX.toFixed(1) + '" y1="' + padT + '" x2="' + todayX.toFixed(1) + '" y2="' + (svgH - padB) + '" stroke="#94a3b8" stroke-width="1" stroke-dasharray="3 3"/><text x="' + todayX.toFixed(1) + '" y="' + (padT - 4) + '" text-anchor="middle" fill="#64748b" font-size="10">hoje</text>';
      // Eixo X: só alguns rótulos pra não poluir
      const xLabels = Array.from({ length: totalDays }, (_, i) => i + 1).map(d => '<text x="' + xFor(d).toFixed(1) + '" y="' + (svgH - padB + 14) + '" text-anchor="middle" fill="#64748b" font-size="9">' + d + '</text>').join('');
      // Total projetado — usa dias restantes do mês (não o length de strings SVG)
      const remainingDays = lastDayFc - todayFc;
      const projTotal = totalSoFar + remainingDays * avgPerDay;
      const legendReal = '<span style="display:inline-flex;align-items:center;gap:4px"><b style="display:inline-block;width:16px;height:3px;background:#2563eb;border-radius:2px"></b>Realizado até hoje: ' + money.format(totalSoFar) + '</span>';
      const legendProj = '<span style="display:inline-flex;align-items:center;gap:4px"><b style="display:inline-block;width:16px;height:3px;background:#f97316;border-radius:2px;border-bottom:2px dashed #f97316"></b>Projeção total do mês: ≈ ' + money.format(projTotal) + '</span>';
      const legendHtml = '<div style="display:flex;flex-wrap:wrap;gap:14px;font-size:12px;color:#475569;padding:6px 0 2px">' + legendReal + legendProj + '</div>';
      const forecastMode = analyticsChartMode('pw-analytics-forecast', 'line');
      if (forecastMode === 'vertical') {
        // Versão em barras: mesmos dias/valores do gráfico de linhas, só que
        // como colunas — real em azul, projeção em laranja hachurado.
        const barItems = Array.from({ length: totalDays }, (_, i) => {
          const point = realPoints[i] || projPoints[i];
          if (!point) return '';
          const isProj = !realPoints[i];
          const heightPct = Math.max(5, point.value / maxFc * 100).toFixed(1);
          const style = isProj
            ? 'height:' + heightPct + '%;background:repeating-linear-gradient(45deg,#f97316 0 4px,#fb923c 4px 8px)'
            : 'height:' + heightPct + '%;background:linear-gradient(180deg,#2563eb,#06b6d4)';
          return '<div title="' + escapeHtml(point.label + ' · ' + money.format(point.value) + (isProj ? ' (projeção)' : '')) + (i + 1 === todayFc ? ' · hoje' : '') + '"><i style="' + style + '"></i><small' + (i + 1 === todayFc ? ' style="color:#2563eb;font-weight:700"' : '') + '>' + (i + 1) + '</small></div>';
        }).join('');
        forecastEl.innerHTML = '<div class="pw-analytics-columns pw-analytics-forecast-columns">' + barItems + '</div>' + legendHtml;
      } else {
        forecastEl.innerHTML =
          '<div style="position:relative">' +
          // aspect-ratio (em vez de altura fixa em px) mantém a proporção do
          // viewBox em qualquer largura de container — altura fixa com
          // preserveAspectRatio="none" esticava o gráfico na horizontal em
          // telas largas, deixando os picos achatados e desproporcionais.
          '<svg id="pw-forecast-svg" viewBox="0 0 ' + svgW + ' ' + svgH + '" style="width:100%;aspect-ratio:' + svgW + '/' + svgH + ';height:auto;max-height:260px;overflow:visible;cursor:crosshair" preserveAspectRatio="none" role="img" aria-label="Perspectiva de vendas do mês">' +
          realLine + projLine + todayLine + xLabels +
          // Pontos invisíveis clicáveis em cada dia — circulo transparente maior pra facilitar o toque
          realPoints.map((p, i) => p !== null ? '<circle cx="' + xFor(i + 1).toFixed(1) + '" cy="' + yFor(p.value).toFixed(1) + '" r="10" fill="transparent" data-fc-day="' + (i + 1) + '" data-fc-value="' + p.value.toFixed(2) + '" data-fc-type="real" style="cursor:pointer"/><circle cx="' + xFor(i + 1).toFixed(1) + '" cy="' + yFor(p.value).toFixed(1) + '" r="3.5" fill="#2563eb" pointer-events="none"/>' : '').join('') +
          projPoints.map((p, i) => p !== null ? '<circle cx="' + xFor(i + 1).toFixed(1) + '" cy="' + yFor(p.value).toFixed(1) + '" r="10" fill="transparent" data-fc-day="' + (i + 1) + '" data-fc-value="' + p.value.toFixed(2) + '" data-fc-type="proj" style="cursor:pointer"/><circle cx="' + xFor(i + 1).toFixed(1) + '" cy="' + yFor(p.value).toFixed(1) + '" r="3.5" fill="#f97316" pointer-events="none"/>' : '').join('') +
          // Tooltip (element) — posicionado via JS
          '<g id="pw-forecast-tooltip" style="display:none" pointer-events="none">' +
            '<rect id="pw-forecast-tooltip-bg" rx="5" ry="5" fill="#1e2535" opacity="0.93"/>' +
            '<text id="pw-forecast-tooltip-text" fill="#f1f5f9" font-size="12" font-family="sans-serif"></text>' +
          '</g>' +
          '</svg></div>' + legendHtml;
      }

      // Interatividade: mostrar tooltip SVG ao clicar/hover num ponto
      const svg = $('#pw-forecast-svg');
      const tooltip = $('#pw-forecast-tooltip');
      const tooltipBg = $('#pw-forecast-tooltip-bg');
      const tooltipText = $('#pw-forecast-tooltip-text');
      if (svg && tooltip) {
        const showTooltip = (circle) => {
          const day = circle.dataset.fcDay;
          const value = parseFloat(circle.dataset.fcValue);
          const type = circle.dataset.fcType;
          const cx = parseFloat(circle.getAttribute('cx'));
          const cy = parseFloat(circle.getAttribute('cy'));
          const label = (type === 'proj' ? '📈 Projeção' : '💰 Realizado') + ' dia ' + day;
          const valueStr = money.format(value);
          tooltipText.textContent = '';
          const line1 = document.createElementNS('http://www.w3.org/2000/svg', 'tspan');
          line1.setAttribute('x', '0'); line1.setAttribute('dy', '0'); line1.textContent = label;
          const line2 = document.createElementNS('http://www.w3.org/2000/svg', 'tspan');
          line2.setAttribute('x', '0'); line2.setAttribute('dy', '16'); line2.setAttribute('font-weight', '700'); line2.setAttribute('fill', type === 'proj' ? '#fb923c' : '#93c5fd'); line2.textContent = valueStr;
          tooltipText.appendChild(line1); tooltipText.appendChild(line2);
          const pad = 8;
          const tw = Math.max(valueStr.length, label.length) * 7 + pad * 2;
          const th = 38;
          let tx = cx + 12; let ty = cy - th / 2;
          if (tx + tw > svgW - 10) tx = cx - tw - 12;
          if (ty < 5) ty = 5;
          tooltipText.setAttribute('transform', 'translate(' + (tx + pad) + ',' + (ty + pad + 12) + ')');
          tooltipBg.setAttribute('x', tx); tooltipBg.setAttribute('y', ty); tooltipBg.setAttribute('width', tw); tooltipBg.setAttribute('height', th);
          tooltip.style.display = '';
          // Destaca o ponto
          $$('[data-fc-day]', svg).forEach(c => c.setAttribute('r', '10'));
          circle.setAttribute('r', '14');
        };
        const hideTooltip = () => { tooltip.style.display = 'none'; $$('[data-fc-day]', svg).forEach(c => c.setAttribute('r', '10')); };
        svg.addEventListener('click', event => {
          const circle = event.target.closest('[data-fc-day]');
          if (!circle) { hideTooltip(); return; }
          showTooltip(circle);
        });
        svg.addEventListener('mouseover', event => {
          const circle = event.target.closest('[data-fc-day]');
          if (circle) showTooltip(circle);
        });
        svg.addEventListener('mouseout', event => {
          if (!event.relatedTarget || !event.relatedTarget.closest || !event.relatedTarget.closest('[data-fc-day]')) hideTooltip();
        });
      }
    }
    const statusMap = {}; orders.filter(order => order.status !== 'Entregue').forEach(order => { const key = order.status || 'Não informada'; statusMap[key] = (statusMap[key] || 0) + 1; });
    $('#pw-analytics-status-chart').innerHTML = analyticsBarRows(Object.entries(statusMap).map(([label,value]) => ({ label,value, color:statusDefinition(label).color })).sort((a,b) => b.value-a.value), value => value + ' pedido(s)', '#2563eb', 'pw-analytics-status-chart');
    const productValues = {}; orders.forEach(order => (order.items || []).forEach(item => { const key = item.description || item.code || 'Produto'; productValues[key] = (productValues[key] || 0) + itemFinancialBreakdown(item, order.origin || order.client && order.client.origin || 'Normal').net; }));
    $('#pw-analytics-products-chart').innerHTML = analyticsBarRows(Object.entries(productValues).map(([label,value]) => ({ label,value })).sort((a,b) => b.value-a.value).slice(0,7), value => money.format(value), '#7c3aed', 'pw-analytics-products-chart');
    const paymentValues = {}; orders.forEach(order => (order.payments || []).forEach(payment => { const key = payment.method || 'Não informada'; paymentValues[key] = (paymentValues[key] || 0) + Number(payment.value || 0); }));
    const paymentEntries = Object.entries(paymentValues).map(([label,value], index) => ({ label,value,color:['#2563eb','#16a34a','#f59e0b','#7c3aed','#db2777','#0891b2'][index % 6] })).sort((a,b) => b.value-a.value);
    const paymentTotal = paymentEntries.reduce((sum,item) => sum+item.value,0);
    let angle = 0; const slices = paymentEntries.map(item => { const start=angle; angle += paymentTotal ? item.value/paymentTotal*360 : 0; return item.color+' '+start+'deg '+angle+'deg'; });
    const paymentMode = analyticsChartMode('pw-analytics-payments-chart', 'donut');
    $('#pw-analytics-payments-chart').innerHTML = paymentEntries.length ? (paymentMode === 'donut' ? '<div class="pw-analytics-donut-layout"><div class="pw-analytics-donut" style="background:conic-gradient(' + slices.join(',') + ')"><span>' + escapeHtml(money.format(paymentTotal)) + '<small>recebido</small></span></div><div class="pw-analytics-legend">' + paymentEntries.map(item => '<div><i style="background:'+item.color+'"></i><span>'+escapeHtml(item.label)+'<small>'+(item.value/paymentTotal*100).toFixed(1).replace('.',',')+'% do total</small></span><strong>'+escapeHtml(money.format(item.value))+'</strong></div>').join('') + '</div></div>' : analyticsBarRows(paymentEntries, value => money.format(value), '#2563eb', 'pw-analytics-payments-chart')) : '<div class="pw-analytics-empty">Nenhum pagamento registrado.</div>';
    const clientValues = {}; orders.forEach(order => { const key = order.client && order.client.name || 'Não identificado'; clientValues[key]=(clientValues[key]||0)+adjustedOrderTotal(order); });
    $('#pw-analytics-clients-chart').innerHTML = analyticsBarRows(Object.entries(clientValues).map(([label,value]) => ({ label,value })).sort((a,b)=>b.value-a.value).slice(0,7), value => money.format(value), '#ea580c', 'pw-analytics-clients-chart');
    const receivableValues = {}; orders.forEach(order => { const key = order.client && order.client.name || 'Não identificado'; const balance = Math.max(0, adjustedOrderTotal(order) - Number(order.paid || 0)); if (balance > 0.005) receivableValues[key] = (receivableValues[key] || 0) + balance; });
    $('#pw-analytics-receivables-chart').innerHTML = analyticsBarRows(Object.entries(receivableValues).map(([label,value]) => ({ label,value })).sort((a,b)=>b.value-a.value).slice(0,7), value => money.format(value), '#dc2626', 'pw-analytics-receivables-chart');
    const expenseCategoryValues = {}, expenseSupplierValues = {};
    expenses.forEach(expense => {
      const categoryName = dtfCategoryName(expense.category || 'Outro');
      const supplierName = expense.supplier || 'Não informado';
      expenseCategoryValues[categoryName] = (expenseCategoryValues[categoryName] || 0) + Number(expense.value || 0);
      expenseSupplierValues[supplierName] = (expenseSupplierValues[supplierName] || 0) + Number(expense.value || 0);
    });
    $('#pw-analytics-expense-category-chart').innerHTML = analyticsBarRows(Object.entries(expenseCategoryValues).map(([label,value]) => ({ label,value })).sort((a,b)=>b.value-a.value), value => money.format(value), '#b45309', 'pw-analytics-expense-category-chart');
    $('#pw-analytics-expense-supplier-chart').innerHTML = analyticsBarRows(Object.entries(expenseSupplierValues).map(([label,value]) => ({ label,value })).sort((a,b)=>b.value-a.value).slice(0,7), value => money.format(value), '#7c3aed', 'pw-analytics-expense-supplier-chart');
    $('#pw-analytics-ad-supplier-chart').innerHTML = analyticsSupplierDonut(expenses, 'ads', 'pw-analytics-ad-supplier-chart');
    $('#pw-analytics-ad-date-chart').innerHTML = analyticsAdDateBars(expenses, range);
    $('#pw-analytics-material-comparison-chart').innerHTML = analyticsMaterialComparisonRows(materialComparisonRows, 'pw-analytics-material-comparison-chart');
    $('#pw-analytics-profit-chart').innerHTML = analyticsBarRows([{ label:'Faturamento', value:revenue, color:'#2563eb' }, { label:'Despesas', value:expenseTotal, color:'#b45309' }, { label:'Resultado estimado', value:Math.abs(estimatedProfit), color:estimatedProfit >= 0 ? '#15803d' : '#dc2626' }], (value, entry) => entry.label === 'Resultado estimado' ? money.format(estimatedProfit) : money.format(value), '#15803d', 'pw-analytics-profit-chart');
    const gauge = (label,value,detail,color) => '<div class="pw-analytics-gauge" style="--gauge:'+Math.max(0,Math.min(100,value))+'%;--gauge-color:'+color+'"><i><span>'+Math.round(value)+'%</span></i><strong>'+escapeHtml(label)+'</strong><small>'+escapeHtml(detail)+'</small></div>';
    const delivered = orders.filter(order => order.status === 'Entregue').length;
    const late = orders.filter(order => order.status === 'Entregue' && order.actualDelivery && order.requestedDelivery && order.actualDelivery > order.requestedDelivery).length;
    const productionCriticalOrders = orders.filter(order => !isOrderFinalized(order) && orderIsBeforeProductionReady(order));
    const awaitingDeliveryOrders = orders.filter(order => order.status === 'Aguardando entrega');
    const finalizationEntries = [
      { label:'Finalizados', value:finalized, color:'#16a34a' },
      { label:'Em aberto', value:Math.max(0, orders.length - finalized), color:'#f59e0b' }
    ];
    $('#pw-analytics-finalization-chart').innerHTML = orders.length ? analyticsBarRows(finalizationEntries, (value) => value + ' pedido(s) · ' + (orders.length ? (value / orders.length * 100).toFixed(1).replace('.', ',') : '0,0') + '%', '#2563eb', 'pw-analytics-finalization-chart') : '<div class="pw-analytics-empty">Nenhum pedido encontrado para os filtros selecionados.</div>';
    let productionCriticalAmount = 0; let awaitingDeliveryAmount = 0; let pendingPaymentCount = 0; let pendingPaymentAmount = 0;
    orders.forEach(order => {
      if (!isOrderFinalized(order) && orderIsBeforeProductionReady(order)) productionCriticalAmount += adjustedOrderTotal(order);
      if (order.status === 'Aguardando entrega') awaitingDeliveryAmount += adjustedOrderTotal(order);
      const balance = Math.max(0, adjustedOrderTotal(order) - Number(order.paid || 0));
      if (order.status === 'Entregue' && balance > 0.005) { pendingPaymentCount += 1; pendingPaymentAmount += balance; }
    });
    const pendingEntries = [
      { label:'Produção crítica', value:productionCriticalOrders.length, amount:productionCriticalAmount, color:'#dc2626' },
      { label:'Aguardando entrega', value:awaitingDeliveryOrders.length, amount:awaitingDeliveryAmount, color:'#0891b2' },
      { label:'Entregues a receber', value:pendingPaymentCount, amount:pendingPaymentAmount, color:'#d97706' }
    ];
    $('#pw-analytics-pending-chart').innerHTML = orders.length ? analyticsBarRows(pendingEntries, (value, entry) => value + ' pedido(s) · ' + money.format(entry.amount), '#dc2626', 'pw-analytics-pending-chart') : '<div class="pw-analytics-empty">Nenhum pedido encontrado para os filtros selecionados.</div>';
    $('#pw-analytics-operation-chart').innerHTML = gauge('Pedidos finalizados', orders.length ? finalized/orders.length*100 : 0, finalized+' de '+orders.length, '#16a34a') + gauge('Pedidos com arte', orders.length ? withArt/orders.length*100 : 0, withArt+' de '+orders.length, '#7c3aed') + gauge('Valores recebidos', revenue ? received/revenue*100 : 0, money.format(received)+' de '+money.format(revenue), '#2563eb') + gauge('Entregas registradas', orders.length ? delivered/orders.length*100 : 0, delivered+' de '+orders.length, '#0891b2');
    $('#pw-analytics-delivery-chart').innerHTML = analyticsBarRows([{label:'Produção crítica',value:productionCriticalOrders.length,color:'#dc2626'},{label:'Aguardando entrega',value:awaitingDeliveryOrders.length,color:'#0891b2'},{label:'Entregues no prazo',value:Math.max(0, delivered - late),color:'#15803d'},{label:'Entregues com atraso',value:late,color:'#dc2626'}], value => value + ' pedido(s)', '#2563eb', 'pw-analytics-delivery-chart');
  }

  const systemViewContext = {
    dashboard: { group: 'Painel', title: 'Painel de controle', description: 'Visão geral dos pedidos, prazos e indicadores do sistema.', icon: '⌂' },
    analytics: { group: 'Gráficos', title: 'Central de gráficos', description: 'Análises visuais e filtráveis dos resultados e da operação.', icon: '◫' },
    order: { group: 'Cadastro', title: 'Cadastro de pedidos', description: 'Inclua um novo pedido ou altere os dados do pedido selecionado.', icon: '▤' },
    orders: { group: 'Relatórios', title: 'Relatório de pedidos', description: 'Consulte, filtre e acompanhe os pedidos cadastrados.', icon: '⌕' },
    clients: { group: 'Relatórios', title: 'Relatório de clientes', description: 'Consulte os clientes cadastrados e seus respectivos registros.', icon: '♙' },
    'monthly-closing': { group: 'Relatórios', title: 'Fechamento mensal', description: 'Acompanhe e receba os pedidos acumulados dos clientes com cobrança mensal.', icon: '$' },
    products: { group: 'Relatórios · Estoque', title: 'Relatório de produtos', description: 'Consulte produtos, valores, variações e situação do cadastro.', icon: '▣' },
    categories: { group: 'Relatórios · Estoque', title: 'Relatório de categorias', description: 'Consulte as categorias utilizadas na organização dos produtos.', icon: '⌑' },
    units: { group: 'Relatórios · Estoque', title: 'Relatório de unidades de venda', description: 'Consulte as unidades utilizadas na comercialização dos produtos.', icon: '↔' },
    'order-origins': { group: 'Relatórios · Estoque', title: 'Relatório de origens do pedido', description: 'Consulte as origens disponíveis para identificar pedidos diretos e de marketplaces.', icon: '◈' },
    suppliers: { group: 'Relatórios', title: 'Relatório de fornecedores', description: 'Consulte contatos e dados dos fornecedores cadastrados.', icon: '♜' },
    'payment-methods': { group: 'Relatórios', title: 'Relatório de formas de pagamento', description: 'Consulte as formas de pagamento disponíveis no sistema.', icon: '$' },
    arts: { group: 'Relatórios', title: 'Relatório de artes', description: 'Pesquise, visualize, baixe e prepare as artes aprovadas dos pedidos.', icon: '▧' },
    'dtf-simulator': { group: 'Relatórios', title: 'Simulador DTF UV', description: 'Simule o valor de uma arte DTF UV pelo PDF, pela altura, pela quantidade de adesivos ou pelo tamanho desejado.', icon: '📐' },
    'marketplace-ml': { group: 'Relatórios / Marketplace', title: 'Mercado Livre', description: 'Perguntas e mensagens pendentes, financeiro estimado e reputação da conta no Mercado Livre.', icon: '🛒' },
    'marketplace-shopee': { group: 'Relatórios / Marketplace', title: 'Shopee', description: 'Status da conexão e pedidos da Shopee.', icon: '🛍' },
    'dtf-costs': { group: 'Cadastro / Despesas', title: 'Cadastros / Despesas', description: 'Registre insumos, anúncios, fornecedores e demais gastos da operação.', icon: '◉' },
    'dtf-cost-report': { group: 'Relatórios', title: 'Relatório de despesas', description: 'Analise custos, anúncios, consumo e gastos da operação.', icon: '◉' },
    'dtf-items': { group:'Relatórios / Despesas', title:'Insumo, peça ou serviço', description:'Consulte os cadastros utilizados no campo Insumo, peça ou serviço das despesas.', icon:'▦' },
    'dtf-categories': { group: 'Cadastro / Despesas', title: 'Categorias', description: 'Gerencie as categorias das despesas.', icon: '≡' },
    'dtf-units': { group: 'Cadastro / Despesas', title: 'Unidades sugeridas', description: 'Gerencie as unidades sugeridas para os itens.', icon: '↔' },
    'dtf-list': { group: 'Relatórios / Despesas', title: 'Despesas / Listagem', description: 'Consulte todas as despesas registradas e filtre o período desejado.', icon: '☷' },
    'dtf-category-report': { group: 'Relatórios / Despesas', title: 'Relatório de categorias de despesas', description: 'Consulte as categorias usadas no cadastro de despesas.', icon: '≡' },
    'dtf-movement-report': { group:'Relatórios / Despesas', title:'Movimentação', description:'Cadastros utilizados no campo Movimentação da despesa.', icon:'⇄' },
    nfe: { group: 'Cadastros', title: 'Cadastro fiscal da NF-e', description: 'Configure os dados padrão usados na preparação, assinatura e autorização de NF-e.', icon: '▤' },
    'nfe-pending': { group: 'Relatórios', title: 'NF-e — Marketplace', description: 'Pedidos de Mercado Livre e Shopee. Gere o PDF para emissão manual e anexe o XML após emitir.', icon: '📄' },
    trash: { group: 'Administração', title: 'Lixeira', description: 'Consulte, restaure ou elimine definitivamente registros excluídos.', icon: '♲' },
    settings: { group: 'Administração', title: 'Configurações', description: 'Defina permissões, recursos e preferências gerais do sistema.', icon: '⚙' }
  };

  function updateSystemViewContext(viewName) {
    const context = viewName === 'order' && editingOrderNumber
      ? { group: 'Edição', title: 'Edição de pedidos', description: 'Altere os dados do pedido selecionado e salve para gravar as mudanças.', icon: '✎' }
      : (systemViewContext[viewName] || systemViewContext.dashboard);
    const host = $('#pw-view-context');
    if (!host) return;
    $('#pw-view-context-group').textContent = context.group;
    $('#pw-view-context-title').textContent = context.title;
    $('#pw-view-context-description').textContent = context.description;
    $('#pw-view-context-icon').textContent = context.icon;
    host.dataset.currentView = viewName;
    const liveControl = $('#pw-dashboard-live-control');
    if (liveControl) liveControl.hidden = viewName !== 'dashboard';
  }

  function showSystemView(viewName) {
    if (['dtf-unit-report', 'dtf-units'].includes(viewName)) viewName = 'units';
    if (['settings', 'nfe', 'dtf-costs', 'dtf-cost-report', 'dtf-items', 'dtf-categories', 'dtf-units', 'dtf-list', 'dtf-category-report', 'dtf-unit-report', 'dtf-movement-report'].includes(viewName) && !userIsAdministrator(currentUser)) {
      showMessage('Apenas administradores podem acessar esta área.', 'error');
      return;
    }
    const accessKey = menuKeyForView(viewName);
    if (accessKey && !canAccessMenu(accessKey)) {
      showMessage('O administrador bloqueou o acesso deste usuário a este menu.', 'error');
      return false;
    }
    const activeView = $('.pw-system-view.pw-active');
    if (activeView && activeView.dataset.view === 'order' && viewName !== 'order' && orderHasUnsavedChanges() && !bypassOrderUnsavedPrompt) {
      openUnsavedChoice('pw-order-form', () => showSystemView(viewName));
      return false;
    }
    $$('.pw-system-view').forEach(view => view.classList.toggle('pw-active', view.dataset.view === viewName));
    $$('[data-system-view]').forEach(button => button.classList.toggle('pw-active', button.dataset.systemView === viewName));
    updateSystemViewContext(viewName);
    recordMenuVisit(viewName);
    renderQuickAccessBar(viewName);
    const editingNote = $('#pw-editing-note');
    if (editingNote) editingNote.hidden = viewName !== 'order';
    if (viewName === 'dashboard') dashboardViewMode = userIsAdministrator(currentUser) ? 'normal' : 'collaborator';
    const bulkKindForView = {
      orders: 'order', clients: 'client', products: 'product', categories: 'category', units: 'unit', 'order-origins': 'orderOrigin',
      suppliers: 'supplier', 'payment-methods': 'paymentMethod', 'dtf-category-report': 'dtfCategory',
      'dtf-movement-report': 'dtfMovement', 'dtf-items': 'dtfItem', 'dtf-list': 'dtfCost'
    }[viewName];
    if (bulkKindForView) {
      bulkSelections[bulkKindForView] = [];
      $$('[data-row-select="' + bulkKindForView + '"]').forEach(input => { input.checked = false; });
      const selectAll = $('[data-select-all="' + bulkKindForView + '"]');
      if (selectAll) { selectAll.checked = false; selectAll.indeterminate = false; }
      updateBulkToolbar(bulkKindForView);
    }
    // Mostra o que já está em cache na hora (sem tela em branco) e, em
    // seguida, busca a versão mais recente do servidor sozinho — pedido
    // explícito: entrar de novo nesse relatório já deve vir atualizado.
    if (viewName === 'orders') { renderOrdersConsultation(); refreshOrdersReport(); }
    if (viewName === 'clients') renderClientsConsultation();
    if (viewName === 'monthly-closing') renderMonthlyClosingReport();
    if (viewName === 'products') renderProductsConsultation();
    if (viewName === 'categories') renderRegistryConsultation('category');
    if (viewName === 'units') renderRegistryConsultation('unit');
    if (viewName === 'order-origins') renderRegistryConsultation('orderOrigin');
    if (viewName === 'suppliers') renderRegistryConsultation('supplier');
    if (viewName === 'payment-methods') renderRegistryConsultation('paymentMethod');
    if (viewName === 'arts') renderArtsReport();
    if (viewName === 'nfe') renderNfeSettings();
    if (viewName === 'nfe-pending') { renderNfePendingOrders(); markNfePendingNotificationsSeen(); markNfeReadyNotificationsSeen(); }
    if (viewName === 'preferences') initPreferencesView();
    stopNfePendingLivePolling();
    stopMelhorEnvioBalancePolling();
    stopMelhorEnvioTrackingAutoRefresh();
    if (viewName === 'nfe-pending') startNfePendingLivePolling();
    if (viewName === 'shipping-label') { resetFrenetLabel(); loadMelhorEnvioBalance('pw-me'); startMelhorEnvioBalancePolling('pw-me'); }
    if (viewName === 'shipping-history') { renderMelhorEnvioLabelsHistory(); loadMelhorEnvioBalance('pw-me-history'); startMelhorEnvioBalancePolling('pw-me-history'); startMelhorEnvioTrackingAutoRefresh(); }

    if (viewName === 'dtf-costs') renderDtfCostRegistry();
    if (viewName === 'dtf-items') { renderDtfCatalog(); }
    if (viewName === 'dtf-categories') { renderDtfCategories(); }
    if (viewName === 'dtf-category-report') { renderDtfExpenseReport('category'); }
    if (viewName === 'dtf-movement-report') renderDtfExpenseReport('movement');
    if (viewName === 'dtf-list') { const s = $('[data-view="dtf-list"]'); if (s) s.dataset.listTab = dtfListTab; renderDtfExpenseReport('cost'); }
    if (viewName === 'dtf-cost-report') renderDtfCostReport();
    stopMlMessagesAutoRefresh();
    if (viewName === 'marketplace-ml') {
      // Veio do ícone de aviso (⚠ piscando)? Abre direto na aba da causa do
      // aviso — mensagem (pergunta/pós-venda) leva pra "Mensagens", pedido
      // novo leva pra "Financeiro". Entrada normal pelo menu continua em
      // "Financeiro" (aba padrão).
      const notifyButton = $('#pw-ml-notify-button');
      const notifyReason = (notifyButton && !notifyButton.hidden) ? notifyButton.dataset.mlNotifyReason : '';
      activateMarketplaceTab(notifyReason === 'mensagens' ? 'mensagens' : 'financeiro');
      if (userIsAdministrator(currentUser)) markMlNotificationsSeen();
    }
    if (viewName === 'marketplace-shopee') {
      activateShopeeTab('status');
      if (userIsAdministrator(currentUser)) markShopeeNotificationsSeen();
    }
    if (viewName === 'analytics') renderAnalytics();
    if (viewName === 'dashboard') { renderDashboard(); refreshDashboardLive(); }
    if (viewName === 'trash') renderTrash();
    if (viewName === 'settings') renderSettings();
    root.scrollIntoView({ behavior: 'smooth', block: 'start' });
    try { sessionStorage.setItem('pw_last_view', viewName); } catch(e) {}
    return true;
  }

  // ── NF-e Marketplace ─────────────────────────────────────────────────────

  // Valida campos obrigatórios para emissão de NF-e num pedido marketplace.
  // Retorna array de strings descrevendo o que falta (vazio = tudo ok).
  function validateMarketplaceNfe(clientRecord, orderItems) {
    const issues = [];
    const addr = clientRecord.address || {};
    if (!(clientRecord.name || '').trim()) issues.push('Nome do cliente');
    if (!(clientRecord.document || '').replace(/\D/g, '')) issues.push('CPF / CNPJ do cliente');
    if (!(addr.cep || '').replace(/\D/g, '')) issues.push('CEP do endereço');
    if (!(addr.street || '').trim()) issues.push('Logradouro do endereço');
    if (!(addr.number || '').trim()) issues.push('Número do endereço');
    if (!(addr.neighborhood || '').trim()) issues.push('Bairro do endereço');
    if (!(addr.city || '').trim()) issues.push('Cidade do endereço');
    if (!(addr.state || '').trim()) issues.push('UF do endereço');
    if (!orderItems.length) {
      issues.push('Ao menos um item no pedido');
    } else {
      if (orderItems.some(item => !item.description.trim())) issues.push('Descrição de todos os itens');
      if (orderItems.some(item => !Number(item.salePrice || item.unitPrice || 0))) issues.push('Preço de todos os itens (obrigatório para NF-e)');
    }
    return issues;
  }

  // Modal de aviso de dados incompletos para NF-e.
  // Retorna Promise<'save'|'cancel'>.
  function promptNfeValidation(issues) {
    return new Promise(resolve => {
      const overlay = document.createElement('div');
      overlay.id = 'pw-nfe-validation-overlay';
      overlay.style.cssText = 'position:fixed;inset:0;z-index:2147483600;background:rgba(0,0,0,.48);display:flex;align-items:center;justify-content:center;padding:20px';
      const listHtml = issues.map(i => '<li>' + escapeHtml(i) + '</li>').join('');
      overlay.innerHTML = '<div class="pw-nfev-box"><div class="pw-nfev-header"><span class="pw-nfev-icon">⚠️</span><h3 class="pw-nfev-title">Dados incompletos para NF-e</h3><button class="pw-nfev-close" type="button" aria-label="Fechar">✕</button></div><div class="pw-nfev-body"><p>Os seguintes dados necessários para emissão de NF-e estão faltando ou inválidos neste pedido de marketplace:</p><ul class="pw-nfev-list">' + listHtml + '</ul><p class="pw-nfev-hint">Você pode salvar mesmo assim e corrigir depois, ou voltar e preencher os campos agora.</p></div><div class="pw-nfev-actions"><button class="pw-btn pw-btn-primary pw-nfev-save" type="button">Salvar mesmo assim</button><button class="pw-btn pw-btn-outline pw-nfev-cancel" type="button">Voltar e corrigir</button></div></div>';
      document.body.appendChild(overlay);
      const cleanup = () => overlay.remove();
      overlay.querySelector('.pw-nfev-save').addEventListener('click', () => { cleanup(); resolve('save'); });
      overlay.querySelector('.pw-nfev-cancel').addEventListener('click', () => { cleanup(); resolve('cancel'); });
      overlay.querySelector('.pw-nfev-close').addEventListener('click', () => { cleanup(); resolve('cancel'); });
      overlay.addEventListener('click', e => { if (e.target === overlay) { cleanup(); resolve('cancel'); } });
    });
  }

  // Ícone HTML da plataforma de marketplace.
  function nfePlatformIcon(origin) {
    if (/mercado\s*livre/i.test(origin)) {
      return '<span class="pw-client-origin-dot pw-origin-mercado-livre pw-tooltip" data-tooltip="Mercado Livre" aria-label="Mercado Livre">🤝</span>';
    }
    if (/shopee/i.test(origin)) {
      return '<span class="pw-client-origin-dot pw-origin-shopee pw-tooltip" data-tooltip="Shopee" aria-label="Shopee"><span class="pw-shopee-bag">S</span></span>';
    }
    return escapeHtml(origin);
  }

  // Renderiza a tabela de pedidos marketplace no relatório NF-e.
  // Exibe apenas pedidos ainda não finalizados (status ≠ Entregue).
  async function renderNfePendingOrders() {
    const body = $('#pw-nfe-pending-body');
    if (!body) return;
    const orders = getOrders().filter(order =>
      orderOriginIsMarketplace(order.origin || (order.client && order.client.origin) || '') &&
      !isOrderFinalized(order)
    );
    const sorted = orders.slice().sort((a, b) => (parseInt(b.orderNumber, 10) || 0) - (parseInt(a.orderNumber, 10) || 0));
    const genPdfBtn = $('#pw-nfe-gen-pdf');
    if (genPdfBtn) genPdfBtn.disabled = true;
    if (!sorted.length) {
      body.innerHTML = '<tr><td colspan="10" class="pw-table-empty">Nenhum pedido de marketplace em aberto encontrado.</td></tr>';
      return;
    }
    body.innerHTML = sorted.map(order => {
      const client = order.client || {};
      const orderItems = order.items || [];
      const origin = order.origin || (client.origin) || '';
      const hasXml = !!(order.nfeXml && order.nfeXml.filename);
      const xmlBy = hasXml && order.nfeXml.by ? order.nfeXml.by : '';
      const xmlAt = hasXml && order.nfeXml.at ? new Date(order.nfeXml.at).toLocaleString('pt-BR', {day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'}) : '';
      const xmlAttachedTitle = ['XML de NF-e anexado', xmlBy && 'por ' + xmlBy, xmlAt && 'em ' + xmlAt].filter(Boolean).join(' ');
      const nfeStatus = hasXml
        ? '<span class="pw-nfe-status pw-nfe-attached" title="' + escapeHtml(xmlAttachedTitle) + '">✅ XML anexado</span>'
        : '<span class="pw-nfe-status pw-nfe-pending-badge">⏳ Aguardando XML</span>';
      const xmlDownload = (() => { try { const d = JSON.parse(window.localStorage.getItem('pw_nfe_xml_downloads') || '{}'); return d[String(order.orderNumber)] || null; } catch (e) { return null; } })();
      const dlBy = xmlDownload && xmlDownload.by ? xmlDownload.by : '';
      const dlAt = xmlDownload && xmlDownload.at ? new Date(xmlDownload.at).toLocaleString('pt-BR', {day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'}) : '';
      const dlTitle = xmlDownload ? escapeHtml(['Baixado', dlBy && 'por ' + dlBy, dlAt && 'em ' + dlAt].filter(Boolean).join(' ')) : '';
      const dlLabel = xmlDownload ? '✓ Baixado' : '⬇ Baixar XML';
      const xmlAction = hasXml
        ? '<button class="pw-btn pw-btn-soft pw-btn-xs pw-nfe-download-xml" data-order="' + escapeHtml(order.orderNumber) + '" type="button"' + (dlTitle ? ' title="' + dlTitle + '"' : '') + '>' + dlLabel + '</button> <button class="pw-btn pw-btn-danger pw-btn-xs pw-nfe-remove-xml" data-order="' + escapeHtml(order.orderNumber) + '" type="button" title="Remover XML">✕</button>'
        : '<label class="pw-btn pw-btn-soft pw-btn-xs pw-nfe-upload-label"><input type="file" class="pw-nfe-xml-input" data-order="' + escapeHtml(order.orderNumber) + '" accept=".xml,application/xml,text/xml" style="display:none">📎 Anexar XML</label>';
      const prodSummary = escapeHtml(orderItems.slice(0, 2).map(i => i.description || '').join(', ') + (orderItems.length > 2 ? '…' : ''));
      return '<tr data-nfe-order="' + escapeHtml(order.orderNumber) + '">' +
        '<td class="pw-select-cell"><input type="checkbox" class="pw-nfe-row-check" data-order="' + escapeHtml(order.orderNumber) + '"></td>' +
        '<td class="pw-nfe-platform-cell">' + nfePlatformIcon(origin) + '</td>' +
        '<td>' + escapeHtml(order.orderNumber) + '</td>' +
        '<td>' + escapeHtml(dateLabel(order.createdDate || '')) + '</td>' +
        '<td>' + escapeHtml(client.name || '') + '</td>' +
        '<td>' + escapeHtml(client.document || '') + '</td>' +
        '<td class="pw-nfe-products-cell" title="' + escapeHtml(orderItems.map(i => i.description || '').join(', ')) + '">' + prodSummary + '</td>' +
        '<td>' + escapeHtml(money.format(Number(order.total || 0))) + '</td>' +
        '<td>' + nfeStatus + '</td>' +
        '<td class="pw-nfe-actions-cell">' + xmlAction + '</td>' +
        '</tr>';
    }).join('');
    $$('.pw-nfe-xml-input', body).forEach(input => input.addEventListener('change', nfePendingHandleXmlUpload));
    $$('.pw-nfe-download-xml', body).forEach(btn => btn.addEventListener('click', nfePendingHandleXmlDownload));
    $$('.pw-nfe-remove-xml', body).forEach(btn => btn.addEventListener('click', nfePendingHandleXmlRemove));
    $$('.pw-nfe-row-check', body).forEach(input => input.addEventListener('change', nfePendingUpdateBulk));
    const selectAll = $('#pw-nfe-select-all');
    if (selectAll) {
      selectAll.checked = false;
      selectAll.replaceWith(selectAll.cloneNode(true)); // remove old listeners
      const fresh = $('#pw-nfe-select-all');
      if (fresh) fresh.addEventListener('change', () => {
        $$('.pw-nfe-row-check', body).forEach(c => { c.checked = fresh.checked; });
        nfePendingUpdateBulk();
      });
    }
  }

  function nfePendingUpdateBulk() {
    const checked = $$('.pw-nfe-row-check:checked');
    const genPdfBtn = $('#pw-nfe-gen-pdf');
    if (genPdfBtn) genPdfBtn.disabled = checked.length === 0;
  }

  async function nfePendingHandleXmlUpload(event) {
    const input = event.target;
    const orderNumber = input.dataset.order;
    const file = input.files && input.files[0];
    if (!file || !orderNumber) return;
    if (!file.name.toLowerCase().endsWith('.xml')) { showMessage('Selecione um arquivo .xml.', 'error'); return; }
    const label = input.closest('label');
    if (label) { label.textContent = '⏳ Enviando…'; }
    try {
      const form = new FormData();
      form.append('action', 'pw_personalizados_nfe_upload_xml');
      form.append('nonce', SERVER.nonce);
      form.append('order_number', orderNumber);
      form.append('xml_file', file);
      const response = await fetch(SERVER.ajaxUrl, { method: 'POST', credentials: 'same-origin', body: form });
      const result = await response.json();
      if (!result || !result.success) throw new Error((result && result.data && result.data.message) || 'Falha no envio.');
      showMessage('XML anexado ao pedido ' + orderNumber + '.', 'success');
      await refreshSharedStorageSnapshot();
      renderNfePendingOrders();
    } catch (err) {
      showMessage('Erro ao enviar XML: ' + (err.message || 'tente novamente.'), 'error');
      renderNfePendingOrders();
    }
  }

  function nfePendingHandleXmlDownload(event) {
    const btn = event.currentTarget;
    const orderNumber = btn.dataset.order;
    if (!orderNumber || !SERVER.ajaxUrl || !SERVER.nonce) return;
    const url = SERVER.ajaxUrl + '?action=pw_personalizados_nfe_download_xml&nonce=' + encodeURIComponent(SERVER.nonce) + '&order_number=' + encodeURIComponent(orderNumber);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'nfe-' + orderNumber + '.xml';
    document.body.appendChild(a);
    a.click();
    a.remove();
    try {
      const downloads = JSON.parse(window.localStorage.getItem('pw_nfe_xml_downloads') || '{}');
      downloads[String(orderNumber)] = { by: (SERVER.currentUser && SERVER.currentUser.display) || '', at: new Date().toISOString() };
      window.localStorage.setItem('pw_nfe_xml_downloads', JSON.stringify(downloads));
    } catch (e) {}
    renderNfePendingOrders();
  }

  async function nfePendingHandleXmlRemove(event) {
    const btn = event.currentTarget;
    const orderNumber = btn.dataset.order;
    if (!orderNumber) return;
    if (!confirm('Remover o XML de NF-e do pedido ' + orderNumber + '?\nEsta ação não pode ser desfeita.')) return;
    btn.disabled = true;
    try {
      const form = new URLSearchParams();
      form.append('action', 'pw_personalizados_nfe_remove_xml');
      form.append('nonce', SERVER.nonce);
      form.append('order_number', orderNumber);
      const response = await fetch(SERVER.ajaxUrl, { method: 'POST', credentials: 'same-origin', headers: { 'Content-Type': 'application/x-www-form-urlencoded; charset=UTF-8' }, body: form.toString() });
      const result = await response.json();
      if (!result || !result.success) throw new Error((result && result.data && result.data.message) || 'Falha ao remover.');
      showMessage('XML removido do pedido ' + orderNumber + '.', 'success');
      await refreshSharedStorageSnapshot();
      renderNfePendingOrders();
    } catch (err) {
      showMessage('Erro ao remover XML: ' + (err.message || 'tente novamente.'), 'error');
      btn.disabled = false;
    }
  }

  async function nfePendingGeneratePdf() {
    const checked = Array.from($$('.pw-nfe-row-check:checked')).map(c => c.dataset.order).filter(Boolean);
    if (!checked.length) { showMessage('Selecione ao menos um pedido.', 'error'); return; }
    const btn = $('#pw-nfe-gen-pdf');
    if (btn) btn.disabled = true;
    try {
      const form = new URLSearchParams();
      form.append('action', 'pw_personalizados_nfe_generate_pdf');
      form.append('nonce', SERVER.nonce);
      checked.forEach(n => form.append('order_numbers[]', n));
      const response = await fetch(SERVER.ajaxUrl, { method: 'POST', credentials: 'same-origin', headers: { 'Content-Type': 'application/x-www-form-urlencoded; charset=UTF-8' }, body: form.toString() });
      const result = await response.json();
      if (!result || !result.success || !result.data || !result.data.pdf) throw new Error((result && result.data && result.data.message) || 'Falha ao gerar PDF.');
      const bytes = Uint8Array.from(atob(result.data.pdf), c => c.charCodeAt(0));
      const blob = new Blob([bytes], { type: 'application/pdf' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = result.data.filename || 'nfe-pedidos.pdf';
      document.body.appendChild(a);
      a.click();
      a.remove();
      URL.revokeObjectURL(url);
    } catch (err) {
      showMessage('Erro ao gerar PDF: ' + (err.message || 'tente novamente.'), 'error');
    } finally {
      if (btn) btn.disabled = false;
      nfePendingUpdateBulk();
    }
  }

  function dateLabel(value) {
    if (!value) return '—';
    const date = new Date(value.length === 10 ? value + 'T12:00:00' : value);
    return Number.isNaN(date.getTime()) ? String(value) : date.toLocaleDateString('pt-BR');
  }

  function daysUntil(value) {
    if (!value) return null;
    const target = new Date(value + 'T12:00:00');
    const today = new Date(localDateValue(new Date()) + 'T12:00:00');
    return Math.ceil((target - today) / 86400000);
  }

  function orderIsBeforeProductionReady(order) {
    const currentStatusIndex = statusIndex(order && order.status || 'Criação da arte');
    const productionReadyIndex = statusIndex('Produzido');
    return currentStatusIndex >= 0 && productionReadyIndex >= 0 && currentStatusIndex < productionReadyIndex;
  }

  function orderHasCriticalDeadline(order) {
    const days = daysUntil(order && order.requestedDelivery);
    return !isOrderFinalized(order) && days != null && days <= 0 && orderIsBeforeProductionReady(order);
  }

  function adjustedOrderTotal(order) {
    const record = order || {};
    const origin = record.origin || record.client && record.client.origin || 'Normal';
    const itemTotals = Array.isArray(record.items) && record.items.length ? orderItemTotals(record, origin) : null;
    // Pedidos de marketplace podem ter sido gravados antes desta regra. Quando
    // houver tarifa nos itens, reconstrói o líquido pela venda menos a tarifa;
    // nos demais casos preserva o total-base já salvo do pedido.
    const base = itemTotals && orderOriginIsMarketplace(origin) && itemTotals.fees > 0.005
      ? itemTotals.net
      : Number(record.total || 0);
    return Math.max(0, base - Number(record.discount || 0) + Number(record.surcharge || 0));
  }

  function orderDate(order) {
    const value = order && (order.createdDate || order.lastChange);
    const date = value ? new Date(String(value).length === 10 ? value + 'T12:00:00' : value) : null;
    return date && !Number.isNaN(date.getTime()) ? date : null;
  }

  function aggregateDashboardProducts(orders) {
    const map = {};
    orders.forEach(order => (order.items || []).forEach(item => {
      const unit = String(item.unit || 'un.').trim() || 'un.';
      const key = String(item.productId || item.code || item.description || 'sem-produto') + '|' + unit;
      if (!map[key]) map[key] = { id:key, code:item.code || '', description:item.description || 'Produto sem descrição', unit, quantity:0, orders:0, revenue:0 };
      map[key].quantity += Number(item.quantity || 0);
      map[key].orders += 1;
      map[key].revenue += itemFinancialBreakdown(item, order.origin || order.client && order.client.origin || 'Normal').net;
    }));
    return Object.values(map).sort((a,b) => b.quantity - a.quantity || b.revenue - a.revenue);
  }

  function aggregateDashboardClients(orders) {
    const map = {};
    orders.forEach(order => {
      const client = order.client || {};
      const key = String(client.id || client.phone || client.email || client.name || 'sem-cliente');
      if (!map[key]) map[key] = { id:key, name:client.name || 'Cliente não identificado', phone:client.phone || '', orders:0, revenue:0, lastDate:'' };
      map[key].orders += 1;
      map[key].revenue += adjustedOrderTotal(order);
      const date = orderDate(order);
      if (date && (!map[key].lastDate || date > new Date(map[key].lastDate))) map[key].lastDate = date.toISOString();
    });
    return Object.values(map).sort((a,b) => b.revenue - a.revenue || b.orders - a.orders);
  }

  function orderEstimatedCost(order) {
    const products = getProducts();
    return (order.items || []).reduce((sum, item) => {
      const product = products.find(candidate => String(candidate.id) === String(item.productId || ''));
      const unitCost = Number(item.unitCost != null ? item.unitCost : product && product.cost || 0);
      return sum + Number(item.quantity || 0) * unitCost;
    }, 0);
  }

  function dashboardFilterValues() {
    return {
      start: $('#pw-dashboard-filter-start').value,
      end: $('#pw-dashboard-filter-end').value,
      status: $('#pw-dashboard-filter-status').value,
      origin: $('#pw-dashboard-filter-origin').value,
      client: $('#pw-dashboard-filter-client').value,
      responsible: $('#pw-dashboard-filter-responsible').value,
      category: $('#pw-dashboard-filter-category').value
    };
  }

  function dashboardFilteredOrders(source) {
    const filters = dashboardFilterValues();
    return source.filter(order => {
      const date = String(order.createdDate || '').slice(0, 10);
      const origin = order.origin || order.client && order.client.origin || 'Normal';
      const clientKey = String(order.client && (order.client.id || order.client.name) || '');
      const responsible = createdByFilterValue(order);
      const categoryMatch = !filters.category || (order.items || []).some(item => {
        const product = getProducts().find(candidate => String(candidate.id) === String(item.productId || ''));
        return product && String(product.categoryId || '') === filters.category;
      });
      return (!filters.start || date >= filters.start) && (!filters.end || date <= filters.end) &&
        (!filters.status || (order.status || 'Sem situação') === filters.status) &&
        (!filters.origin || origin === filters.origin) &&
        (!filters.client || clientKey === filters.client) && (!filters.responsible || responsible === filters.responsible) && categoryMatch;
    });
  }

  function fillDashboardFilters(orders) {
    const fill = (selector, values, label) => {
      const select = $(selector); const current = select.value;
      const uniqueValues = uniqueFilterEntries(values);
      select.innerHTML = '<option value="">' + label + '</option>' + uniqueValues.map(item => '<option value="' + escapeHtml(item.value) + '">' + escapeHtml(item.label) + '</option>').join('');
      const currentEntry = values.find(item => item.value === current);
      const currentLabelKey = normalize(currentEntry && currentEntry.label).replace(/\s+/g, ' ');
      const restored = uniqueValues.find(item => item.value === current || (currentLabelKey && normalize(item.label).replace(/\s+/g, ' ') === currentLabelKey));
      if (restored) select.value = restored.value;
    };
    fill('#pw-dashboard-filter-status', Array.from(new Set(orders.map(order => order.status || 'Sem situação'))).sort().map(value => ({ value, label:value })), 'Todas');
    fill('#pw-dashboard-filter-origin', Array.from(new Set(orders.map(order => order.origin || order.client && order.client.origin || 'Normal'))).sort().map(value => ({ value, label:value })), 'Todas');
    const clients = new Map(); const responsibles = new Map();
    orders.forEach(order => {
      if (order.client) clients.set(String(order.client.id || order.client.name), order.client.name || 'Cliente sem nome');
      if (order.createdBy) {
        const key = createdByFilterValue(order);
        const label = createdByFilterLabel(order);
        if (key && label) responsibles.set(key, label);
      }
    });
    fill('#pw-dashboard-filter-client', Array.from(clients, ([value,label]) => ({ value,label })).sort((a,b) => a.label.localeCompare(b.label)), 'Todos');
    fill('#pw-dashboard-filter-responsible', Array.from(responsibles, ([value,label]) => ({ value,label })).sort((a,b) => a.label.localeCompare(b.label)), 'Todos os usuários');
    fill('#pw-dashboard-filter-category', getCategories().filter(item => item.active !== false).map(item => ({ value:String(item.id), label:item.name })).sort((a,b) => a.label.localeCompare(b.label)), 'Todas');
  }

  function dashboardCard(title, value, description, report, className, comparison) {
    const cardKey = 'metric-' + normalize(title).replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
    const valueText = value == null ? '' : String(value).trim();
    const numericText = valueText.replace(/[^0-9,.-]/g, '').replace(/\.(?=\d{3}(?:\D|$))/g, '').replace(',', '.');
    const numericValue = numericText && /^-?(?:\d+(?:\.\d+)?|\.\d+)$/.test(numericText) ? Number(numericText) : NaN;
    const emptyClass = value == null || valueText === '' || (Number.isFinite(numericValue) && numericValue === 0) ? ' pw-dashboard-card-empty' : '';
    const criticalMarker = String(className || '').includes('pw-critical-question') ? '<i class="pw-dashboard-critical-question pw-tooltip" data-tooltip="Indicador importante: exige atenção" title="Indicador importante: exige atenção" aria-label="Indicador importante: exige atenção">!</i>' : '';
    return '<button class="pw-dashboard-card' + emptyClass + ' ' + (className || '') + '" type="button" data-dashboard-card-key="' + escapeHtml(cardKey) + '" data-dashboard-report="' + escapeHtml(report) + '">' + criticalMarker + '<small>' + escapeHtml(title) + '</small><strong>' + escapeHtml(valueText) + '</strong><span>' + escapeHtml(description) + '</span>' + (comparison ? '<span class="pw-card-comparison ' + comparison.className + '">' + escapeHtml(comparison.text) + '</span>' : '') + '</button>';
  }

  function applyDashboardCardVisibility() {
    const settings = getSettings();
    const administratorConfiguration = userIsAdministrator(currentUser) && dashboardViewMode === 'admin';
    const collaboratorPreview = !userIsAdministrator(currentUser) || dashboardViewMode === 'collaborator';
    $$('[data-view="dashboard"] [data-dashboard-card-key]').forEach(card => {
      const visibleToCollaborators = settings.dashboardCards[card.dataset.dashboardCardKey] !== false;
      card.classList.toggle('pw-dashboard-card-collaborator-hidden', administratorConfiguration && !visibleToCollaborators);
      card.hidden = collaboratorPreview && !visibleToCollaborators;
      if (administratorConfiguration) card.title = visibleToCollaborators ? 'Visível para colaboradores · botão direito para ocultar' : 'Oculto para colaboradores · botão direito para mostrar';
      else card.removeAttribute('title');
    });
    $$('[data-view="dashboard"] [data-dashboard-card-group]').forEach(group => {
      const cards = $$('[data-dashboard-card-key]', group);
      group.hidden = collaboratorPreview && cards.length > 0 && cards.every(card => settings.dashboardCards[card.dataset.dashboardCardKey] === false);
    });
    const toggle = $('#pw-dashboard-view-mode');
    if (toggle) {
      toggle.hidden = !userIsAdministrator(currentUser);
      const labels = { normal:'Normal', admin:'Administrador', collaborator:'Colaborador' };
      toggle.textContent = '👁 Atual: ' + labels[dashboardViewMode];
      toggle.classList.toggle('pw-dashboard-collaborator-preview', dashboardViewMode === 'collaborator');
      toggle.classList.toggle('pw-dashboard-administrator-view', dashboardViewMode === 'admin');
    }
  }

  function importantAlertUserKey() {
    const user = currentUser || {};
    return String(user.id || user.login || user.user_login || 'usuario').replace(/[^A-Za-z0-9_-]/g, '_');
  }

  function dismissedImportantAlerts() {
    try {
      const saved = JSON.parse(window.localStorage.getItem('pw_personalizados_dismissed_alerts_' + importantAlertUserKey()) || '[]');
      return new Set(Array.isArray(saved) ? saved : []);
    } catch (error) { return new Set(); }
  }

  function dismissImportantAlert(key) {
    const dismissed = dismissedImportantAlerts();
    dismissed.add(String(key));
    try { window.localStorage.setItem('pw_personalizados_dismissed_alerts_' + importantAlertUserKey(), JSON.stringify(Array.from(dismissed).slice(-300))); } catch (error) {}
  }

  function orderBelongsToCurrentUser(order) {
    if (userIsAdministrator(currentUser)) return true;
    const current = [currentUser && currentUser.full_name, currentUser && currentUser.display, currentUser && currentUser.login, currentUser && currentUser.user_login].map(value => normalize(value).replace(/\s+/g, ' ')).filter(Boolean);
    return current.includes(createdByFilterValue(order));
  }

  function orderHasDtfUvMissingArt(order) {
    return (Array.isArray(order && order.items) ? order.items : []).some(item => {
      if (!analyticsIsDtfUvItem(item)) return false;
      return !itemHasApprovedPdfArt(item);
    });
  }

  function artIsPdf(art) {
    if (!art || !(art.id || art.url || art.name)) return false;
    return String(art.mime || '').toLowerCase().includes('pdf') || /\.pdf(?:$|\?)/i.test(String(art.name || art.url || ''));
  }

  function itemCategoryId(item) {
    if (!item) return '';
    if (item.categoryId || item.category) return String(item.categoryId || item.category);
    const product = getProducts().find(product => String(product.id || product.code) === String(item.productId || item.code));
    return String((product && (product.categoryId || product.category)) || '');
  }

  function getPdfRules() {
    const stored = readStorage(STORAGE.pdfRules, {});
    return stored && typeof stored === 'object' ? stored : {};
  }

  function itemHasApprovedPdfArt(item) {
    return !!(item && artIsPdf(item.art));
  }

  function statusRequiresApprovedPdfArt(status) {
    const selected = statusIndex(status);
    const approved = statusIndex('Arte aprovada');
    return selected >= approved && approved >= 0;
  }

  function missingApprovedPdfArtItems(orderItems) {
    const rules = getPdfRules();
    return (Array.isArray(orderItems) ? orderItems : []).filter(item => {
      if (itemHasApprovedPdfArt(item)) return false;
      const rule = rules[itemCategoryId(item)];
      if (rule && (rule.enabled === false || rule.required === false)) return false;
      return true;
    });
  }

  /** Origem do pedido pra decidir se a arte é obrigatória: usa o cadastro
   * salvo quando existir; durante a criação (pedido ainda sem registro),
   * cai pro seletor de origem do próprio formulário. */
  function orderOriginForArtsCheck(orderNumber) {
    const stored = orderNumber ? getOrders().find(order => String(order.orderNumber) === String(orderNumber)) : null;
    if (stored) return stored.origin || (stored.client && stored.client.origin) || 'Normal';
    const originField = $('#pw-order-client-origin');
    return (originField && originField.value) || 'Normal';
  }

  /** Chave por usuário + pedido pra nunca perguntar duas vezes pro mesmo
   * usuário sobre o mesmo pedido — mesmo padrão usado pelos beeps de
   * notificação (localStorage, é uma conveniência do navegador/dispositivo,
   * não precisa sincronizar entre aparelhos). */
  function marketplaceArtPromptStorageKey(orderNumber) {
    const userId = (currentUser && currentUser.id) || 'anon';
    return 'pw_art_prompt_seen_' + userId + '_' + orderNumber;
  }
  function hasAskedMarketplaceArtPrompt(orderNumber) {
    try { return window.localStorage.getItem(marketplaceArtPromptStorageKey(orderNumber)) === '1'; } catch (error) { return false; }
  }
  function markMarketplaceArtPromptAsked(orderNumber) {
    try { window.localStorage.setItem(marketplaceArtPromptStorageKey(orderNumber), '1'); } catch (error) { /* sem localStorage, pergunta de novo na próxima — não é crítico */ }
  }

  /** Pedidos de marketplace não bloqueiam por falta de arte — apenas
   * lembra o usuário, uma única vez por usuário por pedido, e se ele
   * confirmar já abre o pedido em modo edição pra inserir a arte. Se
   * recusar, ou já tiver perguntado antes pra este usuário neste pedido,
   * simplesmente não pergunta de novo e a alteração de situação segue
   * normalmente (esta função nunca bloqueia, só avisa). */
  function promptMarketplaceMissingArt(orderNumber, missing) {
    if (!orderNumber || hasAskedMarketplaceArtPrompt(orderNumber)) return;
    markMarketplaceArtPromptAsked(orderNumber);
    const wantsToInsertNow = window.confirm('Este pedido (marketplace) ainda não tem uma arte em PDF aprovada.\n\nDeseja inserir a arte agora?');
    if (!wantsToInsertNow) return;
    missingApprovedArtRowIds = new Set((missing || []).map(item => String(item && item.rowId || '')));
    loadOrder(String(orderNumber));
    window.setTimeout(() => {
      const target = $('.pw-item-art-required .pw-item-art');
      if (target) target.click();
    }, 150);
  }

  function requireApprovedPdfArts(status, orderItems, orderNumber, openEditor) {
    if (!statusRequiresApprovedPdfArt(status)) return true;
    const missing = missingApprovedPdfArtItems(orderItems);
    if (!missing.length) return true;
    if (orderOriginIsMarketplace(orderOriginForArtsCheck(orderNumber))) {
      return true;
    }
    missingApprovedArtRowIds = new Set(missing.map(item => String(item && item.rowId || '')));
    if (openEditor && orderNumber) loadOrder(String(orderNumber));
    else renderItems();
    const labels = missing.slice(0, 3).map((item, index) => String(item && (item.description || item.code) || ('Produto ' + (index + 1))));
    const remainder = missing.length > labels.length ? ' e mais ' + (missing.length - labels.length) : '';
    showMessage('Não é possível avançar para "' + statusDefinition(status).label + '". Anexe uma arte em PDF em cada produto pendente: ' + labels.join('; ') + remainder + '.', 'error');
    window.setTimeout(() => {
      const first = $('.pw-item-art-required .pw-item-art');
      if (first) first.focus();
    }, 120);
    return false;
  }

  function importantDashboardAlerts(orders) {
    const scopedOrders = userIsAdministrator(currentUser) ? orders : orders.filter(orderBelongsToCurrentUser);
    const make = (type, title, detail, level, report, records) => ({ key:type + ':' + records.map(record => String(record.orderNumber || record.id || '')).sort().join(','), title, detail, level, report, count:records.length });
    const alerts = [];
    const overdue = scopedOrders.filter(orderHasCriticalDeadline);
    if (overdue.length) alerts.push(make('production-overdue', 'Produção com prazo vencido', overdue.length + ' pedido(s) ainda não pronto(s) com prazo para hoje ou vencido.', 'critical', 'alert-production-overdue', overdue));
    const soon = scopedOrders.filter(order => !isOrderFinalized(order) && orderIsBeforeProductionReady(order) && (() => { const days = daysUntil(order.requestedDelivery); return days != null && days >= 1 && days <= 3; })());
    if (soon.length) alerts.push(make('production-soon', 'Produção com prazo curto', soon.length + ' pedido(s) ainda não pronto(s) com entrega nos próximos 3 dias.', 'warning', 'alert-production-soon', soon));
    const deliveredPending = scopedOrders.filter(order => order.status === 'Entregue' && !orderHasNoPendingBalance(order));
    if (deliveredPending.length) {
      const balance = deliveredPending.reduce((sum, order) => sum + Math.max(0, adjustedOrderTotal(order) - Number(order.paid || 0)), 0);
      alerts.push(make('delivered-receivable', 'Recebimentos após entrega', deliveredPending.length + ' pedido(s) entregue(s) ainda aguardam ' + money.format(balance) + '.', 'financial', 'alert-delivered-receivables', deliveredPending));
    }
    const stalled = scopedOrders.filter(order => !isOrderFinalized(order) && orderIsBeforeProductionReady(order) && (() => { const changed = order.lastChange ? new Date(order.lastChange) : orderDate(order); return changed && Math.floor((new Date() - changed) / 86400000) >= 3; })());
    if (stalled.length) alerts.push(make('production-stalled', 'Produção sem atualização', stalled.length + ' pedido(s) na etapa crítica sem alteração há 3 dias ou mais.', 'warning', 'stalled-orders', stalled));
    // Depois da entrega o pedido já saiu da operação; a pendência de arte
    // continua registrada no histórico, mas não deve gerar alerta ativo.
    scopedOrders.filter(order => normalize(order && order.status) !== normalize('Entregue') && !orderOriginIsMarketplace(orderOriginForArtsCheck(order)) && orderHasDtfUvMissingArt(order)).forEach(order => {
      const number = String(order && order.orderNumber || '');
      const client = String(order && order.client && order.client.name || 'Cliente não identificado');
      const missingItems = (Array.isArray(order && order.items) ? order.items : []).filter(item => analyticsIsDtfUvItem(item) && !itemHasApprovedPdfArt(item));
      alerts.push({
        key: 'dtf-missing-art:' + number,
        title: 'DTF UV sem arte anexada',
        detail: number + ' · ' + client + ' · ' + missingItems.length + (missingItems.length === 1 ? ' item DTF UV sem PDF.' : ' itens DTF UV sem PDF.'),
        level: 'critical',
        report: '',
        directOrder: number,
        count: 1,
        dismissible: false
      });
    });
    if (userIsAdministrator(currentUser)) {
      const expenses = getDtfCosts().filter(expense => !String(expense && expense.supplier || '').trim() || normalize(expense.supplier) === normalize('Não informado'));
      if (expenses.length) alerts.push(make('expense-supplier', 'Despesas sem fornecedor/local', expenses.length + ' lançamento(s) de gasto sem fornecedor ou local informado.', 'registration', 'alert-expense-without-supplier', expenses));
      const belowCost = getProducts().filter(product => Number(product.cost || 0) > Number(product.price || 0));
      if (belowCost.length) alerts.push(make('below-cost', 'Produtos abaixo do custo', belowCost.length + ' produto(s) possuem venda menor que o custo cadastrado.', 'financial', 'below-cost-products', belowCost));
    }
    const priority = { critical:0, financial:1, warning:2, registration:3 };
    return alerts.sort((a,b) => priority[a.level] - priority[b.level] || a.title.localeCompare(b.title));
  }

  function dashboardStatusChart(orders) {
    const totals = {};
    ORDER_STATUS_FLOW.forEach(item => { totals[item.value] = { count:0, value:0 }; });
    (orders || []).forEach(order => {
      const status = order && order.status || 'Sem situação';
      if (!totals[status]) totals[status] = { count:0, value:0 };
      totals[status].count += 1;
      totals[status].value += adjustedOrderTotal(order);
    });
    const entries = Object.entries(totals).filter(([status]) => status !== 'Entregue').sort((a, b) => {
      const aIndex = statusIndex(a[0]), bIndex = statusIndex(b[0]);
      return (aIndex < 0 ? 999 : aIndex) - (bIndex < 0 ? 999 : bIndex) || a[0].localeCompare(b[0]);
    });
    const delivered = (orders || []).filter(order => order && order.status === 'Entregue');
    const deliveredPaid = delivered.filter(orderHasNoPendingBalance);
    const deliveredPending = delivered.filter(order => !orderHasNoPendingBalance(order));
    const summarize = rows => rows.reduce((summary, order) => {
      summary.count += 1;
      summary.total += adjustedOrderTotal(order);
      summary.pending += Math.max(0, adjustedOrderTotal(order) - Number(order.paid || 0));
      return summary;
    }, { count:0, total:0, pending:0 });
    const paidSummary = summarize(deliveredPaid);
    const pendingSummary = summarize(deliveredPending);
    const metric = dashboardStatusMetric === 'value' ? 'value' : 'count';
    const metricLabel = metric === 'value' ? 'Valor total' : 'Número de pedidos';
    const metricColorClass = metric === 'value' ? 'pw-dashboard-status-bar-value' : 'pw-dashboard-status-bar-count';
    const maxMetric = Math.max(1, ...entries.map(entry => entry[1][metric]));
    const legend = '<div class="pw-dashboard-status-toolbar" role="toolbar" aria-label="Métrica do gráfico"><span>Exibir:</span><div class="pw-toggle-group"><button type="button" class="pw-toggle-btn' + (metric === 'count' ? ' is-active' : '') + '" data-dashboard-status-metric="count" aria-pressed="' + (metric === 'count' ? 'true' : 'false') + '">▤ Número de pedidos</button><button type="button" class="pw-toggle-btn' + (metric === 'value' ? ' is-active' : '') + '" data-dashboard-status-metric="value" aria-pressed="' + (metric === 'value' ? 'true' : 'false') + '">R$ Valor total</button></div></div>';
    const columns = entries.map(([status, values]) => {
      const definition = ORDER_STATUS_FLOW.find(item => item.value === status);
      const label = definition ? definition.label : status;
      const tooltip = label + ' · ' + values.count + ' pedido(s) · ' + money.format(values.value);
      const height = values[metric] > 0 ? Math.max(5, values[metric] / maxMetric * 100) : 0;
      const valueLabel = metric === 'value' ? money.format(values.value) : values.count + ' pedido(s)';
      return '<button class="pw-dashboard-status-group" type="button" data-dashboard-report="status-orders" data-dashboard-value="' + escapeHtml(status) + '" title="' + escapeHtml(tooltip) + '" aria-label="' + escapeHtml(tooltip) + '"><span class="pw-dashboard-status-bars"><i class="' + metricColorClass + '" style="height:' + height.toFixed(1) + '%"><b>' + escapeHtml(valueLabel) + '</b></i></span><strong>' + escapeHtml(label) + '</strong><small>' + escapeHtml(valueLabel) + '</small></button>';
    }).join('');
    const deliveredSummary = '<div class="pw-dashboard-delivered-summary" aria-label="Resumo dos pedidos entregues"><strong>Entregues</strong><span class="pw-dashboard-delivered-summary-item pw-dashboard-delivered-paid"><b>Quitados</b><em>' + paidSummary.count + ' pedido(s) · ' + escapeHtml(money.format(paidSummary.total)) + '</em></span><span class="pw-dashboard-delivered-summary-item pw-dashboard-delivered-pending"><b>A receber</b><em>' + pendingSummary.count + ' pedido(s) · ' + escapeHtml(money.format(pendingSummary.total)) + (pendingSummary.count ? ' · saldo: ' + escapeHtml(money.format(pendingSummary.pending)) : '') + '</em></span></div>';
    return legend + '<div class="pw-dashboard-status-chart" role="list" aria-label="' + escapeHtml(metricLabel + ' por situações em andamento') + '"><div class="pw-dashboard-status-chart-axis"><span>Valor relativo · ' + escapeHtml(metricLabel) + '</span></div><div class="pw-dashboard-status-chart-columns">' + columns + '</div></div>' + deliveredSummary;
  }

  function renderDashboard() {
    const allOrders = getOrders();
    fillDashboardFilters(allOrders);
    const orders = dashboardFilteredOrders(allOrders);
    const filteredSales = orders.reduce((sum, order) => sum + adjustedOrderTotal(order), 0);
    $('#pw-dashboard-filter-summary').innerHTML = '<span>Resultado do filtro</span><strong>' + orders.length + ' pedido(s) · ' + escapeHtml(money.format(filteredSales)) + ' em vendas</strong>';
    const productionCritical = orders.filter(order => !isOrderFinalized(order) && orderIsBeforeProductionReady(order));
    const overdue = productionCritical.filter(orderHasCriticalDeadline);
    const awaitingDelivery = orders.filter(order => order && order.status === 'Aguardando entrega');
    const deliveredAwaitingPayment = orders.filter(order => order && order.status === 'Entregue' && !orderHasNoPendingBalance(order));
    const deliveredAwaitingPaymentBalance = deliveredAwaitingPayment.reduce((sum, order) => sum + Math.max(0, adjustedOrderTotal(order) - Number(order.paid || 0)), 0);
    $('#pw-dashboard-cards').innerHTML = [
      dashboardCard('Produção em etapa crítica', productionCritical.length, 'Da criação da arte até a produção ficar pronta — acompanhe o prazo de entrega.', 'production-critical', 'pw-production-critical pw-critical-question', null),
      dashboardCard('Produção com prazo crítico', overdue.length, 'Previsão para hoje ou vencida antes da produção pronta.', 'late-orders', 'pw-alert pw-production-overdue pw-critical-question', null),
      dashboardCard('Aguardando entrega', awaitingDelivery.length, 'Produto pronto; aguarda retirada, despacho ou entrega. Não é uma etapa crítica de produção.', 'awaiting-delivery', awaitingDelivery.length ? 'pw-logistics-ready' : '', null),
      dashboardCard('Entregues a receber', money.format(deliveredAwaitingPaymentBalance), deliveredAwaitingPayment.length + ' pedido(s) já entregues com saldo pendente.', 'delivered-receivables', 'pw-financial-attention pw-critical-question', null)
    ].join('');

    $('#pw-dashboard-status').innerHTML = dashboardStatusChart(orders);

    const dismissedAlerts = dismissedImportantAlerts();
    const alerts = importantDashboardAlerts(orders).filter(alert => alert.dismissible === false || !dismissedAlerts.has(alert.key));
    $('#pw-dashboard-deadlines').innerHTML = alerts.length ? '<div class="pw-important-alert-list">' + alerts.map(alert => {
      const direct = alert.directOrder ? ' data-dashboard-direct-order="' + escapeHtml(alert.directOrder) + '" title="Abrir edição do pedido ' + escapeHtml(alert.directOrder) + '" aria-label="Abrir edição do pedido ' + escapeHtml(alert.directOrder) + '"' : '';
      const report = alert.report ? ' data-dashboard-report="' + escapeHtml(alert.report) + '"' : '';
      const dismiss = alert.dismissible === false ? '' : '<button class="pw-btn pw-btn-soft pw-btn-icon pw-tooltip pw-important-alert-dismiss" type="button" data-dismiss-important-alert="' + escapeHtml(alert.key) + '" data-tooltip="Dispensar somente para você" title="Dispensar somente para você" aria-label="Dispensar somente para você">×</button>';
      return '<div class="pw-important-alert pw-important-alert-' + escapeHtml(alert.level) + (alert.dismissible === false ? ' pw-important-alert-required' : '') + '"><button class="pw-important-alert-main" type="button"' + direct + report + '><span class="pw-important-alert-icon">!</span><span><strong>' + escapeHtml(alert.title) + '</strong><small>' + escapeHtml(alert.detail) + '</small></span></button>' + dismiss + '</div>';
    }).join('') + '</div>' : '<p>Nenhum alerta importante para você no momento.</p>';

    const now = new Date();
    const todayKey = localDateValue(now);
    const currentStart = new Date(now.getFullYear(), now.getMonth(), 1);
    const currentEnd = new Date(now.getFullYear(), now.getMonth() + 1, 1);
    const previousStart = new Date(now.getFullYear(), now.getMonth() - 1, 1);
    const currentOrders = orders.filter(order => { const date = orderDate(order); return date && date >= currentStart && date < currentEnd; });
    const previousOrders = orders.filter(order => { const date = orderDate(order); return date && date >= previousStart && date < currentStart; });
    const todayOrders = orders.filter(order => String(order.createdDate || '').slice(0, 10) === todayKey);
    const difference = currentOrders.length - previousOrders.length;
    const percent = previousOrders.length ? Math.round((difference / previousOrders.length) * 100) : (currentOrders.length ? 100 : 0);
    const comparison = { text:(difference >= 0 ? '+' : '') + difference + ' pedido(s) · ' + (percent >= 0 ? '+' : '') + percent + '% sobre o mês anterior', className:difference > 0 ? 'pw-up' : difference < 0 ? 'pw-down' : '' };
    $('#pw-dashboard-periods').innerHTML = [
      dashboardCard('Total de pedidos', orders.length, money.format(orders.reduce((sum, order) => sum + adjustedOrderTotal(order), 0)), 'all-orders', '', null),
      dashboardCard('Pedidos de hoje', todayOrders.length, money.format(todayOrders.reduce((sum, order) => sum + adjustedOrderTotal(order), 0)), 'today-orders', '', null),
      dashboardCard('Mês atual', currentOrders.length, money.format(currentOrders.reduce((sum, order) => sum + adjustedOrderTotal(order), 0)), 'current-month-orders', difference >= 0 ? 'pw-positive' : 'pw-warning', comparison),
      dashboardCard('Mês anterior', previousOrders.length, money.format(previousOrders.reduce((sum, order) => sum + adjustedOrderTotal(order), 0)), 'previous-month-orders', '', null)
    ].join('');

    const revenue = orders.reduce((sum, order) => sum + adjustedOrderTotal(order), 0);
    const cost = orders.reduce((sum, order) => sum + orderEstimatedCost(order), 0);
    const profit = revenue - cost;
    const margin = revenue ? Math.round((profit / revenue) * 1000) / 10 : 0;
    const ticket = orders.length ? revenue / orders.length : 0;
    const pendingOrders = orders.filter(order => adjustedOrderTotal(order) - Number(order.paid || 0) > 0);
    $('#pw-dashboard-financial').innerHTML = [
      dashboardCard('Faturamento', money.format(revenue), orders.length + ' pedido(s)', 'financial-orders', 'pw-positive', null),
      dashboardCard('Ticket médio', money.format(ticket), 'Valor médio por pedido', 'financial-orders', '', null),
      dashboardCard('Resultado após custo dos produtos', money.format(profit), 'Margem estimada após custo dos produtos: ' + margin.toLocaleString('pt-BR') + '%', 'financial-orders', profit < 0 ? 'pw-alert' : 'pw-positive', null),
      dashboardCard('Previsão de recebimentos', money.format(pendingOrders.reduce((sum, order) => sum + Math.max(0, adjustedOrderTotal(order) - Number(order.paid || 0)), 0)), pendingOrders.length + ' pedido(s) com saldo', 'receivables', '', null)
    ].join('');

    const stalled = productionCritical.filter(order => { const changed = order.lastChange ? new Date(order.lastChange) : orderDate(order); return changed && Math.floor((now - changed) / 86400000) >= 3; });
    const finalizedWithDates = orders.filter(order => order.status === 'Entregue' && order.actualDelivery && order.requestedDelivery);
    const lateDelivered = finalizedWithDates.filter(order => order.actualDelivery > order.requestedDelivery);
    const finalizedOrders = orders.filter(isOrderFinalized);
    $('#pw-dashboard-intelligence').innerHTML = [
      dashboardCard('Produção sem atualização', stalled.length, 'Etapa crítica sem alteração há 3 dias ou mais.', 'stalled-orders', 'pw-warning pw-critical-question', null),
      dashboardCard('Pedidos finalizados', finalizedOrders.length, 'Entregues e quitados, sem saldo pendente de pagamento.', 'finalized-orders', finalizedOrders.length ? 'pw-positive pw-finalized' : '', null),
      dashboardCard('Entregas fora do prazo', lateDelivered.length, finalizedWithDates.length ? Math.round((lateDelivered.length / finalizedWithDates.length) * 100) + '% das entregas avaliadas' : 'Sem entregas avaliadas', 'delivered-late', lateDelivered.length ? 'pw-alert' : '', null)
    ].join('');

    const productRanking = aggregateDashboardProducts(orders);
    $('#pw-dashboard-products').innerHTML = productRanking.length ? productRanking.slice(0,5).map((item,index) => '<button class="pw-global-result pw-dashboard-list-button" type="button" data-dashboard-report="best-products"><span>#' + (index + 1) + '</span><strong>' + escapeHtml(item.description) + '</strong><b>' + escapeHtml(Number(item.quantity).toLocaleString('pt-BR')) + ' ' + escapeHtml(item.unit) + ' · ' + escapeHtml(money.format(item.revenue)) + '</b></button>').join('') : '<p>Ainda não há itens vendidos para analisar.</p>';

    const clientRanking = aggregateDashboardClients(orders);
    const recovery = clientRanking.filter(client => client.orders >= 2 && client.lastDate && Math.floor((now - new Date(client.lastDate)) / 86400000) >= 90);
    const inactive = getClients().filter(client => {
      const history = clientRanking.find(item => item.id === String(client.id) || normalize(item.name) === normalize(client.name));
      return !history || (history.lastDate && Math.floor((now - new Date(history.lastDate)) / 86400000) >= 90);
    });
    $('#pw-dashboard-customers').innerHTML = [
      '<button class="pw-global-result pw-dashboard-list-button" type="button" data-dashboard-report="best-customers"><span>Ranking</span><strong>Melhores clientes</strong><b>' + clientRanking.length + '</b></button>',
      '<button class="pw-global-result pw-dashboard-list-button" type="button" data-dashboard-report="recovery-customers"><span>Recuperação</span><strong>Bons clientes sem comprar há 90 dias</strong><b>' + recovery.length + '</b></button>',
      '<button class="pw-global-result pw-dashboard-list-button" type="button" data-dashboard-report="inactive-customers"><span>Inativos</span><strong>Clientes sem compra recente</strong><b>' + inactive.length + '</b></button>'
    ].join('');

    $('#pw-dashboard-registries').innerHTML = [
      dashboardCard('Pedidos', allOrders.length, 'Pedidos cadastrados', 'registry-orders', '', null),
      dashboardCard('Clientes', getClients().length, 'Clientes cadastrados', 'registry-clients', '', null),
      dashboardCard('Produtos', getProducts().length, 'Produtos cadastrados', 'registry-products', '', null),
      dashboardCard('Categorias', getCategories().length, 'Categorias cadastradas', 'registry-categories', '', null),
      dashboardCard('Unidades', getUnits().length, 'Unidades de venda cadastradas', 'registry-units', '', null),
      dashboardCard('Fornecedores', getSuppliers().length, 'Fornecedores cadastrados', 'registry-suppliers', '', null),
      dashboardCard('Formas de pagamento', getPaymentMethods().length, 'Formas disponíveis para recebimentos', 'registry-payment-methods', '', null),
      dashboardCard('Categorias de despesas', getDtfExpenseCategoryRecords().length, 'Categorias usadas no cadastro de despesas', 'registry-dtf-categories', '', null),
      dashboardCard('Insumos, peças ou serviços', getDtfCatalog().length, 'Itens disponíveis para despesas', 'registry-dtf-items', '', null),
      dashboardCard('Movimentações de despesas', getDtfExpenseMovements().length, 'Tipos de movimentação cadastrados', 'registry-dtf-movements', '', null),
      dashboardCard('Despesas registradas', getDtfCosts().length, 'Lançamentos de despesas', 'registry-expenses', '', null)
    ].join('');
    updateTrashBadge();
    applyDashboardCardVisibility();
  }

  function openDashboardReport(type, value) {
    const orders = dashboardFilteredOrders(getOrders());
    const now = new Date();
    const currentStart = new Date(now.getFullYear(), now.getMonth(), 1);
    const currentEnd = new Date(now.getFullYear(), now.getMonth() + 1, 1);
    const previousStart = new Date(now.getFullYear(), now.getMonth() - 1, 1);
    let title = 'Relatório';
    let headers = [];
    let rows = [];
    let summary = [];
    let records = [];
    const orderReports = {
      'all-orders': () => orders,
      'active-orders': () => orders.filter(isOrderActive),
      'production-critical': () => orders.filter(order => !isOrderFinalized(order) && orderIsBeforeProductionReady(order)),
      'alert-production-overdue': () => orders.filter(orderHasCriticalDeadline),
      'alert-production-soon': () => orders.filter(order => !isOrderFinalized(order) && orderIsBeforeProductionReady(order) && (() => { const days = daysUntil(order.requestedDelivery); return days != null && days >= 1 && days <= 3; })()),
      'alert-delivered-receivables': () => orders.filter(order => order.status === 'Entregue' && !orderHasNoPendingBalance(order)),
      'late-orders': () => orders.filter(orderHasCriticalDeadline),
      'next-orders': () => orders.filter(order => { const days = daysUntil(order.requestedDelivery); return !isOrderFinalized(order) && days != null && days >= 1 && days <= 3; }),
      'receivables': () => orders.filter(order => adjustedOrderTotal(order) - Number(order.paid || 0) > 0),
      'awaiting-delivery': () => orders.filter(order => order.status === 'Aguardando entrega'),
      'delivered-receivables': () => orders.filter(order => order.status === 'Entregue' && !orderHasNoPendingBalance(order)),
      'finalized-orders': () => orders.filter(isOrderFinalized),
      'today-orders': () => orders.filter(order => String(order.createdDate || '').slice(0, 10) === localDateValue(now)),
      'current-month-orders': () => orders.filter(order => { const date = orderDate(order); return date && date >= currentStart && date < currentEnd; }),
      'previous-month-orders': () => orders.filter(order => { const date = orderDate(order); return date && date >= previousStart && date < currentStart; }),
      'status-orders': () => orders.filter(order => (order.status || 'Sem situação') === value),
      'financial-orders': () => orders,
      'stalled-orders': () => orders.filter(order => { const changed = order.lastChange ? new Date(order.lastChange) : orderDate(order); return !isOrderFinalized(order) && orderIsBeforeProductionReady(order) && changed && Math.floor((now - changed) / 86400000) >= 3; }),
      'delivered-late': () => orders.filter(order => order.status === 'Entregue' && order.actualDelivery && order.requestedDelivery && order.actualDelivery > order.requestedDelivery),
      'registry-orders': () => orders
    };
    const orderTitles = {
      'all-orders':'Todos os pedidos', 'active-orders':'Pedidos ativos', 'production-critical':'Pedidos na etapa crítica de produção', 'alert-production-overdue':'Produção com prazo vencido', 'alert-production-soon':'Produção com prazo curto', 'alert-delivered-receivables':'Pedidos entregues com recebimento pendente', 'late-orders':'Prazos críticos antes da produção pronta', 'next-orders':'Entregas nos próximos 3 dias',
      'receivables':'Valores a receber', 'awaiting-delivery':'Pedidos aguardando entrega', 'delivered-receivables':'Pedidos entregues com saldo pendente', 'finalized-orders':'Pedidos finalizados', 'today-orders':'Pedidos de hoje', 'current-month-orders':'Pedidos do mês atual', 'previous-month-orders':'Pedidos do mês anterior',
      'status-orders':'Pedidos — ' + (value || 'Sem situação'), 'registry-orders':'Pedidos cadastrados'
      , 'financial-orders':'Resultado financeiro dos pedidos', 'stalled-orders':'Produção sem atualização há 3 dias ou mais', 'delivered-late':'Entregas realizadas fora do prazo'
    };

    if (orderReports[type]) {
      title = orderTitles[type];
      // Cards de prazo de produção são sobre prazo de ENTREGA (o que de fato
      // importa acompanhar), não data de criação — ordena pela previsão de
      // entrega mais próxima primeiro, sem previsão vai pro final da lista.
      const sortByDeliveryDeadline = ['production-critical', 'late-orders', 'alert-production-overdue', 'alert-production-soon', 'next-orders'].includes(type);
      records = orderReports[type]().sort(sortByDeliveryDeadline
        ? (a, b) => String(a.requestedDelivery || '9999-99-99').localeCompare(String(b.requestedDelivery || '9999-99-99'))
        : (a, b) => String(b.createdDate || '').localeCompare(String(a.createdDate || '')));
      const total = records.reduce((sum, order) => sum + adjustedOrderTotal(order), 0);
      const pending = records.reduce((sum, order) => sum + Math.max(0, adjustedOrderTotal(order) - Number(order.paid || 0)), 0);
      summary = [['Registros', records.length], ['Valor líquido dos pedidos', money.format(total)], ['Saldo pendente', money.format(pending)]];
      headers = ['Pedido', 'Nº plataforma', 'Origem', 'Data', 'Cliente', 'Situação', 'Entrega', 'Valor', 'Pendente'];
      rows = records.map(order => {
        const pendingValue = Math.max(0, adjustedOrderTotal(order) - Number(order.paid || 0));
        const origin = order.origin || order.client && order.client.origin || 'Normal';
        return '<tr data-dashboard-order="' + escapeHtml(order.orderNumber) + '" style="cursor:pointer"><td><strong>' + escapeHtml(order.orderNumber) + '</strong></td><td>' + escapeHtml(order.marketplaceOrderNumber || '—') + '</td><td>' + escapeHtml(origin) + '</td><td>' + escapeHtml(dateLabel(order.createdDate)) + '</td><td>' + escapeHtml(order.client && order.client.name || '—') + '</td><td>' + escapeHtml(order.status || '—') + '</td><td>' + escapeHtml(dateLabel(order.requestedDelivery)) + '</td><td>' + escapeHtml(money.format(adjustedOrderTotal(order))) + '</td><td>' + escapeHtml(money.format(pendingValue)) + '</td></tr>';
      });
    } else if (type === 'alert-expense-without-supplier') {
      title = 'Despesas sem fornecedor ou local';
      records = getDtfCosts().filter(expense => !String(expense && expense.supplier || '').trim() || normalize(expense.supplier) === normalize('Não informado')).map(expenseDisplayRecord);
      summary = [['Lançamentos', records.length], ['Valor total', money.format(records.reduce((sum, item) => sum + Number(item.value || 0), 0))], ['Ação necessária', 'Informar fornecedor/local']];
      headers = ['Data', 'Categoria', 'Item', 'Valor', 'Fornecedor/local'];
      rows = records.map(item => '<tr><td>' + escapeHtml(dateLabel(item.date)) + '</td><td>' + escapeHtml(item.category || '—') + '</td><td><strong>' + escapeHtml(item.item || '—') + '</strong></td><td>' + escapeHtml(money.format(Number(item.value || 0))) + '</td><td>' + escapeHtml(item.supplier || 'Não informado') + '</td></tr>');
    } else if (type === 'best-products') {
      title = 'Itens mais vendidos';
      records = aggregateDashboardProducts(orders);
      summary = [['Itens diferentes', records.length], ['Quantidade vendida', records.reduce((sum,item) => sum + item.quantity, 0)], ['Faturamento', money.format(records.reduce((sum,item) => sum + item.revenue, 0))]];
      headers = ['Posição', 'Código', 'Produto', 'Quantidade', 'Presença em pedidos', 'Faturamento'];
      rows = records.map((item,index) => '<tr><td>#' + (index + 1) + '</td><td>' + escapeHtml(item.code || '—') + '</td><td><strong>' + escapeHtml(item.description) + '</strong></td><td>' + escapeHtml(Number(item.quantity).toLocaleString('pt-BR') + ' ' + item.unit) + '</td><td>' + escapeHtml(String(item.orders)) + '</td><td>' + escapeHtml(money.format(item.revenue)) + '</td></tr>');
    } else if (type === 'below-cost-products') {
      title = 'Produtos com preço abaixo do custo';
      records = getProducts().filter(product => Number(product.cost || 0) > Number(product.price || 0));
      summary = [['Produtos', records.length], ['Custo total unitário', money.format(records.reduce((sum,item) => sum + Number(item.cost || 0), 0))], ['Venda total unitária', money.format(records.reduce((sum,item) => sum + Number(item.price || 0), 0))]];
      headers = ['Código', 'Produto', 'Custo', 'Venda', 'Diferença'];
      rows = records.map(item => '<tr><td>' + escapeHtml(item.code || '—') + '</td><td><strong>' + escapeHtml(item.description || '—') + '</strong></td><td>' + escapeHtml(money.format(Number(item.cost || 0))) + '</td><td>' + escapeHtml(money.format(Number(item.price || 0))) + '</td><td>' + escapeHtml(money.format(Number(item.price || 0) - Number(item.cost || 0))) + '</td></tr>');
    } else if (type === 'best-customers' || type === 'recovery-customers' || type === 'inactive-customers') {
      const ranking = aggregateDashboardClients(orders);
      if (type === 'best-customers') {
        title = 'Melhores clientes';
        records = ranking;
      } else if (type === 'recovery-customers') {
        title = 'Clientes com potencial de recuperação';
        records = ranking.filter(client => client.orders >= 2 && client.lastDate && Math.floor((now - new Date(client.lastDate)) / 86400000) >= 90);
      } else {
        title = 'Clientes inativos';
        records = getClients().map(client => {
          const history = ranking.find(item => item.id === String(client.id) || normalize(item.name) === normalize(client.name));
          return history || { id:String(client.id), name:client.name || '—', phone:client.phone || '', orders:0, revenue:0, lastDate:'' };
        }).filter(client => !client.lastDate || Math.floor((now - new Date(client.lastDate)) / 86400000) >= 90);
      }
      summary = [['Clientes', records.length], ['Pedidos históricos', records.reduce((sum,item) => sum + item.orders, 0)], ['Valor histórico', money.format(records.reduce((sum,item) => sum + item.revenue, 0))]];
      headers = ['Cliente', 'Telefone', 'Pedidos', 'Valor comprado', 'Última compra', 'Dias sem comprar'];
      rows = records.map(client => {
        const inactiveDays = client.lastDate ? Math.floor((now - new Date(client.lastDate)) / 86400000) : null;
        return '<tr><td><strong>' + escapeHtml(client.name) + '</strong></td><td>' + escapeHtml(client.phone || '—') + '</td><td>' + client.orders + '</td><td>' + escapeHtml(money.format(client.revenue)) + '</td><td>' + escapeHtml(client.lastDate ? dateLabel(client.lastDate) : 'Nenhuma compra') + '</td><td>' + escapeHtml(inactiveDays == null ? 'Sem histórico' : inactiveDays + ' dia(s)') + '</td></tr>';
      });
    } else {
      const registryMap = {
        'registry-clients': { title:'Clientes cadastrados', records:getClients(), headers:['Código','Nome','Telefone','E-mail'], row:item => [item.code,item.name,item.phone,item.email] },
        'registry-products': { title:'Produtos cadastrados', records:getProducts(), headers:['Código','Produto','Valor de venda','Ativo'], row:item => [item.code,item.description,money.format(Number(item.price || 0)),item.active === false ? 'Não' : 'Sim'] },
        'registry-categories': { title:'Categorias cadastradas', records:getCategories(), headers:['Código','Categoria','Ativa'], row:item => [item.code,item.name,item.active === false ? 'Não' : 'Sim'] },
        'registry-units': { title:'Unidades cadastradas', records:getUnits(), headers:['Código','Unidade','Sigla','Ativa'], row:item => [item.code,item.name,item.symbol,item.active === false ? 'Não' : 'Sim'] },
        'registry-suppliers': { title:'Fornecedores cadastrados', records:getSuppliers(), headers:['Código','Fornecedor','Contato','Telefone'], row:item => [item.code,item.name,item.contact,item.phone] },
        'registry-payment-methods': { title:'Formas de pagamento cadastradas', records:getPaymentMethods(), headers:['Código','Forma de pagamento','Situação'], row:item => [item.code,item.name,item.active === false ? 'Inativa' : 'Ativa'] },
        'registry-dtf-categories': { title:'Categorias de despesas cadastradas', records:getDtfExpenseCategoryRecords(), headers:['Código','Categoria','Situação'], row:item => [item.code,item.name,item.active === false ? 'Inativa' : 'Ativa'] },
        'registry-dtf-items': { title:'Insumos, peças ou serviços cadastrados', records:getDtfCatalog(), headers:['Código','Categoria','Item','Unidade','Situação'], row:item => [item.code,dtfCategoryName(item.category),item.name,dtfUnitValue(item.unit),item.active === false ? 'Inativo' : 'Ativo'] },
        'registry-dtf-movements': { title:'Movimentações de despesas cadastradas', records:getDtfExpenseMovements(), headers:['Código','Movimentação','Situação'], row:item => [item.code,item.name,item.active === false ? 'Inativa' : 'Ativa'] },
        'registry-expenses': { title:'Despesas registradas', records:getDtfCosts().map(expenseDisplayRecord), headers:['Data','Categoria','Item','Valor','Fornecedor'], row:item => [dateLabel(item.date),dtfCategoryName(item.category),item.item,money.format(Number(item.value || 0)),item.supplier || '—'] }
      };
      const config = registryMap[type];
      if (!config) return;
      title = config.title; records = config.records; headers = config.headers;
      summary = [['Registros', records.length], ['Ativos', records.filter(item => item.active !== false).length], ['Inativos', records.filter(item => item.active === false).length]];
      rows = records.map(item => '<tr>' + config.row(item).map(cell => '<td>' + escapeHtml(cell == null || cell === '' ? '—' : String(cell)) + '</td>').join('') + '</tr>');
    }

    $('#pw-dashboard-report-title').textContent = title;
    $('#pw-dashboard-report-summary').innerHTML = '<div class="pw-dashboard-report-summary">' + summary.map(item => '<div><small>' + escapeHtml(String(item[0])) + '</small><strong>' + escapeHtml(String(item[1])) + '</strong></div>').join('') + '</div>';
    $('#pw-dashboard-report-head').innerHTML = '<tr>' + headers.map(header => '<th>' + escapeHtml(header) + '</th>').join('') + '</tr>';
    $('#pw-dashboard-report-body').innerHTML = rows.length ? rows.join('') : '<tr><td colspan="' + Math.max(1, headers.length) + '">Nenhum registro encontrado para este relatório.</td></tr>';
    dashboardReportFooter(records, headers);
    enableTableSorting($('#pw-dashboard-report-modal .pw-data-table'));
    openModal('pw-dashboard-report-modal', true);
  }

  function renderPagination(view, total) {
    const section = $('[data-view="' + view + '"]');
    if (!section) return;
    let host = $('.pw-pagination', section);
    if (!host) { host = document.createElement('div'); host.className = 'pw-pagination'; section.appendChild(host); }
    const legends = view === 'orders' ? $('.pw-table-legends', section) : null;
    if (legends) section.insertBefore(host, legends);
    const pages = Math.max(1, Math.ceil(total / PAGE_SIZE));
    paginationState[view] = Math.min(paginationState[view] || 1, pages);
    host.innerHTML = '<button class="pw-btn pw-btn-soft" type="button" data-page="' + view + '" data-page-number="' + (paginationState[view] - 1) + '"' + (paginationState[view] <= 1 ? ' disabled' : '') + '>‹</button><span>Página ' + paginationState[view] + ' de ' + pages + ' · ' + total + ' registro(s)</span><button class="pw-btn pw-btn-soft" type="button" data-page="' + view + '" data-page-number="' + (paginationState[view] + 1) + '"' + (paginationState[view] >= pages ? ' disabled' : '') + '>›</button>';
  }

  function reportFooter(tbody, pageRows, filteredRows, allRows, sums) {
    if (!tbody) return;
    const table = tbody.closest('table');
    if (!table) return;
    let footer = $('tfoot.pw-report-footer', table);
    if (!footer) {
      footer = document.createElement('tfoot');
      footer.className = 'pw-report-footer';
      table.appendChild(footer);
    }
    const columnCount = table.tHead && table.tHead.rows.length ? table.tHead.rows[0].cells.length : 0;
    const sumMap = sums || {};
    const sumIndexes = Object.keys(sumMap).map(Number).filter(index => Number.isInteger(index) && index >= 0 && index < columnCount).sort((a, b) => a - b);
    const firstSum = sumIndexes.length ? sumIndexes[0] : columnCount;
    const cells = [];
    const summaryColspan = Math.max(1, firstSum);
    cells.push('<td class="pw-report-counts" colspan="' + summaryColspan + '"><strong>Exibidos nesta página: ' + pageRows.length + '</strong><span>Filtrados: ' + filteredRows.length + ' de ' + allRows.length + ' registro(s)</span></td>');
    for (let index = summaryColspan; index < columnCount; index += 1) {
      if (Object.prototype.hasOwnProperty.call(sumMap, index)) {
        const item = sumMap[index];
        cells.push('<td class="pw-report-sum"><small>' + escapeHtml(item.label || 'Soma filtrada') + '</small><strong>' + escapeHtml(item.format === 'number' ? Number(item.value || 0).toLocaleString('pt-BR') : money.format(Number(item.value || 0))) + '</strong></td>');
      } else cells.push('<td></td>');
    }
    footer.innerHTML = '<tr>' + cells.join('') + '</tr>';
  }

  function dashboardReportFooter(records, headers) {
    const body = $('#pw-dashboard-report-body');
    const sums = {};
    const sumHeaders = /^(quantidade|pedidos|presen[cç]a em pedidos|valor|valor comprado|faturamento|custo|venda|diferen[cç]a|pendente)$/i;
    headers.forEach((header, index) => {
      if (!sumHeaders.test(String(header).trim())) return;
      const values = $$('tr', body).map(row => row.children[index]).filter(Boolean).map(cell => {
        const text = String(cell.textContent || '').trim();
        if (/^-?\d+(?:[.,]\d+)?$/.test(text)) return Number(text.replace(',', '.'));
        return sortableValue(cell);
      }).filter(value => typeof value === 'number' && Number.isFinite(value));
      if (values.length) sums[index] = { label:'Soma filtrada', value:values.reduce((sum, value) => sum + value, 0), format:/^(quantidade|pedidos|presen[cç]a em pedidos)$/i.test(header) ? 'number' : 'money' };
    });
    reportFooter(body, records, records, records, sums);
  }

  function selectionCell(kind, id) {
    const checked = bulkSelections[kind].includes(String(id)) ? ' checked' : '';
    return '<td class="pw-select-cell"><input type="checkbox" data-row-select="' + kind + '" value="' + escapeHtml(id) + '"' + checked + ' aria-label="Selecionar registro"></td>';
  }

  function updateBulkToolbar(kind) {
    const count = bulkSelections[kind].length;
    const countNode = $('[data-selected-count="' + kind + '"]');
    if (countNode) countNode.textContent = count + (count === 1 ? ' selecionado' : ' selecionados');
    const edit = $('[data-bulk-edit="' + kind + '"]');
    const remove = $('[data-bulk-delete="' + kind + '"]');
    if (edit) edit.disabled = count === 0;
    if (remove) remove.disabled = count === 0;
    if (kind === 'order' && $('#pw-audit-order-status')) $('#pw-audit-order-status').disabled = count === 0;
    if (kind === 'order' && $('#pw-print-selected-orders')) $('#pw-print-selected-orders').disabled = count === 0;
    if (kind === 'arts' && $('#pw-art-preview')) renderArtPreview(selectedArtRecord);
    if (kind === 'client' && $('#pw-create-wp-login')) $('#pw-create-wp-login').disabled = count !== 1;
    const all = $('[data-select-all="' + kind + '"]');
    const visible = $$('[data-row-select="' + kind + '"]');
    if (all) {
      all.checked = visible.length > 0 && visible.every(input => input.checked);
      all.indeterminate = visible.some(input => input.checked) && !all.checked;
    }
  }

  function pruneBulkSelection(kind, validIds) {
    const valid = new Set(validIds.map(String));
    bulkSelections[kind] = bulkSelections[kind].filter(id => valid.has(String(id)));
    updateBulkToolbar(kind);
  }

  function orderStatusOptions(selected) {
    const currentIndex = statusIndex(selected);
    return ORDER_STATUS_FLOW
      .map((status, index) => '<option value="' + escapeHtml(status.value) + '"' + (status.value === selected ? ' selected' : '') + (index !== currentIndex + 1 ? ' disabled' : '') + '>' + escapeHtml(status.label) + '</option>')
      .join('');
  }

  function syncOrderStatusSelect(selected) {
    const select = $('#pw-status');
    if (!select) return;
    select.innerHTML = orderStatusOptions(selected);
    select.value = selected;
    select.dataset.previousStatus = selected;
    syncCurrentStatusDate();
  }

  function updateStoredOrderStatus(orderNumber, status, actualDelivery) {
    const orders = getOrders();
    const index = orders.findIndex(order => order.orderNumber === orderNumber);
    if (index < 0) return false;
    if (!requireApprovedPdfArts(status, orders[index].items || [], orderNumber, true)) return false;
    const previous = orders[index].status || 'Criação da arte';
    orders[index].status = status;
    orders[index].actualDelivery = status === 'Entregue' ? actualDelivery : '';
    syncOrderFinalization(orders[index]);
    orders[index].lastChange = new Date().toISOString();
    orders[index].timeline = Array.isArray(orders[index].timeline) ? orders[index].timeline : [];
    orders[index].timeline.push({ status, previous, at: new Date().toISOString(), actor: currentActor(), note: '' });
    writeStorage(STORAGE.orders, orders);
    recordAudit('order', orderNumber, 'Situação alterada', previous + ' → ' + status);
    renderOrdersConsultation();
    return true;
  }

  function orderFinancialSummaryHtml(order) {
    const itemTotals = orderItemTotals(order);
    const gross = Math.max(0, itemTotals.gross);
    const platformFees = Math.max(0, itemTotals.fees);
    const discount = Math.max(0, Number(order && order.discount || 0));
    const surcharge = Math.max(0, Number(order && order.surcharge || 0));
    const net = adjustedOrderTotal(order);
    const paid = Math.min(net, Math.max(0, Number(order && order.paid || 0)));
    const pending = Math.max(0, net - paid);
    const paymentEntries = Array.isArray(order && order.payments) ? order.payments.filter(payment => Number(payment && payment.value || 0) > 0) : [];
    const paymentText = paymentEntries.length ? paymentEntries.map(payment => (payment.method || 'Pagamento') + ': ' + money.format(Number(payment.value || 0))).join(' · ') : 'Nenhum recebimento registrado';
    return '<div class="pw-order-financial-summary"><strong>Resumo financeiro</strong><div class="pw-order-financial-grid"><span><small>Total bruto</small><b>' + escapeHtml(money.format(gross)) + '</b></span><span><small>Tarifas plataforma</small><b>' + escapeHtml(money.format(platformFees)) + '</b></span><span><small>Descontos</small><b>' + escapeHtml(money.format(discount)) + '</b></span><span><small>Acréscimos</small><b>' + escapeHtml(money.format(surcharge)) + '</b></span><span><small>Total líquido</small><b>' + escapeHtml(money.format(net)) + '</b></span><span><small>Recebido</small><b class="pw-financial-received">' + escapeHtml(money.format(paid)) + '</b></span><span><small>Saldo pendente</small><b class="' + (pending > 0.005 ? 'pw-financial-pending' : 'pw-financial-settled') + '">' + escapeHtml(pending > 0.005 ? money.format(pending) : 'Nenhum saldo pendente') + '</b></span></div><small class="pw-order-financial-payments">Recebimentos: ' + escapeHtml(paymentText) + '</small></div>';
  }

  function orderOriginFilterIconHtml(record) {
    const name = record && record.name || '';
    if (normalize(name) === normalize('Mercado Livre')) return '<span class="pw-client-origin-dot pw-origin-mercado-livre">🤝</span>';
    if (normalize(name) === normalize('Shopee')) return '<span class="pw-client-origin-dot pw-origin-shopee"><span class="pw-shopee-bag">S</span></span>';
    if (record && record.marketplace) return '<span class="pw-client-origin-dot pw-origin-marketplace">◈</span>';
    return '<span class="pw-client-origin-dot pw-origin-normal">☺</span>';
  }

  /**
   * Seleção de origens do filtro do relatório de pedidos, persistida por
   * usuário no navegador. Na primeira vez que o usuário abre o relatório
   * (sem nada salvo ainda), todas as origens ativas entram marcadas por
   * padrão — a partir daí, a escolha do usuário é lembrada.
   */
  function ordersOriginFilterStorageKey() {
    return 'pw_personalizados_orders_origin_filter_' + importantAlertUserKey();
  }

  function saveOrdersOriginFilters() {
    try { window.localStorage.setItem(ordersOriginFilterStorageKey(), JSON.stringify(ordersOriginFilters || [])); } catch (error) { /* localStorage indisponível: aplica só nesta sessão */ }
  }

  function ensureOrdersOriginFilters() {
    if (Array.isArray(ordersOriginFilters)) return ordersOriginFilters;
    let stored = null;
    try { stored = JSON.parse(window.localStorage.getItem(ordersOriginFilterStorageKey()) || 'null'); } catch (error) { stored = null; }
    if (Array.isArray(stored)) {
      ordersOriginFilters = stored;
    } else {
      ordersOriginFilters = getOrderOrigins().filter(record => record.active !== false).map(record => record.name);
      saveOrdersOriginFilters();
    }
    return ordersOriginFilters;
  }

  /**
   * Ícones de origem no filtro do relatório de pedidos. Cada ícone é
   * independente: clicar liga/desliga aquela origem no filtro, dá pra
   * marcar várias ao mesmo tempo ou nenhuma. Com pelo menos uma marcada,
   * as não marcadas ficam esmaecidas para indicar quais estão fora.
   */
  function renderOrdersOriginFilter() {
    const host = $('#pw-orders-origin-filter');
    if (!host) return;
    const selected = ensureOrdersOriginFilters();
    const hasSelection = selected.length > 0;
    const origins = getOrderOrigins().filter(record => record.active !== false || selected.some(name => normalize(name) === normalize(record.name)));
    host.innerHTML = origins.map(record => {
      const isSelected = selected.some(name => normalize(name) === normalize(record.name));
      const isActive = hasSelection && isSelected;
      const isDimmed = hasSelection && !isSelected;
      return '<button type="button" class="pw-origin-filter-btn' + (isActive ? ' pw-active' : '') + (isDimmed ? ' pw-dimmed' : '') + '" data-origin-filter="' + escapeHtml(record.name) + '" aria-pressed="' + (isSelected ? 'true' : 'false') + '" title="Filtrar pedidos de: ' + escapeHtml(record.name) + '">' + orderOriginFilterIconHtml(record) + '<span>' + escapeHtml(record.name) + '</span></button>';
    }).join('');
  }

  function ordersSituationFilterStorageKey() {
    return 'pw_personalizados_orders_situation_filter_' + importantAlertUserKey();
  }

  function saveOrdersSituationFilters() {
    try { window.localStorage.setItem(ordersSituationFilterStorageKey(), JSON.stringify(ordersSituationFilters || [])); } catch (error) { /* localStorage indisponível: aplica só nesta sessão */ }
  }

  /** Igual ao filtro de origem (mesmo padrão de pílulas), mas por situação —
   * padrão de fábrica: todas marcadas, MENOS "Entregue" (é o que o dia a dia
   * mais quer ver de cara: só o que ainda está em andamento). */
  function ensureOrdersSituationFilters() {
    if (Array.isArray(ordersSituationFilters)) return ordersSituationFilters;
    let stored = null;
    try { stored = JSON.parse(window.localStorage.getItem(ordersSituationFilterStorageKey()) || 'null'); } catch (error) { stored = null; }
    if (Array.isArray(stored)) {
      ordersSituationFilters = stored;
    } else {
      ordersSituationFilters = ORDER_STATUS_FLOW.map(status => status.value).filter(value => value !== 'Entregue');
      saveOrdersSituationFilters();
    }
    return ordersSituationFilters;
  }

  function renderOrdersSituationFilter() {
    const host = $('#pw-orders-situation-filter-bar');
    if (!host) return;
    const selected = ensureOrdersSituationFilters();
    const hasSelection = selected.length > 0;
    host.innerHTML = ORDER_STATUS_FLOW.map(status => {
      const isSelected = selected.includes(status.value);
      const isActive = hasSelection && isSelected;
      const isDimmed = hasSelection && !isSelected;
      return '<button type="button" class="pw-origin-filter-btn' + (isActive ? ' pw-active' : '') + (isDimmed ? ' pw-dimmed' : '') + '" data-situation-filter="' + escapeHtml(status.value) + '" aria-pressed="' + (isSelected ? 'true' : 'false') + '" title="Filtrar pedidos em: ' + escapeHtml(status.label) + '"><i class="pw-status-dot" style="' + statusVisualStyle(status) + '" aria-hidden="true">' + escapeHtml(status.code) + '</i><span>' + escapeHtml(status.label) + '</span></button>';
    }).join('');
  }

  /** Monta a linha de detalhe (produtos + resumo financeiro) de um pedido —
   * extraída pra ser reaproveitada tanto no render completo da tabela quanto
   * na expansão animada (openRowDetail), que insere só essa linha sem
   * redesenhar a tabela inteira. */
  function orderItemsDetailRowHtml(order, orderNumber) {
    const products = Array.isArray(order.items) ? order.items : [];
    const productRows = products.length ? products.map((item, index) => { const breakdown = itemFinancialBreakdown(item, order.origin || order.client && order.client.origin || 'Normal'); return '<tr><td>' + (index + 1) + '</td><td><strong>' + escapeHtml(item.code || '—') + '</strong></td><td>' + escapeHtml(item.description || '—') + '</td><td>' + escapeHtml(item.unit || '—') + '</td><td>' + escapeHtml(Number(item.quantity || 0).toLocaleString('pt-BR')) + '</td><td>' + escapeHtml(money.format(breakdown.netUnit)) + '</td><td>' + escapeHtml(money.format(breakdown.net)) + '</td></tr>'; }).join('') : '<tr><td colspan="7" class="pw-empty-table">Este pedido não possui produtos.</td></tr>';
    return '<tr class="pw-order-items-detail-row"><td colspan="10"><div class="pw-row-detail-inner"><div class="pw-order-items-detail">' + orderFinancialSummaryHtml(order) + '<strong>Produtos do pedido ' + escapeHtml(orderNumber) + '</strong><table><thead><tr><th>#</th><th>Código</th><th>Produto</th><th>Unidade</th><th>Quantidade</th><th>Unitário</th><th>Total</th></tr></thead><tbody>' + productRows + '</tbody></table></div></div></td></tr>';
  }

  /** Um clique num pedido do relatório de Pedidos expande/recolhe os detalhes
   * suavemente (openRowDetail/closeRowDetail) em vez de redesenhar a tabela
   * inteira — só um pedido expandido por vez, igual ao comportamento de
   * Etiquetas geradas. */
  function toggleOrderRowDetail(orderNumber, row) {
    if (!orderNumber || !row) return;
    const alreadyOpen = expandedOrderRows.has(orderNumber);
    if (alreadyOpen) {
      expandedOrderRows.clear();
      const detailRow = row.nextElementSibling;
      if (detailRow && detailRow.matches('.pw-order-items-detail-row')) closeRowDetail(detailRow, row);
      return;
    }
    const previousOrderNumber = expandedOrderRows.size ? Array.from(expandedOrderRows)[0] : '';
    if (previousOrderNumber) {
      const previousRow = document.querySelector('.pw-order-report-row[data-record-id="' + CSS.escape(previousOrderNumber) + '"]');
      const previousDetailRow = previousRow && previousRow.nextElementSibling;
      if (previousDetailRow && previousDetailRow.matches('.pw-order-items-detail-row')) closeRowDetail(previousDetailRow, previousRow);
    }
    const order = getOrders().find(item => String(item.orderNumber) === orderNumber);
    if (!order) return;
    expandedOrderRows.clear();
    expandedOrderRows.add(orderNumber);
    openRowDetail(row, orderItemsDetailRowHtml(order, orderNumber));
  }

  const ordersSortGetters = {
    orderNumber: order => Number(order.orderNumber) || 0,
    // Só a data (sem hora): granularidade por minuto deixava cada pedido
    // praticamente único, então um critério seguinte (ex.: Situação) nunca
    // tinha empate pra desempatar — na prática nunca "aparecia" ordenando.
    // Por data (sem hora), pedidos do mesmo dia empatam e aí sim Situação
    // funciona como critério seguinte, do jeito que se espera ao clicar nela.
    createdDate: order => String(order.createdDate || ''),
    clientName: order => (order.client && order.client.name) || '',
    status: order => order.status || '',
    total: order => adjustedOrderTotal(order),
  };

  /** Busca a cópia mais recente dos pedidos direto do servidor e redesenha o
   * relatório — usado tanto ao entrar na tela (automático) quanto no botão
   * "↻ Atualizar" (manual). Também limpa o aviso piscante de "pedido novo"
   * (ícone do menu e este botão), já que o usuário acabou de puxar os dados
   * mais recentes. */
  async function refreshOrdersReport() {
    const ok = await refreshSharedStorageSnapshot();
    if (ok) renderOrdersConsultation();
    markOrderNotificationsSeen();
    // Limpa imediatamente o blink de alteração de campos (o fingerprint já foi
    // atualizado por renderOrdersConsultation acima).
    const refreshBtn = $('#pw-orders-refresh');
    if (refreshBtn) refreshBtn.classList.remove('pw-ml-notify-blink');
    return ok;
  }

  function renderOrdersConsultation() {
    const query = normalize($('#pw-orders-consult-search').value);
    const allDates = $('#pw-orders-all-dates').checked;
    const start = $('#pw-orders-date-start').value;
    const end = $('#pw-orders-date-end').value;
    const allRows = getOrders();
    const historyFilter = $('#pw-orders-status-filter').value || 'open';
    renderOrdersOriginFilter();
    renderOrdersSituationFilter();
    const rows = allRows.filter(order => {
      const searchable = [order.orderNumber, order.marketplaceOrderNumber, order.client && order.client.name, order.client && order.client.phone, order.client && order.client.document, order.status, order.origin].join(' ');
      const matchesText = !query || normalize(searchable).includes(query);
      const date = String(order.createdDate || '').slice(0, 10);
      const matchesPeriod = allDates || ((!start || date >= start) && (!end || date <= end));
      const matchesHistory = historyFilter === 'all' || (historyFilter === 'finalized' ? isOrderFinalized(order) : !isOrderFinalized(order));
      const selectedSituations = ensureOrdersSituationFilters();
      const matchesSituation = selectedSituations.length === 0 || selectedSituations.includes(order.status || 'Criação da arte');
      const selectedOrigins = ensureOrdersOriginFilters();
      const matchesOrigin = selectedOrigins.length === 0 || selectedOrigins.some(name => normalize(name) === normalize(order.origin || (order.client && order.client.origin) || 'Normal'));
      return matchesText && matchesPeriod && matchesHistory && matchesSituation && matchesOrigin;
    }).sort((multiSortState.orders || []).length
      ? compareByMultiSort('orders', ordersSortGetters)
      : (a, b) => (Number(b.orderNumber) || 0) - (Number(a.orderNumber) || 0) || String(b.lastChange || b.createdDate || '').localeCompare(String(a.lastChange || a.createdDate || '')));
    ordersViewFingerprint = buildOrdersViewFingerprint(rows);
    filteredRecordIds.order = rows.map(order => String(order.orderNumber));
    const pageRows = rows.slice((paginationState.orders - 1) * PAGE_SIZE, paginationState.orders * PAGE_SIZE);
    const body = $('#pw-orders-consult-body');
    const legend = $('#pw-order-status-legend');
    if (legend) legend.innerHTML = statusLegendHtml();
    const paymentLegend = $('#pw-payment-method-legend');
    if (paymentLegend) paymentLegend.innerHTML = paymentMethodLegendHtml();
    const infoLegend = $('#pw-order-info-legend');
    if (infoLegend) infoLegend.innerHTML = orderInfoLegendHtml();
    body.innerHTML = rows.length ? pageRows.map(order => {
      const orderNumber = String(order.orderNumber || '');
      const creator = createdByFilterLabel(order) || 'Não informado';
      const adjustments = [];
      if (Number(order.discount || 0) > 0.005) adjustments.push('Desconto no faturamento: ' + money.format(Number(order.discount || 0)));
      if (Number(order.surcharge || 0) > 0.005) adjustments.push('Acréscimo no faturamento: ' + money.format(Number(order.surcharge || 0)));
      const platformFees = orderItemTotals(order).fees;
      if (platformFees > 0.005) adjustments.push('Tarifas de marketplace: ' + money.format(platformFees));
      const totalTooltip = adjustments.length ? ' title="' + escapeHtml(adjustments.join(' · ')) + '" data-tooltip="' + escapeHtml(adjustments.join(' · ')) + '"' : '';
      const mainRow = '<tr class="pw-order-report-row' + (expandedOrderRows.has(orderNumber) ? ' pw-expanded' : '') + '" data-record-kind="order" data-record-id="' + escapeHtml(orderNumber) + '">' + selectionCell('order', order.orderNumber) +
      '<td class="pw-order-number-cell pw-tooltip" title="Cadastrado por: ' + escapeHtml(creator) + '" data-tooltip="Cadastrado por: ' + escapeHtml(creator) + '"><strong>' + escapeHtml(order.orderNumber || '—') + '</strong></td>' +
      '<td class="pw-order-created-date"><small>' + escapeHtml(order.createdDate ? new Date(order.createdDate + 'T' + (order.orderTime || '00:00')).toLocaleString('pt-BR', { day:'2-digit', month:'2-digit', year:'numeric', hour:'2-digit', minute:'2-digit' }) : '—') + '</small></td>' +
      '<td>' + escapeHtml(order.client && order.client.name || '—') + '</td>' +
      '<td><select class="pw-inline-status" data-order-status="' + escapeHtml(order.orderNumber) + '" data-previous-status="' + escapeHtml(order.status || 'Criação da arte') + '"' + (isOrderFinalized(order) ? ' disabled title="Pedido finalizado: não pode mais ser alterado"' : (orderIsLockedForCollaborator(order) ? ' disabled title="Pedido bloqueado para alterações após a mudança de situação"' : '')) + '>' + orderStatusOptions(order.status || 'Criação da arte') + '</select>' +
      '<small class="pw-order-status-date" data-order-status-date="' + escapeHtml(order.orderNumber) + '">' + escapeHtml(formatStatusDate(orderStatusDate(order, order.status || 'Criação da arte'))) + '</small></td>' +
      '<td><div class="pw-order-history-indicators">' + statusDotsHtml(order) + '</div></td>' +
      '<td>' + paymentMethodDotsHtml(order) + '</td>' +
      '<td>' + orderInfoIndicatorsHtml(order) + '</td>' +
      '<td>' + (orderArtFiles(order).length ? '<button class="pw-btn pw-btn-soft pw-btn-icon pw-tooltip" type="button" data-download-order-arts="' + escapeHtml(order.orderNumber) + '" data-tooltip="' + escapeHtml(orderArtTooltip(order) + (orderArtFiles(order).some(orderArtIsPreviewable) ? '' : ' — sem pré-visualização, só baixar')) + '" title="' + escapeHtml(orderArtTooltip(order)) + '" aria-label="Ver anexos do pedido">' + (orderArtFiles(order).some(orderArtIsPreviewable) ? '👁' : '📎') + '</button>' : '—') + '</td>' +
      '<td class="pw-order-total-cell' + (adjustments.length ? ' pw-tooltip' : '') + '"' + totalTooltip + '>' + escapeHtml(money.format(adjustedOrderTotal(order))) + '</td></tr>';
      if (!expandedOrderRows.has(orderNumber)) return mainRow;
      return mainRow + orderItemsDetailRowHtml(order, orderNumber);
    }).join('')
      : '<tr><td class="pw-empty-table" colspan="10">Nenhum pedido encontrado.</td></tr>';
    pruneBulkSelection('order', rows.map(order => order.orderNumber));
    reportFooter(body, pageRows, rows, allRows, { 9: { label:'Total filtrado', value:rows.reduce((sum, order) => sum + adjustedOrderTotal(order), 0) } });
    renderPagination('orders', rows.length);
    updateSortIndicators('orders', '[data-view="orders"] thead');
  }

