  function registryConfig(kind) {
    return {
      category: { plural: 'categories', label: 'categoria', records: getCategories, storage: STORAGE.categories, search: '#pw-categories-consult-search', body: '#pw-categories-consult-body' },
      dtfCategory: { plural: 'dtf-category-report', label: 'categoria de despesa', records: getDtfExpenseCategoryRecords, storage: STORAGE.dtfExpenseCategories, search: '#pw-dtf-category-report-search', body: '#pw-dtf-category-report-body' },
      dtfItem: { plural: 'dtf-items', label: 'insumo, peça ou serviço', records: getDtfCatalog, storage: STORAGE.dtfCatalog },
      dtfMovement: { plural:'dtf-movement-report', label:'movimentação de despesa', records:getDtfExpenseMovements, storage:STORAGE.dtfExpenseMovements },
      dtfCost: { plural: 'dtf-list', label: 'despesa', records: getDtfCosts, storage: STORAGE.dtfCosts },
      unit: { plural: 'units', label: 'unidade de venda', records: getUnits, storage: STORAGE.units, search: '#pw-units-consult-search', body: '#pw-units-consult-body' },
      supplier: { plural: 'suppliers', label: 'fornecedor', records: getSuppliers, storage: STORAGE.suppliers, search: '#pw-suppliers-consult-search', body: '#pw-suppliers-consult-body' },
      paymentMethod: { plural: 'paymentMethods', label: 'forma de pagamento', records: getPaymentMethods, storage: STORAGE.paymentMethods, search: '#pw-payment-methods-consult-search', body: '#pw-payment-methods-consult-body' },
      orderOrigin: { plural: 'order-origins', label: 'origem do pedido', records: getOrderOrigins, storage: STORAGE.orderOrigins, search: '#pw-order-origins-consult-search', body: '#pw-order-origins-consult-body' }
    }[kind];
  }

  function openRegistryEditor(kind, record) {
    const config = registryConfig(kind);
    if (kind.startsWith('dtf') && !userIsAdministrator(currentUser)) return showMessage('Apenas administradores podem alterar cadastros de despesas.', 'error');
    if (kind === 'dtfCost') { editDtfCost(record); return; }
    $('#pw-save-registry').classList.remove('pw-saved');
    if (!record) { bulkEditContext = { kind:'', ids:[], index:0 }; renderBulkNavigation(); }
    $('#pw-registry-modal').className = 'pw-modal pw-registry-kind-' + kind;
    $('#pw-registry-kind').value = kind;
    $('#pw-registry-id').value = record && record.id || '';
    $('#pw-registry-modal-title').textContent = (record ? 'Alterar ' : 'Cadastrar ') + config.label;
    $('#pw-registry-code').value = record && record.code || nextRegistryCode(kind);
    $('#pw-registry-code').readOnly = !(record && userIsAdministrator(currentUser));
    $('#pw-registry-code').title = record && userIsAdministrator(currentUser) ? 'Administrador: código editável' : 'O código é automático em novos cadastros';
    $('#pw-registry-name').value = record && record.name || '';
    $('#pw-registry-active').checked = !record || record.active !== false;
    $('#pw-registry-marketplace').checked = !!(record && record.marketplace);
    $('#pw-registry-symbol').value = record && record.symbol || '';
    $('#pw-registry-contact').value = record && record.contact || '';
    $('#pw-registry-phone').value = record && record.phone || '';
    $('#pw-registry-email').value = record && record.email || '';
    $('#pw-registry-document').value = record && record.document || '';
    $('#pw-registry-notes').value = record && record.notes || '';
    $('#pw-registry-supplier-type').value = (kind === 'supplier' && record && record.supplierType) || '';
    if (kind === 'dtfItem') {
      const category = dtfCategoryName(record && record.category || $('#pw-dtf-cost-category').value || 'Outro');
      const categories = [...new Set([...getDtfExpenseCategories(), category].filter(Boolean))];
      $('#pw-registry-expense-category').innerHTML = categories.map(name => '<option value="' + escapeHtml(name) + '">' + escapeHtml(name) + '</option>').join('');
      $('#pw-registry-expense-category').value = category;
      populateDtfUnitSelect($('#pw-registry-expense-unit'), record && record.unit || 'unidade');
    }
    openModal('pw-registry-modal', true);
  }

  // Getters por tipo de cadastro — cada um só usa as chaves que aparecem nas
  // colunas ordenáveis daquela tabela (marcadas com data-sort-key no PHP).
  const registrySortGetters = {
    category: { code: r => Number(r.code) || 0, name: r => r.name || '', active: r => r.active !== false ? 1 : 0 },
    unit: { code: r => Number(r.code) || 0, name: r => r.name || '', symbol: r => r.symbol || '', active: r => r.active !== false ? 1 : 0 },
    orderOrigin: { code: r => Number(r.code) || 0, name: r => r.name || '', marketplace: r => r.marketplace ? 1 : 0, active: r => r.active !== false ? 1 : 0 },
    supplier: { code: r => Number(r.code) || 0, name: r => r.name || '', contact: r => r.contact || '', phone: r => r.phone || '', document: r => r.document || '', active: r => r.active !== false ? 1 : 0 },
    paymentMethod: { code: r => Number(r.code) || 0, name: r => r.name || '', active: r => r.active !== false ? 1 : 0 },
  };

  function renderRegistryConsultation(kind) {
    const expenseType = { dtfCategory:'category', dtfMovement:'movement', dtfItem:'item', dtfCost:'cost' }[kind];
    if (expenseType) return renderDtfExpenseReport(expenseType);
    const config = registryConfig(kind);
    const query = normalize($(config.search).value);
    const allRows = orderedRecords(config.records());
    const rows = allRows.filter(record => !query || normalize([record.code, record.name, record.symbol, record.contact, record.phone, record.document].join(' ')).includes(query))
      .sort((multiSortState[config.plural] || []).length ? compareByMultiSort(config.plural, registrySortGetters[kind]) : () => 0);
    filteredRecordIds[kind] = rows.map(record => String(record.id));
    const pageKey = config.plural;
    const pageRows = rows.slice((paginationState[pageKey] - 1) * PAGE_SIZE, paginationState[pageKey] * PAGE_SIZE);
    const body = $(config.body);
    body.innerHTML = rows.length ? pageRows.map(record => {
      const status = record.active !== false ? 'Ativo' : 'Inativo';
      const start = '<tr draggable="' + (userIsAdministrator(currentUser) ? 'true' : 'false') + '" data-record-kind="' + kind + '" data-record-id="' + escapeHtml(record.id) + '">';
      if (kind === 'category') return start + selectionCell(kind, record.id) + '<td>' + escapeHtml(record.code) + '</td><td><strong>' + escapeHtml(record.name) + '</strong></td><td>' + status + '</td></tr>';
      if (kind === 'paymentMethod') return start + selectionCell(kind, record.id) + '<td>' + escapeHtml(record.code) + '</td><td><strong>' + escapeHtml(record.name) + '</strong></td><td>' + status + '</td></tr>';
      if (kind === 'orderOrigin') return start + selectionCell(kind, record.id) + '<td>' + escapeHtml(record.code) + '</td><td><strong>' + escapeHtml(record.name) + '</strong></td><td>' + (record.marketplace ? 'Sim' : 'Não') + '</td><td>' + status + '</td></tr>';
      if (kind === 'unit') return start + selectionCell(kind, record.id) + '<td>' + escapeHtml(record.code) + '</td><td><strong>' + escapeHtml(record.name) + '</strong></td><td>' + escapeHtml(record.symbol || '—') + '</td><td>' + status + '</td></tr>';
      const supplierTypeLabel = record.supplierType === 'materials' ? 'Materiais' : record.supplierType === 'ads' ? 'Anúncios' : record.supplierType === 'both' ? 'Materiais e Anúncios' : '—';
      return start + selectionCell(kind, record.id) + '<td>' + escapeHtml(record.code) + '</td><td><strong>' + escapeHtml(record.name) + '</strong></td><td>' + supplierTypeLabel + '</td><td>' + escapeHtml(record.contact || '—') + '</td><td>' + escapeHtml(record.phone || '—') + '</td><td>' + escapeHtml(record.document || '—') + '</td><td>' + status + '</td></tr>';
    }).join('') : '<tr><td class="pw-empty-table" colspan="8">Nenhum registro encontrado.</td></tr>';
    pruneBulkSelection(kind, rows.map(record => record.id));
    reportFooter(body, pageRows, rows, allRows);
    renderPagination(pageKey, rows.length);
    // config.plural é a chave usada pra paginação/ordenação (nem sempre bate
    // com o valor de data-view no HTML — ex.: "paymentMethods" vs. o atributo
    // "payment-methods" — por isso o mapeamento explícito aqui).
    const registryViewNames = { categories: 'categories', units: 'units', 'order-origins': 'order-origins', suppliers: 'suppliers', paymentMethods: 'payment-methods' };
    updateSortIndicators(config.plural, '[data-view="' + (registryViewNames[config.plural] || config.plural) + '"] thead');
  }

  function registryOrderSource(kind) {
    if (kind === 'client') return { records: getClients(), storage: STORAGE.clients, render: renderClientsConsultation };
    if (kind === 'product') return { records: getProducts(), storage: STORAGE.products, render: renderProductsConsultation };
    const config = registryConfig(kind);
    return config ? { records: config.records(), storage: config.storage, render: () => renderRegistryConsultation(kind) } : null;
  }

  async function saveDraggedRegistryOrder(kind, body) {
    const source = registryOrderSource(kind);
    if (!source || !userIsAdministrator(currentUser)) return;
    const ids = $$('tr[data-record-kind="' + kind + '"]', body).map(row => String(row.dataset.recordId));
    if (ids.length < 2) return;
    const ordered = orderedRecords(source.records);
    const positionMap = new Map(ordered.map((record, index) => [String(record.id), Number.isFinite(Number(record.position)) ? Number(record.position) : index]));
    const slots = ids.map(id => positionMap.get(id)).sort((a, b) => a - b);
    ids.forEach((id, index) => {
      const record = source.records.find(item => String(item.id) === id);
      if (record) record.position = slots[index];
    });
    const saved = kind.startsWith('dtf') ? await saveExpenseCollection(source.storage, source.records) : await writeStorage(source.storage, source.records, { immediate: true });
    if (!saved) return;
    recordAudit(kind, 'order', 'Ordem dos registros alterada', ids.length + ' registros reposicionados');
    source.render();
    showMessage('Nova ordem dos registros salva.', 'success');
  }

  function sortableValue(cell) {
    const select = $('select', cell);
    if (select) {
      const selectedOption = select.options[select.selectedIndex];
      return normalize(selectedOption ? selectedOption.textContent : select.value);
    }
    const text = String(cell.textContent || '').trim();
    const brDate = text.match(/^(\d{2})\/(\d{2})\/(\d{4})/);
    if (brDate) return brDate[3] + brDate[2] + brDate[1];
    if (/^R\$/.test(text)) return Number(text.replace(/[^0-9,-]/g, '').replace('.', '').replace(',', '.')) || 0;
    return normalize(text);
  }

  function enableTableSorting(table) {
    if (!table) return;
    const headers = table.tHead && table.tHead.rows.length ? Array.from(table.tHead.rows[0].cells) : [];
    // Tabela já migrada pra engine de multi-ordenação nova (attachSortableHeaders)
    // fica inteira fora deste mecanismo antigo — misturar as duas nos MESMOS
    // cabeçalhos gera dois indicadores de seta e estado inconsistente.
    if (headers.some(header => header.dataset.sortKey)) return;
    headers.forEach((header, columnIndex) => {
      // data-sort-key marca colunas já controladas pela engine de ordenação
      // multi-coluna nova (attachSortableHeaders/toggleMultiSort) — esse
      // mecanismo antigo (single-column, reordena o DOM direto) tem que
      // ignorar essas colunas, senão os dois sistemas brigam pelo mesmo
      // cabeçalho (foi exatamente isso que causou duas setas e estado
      // "grudado" na tela Pedidos ao migrar suas colunas pra engine nova).
      if (header.classList.contains('pw-select-cell') || header.dataset.sortReady || header.dataset.sortKey) return;
      header.dataset.sortReady = '1';
      header.title = 'Clique para ordenar: crescente, decrescente e ordem padrão';
      header.addEventListener('click', () => {
        const current = header.classList.contains('pw-sort-asc') ? 'asc' : (header.classList.contains('pw-sort-desc') ? 'desc' : 'none');
        const next = current === 'none' ? 'asc' : (current === 'asc' ? 'desc' : 'none');
        headers.forEach(item => {
          item.classList.remove('pw-sort-asc', 'pw-sort-desc');
          item.removeAttribute('aria-sort');
        });
        if (next !== 'none') {
          header.classList.add(next === 'asc' ? 'pw-sort-asc' : 'pw-sort-desc');
          header.setAttribute('aria-sort', next === 'asc' ? 'ascending' : 'descending');
        }
        const body = $('tbody', table);
        Array.from(body.children).filter(row => row.classList && row.classList.contains('pw-order-items-detail-row')).forEach(row => row.remove());
        const ordersBody = $('#pw-orders-consult-body');
        if (ordersBody && table.contains(ordersBody)) expandedOrderRows.clear();
        const rows = Array.from(body.children).filter(row => row.tagName === 'TR' && !row.querySelector('.pw-empty-table') && !row.classList.contains('pw-order-items-detail-row'));
        rows.forEach((row, index) => {
          if (!row.dataset.pwDefaultIndex) row.dataset.pwDefaultIndex = String(index + 1);
        });
        rows.sort((a, b) => {
          if (next === 'none') return Number(a.dataset.pwDefaultIndex) - Number(b.dataset.pwDefaultIndex);
          const direction = next === 'asc' ? 1 : -1;
          const av = sortableValue(a.children[columnIndex]);
          const bv = sortableValue(b.children[columnIndex]);
          if (typeof av === 'number' && typeof bv === 'number') return (av - bv) * direction;
          return String(av).localeCompare(String(bv), 'pt-BR', { numeric: true, sensitivity: 'base' }) * direction;
        }).forEach(row => body.appendChild(row));
      });
    });
  }

  function enableConsultationSorting() {
    $$('.pw-consultation .pw-data-table').forEach(enableTableSorting);
  }

  function loadOrder(orderNumber) {
    const order = getOrders().find(record => record.orderNumber === orderNumber);
    if (!order) return showMessage('Pedido não encontrado.', 'error');
    if ($('[data-view="order"].pw-active') && String($('#pw-order-number').value) !== String(orderNumber) && orderHasUnsavedChanges() && !bypassOrderUnsavedPrompt) {
      openUnsavedChoice('pw-order-form', () => loadOrder(orderNumber));
      return;
    }
    editingOrderNumber = order.orderNumber;
    aiOrderPaymentPending = false;
    loadedOrderCreator = order.createdBy || null;
    $('#pw-order-number').value = order.orderNumber || '';
    $('#pw-order-number-view').textContent = order.orderNumber || '—';
    $('#pw-created-date').value = order.createdDate || '';
    $('#pw-order-time').value = order.orderTime || '';
    $('#pw-last-change').value = order.lastChange ? dateTime.format(new Date(order.lastChange)) : 'Ainda não alterado';
    $('#pw-created-by').value = loadedOrderCreator && loadedOrderCreator.summary ? loadedOrderCreator.summary : userSummary(currentUser);
    $('#pw-requested-delivery').value = order.requestedDelivery || '';
    syncOrderStatusSelect(order.status || 'Criação da arte');
    formStatusChangeAt = null;
    syncOrderOriginOptions(order.origin || (order.client && order.client.origin) || 'Normal');
    populatePaymentMethodSelects(order.paymentMethod || '', '');
    $('#pw-actual-delivery').value = order.actualDelivery || '';
    syncActualDeliveryAvailability();
    $('#pw-personalization-notes').value = order.personalizationNotes || '';
    setDetailsSection(!!(order.personalizationNotes && order.personalizationNotes.trim()));
    $('#pw-payment-method').value = order.paymentMethod || '';
    $('#pw-payment-status').value = order.paymentStatus || 'Pendente';
    $('#pw-discount-value').value = Number(order.discount || 0).toFixed(2).replace('.', ',');
    $('#pw-surcharge-value').value = Number(order.surcharge || 0).toFixed(2).replace('.', ',');
    $('#pw-paid-value').value = Number(order.paid || 0).toFixed(2).replace('.', ',');
    if (order.client) selectClient(order.client);
    else clearClient();
    syncOrderOriginOptions(order.origin || (order.client && order.client.origin) || 'Normal');
    items = (order.items || []).map((item, index) => {
      const loaded = {
        ...item,
        rowId: item.rowId || 'loaded-' + index + '-' + Date.now(),
        productId: item.productId || item.id || '',
        variationId: item.variationId || '',
        unitId: item.unitId || '',
        unit: item.unit || ''
      };
      if (loaded.dtfUv && loaded.unit !== 'cm') {
        const height = Number(loaded.dtfUv.height || 0);
        const previousTotal = Number(loaded.quantity || 1) * Number(loaded.unitPrice || 0);
        if (height > 0) { loaded.unit = 'cm'; loaded.quantity = height; loaded.unitPrice = previousTotal / height; }
      }
      return loaded;
    });
    renderItems();
    syncDateConstraints();
    updateDeadlineStatus();
    const note = $('#pw-editing-note');
    note.textContent = 'Editando o pedido ' + order.orderNumber + '. Ao salvar, o registro existente será atualizado.';
    note.classList.add('pw-visible');
    updateSystemViewContext('order');
    syncOrderEditLock(order);
    showSystemView('order');
    renderBulkNavigation();
    captureOrderSavedState(true);
  }

  function recordsForKind(kind) {
    if (kind === 'order') return getOrders().map(record => ({ id: record.orderNumber, record }));
    if (kind === 'client') return getClients().map(record => ({ id: record.id, record }));
    if (kind === 'product') return getProducts().map(record => ({ id: record.id, record }));
    const config = registryConfig(kind);
    return config ? config.records().map(record => ({ id: record.id, record })) : [];
  }

  function openBulkRecord(index) {
    const modalId = bulkEditContext.kind === 'dtfCost' ? 'pw-dtf-cost-modal' : bulkEditContext.kind === 'client' ? 'pw-client-modal' : bulkEditContext.kind === 'product' ? 'pw-product-modal' : registryConfig(bulkEditContext.kind) ? 'pw-registry-modal' : '';
    if (modalId && index !== bulkEditContext.index && $('#' + modalId).classList.contains('pw-open') && modalHasUnsavedChanges(modalId)) {
      openUnsavedChoice(modalId, () => openBulkRecord(index), 'navigate'); return;
    }
    if (!bulkEditContext.ids.length) return;
    bulkEditContext.index = Math.max(0, Math.min(index, bulkEditContext.ids.length - 1));
    const id = bulkEditContext.ids[bulkEditContext.index];
    const found = recordsForKind(bulkEditContext.kind).find(item => String(item.id) === String(id));
    if (!found) return;
    if (bulkEditContext.kind === 'order') loadOrder(id);
    else if (bulkEditContext.kind === 'client') openClientEditor(found.record);
    else if (bulkEditContext.kind === 'product') openProductEditor(found.record);
    else openRegistryEditor(bulkEditContext.kind, found.record);
    renderBulkNavigation();
  }

  function renderBulkNavigation() {
    $$('.pw-bulk-nav').forEach(node => node.remove());
    if (bulkEditContext.ids.length <= 1) return;
    const kind = bulkEditContext.kind;
    let host = null;
    if (kind === 'client') host = $('#pw-client-modal .pw-modal-header');
    else if (kind === 'product') host = $('#pw-product-modal .pw-modal-header');
    else if (kind === 'dtfCost') host = $('#pw-dtf-cost-modal .pw-modal-header');
    else if (registryConfig(kind)) host = $('#pw-registry-modal .pw-modal-header');
    else host = $('#pw-editing-note');
    if (!host) return;
    const nav = document.createElement('div');
    nav.className = 'pw-bulk-nav pw-visible';
    const total = bulkEditContext.total || recordsForKind(kind).length;
    const filtered = bulkEditContext.filtered || bulkEditContext.ids.length;
    const countText = filtered < total ? (bulkEditContext.index + 1) + ' de ' + filtered + ' filtrados · ' + total + ' no total' : (bulkEditContext.index + 1) + ' de ' + total + ' registros';
    nav.innerHTML = '<button class="pw-btn pw-btn-soft pw-btn-icon pw-tooltip" type="button" data-bulk-prev data-tooltip="Registro anterior" title="Registro anterior" aria-label="Registro anterior">←</button>' +
      '<span class="pw-bulk-nav-status">' + countText + '</span>' +
      '<button class="pw-btn pw-btn-soft pw-btn-icon pw-tooltip" type="button" data-bulk-next data-tooltip="Próximo registro" title="Próximo registro" aria-label="Próximo registro">→</button>';
    const closeButton = host.querySelector('[data-close-modal]');
    if (closeButton) host.insertBefore(nav, closeButton);
    else host.appendChild(nav);
    $('[data-bulk-prev]', nav).disabled = bulkEditContext.index === 0;
    $('[data-bulk-next]', nav).disabled = bulkEditContext.index >= bulkEditContext.ids.length - 1;
  }

  function startBulkEdit(kind) {
    if (!bulkSelections[kind].length) return;
    const total = recordsForKind(kind).length;
    const ids = bulkSelections[kind].map(String);
    const first = String(bulkSelections[kind][0]);
    bulkEditContext = { kind, ids, index: Math.max(0, ids.indexOf(first)), total: ids.length, filtered: ids.length };
    openBulkRecord(bulkEditContext.index);
  }

  function keepBulkEditorOpen(kind, id) {
    return bulkEditContext.kind === kind && bulkEditContext.ids.some(selectedId => String(selectedId) === String(id));
  }

  /** Cliente ativo referenciado por um pedido — null se o pedido não tem
   * cliente vinculado ou se o cliente já foi movido pra Lixeira (nesse
   * caso o vínculo não deve mais ser considerado). */
  function orderLinkedActiveClient(order) {
    if (!order || !order.client || (!order.client.id && !order.client.name)) return null;
    return getClients().find(client =>
      (order.client.id && String(client.id) === String(order.client.id)) ||
      (!order.client.id && normalize(client.name) === normalize(order.client.name))
    ) || null;
  }

  function linkedDeletionTopics(kind, record) {
    const topics = [];
    const orders = getOrders();
    const costs = getDtfCosts();
    const catalog = getDtfCatalog();
    const orderLabel = order => String(order.orderNumber || 'Pedido sem número');
    const itemMatches = (item, target) => item && target && (String(item.productId || '') === String(target.id || '') || String(item.code || '') === String(target.code || '') || [target.name, ...(target.aliases || [])].some(name => normalize(name) === normalize(item.description || item.item || item.name)));
    if (kind === 'order') {
      const payments = Array.isArray(record.payments) ? record.payments.length : 0;
      if (payments) topics.push('Histórico financeiro: ' + payments + ' pagamento(s) registrado(s)');
      // Só considera o vínculo se o cliente ainda estiver ativo — um cliente
      // já excluído (na Lixeira) não deve mais aparecer como pendência aqui.
      const linkedClient = orderLinkedActiveClient(record);
      if (linkedClient) topics.push('Cliente: ' + linkedClient.name);
    }
    if (kind === 'client') {
      const matches = orders.filter(order => order.client && (String(order.client.id || '') === String(record.id) || normalize(order.client.name) === normalize(record.name)));
      if (matches.length) topics.push('Pedidos: ' + matches.map(orderLabel).join(', '));
    }
    if (kind === 'product') {
      const matches = orders.filter(order => (order.items || []).some(item => itemMatches(item, record)));
      if (matches.length) topics.push('Pedidos: ' + matches.map(orderLabel).join(', '));
    }
    if (kind === 'category') {
      const products = getProducts().filter(item => String(item.categoryId || '') === String(record.id) || normalize(item.category) === normalize(record.name));
      const orderMatches = orders.filter(order => (order.items || []).some(item => normalize(item.category || item.categoryName) === normalize(record.name)));
      if (products.length) topics.push('Produtos: ' + products.map(item => item.name || item.description || item.code).join(', '));
      if (orderMatches.length) topics.push('Pedidos: ' + orderMatches.map(orderLabel).join(', '));
    }
    if (kind === 'unit') {
      const products = getProducts().filter(item => String(item.unitId || '') === String(record.id));
      const catalogMatches = catalog.filter(item => dtfUnitMatches({ ...record, aliases:record.aliases || [] }, item.unit));
      const costMatches = costs.filter(item => dtfUnitMatches({ ...record, aliases:record.aliases || [] }, item.unit));
      if (products.length) topics.push('Produtos: ' + products.map(item => item.name || item.description || item.code).join(', '));
      if (catalogMatches.length) topics.push('Insumos, peças ou serviços: ' + catalogMatches.map(item => item.name).join(', '));
      if (costMatches.length) topics.push('Despesas: ' + costMatches.map(item => item.item || item.id).join(', '));
    }
    if (kind === 'supplier') {
      const productMatches = getProducts().filter(item => String(item.supplierId || '') === String(record.id));
      const costMatches = costs.filter(item => String(item.supplierId || '') === String(record.id) || normalize(item.supplier) === normalize(record.name));
      if (productMatches.length) topics.push('Produtos: ' + productMatches.map(item => item.name || item.description || item.code).join(', '));
      if (costMatches.length) topics.push('Despesas: ' + costMatches.map(item => item.item || item.id).join(', '));
    }
    if (kind === 'paymentMethod') {
      const orderMatches = orders.filter(order => order.paymentMethod === record.name || (order.payments || []).some(payment => payment.method === record.name));
      if (orderMatches.length) topics.push('Pedidos e histórico financeiro: ' + orderMatches.map(orderLabel).join(', '));
    }
    if (kind === 'orderOrigin') {
      const orderMatches = orders.filter(order => normalize(order.origin || (order.client && order.client.origin)) === normalize(record.name));
      if (orderMatches.length) topics.push('Pedidos: ' + orderMatches.map(orderLabel).join(', '));
    }
    if (kind === 'dtfCategory') {
      const itemMatchesByCategory = catalog.filter(item => dtfCategoryMatches(record, item.category));
      const costMatches = costs.filter(item => dtfCategoryMatches(record, item.category));
      if (itemMatchesByCategory.length) topics.push('Insumos, peças ou serviços: ' + itemMatchesByCategory.map(item => item.name).join(', '));
      if (costMatches.length) topics.push('Despesas: ' + costMatches.map(item => item.item || item.id).join(', '));
    }
    if (kind === 'dtfItem') {
      const matches = costs.filter(cost => cost.itemId === record.id || (dtfCategoryName(cost.category) === dtfCategoryName(record.category) && (cost.itemCode === record.code || [record.name, ...(record.aliases || [])].some(name => normalize(name) === normalize(cost.item)))));
      if (matches.length) topics.push('Despesas: ' + matches.map(item => item.item || item.id).join(', '));
    }
    if (kind === 'dtfMovement') {
      const matches = costs.filter(item => dtfMovementMatches(record, item.action));
      if (matches.length) topics.push('Despesas: ' + matches.map(item => item.item || item.id).join(', '));
    }
    return topics;
  }

  /**
   * Ao excluir pedido(s), lista clientes que poderiam ser excluídos junto —
   * mas só quando o cliente for usado EXCLUSIVAMENTE pelos pedidos sendo
   * excluídos agora. Se o cliente tiver qualquer outro pedido ativo (fora
   * deste lote), a opção não é oferecida, pra não arriscar apagar um
   * cadastro que outro pedido ainda precisa.
   */
  function orderCascadeClientOptions(ordersBeingDeleted) {
    const deletingNumbers = new Set(ordersBeingDeleted.map(order => String(order.orderNumber)));
    const seen = new Map();
    ordersBeingDeleted.forEach(order => {
      const client = orderLinkedActiveClient(order);
      if (!client || seen.has(String(client.id))) return;
      const hasOtherOrder = getOrders().some(other =>
        !deletingNumbers.has(String(other.orderNumber)) && orderLinkedActiveClient(other) && String(orderLinkedActiveClient(other).id) === String(client.id)
      );
      if (!hasOtherOrder) seen.set(String(client.id), client);
    });
    return Array.from(seen.values());
  }

  function confirmLinkedDeletion(kind, records) {
    const blocks = records.map(record => ({ record, topics: linkedDeletionTopics(kind, record) })).filter(item => item.topics.length);
    const cascadeClients = kind === 'order' ? orderCascadeClientOptions(records) : [];
    if (!blocks.length) return Promise.resolve(null);
    const modal        = $('#pw-linked-delete-modal');
    const list         = $('#pw-linked-delete-list');
    const help         = $('#pw-linked-delete-help');
    const paymentsHost = $('#pw-linked-delete-payments');
    const cascadeHost  = $('#pw-linked-delete-cascade');

    const baseHelpText = {
      order:         'O pedido será movido para a Lixeira.',
      client:        'O cliente sairá do cadastro ativo, mas os pedidos existentes continuarão com os dados já registrados.',
      product:       'O produto será retirado do estoque ativo. Os itens já lançados em pedidos e seus valores históricos não serão apagados.',
      category:      'A categoria deixará de aparecer como opção de novos cadastros. Produtos e pedidos que já usam essa categoria serão preservados.',
      unit:          'A unidade deixará de aparecer como opção de novos cadastros. Produtos, itens e despesas já vinculados continuarão com a unidade registrada.',
      supplier:      'O fornecedor será retirado do cadastro ativo. Despesas e produtos vinculados continuarão preservando o fornecedor e o histórico.',
      paymentMethod: 'A forma de pagamento deixará de ser oferecida em novos lançamentos. Pedidos e pagamentos antigos manterão a forma utilizada.',
      dtfCategory:   'A categoria de despesa deixará de aparecer como opção. Itens e despesas já registrados continuarão com seu histórico.',
      dtfItem:       'O item deixará de aparecer no cadastro de insumos, peças ou serviços. Despesas já lançadas não serão apagadas.',
      dtfMovement:   'A movimentação deixará de aparecer como opção. Despesas já lançadas continuarão com o tipo de movimentação original.'
    };

    // Para pedidos: cliente vinculado (só leitura) + faturamentos com checkboxes
    // Para outros tipos: lista genérica de vínculos
    if (kind === 'order') {
      const linkedClients = [];
      blocks.forEach(block => {
        const c = orderLinkedActiveClient(block.record);
        if (c && !linkedClients.find(x => String(x.id) === String(c.id))) linkedClients.push(c);
      });
      list.innerHTML = '';
      list.hidden = true;
      const allPayments = [];
      blocks.forEach(block => {
        const order = block.record;
        const orderNum = String(order.orderNumber || '');
        (Array.isArray(order.payments) ? order.payments : []).forEach((p, i) => {
          allPayments.push({ p, i, orderNum });
        });
      });
      if (paymentsHost) {
        if (allPayments.length) {
          paymentsHost.innerHTML =
            '<p class="pw-linked-delete-cascade-title">Faturamentos lançados — marque os que serão excluídos junto com o pedido:</p>' +
            '<ul class="pw-payment-del-list">' +
            allPayments.map(({ p, i, orderNum }) => {
              const val    = money.format(Number(p.value || 0));
              const method = escapeHtml(p.method || '—');
              const date   = p.date ? escapeHtml(p.date.split('-').reverse().join('/')) : '—';
              const type   = escapeHtml(p.type || '');
              return '<li><label class="pw-check-row"><input type="checkbox" checked data-payment-del data-payment-order="' + escapeHtml(orderNum) + '" data-payment-index="' + i + '"><span>' +
                val + ' · ' + method + ' · ' + date + (type ? ' (' + type + ')' : '') +
                '</span></label></li>';
            }).join('') + '</ul>';
          paymentsHost.hidden = false;
        } else {
          paymentsHost.innerHTML = '';
          paymentsHost.hidden = true;
        }
      }
    } else {
      list.innerHTML = '<strong>Este registro está ligado a outras partes do sistema:</strong><ul>' +
        blocks.map(block => {
          const label = escapeHtml(block.record.name || block.record.orderNumber || block.record.code || 'Registro');
          return '<li><strong>' + label + '</strong>' +
            (block.topics.length ? '<ul>' + block.topics.map(t => '<li>' + escapeHtml(t) + '</li>').join('') + '</ul>' : '') +
            '</li>';
        }).join('') + '</ul>' +
        '<p>Se continuar, as ligações serão afetadas, mas os registros relacionados serão preservados.</p>';
      list.hidden = false;
      if (paymentsHost) { paymentsHost.innerHTML = ''; paymentsHost.hidden = true; }
    }

    // Clientes em cascata
    if (cascadeHost) {
      cascadeHost.innerHTML = cascadeClients.length
        ? '<p class="pw-linked-delete-cascade-title">Estes clientes só têm ligação com o(s) pedido(s) que você está excluindo agora — marque se quiser excluí-los junto:</p>' +
          cascadeClients.map(c => '<label class="pw-check-row"><input type="checkbox" data-cascade-client="' + escapeHtml(c.id) + '"> Excluir também o cliente "' + escapeHtml(c.name) + '"</label>').join('')
        : '';
      cascadeHost.hidden = !cascadeClients.length;
    }

    // Help dinâmico — sempre visível, atualiza conforme checkboxes
    function updateHelp() {
      if (!help) return;
      let text = baseHelpText[kind] || 'O registro será removido da listagem ativa, enquanto os dados históricos relacionados serão preservados.';
      if (kind === 'order' && paymentsHost && !paymentsHost.hidden) {
        const checked = $$('[data-payment-del]:checked', modal).length;
        const total   = $$('[data-payment-del]', modal).length;
        if (checked === 0) {
          text += ' O histórico financeiro será preservado integralmente.';
        } else if (checked < total) {
          text += ' ' + checked + ' pagamento(s) marcado(s) serão excluídos junto; os demais serão preservados.';
        } else {
          text += ' Todos os ' + total + ' pagamento(s) serão excluídos junto.';
        }
        const cascade = $$('[data-cascade-client]:checked', modal).length;
        if (cascade) text += ' ' + cascade + ' cliente(s) marcado(s) serão excluídos junto.';
      }
      help.textContent = text;
      help.hidden = false;
    }
    updateHelp();
    modal.addEventListener('change', updateHelp);

    modal.classList.add('pw-open');
    modal.setAttribute('aria-hidden', 'false');
    window.setTimeout(() => $('#pw-linked-delete-confirm').focus(), 30);
    return new Promise(resolve => { linkedDeleteResolver = resolve; });
  }

  function notifyLinkedDeletion(decision) {
    if (decision === true) showMessage('Exclusão confirmada. Os registros vinculados e as categorias vinculadas serão preservados.', 'info');
  }

  async function deleteSelected(kind) {
    if (kind === 'dtfCategory') return deleteDtfExpenseCategories();
    if (['dtfItem','dtfMovement','dtfCost'].includes(kind)) return deleteExpenseRecords(kind, bulkSelections[kind].slice());
    const ids = bulkSelections[kind].slice();
    if (!ids.length) return;
    const selected = recordsForKind(kind).filter(item => ids.includes(String(item.id))).map(item => item.record);
    const linkedDecision = await confirmLinkedDeletion(kind, selected);
    if (linkedDecision && !linkedDecision.confirmed) return;
    if (linkedDecision === null && !confirm('Mover os ' + ids.length + ' registro(s) selecionado(s) para a Lixeira?')) return;
    // Strip selected payments from orders before moving to trash
    if (kind === 'order' && linkedDecision && (linkedDecision.paymentsToDelete || []).length) {
      const paymentsMap = {};
      linkedDecision.paymentsToDelete.forEach(p => {
        if (!paymentsMap[p.orderNumber]) paymentsMap[p.orderNumber] = new Set();
        paymentsMap[p.orderNumber].add(p.index);
      });
      SERVER_STORAGE[STORAGE.orders] = getOrders().map(order => {
        const set = paymentsMap[String(order.orderNumber)];
        return set && set.size ? { ...order, payments: (order.payments || []).filter((_, i) => !set.has(i)) } : order;
      });
    }
    let deleted = 0;
    const results = await Promise.all(ids.map(id => deleteRecord(kind, id, false, true)));
    deleted = results.filter(Boolean).length;
    bulkSelections[kind] = [];
    const cascadeClientIds = linkedDecision ? linkedDecision.cascadeClientIds : [];
    if (cascadeClientIds && cascadeClientIds.length) {
      await Promise.all(cascadeClientIds.map(id => deleteRecord('client', id, false, true)));
    }
    if (kind === 'order' || cascadeClientIds.length) renderOrdersConsultation();
    if (kind === 'client' || cascadeClientIds.length) renderClientsConsultation();
    if (kind === 'product') renderProductsConsultation();
    if (!['order', 'client', 'product'].includes(kind)) renderRegistryConsultation(kind);
    renderTrash();
    showMessage(deleted + ' registro(s) movido(s) para a Lixeira' + (cascadeClientIds.length ? ' (' + cascadeClientIds.length + ' cliente(s) junto)' : '') + '.', deleted ? 'success' : 'error');
    notifyLinkedDeletion(linkedDecision ? linkedDecision.confirmed : true);
  }

  async function deleteExpenseRecords(kind, ids) {
    if (!userIsAdministrator(currentUser) || !ids.length) return;
    const config = registryConfig(kind), records = config.records();
    const removable = records.filter(record => ids.includes(String(record.id)));
    if (!removable.length) return;
    const linkedDecision = await confirmLinkedDeletion(kind, removable);
    if (linkedDecision && !linkedDecision.confirmed) return;
    if (linkedDecision === null && !confirm('Mover ' + removable.length + ' registro(s) para a Lixeira?')) return;
    const next = records.filter(record => !removable.some(item => item.id === record.id));
    if (!await saveExpenseCollection(config.storage, next)) return;
    removable.forEach(record => moveToTrash(kind, record));
    bulkSelections[kind] = [];
    refreshExpenseViews(); renderTrash();
    showMessage(removable.length + ' registro(s) movido(s) para a Lixeira.', 'success');
    notifyLinkedDeletion(linkedDecision ? linkedDecision.confirmed : true);
  }

  async function deleteDtfExpenseCategories() {
    if (!userIsAdministrator(currentUser)) return;
    const ids = bulkSelections.dtfCategory.slice();
    if (!ids.length) return;
    const records = getDtfExpenseCategoryRecords();
    const selected = records.filter(record => ids.includes(record.id));
    if (selected.some(record => normalize(record.name) === normalize('Anúncio'))) {
      showMessage('A categoria Anúncio é obrigatória para os lançamentos da aba Anúncios e não pode ser excluída.', 'error');
      return;
    }
    const removable = selected;
    if (!removable.length) return;
    const linkedDecision = await confirmLinkedDeletion('dtfCategory', removable);
    if (linkedDecision && !linkedDecision.confirmed) return;
    if (linkedDecision === null && !confirm('Mover ' + removable.length + ' categoria(s) para a Lixeira?')) return;
    const button = $('[data-bulk-delete="dtfCategory"]');
    if (button.disabled) return;
    button.disabled = true;
    try {
      const next = records.filter(record => !removable.some(item => item.id === record.id));
      if (!await persistStorage(STORAGE.dtfExpenseCategories, next)) return;
      SERVER_STORAGE[STORAGE.dtfExpenseCategories] = next;
      removable.forEach(record => moveToTrash('dtfCategory', record));
      bulkSelections.dtfCategory = [];
      // Não deixa a opção removida selecionada no formulário de despesas.
      if (removable.some(record => dtfCategoryMatches(record, $('#pw-dtf-cost-category').value))) $('#pw-dtf-cost-category').value = '';
      syncDtfCostItemOptions(); renderDtfExpenseReport('category'); renderTrash();
      showMessage(removable.length + ' categoria(s) movida(s) para a Lixeira. Os vínculos foram preservados.', 'success');
      notifyLinkedDeletion(linkedDecision ? linkedDecision.confirmed : true);
    } finally { updateBulkToolbar('dtfCategory'); }
  }

  async function deleteRecord(kind, id, askConfirmation = true, silent = false) {
    id = String(id);
    let cascadeClientIds = [];
    let linkedDecision = null;
    if (askConfirmation) {
      const candidate = recordsForKind(kind).find(item => String(item.id) === id);
      linkedDecision = candidate ? await confirmLinkedDeletion(kind, [candidate.record]) : null;
      if (linkedDecision && !linkedDecision.confirmed) return false;
      if (linkedDecision === null && !confirm('Mover este registro para a Lixeira?')) return false;
      notifyLinkedDeletion(linkedDecision ? linkedDecision.confirmed : true);
      cascadeClientIds = linkedDecision ? linkedDecision.cascadeClientIds : [];
    }
    let record = null;
    if (kind === 'order') {
      // Strip selected payments before moving to trash
      if (linkedDecision && (linkedDecision.paymentsToDelete || []).length) {
        const toDelete = new Set(linkedDecision.paymentsToDelete.filter(p => p.orderNumber === id).map(p => p.index));
        if (toDelete.size) {
          SERVER_STORAGE[STORAGE.orders] = getOrders().map(o =>
            String(o.orderNumber) !== id ? o : { ...o, payments: (o.payments || []).filter((_, i) => !toDelete.has(i)) }
          );
        }
      }
      record = getOrders().find(order => String(order.orderNumber) === id);
      if (!record) return false;
      // Atualiza a lista local na hora (sem esperar a rede) e apaga só ESTE
      // pedido no servidor — nunca reenvia o array inteiro, pra nunca correr
      // o risco de apagar junto um pedido criado por outro computador que
      // este navegador ainda não tinha sincronizado.
      SERVER_STORAGE[STORAGE.orders] = getOrders().filter(order => String(order.orderNumber) !== id);
      await deleteOrdersOnServer([id]);
      moveToTrash(kind, record);
      if (cascadeClientIds.length) await Promise.all(cascadeClientIds.map(clientId => deleteRecord('client', clientId, false, true)));
      if (!silent) {
        renderOrdersConsultation();
        if (cascadeClientIds.length) renderClientsConsultation();
        renderTrash();
        showMessage('Pedido movido para a Lixeira' + (cascadeClientIds.length ? ' (cliente excluído junto)' : '') + '.', 'success');
      }
      return true;
    }
    if (kind === 'client') {
      record = getClients().find(client => String(client.id) === id); if (!record) return false;
      writeStorage(STORAGE.clients, getClients().filter(client => String(client.id) !== id)); moveToTrash(kind, record);
      if (!silent) { renderClientsConsultation(); renderTrash(); showMessage('Cliente movido para a Lixeira.', 'success'); }
      return true;
    }
    if (kind === 'product') {
      record = getProducts().find(product => String(product.id) === id); if (!record) return false;
      writeStorage(STORAGE.products, getProducts().filter(product => String(product.id) !== id)); moveToTrash(kind, record);
      if (!silent) { renderProductsConsultation(); renderTrash(); showMessage('Produto movido para a Lixeira.', 'success'); }
      return true;
    }
    if (kind === 'category' || kind === 'unit' || kind === 'supplier' || kind === 'paymentMethod' || kind === 'orderOrigin') {
      const config = registryConfig(kind);
      record = config.records().find(item => String(item.id) === id); if (!record) return false;
      writeStorage(config.storage, config.records().filter(record => String(record.id) !== id)); moveToTrash(kind, record);
      if (!silent) renderRegistryConsultation(kind);
      populateProductRegistrySelects();
      if (!silent) showMessage('Registro excluído.', 'success');
      return true;
    }
    return false;
  }

  function moveToTrash(kind, record) {
    const trash = getTrash();
    const recordId = kind === 'order' ? record.orderNumber : record.id;
    trash.unshift({ trashId: 'trash-' + Date.now() + '-' + Math.random().toString(36).slice(2, 6), kind, record, recordId, deletedAt: new Date().toISOString(), deletedBy: currentActor(), deletedByUserId: Number(currentUser && currentUser.id || 0), deletedByLogin: String(currentUser && currentUser.login || '') });
    writeStorage(STORAGE.trash, trash);
    recordAudit(kind, recordId, 'Movido para a Lixeira', 'Registro removido da listagem ativa');
  }

  function storageForKind(kind) {
    return { order: STORAGE.orders, client: STORAGE.clients, product: STORAGE.products, category: STORAGE.categories, dtfCategory: STORAGE.dtfExpenseCategories, dtfItem: STORAGE.dtfCatalog, dtfMovement: STORAGE.dtfExpenseMovements, dtfCost: STORAGE.dtfCosts, unit: STORAGE.units, supplier: STORAGE.suppliers, paymentMethod: STORAGE.paymentMethods, orderOrigin: STORAGE.orderOrigins }[kind];
  }

  function renderTrash() {
    const trash = cleanupExpiredTrash();
    const retentionDays = Math.max(1, Math.min(3650, Math.trunc(Number(getSettings().trashRetentionDays) || 30)));
    const originLabels = {
      order: 'Pedidos', client: 'Cadastro de clientes', product: 'Cadastro de produtos',
      category: 'Cadastro de categorias', unit: 'Cadastro de unidades', supplier: 'Cadastro de fornecedores',
      paymentMethod: 'Formas de pagamento', orderOrigin: 'Origens do pedido', dtfCategory: 'Despesas — Cadastro de categorias',
      dtfItem: 'Despesas — Cadastro de itens', dtfMovement: 'Despesas — Cadastro de movimentações', dtfCost: 'Despesas — Movimentações'
    };
    setTrashSeenCount(trash.length);
    updateTrashBadge();
    $('#pw-trash-body').innerHTML = trash.length ? trash.map(entry => {
      const allowed = trashEntryOwnedByCurrentUser(entry);
      const deletedAt = new Date(entry.deletedAt || 0).getTime();
      const daysLeft = Number.isFinite(deletedAt) ? Math.max(0, Math.ceil((deletedAt + retentionDays * 86400000 - Date.now()) / 86400000)) : retentionDays;
      const daysLeftLabel = daysLeft <= 0 ? '<strong class="pw-trash-days-urgent">Hoje</strong>' : (daysLeft === 1 ? '<strong class="pw-trash-days-urgent">1 dia</strong>' : (daysLeft <= 3 ? '<strong class="pw-trash-days-urgent">' + daysLeft + ' dias</strong>' : daysLeft + ' dias'));
      return '<tr><td><input type="checkbox" data-trash-select value="' + escapeHtml(entry.trashId) + '"' + (allowed ? '' : ' disabled title="Somente o usuário que excluiu ou um administrador pode restaurar"') + '></td><td><strong>' + escapeHtml(originLabels[entry.kind] || 'Outro cadastro') + '</strong></td><td><strong>' + escapeHtml(entry.recordId || '—') + '</strong></td><td>' + escapeHtml(dateTime.format(new Date(entry.deletedAt))) + '</td><td>' + escapeHtml(entry.deletedBy) + '</td><td>' + daysLeftLabel + '</td></tr>';
    }).join('') : '<tr><td colspan="6" class="pw-empty-table">A Lixeira está vazia.</td></tr>';
    $('#pw-trash-selected-count').textContent = '0 selecionados';
  }

  function getArtRecords() {
    const records = [];
    getOrders().forEach(order => {
      (order.items || []).forEach((item, itemIndex) => {
        if (!item.art || !item.art.url) return;
        const createdAt = order.createdDate ? order.createdDate + 'T' + (order.orderTime || '00:00') : '';
        const creator = order.createdBy && (order.createdBy.summary || order.createdBy.name || order.createdBy.login) || '';
        records.push({
          id: String(order.orderNumber) + ':' + String(item.rowId || itemIndex),
          orderNumber: order.orderNumber,
          client: order.client && order.client.name || 'Cliente não informado',
          status: order.status || 'Criação da arte',
          product: item.description || item.code || 'Produto não identificado',
          createdAt,
          updatedAt: order.lastChange || createdAt,
          createdBy: creator,
          itemIndex,
          art: item.art,
          mounted: !!(item.art && item.art.mounted)
        });
      });
    });
    return records.sort((a, b) => {
      const newest = artRecordTimestamp(b) - artRecordTimestamp(a);
      return newest || String(b.id).localeCompare(String(a.id), 'pt-BR', { numeric: true });
    });
  }

  async function setArtMountedStatus(recordId, mounted) {
    const parts = String(recordId).split(':');
    if (parts.length < 2) return;
    const orderNumber = parts[0];
    const rowKey = parts[1];
    const orders = getOrders();
    const order = orders.find(o => String(o.orderNumber) === orderNumber);
    if (!order) return;
    const item = (order.items || []).find((it, idx) => String(it.rowId || idx) === rowKey);
    if (!item || !item.art) return;
    item.art.mounted = !!mounted;
    await writeStorage(STORAGE.orders, orders, { immediate: true });
    renderArtsReport();
  }

  function artRecordTimestamp(record) {
    const art = record && record.art || {};
    const candidates = [art.uploadedAt, art.createdAt, art.updatedAt, art.modified, record && record.updatedAt, record && record.createdAt];
    for (const candidate of candidates) {
      if (!candidate) continue;
      const numeric = typeof candidate === 'number' ? candidate : Number(String(candidate));
      if (Number.isFinite(numeric) && numeric > 0) return numeric > 100000000000 ? numeric : numeric * 1000;
      const parsed = Date.parse(String(candidate));
      if (Number.isFinite(parsed)) return parsed;
    }
    return 0;
  }

  function artFileSize(bytes) {
    const value = Number(bytes || 0);
    if (!value) return 'Não identificado';
    if (value < 1024) return value + ' B';
    if (value < 1048576) return (value / 1024).toFixed(1).replace('.', ',') + ' KB';
    return (value / 1048576).toFixed(2).replace('.', ',') + ' MB';
  }

  function artMetadataHtml(metadata, isPdf) {
    if (!metadata) return '<div class="pw-art-metadata"><div><small>Arquivo</small><strong>Identificando características…</strong></div></div>';
    const dimensions = metadata.width_mm && metadata.height_mm
      ? Number(metadata.width_mm).toFixed(1).replace('.', ',') + ' × ' + Number(metadata.height_mm).toFixed(1).replace('.', ',') + ' mm'
      : (metadata.width_px && metadata.height_px ? metadata.width_px + ' × ' + metadata.height_px + ' px' : 'Não identificadas');
    const entries = [
      ['Formato', metadata.format || (isPdf ? 'PDF' : 'Imagem')],
      ['Tamanho do arquivo', artFileSize(metadata.bytes)],
      ['Largura × altura', dimensions],
      ['Orientação', metadata.orientation || 'Não identificada']
    ];
    if (isPdf) {
      entries.push(['Quantidade de páginas', metadata.pages || 'Não identificada']);
      if (metadata.font_count) entries.push(['Fontes detectadas', metadata.font_count + ' · ' + (metadata.embedded_font_count || 0) + ' incorporada(s)']);
      if (Array.isArray(metadata.font_names) && metadata.font_names.length) entries.push(['Nomes das fontes', metadata.font_names.join(', ')]);
    }
    if (metadata.dpi) entries.push(['Resolução', metadata.dpi + ' DPI']);
    if (metadata.color_space) entries.push(['Espaço de cores', metadata.color_space]);
    if (metadata.modified) entries.push(['Modificado em', metadata.modified]);
    const fontAnalysis = isPdf ? '<div class="pw-art-metadata-wide"><small>Análise de fontes/curvas</small><strong>' + escapeHtml(metadata.font_status || 'Não foi possível analisar') + '</strong></div>' : '';
    return '<div class="pw-art-metadata">' + entries.map(entry => '<div><small>' + escapeHtml(entry[0]) + '</small><strong>' + escapeHtml(String(entry[1])) + '</strong></div>').join('') + fontAnalysis + '</div>';
  }

  async function loadArtMetadata(record) {
    if (!record || !record.art || !record.art.id) return;
    const isPdf = String(record.art.mime || '').includes('pdf') || /\.pdf(?:$|\?)/i.test(record.art.url || '');
    if (record.art.metadata && (!isPdf || Object.prototype.hasOwnProperty.call(record.art.metadata, 'font_status'))) return;
    const form = new URLSearchParams();
    form.append('action', 'pw_personalizados_inspect_order_art');
    form.append('nonce', SERVER.nonce || '');
    form.append('attachment_id', String(record.art.id));
    try {
      const response = await fetch(SERVER.ajaxUrl || '/wp-admin/admin-ajax.php', { method: 'POST', credentials: 'same-origin', headers: { 'Content-Type': 'application/x-www-form-urlencoded; charset=UTF-8' }, body: form.toString() });
      const payload = await response.json();
      if (!response.ok || !payload.success || !payload.data) throw new Error('Não foi possível identificar o arquivo.');
      const orders = getOrders();
      const order = orders.find(candidate => String(candidate.orderNumber) === String(record.orderNumber));
      const item = order && (order.items || [])[record.itemIndex];
      if (!item || !item.art) return;
      item.art.metadata = payload.data;
      if (!await writeStorage(STORAGE.orders, orders, { immediate: true })) return;
      if (selectedArtRecord && selectedArtRecord.id === record.id) {
        selectedArtRecord = getArtRecords().find(candidate => candidate.id === record.id) || null;
        renderArtPreview(selectedArtRecord);
      }
    } catch (error) {
      if (selectedArtRecord && selectedArtRecord.id === record.id) {
        const metadata = $('.pw-art-metadata', $('#pw-art-preview'));
        if (metadata) metadata.innerHTML = '<div><small>Características</small><strong>Não foi possível identificar</strong></div>';
      }
    }
  }

  function artsPdfButtonHtml() {
    const count = bulkSelections.arts.length;
    return '<button class="pw-btn pw-btn-primary pw-arts-tiff-build-btn pw-tooltip" type="button" data-art-pdf-build data-tooltip="Junta as artes em PDF selecionadas na tabela num único PDF vetorial, sem rasterizar nada — preserva a qualidade original, uma abaixo da outra" title="Montar PDF"' + (count ? '' : ' disabled') + '>📄 Montar PDF' + (count ? ' (' + count + ')' : '') + '</button>';
  }

  function renderArtPreview(record) {
    const target = $('#pw-art-preview');
    if (!record) {
      target.innerHTML = '<div class="pw-art-preview-empty">Selecione uma arte para visualizar.</div><div class="pw-art-preview-actions pw-art-preview-actions-empty">' + artsPdfButtonHtml() + '</div>';
      return;
    }
    const art = record.art;
    // Sempre mostra o arquivo ORIGINAL por padrão, mesmo que já exista um
    // PNG convertido/sem fundo gerado antes — gerar essas versões (ou
    // baixá-las) não pode trocar o que o sistema considera "o" anexo do
    // pedido em nenhuma tela.
    const preferred = art;
    const isPdf = String(preferred.mime || '').includes('pdf') || /\.pdf(?:$|\?)/i.test(preferred.url || '');
    const originalIsPdf = String(art.mime || '').includes('pdf') || /\.pdf(?:$|\?)/i.test(art.url || '');
    const preview = isPdf
      ? '<iframe src="' + escapeHtml(preferred.url) + '" title="Prévia da arte ' + escapeHtml(art.code || '') + '"></iframe>'
      : '<img src="' + escapeHtml(preferred.url) + '" alt="Prévia da arte ' + escapeHtml(art.code || '') + '">';
    target.innerHTML = '<div class="pw-art-preview-head"><div><small>Código da arte</small><strong>' + escapeHtml(art.code || '—') + '</strong><span>' + escapeHtml(record.orderNumber + ' · ' + record.product) + '</span></div></div>' +
      '<div class="pw-art-preview-canvas">' + preview + '</div>' + artMetadataHtml(art.metadata, originalIsPdf) + '<div class="pw-art-preview-actions">' +
      '<button class="pw-btn pw-btn-soft" type="button" data-art-download-format="pdf">↓ Baixar PDF</button>' +
      '<button class="pw-btn pw-btn-soft" type="button" data-art-download-format="png">↓ Baixar PNG</button>' +
      '<button class="pw-btn pw-btn-soft" type="button" data-art-download-format="tiff">↓ Baixar TIFF</button>' +
      artsPdfButtonHtml() +
      '</div>';
    loadArtMetadata(record);
  }

  async function downloadSelectedArt(format) {
    if (!selectedArtRecord || !selectedArtRecord.art) return;
    const art = selectedArtRecord.art;
    const normalizedFormat = format === 'png' || format === 'tiff' ? format : 'pdf';
    const label = normalizedFormat.toUpperCase();
    if (normalizedFormat === 'pdf') {
      if (!art.url) return showMessage('O PDF original não está disponível para download.', 'error');
      try {
        await downloadArtWithProgress(art.url, art.name || ((art.code || 'arte') + '.pdf'), label);
      } catch (error) {
        showMessage(error && error.message ? error.message : 'O PDF original não pôde ser baixado.', 'error');
      }
      return;
    }
    const cached = normalizedFormat === 'png' ? (art.convertedPng || art.transparentPng) : art.convertedTiff;
    // PNG/TIFFs criados antes da remoção segura do fundo ou da correção de
    // densidade não carregam a versão da conversão. Force uma nova geração
    // para que o usuário nunca receba uma cópia antiga incorreta.
    const cachedConversionIsCurrent = !['png', 'tiff'].includes(normalizedFormat) || String(cached && cached.conversionVersion || '') === String(SERVER.version || '1.32.81');
    if (cached && cached.url && cachedConversionIsCurrent) {
      try {
        await downloadArtWithProgress(cached.url, cached.name || ((art.code || 'arte') + '.' + normalizedFormat), label);
        return;
      } catch (error) {
        // Uma cópia antiga pode ter sido removida do servidor. Nesse caso,
        // reconverta silenciosamente a partir do PDF original antes de baixar.
        if (!error || !error.downloadHttpError) {
          showMessage(error && error.message ? error.message : ('Não foi possível baixar o ' + label + '.'), 'error');
          return;
        }
      }
    }
    const originalIsPdf = String(art.mime || '').includes('pdf') || /\.pdf(?:$|\?)/i.test(art.url || '');
    if (!originalIsPdf || !art.id) return showMessage('O arquivo original não está disponível para conversão.', 'error');
    if (normalizedFormat === 'png') {
      // Mesmo padrão do modal "Visualizar anexo" (Relatórios → Pedidos →
      // Anexos): nunca usa a IA de segmentação pra remover fundo — ela é
      // treinada pra achar "o assunto principal de uma foto" e erra feio
      // numa folha com muitas cópias do mesmo desenho, apagando pedaço de
      // arte por engano. A remoção determinística do servidor (floodfill de
      // cor exata, "pdf_to_png") é a única usada em todo o sistema onde
      // precisa remover fundo — mesma função, mesmo resultado em qualquer
      // tela.
      await transformSelectedArt('pdf_to_png', { autoDownload: true });
      return;
    }
    try {
      await transformSelectedArtWithAi(normalizedFormat, { autoDownload: true });
    } catch (error) {
      if (error instanceof ArtOperationCancelledError) return;
      // Se a CDN/modelo da IA não estiver disponível, ainda entregamos o
      // arquivo com a remoção segura por borda feita no servidor.
      showMessage('A IA não ficou disponível; aplicando a remoção segura no servidor…', 'info');
      await transformSelectedArt('pdf_to_tiff', { autoDownload: true });
    }
  }

  // O Editor de imagens usa este mesmo modelo local (IS-Net FP16) da biblioteca
  // oficial. O download do modelo fica no navegador e nenhuma arte é enviada
  // para um serviço externo durante a remoção.
  const ART_BACKGROUND_REMOVAL_URL = 'https://cdn.jsdelivr.net/npm/@imgly/background-removal@1.7.0/+esm';
  let artBackgroundRemovalPromise = null;
  function loadArtBackgroundRemoval() {
    if (!artBackgroundRemovalPromise) {
      artBackgroundRemovalPromise = import(ART_BACKGROUND_REMOVAL_URL).then(module => {
        const removeBackground = module.default || module.removeBackground || module.imglyRemoveBackground;
        if (typeof removeBackground !== 'function') throw new Error('A biblioteca de IA não expôs uma função válida.');
        return { removeBackground, preload: typeof module.preload === 'function' ? module.preload : null };
      }).catch(error => { artBackgroundRemovalPromise = null; throw error; });
    }
    return artBackgroundRemovalPromise;
  }

  function updateArtProcessingDetail(text) {
    const detail = $('.pw-processing-detail', $('#pw-processing-overlay'));
    if (detail && text) detail.textContent = text;
  }

  async function requestArtAjax(form, fallbackMessage, signal) {
    const response = await fetch(SERVER.ajaxUrl || '/wp-admin/admin-ajax.php', {
      method: 'POST', credentials: 'same-origin',
      headers: { 'Content-Type': 'application/x-www-form-urlencoded; charset=UTF-8' },
      body: form.toString(),
      signal
    });
    let payload = null;
    let rawBody = '';
    try { rawBody = await response.text(); payload = JSON.parse(rawBody); } catch (error) { payload = null; }
    if (!response.ok || !payload || !payload.success || !payload.data) {
      const data = payload && payload.data;
      const msg = (data && data.message) ? data.message : (fallbackMessage || 'Não foi possível processar a arte.');
      const detail = (!data || !data.message) && rawBody ? ' — Resposta do servidor: ' + rawBody.replace(/[\u0000-\u001f﻿]/g, '').slice(0, 300) : '';
      throw new Error(msg + detail);
    }
    return payload.data;
  }

  async function removeArtBackgroundWithEditorAi(sourceBlob) {
    const api = await loadArtBackgroundRemoval();
    const device = navigator.gpu ? 'gpu' : 'cpu';
    updateArtProcessingDetail('Preparando o modelo IA local do Editor de imagens…');
    updateProcessingProgress(8);
    if (api.preload) await api.preload({ device, model: 'isnet_fp16' });
    let highest = 0;
    const output = await api.removeBackground(sourceBlob, {
      device,
      model: 'isnet_fp16',
      output: { format: 'image/png', type: 'foreground', quality: 1 },
      progress: (key, current, total) => {
        if (total) highest = Math.max(highest, Number(current) / Number(total));
        updateProcessingProgress(12 + highest * 68);
        updateArtProcessingDetail(key ? 'IA: ' + String(key) + '…' : 'IA removendo o fundo…');
      }
    });
    if (!output || !/^image\/png$/i.test(output.type || '')) throw new Error('A IA não devolveu um PNG transparente válido.');
    updateProcessingProgress(82);
    updateArtProcessingDetail('Recorte transparente pronto; salvando com a medida física do PDF…');
    return output;
  }

  // A IA calcula somente a máscara de transparência. Se algum navegador ou
  // versão da biblioteca devolver essa máscara em dimensões menores, use os
  // pixels da rasterização original do PDF para que textos e contornos nunca
  // sejam reamostrados ou suavizados pela etapa de recorte.
  async function getPngBlobDimensions(blob) {
    try {
      const bytes = new Uint8Array(await blob.slice(0, 24).arrayBuffer());
      const signature = [137, 80, 78, 71, 13, 10, 26, 10];
      if (bytes.length < 24 || !signature.every((value, index) => bytes[index] === value)) return null;
      const read = offset => (((bytes[offset] << 24) >>> 0) + (bytes[offset + 1] << 16) + (bytes[offset + 2] << 8) + bytes[offset + 3]);
      return { width: read(16), height: read(20) };
    } catch (_) {
      return null;
    }
  }

  async function preserveOriginalRasterWithAiMask(sourceBlob, aiBlob) {
    const [sourceSize, maskSize] = await Promise.all([getPngBlobDimensions(sourceBlob), getPngBlobDimensions(aiBlob)]);
    if (sourceSize && maskSize && sourceSize.width === maskSize.width && sourceSize.height === maskSize.height) return aiBlob;
    if (typeof createImageBitmap !== 'function') return aiBlob;
    const sourceImage = await createImageBitmap(sourceBlob);
    const maskImage = await createImageBitmap(aiBlob);
    try {
      const width = Number(sourceImage.width || 0);
      const height = Number(sourceImage.height || 0);
      if (!width || !height || maskImage.width === width && maskImage.height === height) return aiBlob;
      updateArtProcessingDetail('Ajustando a máscara sem reduzir os pixels originais…');
      const sourceCanvas = document.createElement('canvas');
      const maskCanvas = document.createElement('canvas');
      sourceCanvas.width = maskCanvas.width = width;
      sourceCanvas.height = maskCanvas.height = height;
      const sourceContext = sourceCanvas.getContext('2d', { willReadFrequently: true });
      const maskContext = maskCanvas.getContext('2d', { willReadFrequently: true });
      if (!sourceContext || !maskContext) return aiBlob;
      sourceContext.imageSmoothingEnabled = false;
      sourceContext.drawImage(sourceImage, 0, 0, width, height);
      maskContext.imageSmoothingEnabled = true;
      maskContext.imageSmoothingQuality = 'high';
      maskContext.drawImage(maskImage, 0, 0, width, height);
      const sourcePixels = sourceContext.getImageData(0, 0, width, height);
      const maskPixels = maskContext.getImageData(0, 0, width, height);
      for (let offset = 3; offset < sourcePixels.data.length; offset += 4) sourcePixels.data[offset] = maskPixels.data[offset];
      sourceContext.putImageData(sourcePixels, 0, 0);
      const merged = await new Promise((resolve, reject) => sourceCanvas.toBlob(blob => blob ? resolve(blob) : reject(new Error('Não foi possível preservar os pixels originais.')), 'image/png', 1));
      return merged;
    } finally {
      if (sourceImage && typeof sourceImage.close === 'function') sourceImage.close();
      if (maskImage && typeof maskImage.close === 'function') maskImage.close();
    }
  }

  /** Erro "silencioso" usado quando o próprio usuário cancela uma conversão/​download em andamento — nunca deve virar mensagem de erro nem disparar um fallback automático. */
  class ArtOperationCancelledError extends Error {}

  async function transformSelectedArtWithAi(format, options = {}) {
    if (!selectedArtRecord || !selectedArtRecord.art) throw new Error('Nenhuma arte foi selecionada.');
    const art = selectedArtRecord.art;
    const isTiff = format === 'tiff';
    const cancelState = { cancelled: false };
    const checkCancelled = () => { if (cancelState.cancelled) throw new ArtOperationCancelledError(); };
    const cancelOp = () => { cancelState.cancelled = true; hideProcessing(); showMessage('Operação cancelada.', 'info'); };
    showProcessing('Removendo fundo com IA', 'Preparando o PDF para o mesmo modelo usado pelo Editor de imagens…', true, true, cancelOp);
    try {
      const sourceForm = new URLSearchParams();
      sourceForm.append('action', 'pw_personalizados_transform_order_art');
      sourceForm.append('nonce', SERVER.nonce || '');
      sourceForm.append('attachment_id', String(art.id || 0));
      sourceForm.append('operation', 'pdf_to_png_raw');
      sourceForm.append('code', art.code || 'ARTE');
      const source = await requestArtAjax(sourceForm, 'Não foi possível preparar o PDF para a IA.');
      checkCancelled();
      if (!source.url || !source.id) throw new Error('O PDF intermediário da IA não foi criado.');
      updateProcessingProgress(6);
      updateArtProcessingDetail('PDF preparado; carregando a arte para a IA local…');
      const sourceResponse = await fetch(source.url, { credentials: 'same-origin', cache: 'no-store' });
      checkCancelled();
      if (!sourceResponse.ok) throw new Error('A imagem intermediária do PDF não pôde ser carregada.');
      const sourceBlob = await sourceResponse.blob();
      const aiBlob = await removeArtBackgroundWithEditorAi(sourceBlob);
      checkCancelled();
      const finalBlob = await preserveOriginalRasterWithAiMask(sourceBlob, aiBlob);
      checkCancelled();
      const form = new FormData();
      form.append('action', 'pw_personalizados_save_ai_order_art');
      form.append('nonce', SERVER.nonce || '');
      form.append('source_attachment_id', String(art.id || 0));
      form.append('format', isTiff ? 'tiff' : 'png');
      form.append('code', art.code || 'ARTE');
      form.append('art', finalBlob, (art.code || 'arte') + '-ai.png');
      updateProcessingProgress(86);
      updateArtProcessingDetail('Gravando ' + (isTiff ? 'TIFF' : 'PNG') + ' com resolução compatível com o PDF…');
      const response = await fetch(SERVER.ajaxUrl || '/wp-admin/admin-ajax.php', { method: 'POST', credentials: 'same-origin', body: form });
      checkCancelled();
      let payload = null;
      try { payload = await response.json(); } catch (error) { payload = null; }
      if (!response.ok || !payload || !payload.success || !payload.data) {
        const data = payload && payload.data;
        throw new Error(data && data.message ? data.message : 'Não foi possível salvar o recorte da IA.');
      }
      const generated = { id: Number(payload.data.id || 0), url: String(payload.data.url || ''), name: String(payload.data.name || ''), mime: String(payload.data.mime || (isTiff ? 'image/tiff' : 'image/png')), conversionVersion: String(SERVER.version || '1.32.81') };
      const orders = getOrders();
      const order = orders.find(candidate => candidate.orderNumber === selectedArtRecord.orderNumber);
      const item = order && (order.items || [])[selectedArtRecord.itemIndex];
      if (!item || !item.art) throw new Error('O vínculo da arte com o pedido não foi localizado.');
      if (isTiff) item.art.convertedTiff = generated;
      else item.art.convertedPng = generated;
      if (!await writeStorage(STORAGE.orders, orders, { immediate: true })) throw new Error('Não foi possível salvar o vínculo da arte no pedido.');
      updateProcessingProgress(94);
      selectedArtRecord = getArtRecords().find(record => record.id === selectedArtRecord.id) || null;
      renderArtsReport();
      checkCancelled();
      if (options.autoDownload && generated.url) await downloadArtWithProgress(generated.url, generated.name || ((art.code || 'arte') + (isTiff ? '.tiff' : '.png')), isTiff ? 'TIFF' : 'PNG');
      showMessage((isTiff ? 'TIFF' : 'PNG') + ' removido com IA e baixado com sucesso.', 'success');
    } finally {
      hideProcessing();
    }
  }

  /** POST simples pro admin-ajax, no mesmo padrão usado no resto do sistema. */
  async function postForm(fields) {
    const form = new URLSearchParams();
    Object.entries(fields).forEach(([key, value]) => {
      if (Array.isArray(value)) value.forEach(item => form.append(key + '[]', item));
      else form.append(key, value);
    });
    const response = await fetch(SERVER.ajaxUrl || '/wp-admin/admin-ajax.php', { method: 'POST', credentials: 'same-origin', cache: 'no-store', headers: { 'Content-Type': 'application/x-www-form-urlencoded; charset=UTF-8' }, body: form.toString() });
    const rawText = await response.text();
    try {
      return JSON.parse(rawText);
    } catch (error) {
      // Resposta não veio em JSON — normalmente sinal de erro fatal do PHP
      // (timeout, memória, etc.) que interrompeu a saída antes do JSON.
      // Guarda o motivo real em vez de simplesmente devolver null, pra não
      // esconder o que de fato aconteceu.
      return { success: false, data: { message: 'O servidor não respondeu corretamente (HTTP ' + response.status + ').', raw: rawText.slice(0, 300) } };
    }
  }

  function renderArtsReport() {
    const query = normalize($('#pw-arts-search').value);
    const hideFinalized = $('#pw-arts-hide-finalized').checked;
    const records = getArtRecords().filter(record => {
      if (hideFinalized && isOrderFinalized(getOrders().find(order => order.orderNumber === record.orderNumber))) return false;
      if (!query) return true;
      const searchable = [
        record.art && record.art.code,
        record.art && record.art.name,
        record.art && record.art.url,
        record.orderNumber,
        record.client,
        record.product,
        record.status,
        record.createdBy
      ].filter(Boolean).join(' ');
      return normalize(searchable).includes(query);
    });
    pruneBulkSelection('arts', records.map(record => record.id));
    $('#pw-arts-body').innerHTML = records.length ? records.map(record => {
      const isPdf = record.art && record.art.mime === 'application/pdf' && record.art.id;
      const checked = bulkSelections.arts.includes(String(record.id));
      const mountedBadge = record.mounted
        ? '<span class="pw-art-mounted-badge pw-art-mounted">✓ Montado</span>'
        : '<span class="pw-art-mounted-badge pw-art-not-mounted">— Não montado</span>';
      const selectCell = '<td class="pw-select-cell"><input type="checkbox" data-row-select="arts" value="' + escapeHtml(record.id) + '"' + (checked ? ' checked' : '') + (isPdf ? '' : ' disabled title="Disponível somente para artes em PDF"') + '></td>';
      return '<tr class="pw-art-report-row' + (selectedArtRecord && selectedArtRecord.id === record.id ? ' pw-selected' : '') + (record.mounted ? ' pw-art-row-mounted' : '') + '" data-art-record="' + escapeHtml(record.id) + '" data-art-mounted="' + (record.mounted ? '1' : '0') + '">' + selectCell + '<td><strong>' + escapeHtml(record.art.code || '—') + '</strong></td><td>' + escapeHtml(record.orderNumber) + '</td><td>' + escapeHtml(record.client) + '</td><td>' + escapeHtml(record.product) + '</td><td>' + escapeHtml(record.art.name || 'Arquivo') + '</td><td>' + mountedBadge + '</td></tr>';
    }).join('') : '<tr><td colspan="7" class="pw-empty-table">Nenhuma arte encontrada.</td></tr>';
    updateBulkToolbar('arts');
    if (selectedArtRecord) {
      selectedArtRecord = getArtRecords().find(record => record.id === selectedArtRecord.id) || null;
      renderArtPreview(selectedArtRecord);
    }
  }

  /**
   * "Montar Tiff": pega os anexos PDF de todas as artes selecionadas no
   * Relatório de artes, converte cada um em página de alta resolução com
   * fundo removido (servidor, uma por vez) e empilha tudo num único TIFF.
   * Progresso real (processada/total) e botão de cancelar de verdade.
   */
  let artsPdfJob = null;
  async function buildArtsPdfFromSelection() {
    const ids = bulkSelections.arts.slice();
    if (!ids.length) { showMessage('Selecione ao menos uma arte em PDF para montar o PDF.', 'error'); return; }
    const records = getArtRecords();
    const attachmentIds = ids
      .map(id => records.find(record => String(record.id) === String(id)))
      .filter(record => record && record.art && record.art.mime === 'application/pdf' && record.art.id)
      .map(record => record.art.id);
    if (!attachmentIds.length) { showMessage('Nenhuma das artes selecionadas está disponível em PDF para montar o PDF.', 'error'); return; }

    let cancelled = false;
    const cancelJob = async () => {
      cancelled = true;
      if (artsPdfJob) {
        try { await postForm({ action: 'pw_personalizados_arts_pdf_cancel', nonce: SERVER.nonce || '', job_id: artsPdfJob }); } catch (error) { /* melhor esforço: o servidor também limpa jobs órfãos sozinho */ }
      }
      hideProcessing();
      showMessage('Montagem do PDF cancelada.', 'info');
    };

    showProcessing('Montando PDF', 'Preparando ' + attachmentIds.length + ' arte(s)…', true, true, cancelJob);
    try {
      const startResponse = await postForm({ action: 'pw_personalizados_arts_pdf_start', nonce: SERVER.nonce || '', attachment_ids: attachmentIds });
      if (!startResponse || !startResponse.success || !startResponse.data) {
        throw new Error((startResponse && startResponse.data && startResponse.data.message) || 'Não foi possível iniciar a montagem do PDF.');
      }
      artsPdfJob = startResponse.data.job_id;
      const total = Number(startResponse.data.total) || attachmentIds.length;

      let skippedCount = 0;
      while (!cancelled) {
        const stepResponse = await postForm({ action: 'pw_personalizados_arts_pdf_step', nonce: SERVER.nonce || '', job_id: artsPdfJob });
        if (!stepResponse || !stepResponse.success || !stepResponse.data) {
          throw new Error((stepResponse && stepResponse.data && stepResponse.data.message) || 'Falha ao processar uma das artes.');
        }
        const data = stepResponse.data;
        if (data.cancelled) { cancelled = true; break; }
        if (data.skipped_id) {
          skippedCount += 1;
          const skippedRecord = records.find(record => record.art && Number(record.art.id) === Number(data.skipped_id));
          const label = skippedRecord ? ('arte ' + (skippedRecord.art.code || skippedRecord.id) + ', pedido ' + skippedRecord.orderNumber) : ('anexo ' + data.skipped_id);
          showMessage('Pulada uma arte com problema (' + label + '): ' + (data.skipped_reason || 'motivo não informado') + '.', 'info');
        }
        if (data.done) {
          artsPdfJob = null;
          updateProcessingProgress(100);
          const okCount = total - (data.skipped ? data.skipped.length : skippedCount);
          const skippedTotal = data.skipped ? data.skipped.length : skippedCount;
          showMessage('PDF montado com ' + okCount + ' de ' + total + ' arte(s)' + (skippedTotal ? ' — ' + skippedTotal + ' pulada(s) por problema no arquivo (veja o motivo acima)' : '') + '. Qualidade original preservada — sem rasterizar.', skippedTotal ? 'info' : 'success');
          // Marca automaticamente as artes como montadas
          const mountedIds = ids.filter(id => {
            if (!data.skipped || !data.skipped.length) return true;
            const rec = records.find(r => String(r.id) === String(id));
            return !rec || !data.skipped.some(s => rec.art && Number(s.attachment_id) === Number(rec.art.id));
          });
          for (const id of mountedIds) { await setArtMountedStatus(id, true); }
          await downloadArtWithProgress(data.url, data.name || 'artes-montadas.pdf', 'PDF');
          return;
        }
        showProcessing('Montando PDF', 'Preparando arte ' + data.processed + ' de ' + data.total + '…', true, true, cancelJob);
        updateProcessingProgress(data.percent);
      }
    } catch (error) {
      hideProcessing();
      showMessage(error && error.message ? error.message : 'Não foi possível montar o PDF.', 'error');
    } finally {
      artsPdfJob = null;
    }
  }

  async function transformSelectedArt(operation, options = {}) {
    if (!selectedArtRecord) return;
    const art = selectedArtRecord.art;
    const source = operation === 'remove_background' && art.convertedPng ? art.convertedPng : art;
    const form = new URLSearchParams();
    form.append('action', 'pw_personalizados_transform_order_art');
    form.append('nonce', SERVER.nonce || '');
    form.append('attachment_id', String(source.id || 0));
    form.append('operation', operation);
    form.append('code', art.code || 'ARTE');
    const isTiff = operation === 'pdf_to_tiff';
    const controller = typeof AbortController === 'function' ? new AbortController() : null;
    let cancelled = false;
    const cancelOp = () => { cancelled = true; if (controller) controller.abort(); hideProcessing(); showMessage('Operação cancelada.', 'info'); };
    showProcessing(isTiff ? 'Convertendo PDF em TIFF' : (operation === 'pdf_to_png' ? 'Convertendo PDF em PNG' : 'Removendo somente o fundo'), isTiff ? 'Renderizando a primeira página em alta resolução, preservando a imagem e as medidas originais.' : (operation === 'pdf_to_png' ? 'Preparando a primeira página em alta qualidade.' : 'Analisando o branco conectado às bordas da arte.'), false, !!controller, controller ? cancelOp : null);
    try {
      const response = await fetch(SERVER.ajaxUrl || '/wp-admin/admin-ajax.php', { method:'POST', credentials:'same-origin', headers:{ 'Content-Type':'application/x-www-form-urlencoded; charset=UTF-8' }, body:form.toString(), signal: controller ? controller.signal : undefined });
      const rawText = await response.text();
      let payload;
      try { payload = JSON.parse(rawText); } catch (parseError) { payload = { success: false, data: { message: 'O servidor não respondeu corretamente (HTTP ' + response.status + '): ' + rawText.slice(0, 200) } }; }
      if (!response.ok || !payload.success || !payload.data) throw new Error(payload.data && payload.data.message || 'Não foi possível processar a arte.');
      const orders = getOrders();
      const order = orders.find(candidate => candidate.orderNumber === selectedArtRecord.orderNumber);
      const item = order && (order.items || [])[selectedArtRecord.itemIndex];
      if (!item || !item.art) throw new Error('O vínculo da arte com o pedido não foi localizado.');
      const generated = { id:Number(payload.data.id || 0), url:String(payload.data.url || ''), name:String(payload.data.name || ''), mime:String(payload.data.mime || (isTiff ? 'image/tiff' : 'image/png')), conversionVersion:String(SERVER.version || '1.32.81') };
      if (operation === 'pdf_to_png') item.art.convertedPng = generated;
      else if (isTiff) item.art.convertedTiff = generated;
      else item.art.transparentPng = generated;
      if (!await writeStorage(STORAGE.orders, orders, { immediate:true })) return;
      selectedArtRecord = getArtRecords().find(record => record.id === selectedArtRecord.id) || null;
      renderArtsReport();
      if (options.autoDownload && generated.url) await downloadArtWithProgress(generated.url, generated.name || ((art.code || 'arte') + (isTiff ? '.tiff' : '.png')), isTiff ? 'TIFF' : 'PNG');
      showMessage(options.autoDownload ? (isTiff ? 'TIFF gerado e baixado com sucesso.' : 'PNG gerado e baixado com sucesso.') : (operation === 'pdf_to_png' ? 'PNG gerado com sucesso.' : 'PNG transparente gerado com sucesso.'), 'success');
    } catch (error) {
      if (cancelled || (error && error.name === 'AbortError')) return;
      showMessage(error.message || 'Não foi possível processar a arte.', 'error');
    } finally {
      hideProcessing();
    }
  }

  function selectedTrashIds() { return $$('[data-trash-select]:checked').map(input => input.value); }

  function restoreTrashEntries(ids) {
    let trash = getTrash(), restored = 0, denied = 0;
    ids.forEach(id => {
      const entry = trash.find(item => item.trashId === id); if (!entry) return;
      if (!trashEntryOwnedByCurrentUser(entry)) { denied += 1; return; }
      const key = storageForKind(entry.kind); if (!key) return;
      if (entry.kind.startsWith('dtf') && !userIsAdministrator(currentUser)) { denied += 1; return; }
      const records = entry.kind.startsWith('dtf') ? registryConfig(entry.kind).records().slice() : readStorage(key, []);
      if (['dtfMovement','dtfItem'].includes(entry.kind) && records.some(record => record.id !== entry.recordId && normalize(record.code) === normalize(entry.record.code))) { denied += 1; return; }
      if (entry.kind === 'dtfCategory' && (!userIsAdministrator(currentUser) || records.some(record => record.id !== entry.recordId && (normalize(record.code) === normalize(entry.record.code) || dtfCategoryMatches(record, entry.record.name))))) { denied += 1; return; }
      // Cadastros comuns (cliente, produto, categoria, etc.) reaproveitam o
      // código numérico de um registro excluído se o próximo cadastro tiver
      // "furos" preenchidos — por isso é preciso checar colisão de código
      // aqui também, não só nos tipos DTF, senão dois registros ativos
      // podem acabar com o mesmo código depois de restaurar um antigo.
      if (entry.record && entry.record.code && records.some(record => record.id !== entry.recordId && normalize(record.code) === normalize(entry.record.code))) { denied += 1; return; }
      const duplicate = records.some(record => String(entry.kind === 'order' ? record.orderNumber : record.id) === String(entry.recordId));
      if (!duplicate) { records.push(entry.record); writeStorage(key, records); restored += 1; recordAudit(entry.kind, entry.recordId, 'Restaurado da Lixeira', 'Registro retornou à listagem ativa'); }
      trash = trash.filter(item => item.trashId !== id);
    });
    writeStorage(STORAGE.trash, trash); refreshAllViews(); showMessage(restored + ' registro(s) restaurado(s).' + (denied ? ' ' + denied + ' não autorizado(s) ou com código já em uso — restaure/edite o código manualmente se precisar.' : ''), restored ? 'success' : 'error');
  }

  function collaboratorUsers() {
    return Array.isArray(SERVER.collaborators) ? SERVER.collaborators.filter(userIsCollaborator) : [];
  }

  /** Lista pra exibição no seletor de acesso: colaboradores (editáveis) + administradores (só consulta, sempre com tudo liberado). */
  function accessDisplayUsers() {
    return Array.isArray(SERVER.collaborators) ? SERVER.collaborators.filter(user => userIsCollaborator(user) || userIsAdministrator(user)) : [];
  }

  function renderAccessUserEditor() {
    const selectedKey = $('#pw-access-user').value;
    const user = accessDisplayUsers().find(item => accessUserKey(item) === selectedKey);
    const body = $('#pw-access-menu-body');
    if (!user) {
      body.innerHTML = '<tr><td colspan="3" class="pw-empty">Selecione um colaborador para configurar o acesso.</td></tr>';
      $('#pw-access-blocked-display').disabled = true;
      return;
    }
    const isAdmin = userIsAdministrator(user);
    if (isAdmin) {
      $('#pw-access-blocked-display').disabled = true;
      $('#pw-access-blocked-display').value = 'Nenhum — Administrador sempre tem acesso a tudo';
      body.innerHTML = '<tr><td colspan="3" class="pw-empty">Administradores sempre têm acesso a todos os menus — aqui é só pra consulta, não dá pra restringir.</td></tr>' +
        menuAccessDefinitions.map(item => '<tr><td><small>' + escapeHtml(item.group) + '</small></td><td><strong>' + escapeHtml(item.label) + '</strong></td><td><label class="pw-access-switch pw-access-switch-locked"><input type="checkbox" checked disabled><i></i><span>Permitido</span></label></td></tr>').join('');
      return;
    }
    const profile = userAccessProfile(user);
    $('#pw-access-blocked-display').disabled = false;
    $('#pw-access-blocked-display').value = profile.blockedDisplay;
    body.innerHTML = menuAccessDefinitions.map(item => '<tr><td><small>' + escapeHtml(item.group) + '</small></td><td><strong>' + escapeHtml(item.label) + '</strong></td><td><label class="pw-access-switch"><input type="checkbox" data-user-menu-access="' + escapeHtml(item.key) + '"' + (profile.menus[item.key] !== false ? ' checked' : '') + '><i></i><span>' + (profile.menus[item.key] !== false ? 'Permitido' : 'Bloqueado') + '</span></label></td></tr>').join('');
  }

  function populateAccessUserSelects() {
    const displayUsers = accessDisplayUsers();
    const copySourceUsers = collaboratorUsers();
    const editor = $('#pw-access-user'); const source = $('#pw-access-copy-source');
    const editorValue = editor.value; const sourceValue = source.value;
    const editorOptions = displayUsers.map(user => '<option value="' + escapeHtml(accessUserKey(user)) + '">' + escapeHtml((user.full_name || user.display || user.login) + ' (' + user.login + ')' + (userIsAdministrator(user) ? ' — Administrador' : '')) + '</option>').join('');
    const sourceOptions = copySourceUsers.map(user => '<option value="' + escapeHtml(accessUserKey(user)) + '">' + escapeHtml((user.full_name || user.display || user.login) + ' (' + user.login + ')') + '</option>').join('');
    editor.innerHTML = '<option value="">Selecione um colaborador</option>' + editorOptions;
    source.innerHTML = '<option value="">Selecione o usuário de origem</option>' + sourceOptions;
    if (displayUsers.some(user => accessUserKey(user) === editorValue)) editor.value = editorValue;
    else if (displayUsers.length === 1) editor.value = accessUserKey(displayUsers[0]);
    if (copySourceUsers.some(user => accessUserKey(user) === sourceValue)) source.value = sourceValue;
  }

  function renderSettings() {
    const settings = getSettings();
    const sequenceInfo = currentOrderSequenceInfo();
    $('#pw-last-order-number').value = sequenceInfo.lastOrder || 'Nenhum pedido cadastrado';
    $('#pw-next-order-sequence').value = sequenceInfo.next;
    $('#pw-next-order-sequence').min = sequenceInfo.highestCurrentMonth + 1;
    updateNextOrderPreview();
    $('#pw-trash-retention-days').value = Math.max(1, Math.min(3650, Math.trunc(Number(settings.trashRetentionDays) || 30)));
    populateAccessUserSelects();
    renderAccessUserEditor();
    applyStatusSettings(settings);
    $('#pw-status-settings-grid').innerHTML = ORDER_STATUS_FLOW.map(item => '<div class="pw-status-setting-row"><span class="pw-status-dot" style="' + statusVisualStyle(item) + '">' + escapeHtml(item.code) + '</span><strong>' + escapeHtml(item.label) + '</strong><label>Sigla<input type="text" maxlength="3" value="' + escapeHtml(item.code) + '" data-status-code="' + escapeHtml(item.value) + '"></label><label>Cor<input type="color" value="' + escapeHtml(item.color) + '" data-status-color="' + escapeHtml(item.value) + '"></label></div>').join('');
    $('#pw-payment-method-settings-grid').innerHTML = getPaymentMethods().map((method, index) => { const definition = paymentMethodDefinition(method.name, index); return '<div class="pw-status-setting-row"><span class="pw-status-dot" style="' + statusVisualStyle(definition) + '">' + escapeHtml(definition.code) + '</span><strong>' + escapeHtml(method.name) + '</strong><label>Sigla<input type="text" maxlength="3" value="' + escapeHtml(definition.code) + '" data-payment-method-code="' + escapeHtml(method.name) + '"></label><label>Cor<input type="color" value="' + escapeHtml(definition.color) + '" data-payment-method-color="' + escapeHtml(method.name) + '"></label></div>'; }).join('') || '<p>Nenhuma forma de pagamento cadastrada.</p>';
    renderSpeechSettings(settings);
  }

  /** Preenche o <select> de vozes só com as vozes de português do Brasil
   * (pt-BR) que o navegador atual disponibiliza — outros idiomas/sotaques
   * (inglês, português de Portugal etc.) não aparecem na lista. Sempre
   * preserva (mesmo que a lista ainda esteja vazia na primeira chamada) o
   * valor já salvo como opção, pra não perder a seleção enquanto as vozes
   * carregam de forma assíncrona (comportamento comum no Chrome). */
  function populateSpeechVoiceSelect(selectedVoiceName) {
    const select = $('#pw-speech-voice');
    if (!select) return;
    const ptBr = getAvailableSpeechVoices()
      .filter(voice => voice.lang.toLowerCase().replace('_', '-').startsWith('pt-br'))
      .sort((a, b) => a.name.localeCompare(b.name));
    const options = ['<option value="">Padrão do navegador (português do Brasil)</option>']
      .concat(ptBr.map(voice => '<option value="' + escapeHtml(voice.name) + '">' + escapeHtml(voice.name) + ' (' + escapeHtml(voice.lang) + ')</option>'));
    if (selectedVoiceName && !ptBr.some(voice => voice.name === selectedVoiceName)) {
      options.push('<option value="' + escapeHtml(selectedVoiceName) + '">' + escapeHtml(selectedVoiceName) + ' (salva — ainda não carregada neste navegador)</option>');
    }
    select.innerHTML = options.join('');
    select.value = selectedVoiceName || '';
  }

  function renderSpeechSettings(settings) {
    const host = $('#pw-speech-settings-list');
    if (!host) return;
    host.innerHTML = PW_SPEECH_LOCATIONS.map(item => '<div class="pw-speech-setting-row"><div class="pw-speech-setting-copy"><strong>' + escapeHtml(item.label) + '</strong><small>' + escapeHtml(item.hint) + '</small></div><input type="text" maxlength="200" placeholder="Vazio = não fala nada aqui" value="' + escapeHtml(speechSettingText(item.key)) + '" data-speech-text="' + escapeHtml(item.key) + '"><button class="pw-btn pw-btn-soft pw-tooltip" type="button" data-speech-play="' + escapeHtml(item.key) + '" data-tooltip="Ouvir o texto deste campo">▶ Ouvir</button></div>').join('');
    populateSpeechVoiceSelect(settings.speechVoice || '');
    const rate = Math.min(2, Math.max(0.5, Number(settings.speechRate) || 1));
    $('#pw-speech-rate').value = rate;
    $('#pw-speech-rate-label').textContent = rate.toFixed(1) + '×';
  }

  function openStatusAudit() {
    if (!userIsAdministrator(currentUser)) return showMessage('Apenas Administradores podem auditar situações.', 'error');
    if (!bulkSelections.order.length) return showMessage('Selecione pelo menos um pedido para auditar.', 'error');
    statusAuditContext = { ids: bulkSelections.order.slice(), index: 0 };
    loadStatusAuditRecord(0, true);
  }

  function loadStatusAuditRecord(targetIndex, openWindow) {
    if (!statusAuditContext.ids.length) return;
    const boundedIndex = Math.max(0, Math.min(targetIndex, statusAuditContext.ids.length - 1));
    if (!openWindow && modalHasUnsavedChanges('pw-status-audit-modal') && !confirm('Existem alterações não salvas neste pedido. Deseja navegar e descartá-las?')) return;
    statusAuditContext.index = boundedIndex;
    const orderNumber = statusAuditContext.ids[boundedIndex];
    const order = getOrders().find(item => String(item.orderNumber) === String(orderNumber));
    if (!order) return showMessage('Pedido não encontrado.', 'error');
    auditingOrderNumber = order.orderNumber;
    $('#pw-status-audit-order').textContent = order.orderNumber + ' · ' + (order.client && order.client.name || 'Sem cliente');
    const currentIndex = statusIndex(order.status || 'Criação da arte');
    $('#pw-status-audit-fields').innerHTML = ORDER_STATUS_FLOW.map((definition, index) => {
      const storedDate = orderStatusDate(order, definition.value);
      const parsed = storedDate ? new Date(storedDate) : null;
      const inputValue = parsed && !Number.isNaN(parsed.getTime()) ? localDateValue(parsed) + 'T' + localTimeValue(parsed) : '';
      const unavailable = index > currentIndex;
      return '<div class="pw-status-audit-row"><span class="pw-status-dot" style="' + statusVisualStyle(definition) + '">' + escapeHtml(definition.code) + '</span><strong>' + escapeHtml(definition.label) + '</strong><input type="datetime-local" data-audit-status="' + escapeHtml(definition.value) + '" value="' + escapeHtml(inputValue) + '"' + (unavailable ? ' disabled title="Esta situação ainda não foi alcançada"' : '') + '></div>';
    }).join('');
    const multiple = statusAuditContext.ids.length > 1;
    $('#pw-status-audit-navigation').hidden = !multiple;
    $('#pw-status-audit-position').textContent = 'Pedido ' + (boundedIndex + 1) + ' de ' + statusAuditContext.ids.length;
    $('#pw-status-audit-prev').disabled = boundedIndex === 0;
    $('#pw-status-audit-next').disabled = boundedIndex >= statusAuditContext.ids.length - 1;
    const rollback = $('#pw-rollback-status-audit');
    if (rollback) {
      const currentDefinition = ORDER_STATUS_FLOW[currentIndex];
      rollback.hidden = currentIndex <= 0;
      rollback.disabled = currentIndex <= 0;
      rollback.textContent = currentIndex > 0 ? '↶ Remover "' + (currentDefinition ? currentDefinition.label : 'última situação') + '"' : '↶ Remover última situação';
    }
    if (openWindow) openModal('pw-status-audit-modal', true);
    else window.setTimeout(() => markModalClean('pw-status-audit-modal'), 0);
  }

  async function saveStatusAudit() {
    if (!userIsAdministrator(currentUser)) return showMessage('Apenas Administradores podem auditar situações.', 'error');
    const orders = getOrders();
    const index = orders.findIndex(item => String(item.orderNumber) === String(auditingOrderNumber));
    if (index < 0) return showMessage('Pedido não encontrado.', 'error');
    const order = orders[index];
    const currentIndex = statusIndex(order.status || 'Criação da arte');
    const entries = [];
    let previousDate = null;
    for (let position = 0; position <= currentIndex; position += 1) {
      const definition = ORDER_STATUS_FLOW[position];
      const field = $('[data-audit-status="' + definition.value + '"]');
      if (!field || !field.value) continue;
      const parsed = new Date(field.value);
      if (Number.isNaN(parsed.getTime())) return showMessage('Existe uma data ou hora inválida na auditoria.', 'error');
      if (previousDate && parsed < previousDate) return showMessage('As datas precisam respeitar a ordem das situações.', 'error');
      entries.push({ status: definition.value, previous: position ? ORDER_STATUS_FLOW[position - 1].value : '', at: parsed.toISOString(), actor: currentActor(), note: '' });
      previousDate = parsed;
    }
    const currentEntry = entries.find(item => item.status === (order.status || 'Criação da arte'));
    if (!currentEntry) return showMessage('Informe a data e a hora da situação atual do pedido.', 'error');
    order.timeline = entries;
    order.lastChange = currentEntry.at;
    orders[index] = order;
    const saved = await writeStorage(STORAGE.orders, orders, { immediate: true });
    if (!saved) return;
    recordAudit('order', order.orderNumber, 'Situações auditadas', 'Datas e horários corrigidos pelo Administrador');
    refreshAllViews();
    closeModal('pw-status-audit-modal', true);
    showMessage('Situações do pedido ' + order.orderNumber + ' atualizadas.', 'success');
  }

  async function rollbackLastAuditedStatus() {
    if (!userIsAdministrator(currentUser)) return showMessage('Apenas Administradores podem remover uma situação registrada.', 'error');
    const orders = getOrders();
    const index = orders.findIndex(item => String(item.orderNumber) === String(auditingOrderNumber));
    if (index < 0) return showMessage('Pedido não encontrado.', 'error');
    const order = orders[index];
    const currentIndex = statusIndex(order.status || 'Criação da arte');
    if (currentIndex <= 0) return showMessage('A situação inicial "Criação da arte" não pode ser removida.', 'error');
    const removed = ORDER_STATUS_FLOW[currentIndex];
    const previous = ORDER_STATUS_FLOW[currentIndex - 1];
    if (!confirm('Remover a última situação registrada ("' + removed.label + '") e voltar o pedido para "' + previous.label + '"?')) return;
    const timeline = orderStatusHistory(order).filter(entry => statusIndex(entry.status) >= 0 && statusIndex(entry.status) < currentIndex).map(entry => ({ ...entry }));
    const previousEntry = timeline[timeline.length - 1];
    order.status = previous.value;
    order.timeline = timeline;
    order.lastChange = previousEntry && previousEntry.at ? previousEntry.at : (order.createdDate ? order.createdDate + 'T' + (order.orderTime || '00:00') : new Date().toISOString());
    if (removed.value === 'Entregue') order.actualDelivery = '';
    syncOrderFinalization(order);
    orders[index] = order;
    const saved = await writeStorage(STORAGE.orders, orders, { immediate: true });
    if (!saved) return;
    recordAudit('order', order.orderNumber, 'Última situação removida', removed.label + ' removida; pedido retornou para ' + previous.label + '.');
    refreshAllViews();
    loadStatusAuditRecord(statusAuditContext.index, false);
    showMessage('Situação removida. O pedido voltou para "' + previous.label + '".', 'success');
  }

  async function runAutomatedTests() {
    const tests = [
      ['Numeração do pedido', /^\d{5}$/.test($('#pw-order-number').value)],
      ['Banco de dados do WordPress', Boolean(SERVER.ajaxUrl && SERVER.nonce)],
      ['Cálculo financeiro', adjustedOrderTotal({ total: 100, discount: 10, surcharge: 5 }) === 95],
      ['Tarifa de marketplace', orderItemTotals([{ quantity: 2, unitPrice: 85, salePrice: 100, marketplaceFee: 15 }], 'Mercado Livre').net === 170],
      ['Lixeira disponível', Array.isArray(getTrash())],
      ['Histórico disponível', Array.isArray(readStorage(STORAGE.audit, []))]
    ];
    const testsHtml = tests.map(test => '<div class="pw-test-result ' + (test[1] ? 'pw-test-ok' : 'pw-test-error') + '">' + (test[1] ? '✓ ' : '✕ ') + escapeHtml(test[0]) + '</div>').join('');
    $('#pw-test-results').innerHTML = testsHtml + '<div class="pw-test-result pw-test-pending">⏳ Executando limpeza do sistema (tabelas, transients, temporários)…</div>';

    let cleanupHtml = '';
    let cleanupOk = true;
    try {
      const payload = await postForm({ action: 'pw_personalizados_system_cleanup', nonce: SERVER.nonce || '' });
      if (!payload || !payload.success || !payload.data) throw new Error((payload && payload.data && payload.data.message) || 'Não foi possível executar a limpeza do sistema.');
      const results = Array.isArray(payload.data.results) ? payload.data.results : [];
      cleanupHtml = results.map(item => '<div class="pw-test-result ' + (item.ok ? 'pw-test-ok' : 'pw-test-error') + '">' + (item.ok ? '🧹 ' : '✕ ') + escapeHtml(item.label) + (item.note ? ' — ' + escapeHtml(item.note) : '') + '</div>').join('');
    } catch (error) {
      cleanupOk = false;
      cleanupHtml = '<div class="pw-test-result pw-test-error">✕ Limpeza do sistema: ' + escapeHtml(error && error.message ? error.message : 'falhou') + '</div>';
    }

    $('#pw-test-results').innerHTML = testsHtml + cleanupHtml;
    const testsOk = tests.every(test => test[1]);
    showMessage(testsOk && cleanupOk ? 'Testes concluídos e limpeza do sistema executada com sucesso.' : 'Um ou mais itens precisam de atenção — veja a lista.', testsOk && cleanupOk ? 'success' : 'error');
    loadCleanupStatus();
  }

  function refreshAllViews() {
    refreshExpenseViews();
    renderOrdersConsultation(); renderClientsConsultation(); renderProductsConsultation();
    renderRegistryConsultation('category'); renderRegistryConsultation('unit'); renderRegistryConsultation('supplier'); renderRegistryConsultation('paymentMethod');
    renderDashboard(); renderAnalytics(); renderTrash(); renderArtsReport(); renderDtfCostRegistry(); renderDtfCostReport(); renderMonthlyClosingReport();
  }

  function monthlyOpenOrders() {
    return getOrders().filter(order => orderUsesMonthlyClosing(order) && adjustedOrderTotal(order) - Number(order.paid || 0) > 0.005);
  }

  function renderMonthlyClosingReport() {
    const body = $('#pw-monthly-body'); if (!body) return;
    const clientSelect = $('#pw-monthly-client');
    const previous = clientSelect.value;
    const clients = getClients().filter(client => client.monthlyClosing === true && Number(client.closingDay) >= 1);
    clientSelect.innerHTML = '<option value="">Todos os clientes com fechamento mensal</option>' + clients.map(client => '<option value="' + escapeHtml(client.id) + '">' + escapeHtml(client.code + ' — ' + client.name + ' · dia ' + client.closingDay) + '</option>').join('');
    clientSelect.value = clients.some(client => String(client.id) === previous) ? previous : '';
    const status = $('#pw-monthly-status').value;
    const today = new Date(localDateValue(new Date()) + 'T23:59:59');
    let orders = monthlyOpenOrders().filter(order => !clientSelect.value || String(order.client && order.client.id) === clientSelect.value);
    orders = orders.filter(order => status === 'all' || (status === 'overdue') === (monthlyDueDate(order) < today));
    const visibleIds = new Set(orders.map(order => String(order.orderNumber)));
    monthlyClosingSelection = monthlyClosingSelection.filter(id => visibleIds.has(String(id)));
    body.innerHTML = orders.length ? orders.map(order => {
      const total = adjustedOrderTotal(order), paid = Number(order.paid || 0), balance = Math.max(0, total - paid), due = monthlyDueDate(order), overdue = due < today;
      return '<tr><td><input type="checkbox" data-monthly-order="' + escapeHtml(order.orderNumber) + '"' + (monthlyClosingSelection.includes(String(order.orderNumber)) ? ' checked' : '') + '></td><td><strong>' + escapeHtml(order.orderNumber) + '</strong></td><td>' + escapeHtml(order.client && order.client.name || '—') + '</td><td>' + escapeHtml(order.createdDate ? String(order.createdDate).slice(0,10).split('-').reverse().join('/') : '—') + '</td><td>' + escapeHtml(localDateValue(due).split('-').reverse().join('/')) + '</td><td><span class="pw-badge ' + (overdue ? 'pw-badge-danger' : 'pw-badge-success') + '">' + (overdue ? 'Vencido' : 'No prazo') + '</span></td><td>' + escapeHtml(money.format(total)) + '</td><td>' + escapeHtml(money.format(paid)) + '</td><td><strong>' + escapeHtml(money.format(balance)) + '</strong></td></tr>';
    }).join('') : '<tr><td colspan="9">Nenhum pedido em aberto para os filtros informados.</td></tr>';
    const totals = orders.reduce((sum, order) => { sum.total += adjustedOrderTotal(order); sum.paid += Number(order.paid || 0); return sum; }, { total:0, paid:0 });
    $('#pw-monthly-count').textContent = String(orders.length); $('#pw-monthly-total').textContent = money.format(totals.total); $('#pw-monthly-paid').textContent = money.format(totals.paid); $('#pw-monthly-balance').textContent = money.format(Math.max(0, totals.total - totals.paid));

    const tfoot = $('#pw-monthly-tfoot');
    if (tfoot && orders.length) {
      const overdueOrders  = orders.filter(o => monthlyDueDate(o) < today);
      const currentOrders  = orders.filter(o => monthlyDueDate(o) >= today);
      const sumGroup = list => list.reduce((s, o) => { s.total += adjustedOrderTotal(o); s.paid += Number(o.paid || 0); return s; }, { total: 0, paid: 0 });
      const ovSum = sumGroup(overdueOrders);
      const curSum = sumGroup(currentOrders);
      const renderRow = (label, count, s, cls) => {
        const bal = Math.max(0, s.total - s.paid);
        return '<tr class="pw-monthly-tfoot-row' + (cls ? ' ' + cls : '') + '">' +
          '<td colspan="6"><strong>' + escapeHtml(label) + '</strong> (' + count + ' registro' + (count !== 1 ? 's' : '') + ')</td>' +
          '<td class="pw-money">' + escapeHtml(money.format(s.total)) + '</td>' +
          '<td class="pw-money">' + escapeHtml(money.format(s.paid))  + '</td>' +
          '<td class="pw-money"><strong>' + escapeHtml(money.format(bal)) + '</strong></td>' +
        '</tr>';
      };
      tfoot.innerHTML =
        (overdueOrders.length  ? renderRow('Vencidos',    overdueOrders.length,  ovSum,  'pw-monthly-tfoot-overdue')  : '') +
        (currentOrders.length  ? renderRow('A vencer',    currentOrders.length,  curSum, 'pw-monthly-tfoot-current')  : '') +
        renderRow('Total geral', orders.length, { total: totals.total, paid: totals.paid }, 'pw-monthly-tfoot-grand');
    } else if (tfoot) {
      tfoot.innerHTML = '';
    }

    $('#pw-monthly-close').disabled = !monthlyClosingSelection.length;
    monthlyClosingVisibleOrders = orders;
  }

  /** Agrupa os pedidos filtrados por cliente — usado só no documento de
   * impressão, pra separar visualmente cada cliente quando o filtro está em
   * "Todos os clientes com fechamento mensal". */
  function groupOrdersByClient(orders) {
    const groups = [];
    const byKey = new Map();
    orders.forEach(order => {
      const client = order.client || {};
      const key = String(client.id || client.name || '—');
      if (!byKey.has(key)) { const group = { client, orders: [] }; byKey.set(key, group); groups.push(group); }
      byKey.get(key).orders.push(order);
    });
    return groups;
  }

  function monthlyClosingOrderPrintHtml(order) {
    const total = adjustedOrderTotal(order), paid = Number(order.paid || 0), balance = Math.max(0, total - paid);
    const products = Array.isArray(order.items) ? order.items : [];
    const rows = products.length ? products.map(item => {
      const breakdown = itemFinancialBreakdown(item, order.origin || (order.client && order.client.origin) || 'Normal');
      return '<tr><td>' + escapeHtml(item.code || '—') + '</td><td>' + escapeHtml(item.description || '—') + '</td><td>' + escapeHtml(Number(item.quantity || 0).toLocaleString('pt-BR')) + '</td><td>' + escapeHtml(money.format(breakdown.netUnit)) + '</td><td>' + escapeHtml(money.format(breakdown.net)) + '</td></tr>';
    }).join('') : '<tr><td colspan="5" class="pw-empty-table">Este pedido não possui itens.</td></tr>';
    return '<div class="pw-monthly-print-order">' +
      '<div class="pw-monthly-print-order-head"><strong>Pedido ' + escapeHtml(order.orderNumber || '—') + '</strong><span>' + escapeHtml(order.createdDate ? String(order.createdDate).slice(0, 10).split('-').reverse().join('/') : '—') + '</span></div>' +
      '<table class="pw-monthly-print-items"><thead><tr><th>Código</th><th>Produto</th><th>Qtd</th><th>Unitário</th><th>Total</th></tr></thead><tbody>' + rows + '</tbody></table>' +
      '<div class="pw-monthly-print-order-totals"><span>Total do pedido: <strong>' + escapeHtml(money.format(total)) + '</strong></span><span>Recebido: <strong>' + escapeHtml(money.format(paid)) + '</strong></span><span>Saldo: <strong>' + escapeHtml(money.format(balance)) + '</strong></span></div>' +
    '</div>';
  }

  /** Busca o código Pix "copia e cola" já pronto (mesma configuração usada
   * pelo módulo pix-qrcode do plugin) pro valor total do documento — se o
   * módulo não estiver configurado/ativo, devolve null e o documento segue
   * sem o Pix em vez de travar a impressão. */
  async function fetchPixPayloadForPrint(amount) {
    try {
      const endpoint = new URL(SERVER.ajaxUrl || '/wp-admin/admin-ajax.php', window.location.href);
      if (endpoint.origin !== window.location.origin) return null;
      const form = new URLSearchParams();
      form.append('action', 'printway_pix_generate_payload');
      form.append('amount', amount.toFixed(2));
      const response = await fetch(endpoint.href, { method: 'POST', credentials: 'same-origin', cache: 'no-store', headers: { 'Content-Type': 'application/x-www-form-urlencoded; charset=UTF-8' }, body: form.toString() });
      const payload = await response.json().catch(() => null);
      if (!payload || !payload.success || !payload.payload) return null;
      return payload.payload;
    } catch (error) { return null; }
  }

  /** Monta o documento detalhado (pedidos + itens + valores + Pix) usado só
   * na impressão do fechamento mensal — chamado logo antes de imprimir, nunca
   * mostrado na tela normal (ver .pw-monthly-print-only no CSS). */
  async function renderMonthlyClosingPrintDocument() {
    const container = $('#pw-monthly-print-body');
    if (!container) return;
    const orders = monthlyClosingVisibleOrders;
    const groups = groupOrdersByClient(orders);
    const grandTotal = orders.reduce((sum, order) => sum + adjustedOrderTotal(order), 0);
    const grandPaid = orders.reduce((sum, order) => sum + Number(order.paid || 0), 0);
    const grandBalance = Math.max(0, grandTotal - grandPaid);
    const bodyHtml = groups.length ? groups.map(group => {
      const client = group.client || {};
      const clientTotal = group.orders.reduce((sum, order) => sum + adjustedOrderTotal(order), 0);
      const clientPaid = group.orders.reduce((sum, order) => sum + Number(order.paid || 0), 0);
      const clientBalance = Math.max(0, clientTotal - clientPaid);
      return '<div class="pw-monthly-print-client">' +
        '<h2>' + escapeHtml(client.name || 'Cliente não identificado') + '</h2>' +
        (client.document || client.phone ? '<p class="pw-monthly-print-client-doc">' + [client.document ? 'CPF/CNPJ: ' + client.document : '', client.phone || ''].filter(Boolean).map(escapeHtml).join(' · ') + '</p>' : '') +
        group.orders.map(monthlyClosingOrderPrintHtml).join('') +
        '<div class="pw-monthly-print-client-totals"><span>Total do cliente: <strong>' + escapeHtml(money.format(clientTotal)) + '</strong></span><span>Recebido: <strong>' + escapeHtml(money.format(clientPaid)) + '</strong></span><span>Saldo devedor: <strong>' + escapeHtml(money.format(clientBalance)) + '</strong></span></div>' +
      '</div>';
    }).join('') : '<p class="pw-empty-table">Nenhum pedido em aberto para os filtros informados.</p>';
    const totalsHtml = '<div class="pw-monthly-print-grand-totals"><span>Total geral: <strong>' + escapeHtml(money.format(grandTotal)) + '</strong></span><span>Total recebido: <strong>' + escapeHtml(money.format(grandPaid)) + '</strong></span><span>Saldo total a pagar: <strong>' + escapeHtml(money.format(grandBalance)) + '</strong></span></div>';
    let payload = null;
    if (grandBalance > 0.005) payload = await fetchPixPayloadForPrint(grandBalance);
    let pixHtml = '';
    if (grandBalance > 0.005) {
      pixHtml = payload
        ? '<div class="pw-monthly-print-pix"><h3>Pagamento via Pix</h3><div id="pw-monthly-print-pix-qr"></div><p class="pw-monthly-print-pix-code">' + escapeHtml(payload) + '</p><p class="pw-field-hint">Escaneie o QR Code com o aplicativo do seu banco ou copie o código acima em "Pix Copia e Cola".</p></div>'
        : '<div class="pw-monthly-print-pix"><p class="pw-field-hint">Chave Pix não configurada — configure em PrintWay → Pix para incluir o QR Code de pagamento neste documento.</p></div>';
    }
    container.innerHTML = bodyHtml + totalsHtml + pixHtml;
    if (payload && typeof QRCode !== 'undefined') {
      const qrHost = document.getElementById('pw-monthly-print-pix-qr');
      if (qrHost) {
        try {
          new QRCode(qrHost, { text: payload, width: 180, height: 180, correctLevel: QRCode.CorrectLevel.M });
          // O QRCode.js desenha no canvas e só DEPOIS troca pra um <img> com o
          // resultado (canvas.toDataURL) — trocar o src de uma <img> é
          // assíncrono (o navegador ainda precisa decodificar/pintar), então
          // sem esperar isso aqui o window.print() (chamado logo depois de
          // renderMonthlyClosingPrintDocument()) podia tirar o "retrato" da
          // impressão antes do QR aparecer de verdade na tela, imprimindo a
          // área vazia. Espera o carregamento (ou no máximo 1,5s) antes de
          // seguir, garantindo que o QR já esteja pintado a tempo do print.
          const qrImg = qrHost.querySelector('img');
          if (qrImg && !(qrImg.complete && qrImg.naturalWidth)) {
            await new Promise(resolve => {
              qrImg.addEventListener('load', resolve, { once: true });
              qrImg.addEventListener('error', resolve, { once: true });
              setTimeout(resolve, 1500);
            });
          }
        } catch (error) { /* segue só com o código copia-e-cola se a lib de QR falhar */ }
      }
    }
  }

  /** Recalcula "Pedidos marcados"/"Total a receber" no topo do modal a partir
   * das caixinhas e valores realmente marcados/preenchidos agora — chamada a
   * cada mudança de checkbox ou de valor pra o resumo nunca ficar
   * desatualizado em relação ao que será de fato gravado. */
  function updateMonthlyClosingModalSummary() {
    const rows = $$('#pw-monthly-closing-detail-body tr[data-monthly-detail-row]');
    let count = 0, total = 0;
    rows.forEach(row => {
      const checkbox = row.querySelector('[data-monthly-detail-select]');
      if (!checkbox || !checkbox.checked) return;
      count++;
      total += parseMoney((row.querySelector('[data-monthly-detail-value]') || {}).value || '0');
    });
    $('#pw-monthly-modal-count').textContent = String(count);
    $('#pw-monthly-modal-balance').textContent = money.format(total);
  }

  /**
   * Abre a tela de fechamento com CADA pedido marcado no relatório listado
   * individualmente (checkbox próprio, forma de pagamento própria, valor
   * próprio pré-preenchido com o saldo do pedido) — pedido explícito do
   * usuário pra substituir o formulário único que distribuía um valor total
   * pelos pedidos mais antigos automaticamente. Só os pedidos com a caixinha
   * marcada no momento de "Confirmar fechamento" são gravados.
   */
  function openMonthlyClosingModal() {
    const entries = getOrders().filter(order => monthlyClosingSelection.includes(String(order.orderNumber)))
      .map(order => ({ order, balance: Math.max(0, adjustedOrderTotal(order) - Number(order.paid || 0)) }))
      .filter(entry => entry.balance > 0.005)
      .sort((a, b) => monthlyDueDate(a.order) - monthlyDueDate(b.order));
    if (!entries.length) return showMessage('Selecione ao menos um pedido com saldo pendente.', 'error');
    const methodOptions = '<option value="">Selecione</option>' + getPaymentMethods().filter(item => item.active !== false).map(item => '<option value="' + escapeHtml(item.name) + '">' + escapeHtml(item.name) + '</option>').join('');
    $('#pw-monthly-closing-detail-body').innerHTML = entries.map(({ order, balance }) =>
      '<tr data-monthly-detail-row="' + escapeHtml(order.orderNumber) + '" data-monthly-detail-balance="' + balance.toFixed(2) + '">' +
        '<td><input type="checkbox" data-monthly-detail-select checked></td>' +
        '<td><strong>' + escapeHtml(order.orderNumber) + '</strong></td>' +
        '<td>' + escapeHtml(order.client && order.client.name || '—') + '</td>' +
        '<td>' + escapeHtml(money.format(balance)) + '</td>' +
        '<td><select data-monthly-detail-method>' + methodOptions + '</select></td>' +
        '<td><input type="text" inputmode="decimal" data-monthly-detail-value value="' + escapeHtml(balance.toFixed(2).replace('.', ',')) + '"></td>' +
      '</tr>'
    ).join('');
    $('#pw-monthly-payment-date').value = localDateValue(new Date());
    $('#pw-monthly-payment-note').value = '';
    $('#pw-monthly-detail-select-all').checked = true;
    updateMonthlyClosingModalSummary();
    openModal('pw-monthly-closing-modal', true);
  }

  async function saveMonthlyClosing() {
    const saveButton = $('#pw-confirm-monthly-closing');
    if (saveButton.disabled) return;
    const dateField = $('#pw-monthly-payment-date');
    const date = dateField.value;
    const note = $('#pw-monthly-payment-note').value.trim();
    if (!date) { dateField.classList.add('pw-field-invalid'); return showMessage('Informe a data do recebimento.', 'error'); }
    dateField.classList.remove('pw-field-invalid');
    const rows = $$('#pw-monthly-closing-detail-body tr[data-monthly-detail-row]');
    const entries = [];
    let hasError = false;
    rows.forEach(row => {
      const checkbox = row.querySelector('[data-monthly-detail-select]');
      const methodField = row.querySelector('[data-monthly-detail-method]');
      const valueField = row.querySelector('[data-monthly-detail-value]');
      methodField.classList.remove('pw-field-invalid');
      valueField.classList.remove('pw-field-invalid');
      if (!checkbox || !checkbox.checked) return;
      const orderNumber = row.dataset.monthlyDetailRow;
      const balance = Number(row.dataset.monthlyDetailBalance || 0);
      const method = methodField.value;
      const value = parseMoney(valueField.value);
      let rowHasError = false;
      if (!method) { methodField.classList.add('pw-field-invalid'); rowHasError = true; }
      if (!(value > 0) || value > balance + 0.005) { valueField.classList.add('pw-field-invalid'); rowHasError = true; }
      if (rowHasError) { hasError = true; return; }
      entries.push({ orderNumber, method, value, balance });
    });
    if (hasError) return showMessage('Corrija os campos destacados antes de salvar.', 'error');
    if (!entries.length) return showMessage('Marque ao menos um pedido para gravar o fechamento.', 'error');
    const orders = JSON.parse(JSON.stringify(getOrders()));
    const batch = 'FM-' + Date.now();
    const auditEntries = [];
    entries.forEach(({ orderNumber, method, value, balance }) => {
      const order = orders.find(item => String(item.orderNumber) === orderNumber);
      if (!order) return;
      order.payments = Array.isArray(order.payments) ? order.payments : [];
      order.payments.push({ method, type: value + 0.005 >= balance ? 'Total' : 'Parcial', value, date, note: (note ? note + ' · ' : '') + 'Fechamento mensal ' + batch, actor: currentActor(), batchId: batch });
      order.paid = Number(order.paid || 0) + value; order.paymentMethod = method; order.paymentStatus = paymentStatusFor(order, order.paid); order.paymentDate = date;
      syncOrderFinalization(order);
      auditEntries.push([orderNumber, batch + ' · ' + method + ' · ' + money.format(value)]);
    });
    saveButton.disabled = true;
    const saved = await persistStorage(STORAGE.orders, orders);
    saveButton.disabled = false;
    if (!saved) return;
    SERVER_STORAGE[STORAGE.orders] = orders;
    auditEntries.forEach(([id, detail]) => recordAudit('order', id, 'Fechamento mensal registrado', detail));
    monthlyClosingSelection = [];
    closeModal('pw-monthly-closing-modal', true);
    refreshAllViews();
    showMessage('Fechamento mensal registrado com sucesso (' + entries.length + ' pedido(s)) e incluído no histórico financeiro.', 'success');
  }

  function renderSearchResults(container, records, formatter, onSelect) {
    container.innerHTML = '';
    if (!records.length) {
      container.innerHTML = '<div class="pw-empty-result">Nenhum registro encontrado.</div>';
      container.classList.add('pw-open');
      return;
    }
    records.forEach(record => {
      const button = document.createElement('button');
      button.type = 'button';
      button.className = 'pw-result-item';
      button.innerHTML = formatter(record);
      button.addEventListener('click', () => {
        onSelect(record);
        container.classList.remove('pw-open');
      });
      container.appendChild(button);
    });
    container.classList.add('pw-open');
  }

  function navigateSearchResults(event, container) {
    const buttons = $$('.pw-result-item', container);
    if (!buttons.length) return;
    const current = buttons.findIndex(button => button.classList.contains('pw-keyboard-active'));
    if (event.key === 'Escape') {
      container.classList.remove('pw-open');
      return;
    }
    if (event.key === 'Enter') {
      if (container.classList.contains('pw-open')) {
        event.preventDefault();
        (buttons[current >= 0 ? current : 0]).click();
      }
      return;
    }
    if (!['ArrowDown', 'ArrowUp'].includes(event.key)) return;
    event.preventDefault();
    const next = event.key === 'ArrowDown'
      ? (current + 1) % buttons.length
      : (current <= 0 ? buttons.length - 1 : current - 1);
    buttons.forEach((button, index) => {
      button.classList.toggle('pw-keyboard-active', index === next);
      button.setAttribute('aria-selected', index === next ? 'true' : 'false');
    });
    container.classList.add('pw-open');
    buttons[next].scrollIntoView({ block: 'nearest' });
  }

  async function syncCustomerTypeToWordPressUser(client) {
    if (!SERVER.ajaxUrl || !SERVER.nonce || !client) return;
    try {
      const form = new URLSearchParams();
      form.append('action', 'pw_personalizados_sync_customer_role');
      form.append('nonce', SERVER.nonce);
      form.append('name', client.name || '');
      form.append('email', client.email || '');
      form.append('phone', client.phone || '');
      form.append('document', client.document || '');
      form.append('customer_type', client.customerType === 'revenda' ? 'revenda' : 'direto');
      await fetch(SERVER.ajaxUrl, { method:'POST', credentials:'same-origin', cache:'no-store', headers:{'Content-Type':'application/x-www-form-urlencoded; charset=UTF-8'}, body:form.toString() });
    } catch (error) { /* sincronização é um extra; falha aqui não deve incomodar o cadastro do cliente */ }
  }

  async function syncCustomerTypeFromWordPressUser(client, pricingPromise) {
    if (!client) return;
    const result = await (pricingPromise || lookupClientPricing(client));
    if (!result || !result.locked || result.source === 'cadastro do cliente') return;
    if (client.customerType === result.type) return;
    const clients = getClients();
    const index = clients.findIndex(record => record.id === client.id);
    if (index < 0) return;
    clients[index] = { ...clients[index], customerType: result.type };
    const saved = await persistStorage(STORAGE.clients, clients);
    if (saved) SERVER_STORAGE[STORAGE.clients] = clients;
  }

  async function lookupClientPricing(client) {
    const lookupVersion = ++selectedClientPricingVersion;
    selectedClientPricing = { type: '', locked: false, source: '' };
    if (client && (client.customerType === 'direto' || client.customerType === 'revenda')) {
      if (lookupVersion === selectedClientPricingVersion) selectedClientPricing = { type: client.customerType, locked: true, source: 'cadastro do cliente' };
      return selectedClientPricing;
    }
    if (!SERVER.ajaxUrl || !SERVER.nonce || !client) return selectedClientPricing;
    try {
      const form = new URLSearchParams();
      form.append('action', 'pw_personalizados_lookup_customer_type');
      form.append('nonce', SERVER.nonce);
      form.append('name', client.name || '');
      form.append('email', client.email || '');
      form.append('phone', client.phone || '');
      form.append('document', client.document || '');
      const response = await fetch(SERVER.ajaxUrl, { method: 'POST', credentials: 'same-origin', cache: 'no-store', headers: { 'Content-Type': 'application/x-www-form-urlencoded; charset=UTF-8' }, body: form.toString() });
      const result = await response.json();
      if (result && result.success && result.data && result.data.found && (result.data.type === 'direto' || result.data.type === 'revenda')) {
        if (lookupVersion === selectedClientPricingVersion) selectedClientPricing = { type: result.data.type, locked: true, source: 'usuário WordPress #' + result.data.user_id };
      }
    } catch (error) {
      console.warn('Não foi possível identificar o tipo do cliente no cadastro de usuários.', error);
    }
    return selectedClientPricing;
  }

  function clientBalanceSummary(client) {
    const currentOrderNumber = $('#pw-order-number') ? $('#pw-order-number').value : '';
    const today = localDateValue(new Date());
    let pendingTotal = 0, pendingCount = 0, hasOverdue = false;
    getOrders().forEach(order => {
      if (String(order.orderNumber) === String(currentOrderNumber)) return;
      if (!order.client || String(order.client.id) !== String(client.id)) return;
      const balance = adjustedOrderTotal(order) - Number(order.paid || 0);
      if (balance > 0.005) {
        pendingTotal += balance;
        pendingCount++;
        if (order.requestedDelivery && order.requestedDelivery < today) hasOverdue = true;
      }
    });
    return { pendingTotal, pendingCount, hasOverdue };
  }

  function selectClient(client) {
    $('#pw-client-id').value = client.id;
    $('#pw-client-name').value = client.name;
    $('#pw-client-phone').value = client.phone || '';
    $('#pw-client-email').value = client.email || '';
    $('#pw-client-document').value = client.document || '';
    $('#pw-client-address-summary').value = [client.address && client.address.street, client.address && client.address.number, client.address && client.address.neighborhood, client.address && client.address.city].filter(Boolean).join(', ') || 'Endereço não informado';
    $('#pw-client-person-type-summary').value = client.personType || documentType(client.document || '') || '—';
    $('#pw-client-customer-type-summary').value = client.customerType === 'revenda' ? 'Revenda' : 'Cliente direto';
    const balanceInfo = clientBalanceSummary(client);
    $('#pw-client-balance-summary').value = balanceInfo.pendingCount === 0
      ? 'Nenhum valor pendente'
      : balanceInfo.pendingCount + (balanceInfo.pendingCount === 1 ? ' pedido em aberto · ' : ' pedidos em aberto · ') + money.format(balanceInfo.pendingTotal) + (balanceInfo.hasOverdue ? ' (com atraso)' : '');
    $('#pw-client-card-name').textContent = client.name;
    $('#pw-client-card-reference').textContent = 'Código ' + (client.code || '—') + ' · ' + (client.origin && client.origin !== 'Normal' ? client.origin + ' · Pedido ' + (client.marketplaceOrderNumber || 'não informado') : (client.phone || client.email || 'Cadastro sem telefone ou e-mail'));
    $('#pw-client-search').value = client.name;
    if (Object.prototype.hasOwnProperty.call(client || {}, 'origin')) {
      syncOrderOriginOptions(client.origin || 'Normal');
    }
    $('#pw-order-marketplace-number').value = client.marketplaceOrderNumber || '';
    syncOrderClientOriginFields();
    // A origem pode ser alterada automaticamente ao selecionar um cliente.
    // Atualize a tabela de produtos também, sem exigir uma nova interação.
    if (items.length) {
      syncOrderItemsForOrigin($('#pw-order-client-origin').value || 'Normal');
      renderItems();
    }
    $('#pw-client-card').classList.add('pw-visible');
    selectedClientPricingRequest = lookupClientPricing(client);
    syncCustomerTypeFromWordPressUser(client, selectedClientPricingRequest);
  }

  function syncOrderClientOriginFields() {
    const origin = $('#pw-order-client-origin').value || 'Normal';
    const marketplace = orderOriginIsMarketplace(origin);
    $('#pw-order-marketplace-number-wrap').hidden = !marketplace;
    $('#pw-order-marketplace-number').required = false;
    $('#pw-order-marketplace-number').placeholder = marketplace ? 'Opcional — preenchido pela IA quando identificado' : '';
    $('#pw-order-marketplace-number').title = marketplace
      ? 'O número interno do pedido é gerado automaticamente. Informe o número da plataforma somente quando estiver disponível.'
      : '';
    if (!marketplace) $('#pw-order-marketplace-number').value = '';
    const marketplaceNumberLabel = $('#pw-order-marketplace-number-label');
    if (marketplaceNumberLabel) {
      marketplaceNumberLabel.textContent = origin === 'Mercado Livre'
        ? 'Número do pedido no Mercado Livre'
        : origin === 'Shopee' ? 'Número do pedido na Shopee' : 'Número do pedido no marketplace';
    }
    const icon = $('#pw-order-origin-icon');
    if (icon) {
      icon.className = 'pw-client-origin-dot ' + (origin === 'Mercado Livre' ? 'pw-origin-mercado-livre' : origin === 'Shopee' ? 'pw-origin-shopee' : marketplace ? 'pw-origin-marketplace' : 'pw-origin-normal');
      icon.innerHTML = origin === 'Mercado Livre' ? '🤝' : origin === 'Shopee' ? '<span class="pw-shopee-bag">S</span>' : marketplace ? '🛒' : '☺';
      icon.title = 'Origem: ' + origin;
    }
  }

  /** Mantém os valores dos itens coerentes com os campos exibidos para a origem atual. */
  function syncOrderItemsForOrigin(origin) {
    const marketplace = orderOriginIsMarketplace(origin || 'Normal');
    items.forEach(item => {
      const salePrice = Math.max(0, Number(item.salePrice || 0));
      const fee = Math.max(0, Number(item.marketplaceFee || 0));
      if (marketplace) {
        // Itens antigos não tinham valor de venda separado: usa o valor unitário
        // atual como valor bruto para que os novos campos já apareçam preenchidos.
        if (!salePrice && Number(item.unitPrice || 0) > 0) item.salePrice = Number(item.unitPrice || 0);
        item.unitPrice = Math.max(0, Number(item.salePrice || 0) - fee);
      } else if (salePrice > 0) {
        // Ao voltar para uma origem comum, o valor unitário volta a representar
        // o preço integral de venda; a tarifa fica preservada para eventual
        // retorno a um marketplace.
        item.unitPrice = salePrice;
      }
    });
    return marketplace;
  }

  function clearClient() {
    ['pw-client-id', 'pw-client-name', 'pw-client-phone', 'pw-client-email', 'pw-client-document', 'pw-client-search']
      .forEach(id => { $('#' + id).value = ''; });
    $('#pw-client-card').classList.remove('pw-visible');
    $('#pw-order-client-origin').value = 'Normal';
    $('#pw-order-marketplace-number').value = '';
    syncOrderClientOriginFields();
    selectedClientPricingVersion += 1;
    selectedClientPricing = { type: '', locked: false, source: '' };
    selectedClientPricingRequest = Promise.resolve(selectedClientPricing);
  }

  function chooseProductVariation(product) {
    const variations = Array.isArray(product.variations) ? product.variations.filter(variation => variation && variation.description) : [];
    if (!variations.length) return addItem(product);
    pendingVariationProduct = product;
    $('#pw-variation-product-name').textContent = (product.code || '') + ' — ' + (product.description || '');
    $('#pw-variation-options').innerHTML = variations.slice().sort((a, b) => Number(a.minQuantity || 1) - Number(b.minQuantity || 1)).map(variation => {
      const unit = getUnits().find(item => item.id === variation.unitId);
      const range = variation.maxQuantity == null || variation.maxQuantity === ''
        ? 'A partir de ' + (variation.minQuantity || 1)
        : 'De ' + (variation.minQuantity || 1) + ' até ' + variation.maxQuantity;
      return '<button class="pw-variation-option" type="button" data-variation-id="' + escapeHtml(variation.id) + '"><strong>' + escapeHtml(variation.description) + '</strong><span>' + escapeHtml(range) + ' · ' + escapeHtml(unit ? unit.name : 'Unidade não informada') + '</span><b>' + escapeHtml(money.format(Number(variation.price || 0))) + '</b></button>';
    }).join('');
    $$('.pw-variation-option', $('#pw-variation-options')).forEach(button => button.addEventListener('click', () => {
      const variation = variations.find(item => String(item.id) === String(button.dataset.variationId));
      if (!variation || !pendingVariationProduct) return;
      addItem(pendingVariationProduct, variation);
      pendingVariationProduct = null;
      closeModal('pw-variation-modal', true);
    }));
    openModal('pw-variation-modal', true);
  }

  function variationForQuantity(product, quantity) {
    const variations = Array.isArray(product && product.variations)
      ? product.variations.filter(variation => variation && variation.description).slice().sort((a, b) => Number(a.minQuantity || 1) - Number(b.minQuantity || 1))
      : [];
    const value = Math.max(1, Math.trunc(Number(quantity) || 1));
    return variations.find((variation, index) => {
      const minimum = Math.max(1, Number(variation.minQuantity) || 1);
      const next = variations[index + 1];
      const automaticMaximum = next ? Math.max(minimum, Number(next.minQuantity || minimum + 1) - 1) : Infinity;
      const maximum = variation.maxQuantity == null || variation.maxQuantity === ''
        ? automaticMaximum
        : Math.max(minimum, Number(variation.maxQuantity) || minimum);
      return value >= minimum && value <= maximum;
    }) || null;
  }

  function applyVariationToItem(item, product, variation) {
    if (!variation) return;
    const unit = getUnits().find(record => record.id === variation.unitId);
    item.variationId = variation.id || '';
    item.description = (product.description || '') + ' — ' + (variation.description || '');
    item.unitId = variation.unitId || '';
    item.unit = unit ? (unit.symbol || unit.name) : '';
    item.unitCost = Number(variation.cost || 0);
    item.unitPrice = Number(variation.price || 0);
  }

  function applyBaseProductToItem(item, product) {
    if (!product) return;
    const unit = getUnits().find(record => record.id === product.unitId);
    item.variationId = '';
    item.description = product.description || '';
    item.unitId = product.unitId || '';
    item.unit = unit ? (unit.symbol || unit.name) : '';
    item.unitCost = Number(product.cost || 0);
    item.unitPrice = Number(product.price || 0);
  }

  function addItem(product, variation = null) {
    const variationId = variation ? variation.id : '';
    const marketplace = isCurrentOrderMarketplace();
    const existing = items.find(item => item.productId && item.productId === product.id && String(item.variationId || '') === String(variationId));
    if (existing) {
      existing.quantity += 1;
      const matchingVariation = variationForQuantity(product, existing.quantity);
      if (matchingVariation) applyVariationToItem(existing, product, matchingVariation);
      else applyBaseProductToItem(existing, product);
      if (marketplace && !Number(existing.salePrice || 0)) existing.salePrice = Number(existing.unitPrice || 0);
    }
    else {
      const unitId = variation ? variation.unitId : product.unitId;
      const unit = getUnits().find(record => record.id === unitId);
      const basePrice = Number(variation ? variation.price : product.price || 0);
      items.push({
        rowId: 'row-' + Date.now() + '-' + Math.random().toString(36).slice(2, 7),
        productId: product.id || '',
        variationId,
        code: product.code || '',
        description: product.description + (variation ? ' — ' + variation.description : ''),
        unitId: unitId || '',
        unit: unit ? (unit.symbol || unit.name) : '',
        unitCost: Number(variation ? variation.cost : product.cost || 0),
        quantity: Math.max(1, Number(variation ? variation.minQuantity : 1) || 1),
        unitPrice: basePrice,
        salePrice: marketplace ? basePrice : 0,
        marketplaceFee: 0
      });
    }
    $('#pw-product-search').value = '';
    renderItems();
  }

  function isCurrentOrderMarketplace() {
    const origin = $('#pw-order-client-origin') ? $('#pw-order-client-origin').value : 'Normal';
    return orderOriginIsMarketplace(origin);
  }

  function preserveOrderOriginForItems(origin) {
    const select = $('#pw-order-client-origin');
    const selected = String(origin || (select && select.value) || 'Normal');
    if (select && select.value !== selected) {
      // O upload do arquivo é assíncrono; se o navegador reconstruir o
      // formulário nesse intervalo, restaura a origem que estava selecionada.
      syncOrderOriginOptions(selected);
      select.value = selected;
    }
    if (select) syncOrderClientOriginFields();
    return select && select.value ? select.value : selected;
  }

  function itemFinancialBreakdown(item, origin) {
    const quantity = Math.max(0, Number(item && item.quantity || 0));
    const marketplace = orderOriginIsMarketplace(origin);
    const saleUnit = Math.max(0, Number(item && item.salePrice || 0));
    const feeUnit = marketplace ? Math.max(0, Number(item && item.marketplaceFee || 0)) : 0;
    const storedUnit = Math.max(0, Number(item && item.unitPrice || 0));
    const hasMarketplaceValues = marketplace && (saleUnit > 0 || feeUnit > 0);
    const netUnit = hasMarketplaceValues ? Math.max(0, saleUnit - feeUnit) : storedUnit;
    const grossUnit = hasMarketplaceValues ? saleUnit : storedUnit;
    return { quantity, gross: quantity * grossUnit, fee: quantity * feeUnit, net: quantity * netUnit, grossUnit, feeUnit, netUnit };
  }

  function orderItemTotals(orderOrItems, originOverride) {
    const order = Array.isArray(orderOrItems) ? null : (orderOrItems || {});
    const list = Array.isArray(orderOrItems) ? orderOrItems : (Array.isArray(order.items) ? order.items : []);
    const origin = originOverride || (order && (order.origin || order.client && order.client.origin)) || 'Normal';
    const totals = list.reduce((result, item) => {
      const breakdown = itemFinancialBreakdown(item, origin);
      result.gross += breakdown.gross;
      result.fees += breakdown.fee;
      result.net += breakdown.net;
      return result;
    }, { gross: 0, fees: 0, net: 0 });
    if (!list.length && order && Number.isFinite(Number(order.total))) {
      totals.net = Math.max(0, Number(order.total || 0));
      totals.gross = totals.net;
    }
    return totals;
  }

  function renderItems(originOverride) {
    const body = $('#pw-items-body');
    body.innerHTML = '';
    const renderOrigin = preserveOrderOriginForItems(originOverride);
    const marketplace = orderOriginIsMarketplace(renderOrigin);
    const hasItems = items.length > 0;
    const headerRow = $('#pw-items-header');
    if (headerRow) {
      const extraHeaders = headerRow.querySelectorAll('.pw-marketplace-col');
      extraHeaders.forEach(cell => cell.remove());
      headerRow.querySelectorAll('.pw-art, .pw-actions').forEach(cell => { cell.hidden = !hasItems; });
      const moneyHeaders = headerRow.querySelectorAll('th.pw-money');
      if (moneyHeaders[1]) moneyHeaders[1].title = '';
      if (marketplace) {
        // Em marketplace a primeira coluna monetária representa o valor
        // unitário/bruto, seguida da plataforma e do total líquido.
        const totalHeader = moneyHeaders[1];
        if (totalHeader) {
          const platformHeader = document.createElement('th');
          platformHeader.className = 'pw-marketplace-col pw-money';
          platformHeader.textContent = 'Valor plataforma';
          totalHeader.title = 'Valor unitário − valor plataforma';
          headerRow.insertBefore(platformHeader, totalHeader);
        }
      }
    }
    if (!items.length) {
      const colspan = marketplace ? 7 : 6;
      body.innerHTML = '<tr id="pw-empty-items-row"><td class="pw-empty-items" colspan="' + colspan + '">Nenhum produto incluído neste pedido.</td></tr>';
      updateTotal();
      refreshOrderSaveState();
      return;
    }

    items.forEach(item => {
      const row = document.createElement('tr');
      const productFieldsLocked = !userIsAdministrator(currentUser);
      row.dataset.rowId = item.rowId;
      row.classList.toggle('pw-item-art-required', missingApprovedArtRowIds.has(String(item.rowId || '')) && !itemHasApprovedPdfArt(item));

      const breakdown = itemFinancialBreakdown(item, renderOrigin);
      const salePrice = Number(item.salePrice || 0);
      const fee = Number(item.marketplaceFee || 0);
      const effectiveUnit = breakdown.netUnit;

      const priceCell = marketplace
        ? '<input class="pw-item-sale-price" type="text" inputmode="decimal" value="' + escapeHtml(salePrice ? salePrice.toFixed(2).replace('.', ',') : '') + '" placeholder="0,00" aria-label="Valor unitário" title="Valor unitário bruto antes da tarifa da plataforma">'
        : '<input class="pw-item-price" type="text" inputmode="decimal" value="' + escapeHtml(effectiveUnit.toFixed(2).replace('.', ',')) + '" aria-label="Valor unitário"' + (productFieldsLocked ? ' readonly title="Somente administradores podem alterar o valor unitário"' : '') + '>';
      const marketplaceCells = marketplace
        ? '<td class="pw-marketplace-col"><input class="pw-item-fee" type="text" inputmode="decimal" value="' + escapeHtml(fee ? fee.toFixed(2).replace('.', ',') : '') + '" placeholder="0,00" aria-label="Valor plataforma" title="Tarifa descontada do valor unitário"></td>'
        : '';

      row.innerHTML =
        '<td><input class="pw-item-code" type="text" value="' + escapeHtml(item.code) + '" aria-label="Código" readonly></td>' +
        '<td><input class="pw-item-description" type="text" value="' + escapeHtml(item.description) + '" aria-label="Descrição"' + (productFieldsLocked ? ' readonly title="Somente administradores podem alterar a descrição"' : '') + '></td>' +
        '<td><span class="pw-item-unit">' + escapeHtml(item.unit || '—') + '</span></td>' +
        '<td><input class="pw-item-quantity" type="number" min="1" step="1" value="' + escapeHtml(item.quantity) + '" aria-label="Quantidade"></td>' +
        '<td>' + priceCell + '</td>' +
        marketplaceCells +
        '<td class="pw-total"><span class="pw-money-display pw-item-total">' + money.format(item.quantity * effectiveUnit) + '</span></td>' +
        '<td class="pw-art"><button class="pw-btn pw-btn-soft pw-btn-icon pw-item-art' + (itemHasApprovedPdfArt(item) ? ' pw-has-art' : '') + '" type="button" title="' + escapeHtml(item.art && item.art.name ? (item.art.code || 'Arte') + ' · ' + item.art.name + ' — clique para substituir por PDF' : 'Anexar arte aprovada em PDF') + '" aria-label="' + escapeHtml(item.art && item.art.name ? 'Substituir arte aprovada em PDF de ' + item.description : 'Anexar arte aprovada em PDF de ' + item.description) + '">📎</button></td>' +
        '<td class="pw-actions"><button class="pw-btn pw-btn-danger pw-btn-icon pw-remove-item" type="button" title="Remover item" aria-label="Remover item">×</button></td>';

      let mlInfoRow = null;
      if (marketplace && (item.mlTarifa != null || item.mlFrete != null)) {
        const mlTotal = Number(item.salePrice || 0);
        const mlTar   = Number(item.mlTarifa  || 0);
        const mlFrt   = Number(item.mlFrete   || 0);
        mlInfoRow = document.createElement('tr');
        mlInfoRow.className = 'pw-item-ml-breakdown';
        mlInfoRow.dataset.rowId = item.rowId;
        // Alinha cada valor embaixo da coluna correspondente da linha do item:
        // Valor unitário → total bruto do ML; Tarifa+Frete ocupa (mescla) as
        // colunas Valor plataforma + Valor total — o bruto a receber já
        // aparece ali em cima, no campo Valor total, sem repetir embaixo.
        mlInfoRow.innerHTML =
          '<td colspan="4" class="pw-item-ml-breakdown-cell pw-item-ml-breakdown-label"><span class="pw-ml-fin-label">' + escapeHtml(renderOrigin === 'Shopee' ? 'Shopee' : 'ML') + '</span></td>' +
          '<td class="pw-item-ml-breakdown-cell">Total <strong>' + money.format(mlTotal) + '</strong></td>' +
          '<td colspan="2" class="pw-item-ml-breakdown-cell">Tarifa <strong>−' + money.format(mlTar) + '</strong> · Frete <strong>−' + money.format(mlFrt) + '</strong></td>' +
          '<td colspan="2" class="pw-item-ml-breakdown-cell"></td>';
      }

      row.addEventListener('input', event => {
        if (event.target.classList.contains('pw-item-description')) item.description = event.target.value;
        if (event.target.classList.contains('pw-item-quantity')) {
          item.quantity = Math.max(1, Math.trunc(Number(event.target.value) || 1));
          const product = getProducts().find(record => record.id === item.productId);
          const matchingVariation = variationForQuantity(product, item.quantity);
          if (product) {
            if (matchingVariation) applyVariationToItem(item, product, matchingVariation);
            else applyBaseProductToItem(item, product);
            if (marketplace) syncOrderItemsForOrigin($('#pw-order-client-origin').value || 'Normal');
            $('.pw-item-description', row).value = item.description;
            $('.pw-item-unit', row).textContent = item.unit || '—';
            if (marketplace) {
              const saleInput = $('.pw-item-sale-price', row);
              if (saleInput) saleInput.value = Number(item.salePrice || 0).toFixed(2).replace('.', ',');
            } else {
              const priceInput = $('.pw-item-price', row);
              if (priceInput) priceInput.value = item.unitPrice.toFixed(2).replace('.', ',');
            }
          }
        }
        if (event.target.classList.contains('pw-item-price') && !marketplace) {
          item.unitPrice = parseMoney(event.target.value);
          // Mantém a próxima conversão para marketplace baseada no preço atual.
          item.salePrice = item.unitPrice;
        }
        if (event.target.classList.contains('pw-item-sale-price')) {
          item.salePrice = parseMoney(event.target.value);
          item.unitPrice = Math.max(0, (item.salePrice || 0) - (item.marketplaceFee || 0));
        }
        if (event.target.classList.contains('pw-item-fee')) {
          item.marketplaceFee = parseMoney(event.target.value);
          item.unitPrice = Math.max(0, (item.salePrice || 0) - (item.marketplaceFee || 0));
        }
        const currentBreakdown = itemFinancialBreakdown(item, preserveOrderOriginForItems(renderOrigin));
        $('.pw-item-total', row).textContent = money.format(currentBreakdown.net);
        updateTotal();
      });

      $('.pw-remove-item', row).addEventListener('click', () => {
        items = items.filter(current => current.rowId !== item.rowId);
        renderItems();
      });
      $('.pw-item-art', row).addEventListener('click', () => {
        itemWaitingForArt = null;
        if (analyticsIsDtfUvItem(item)) {
          openDtfUvModal({ item, art: item.art || null });
          return;
        }
        itemWaitingForArt = item;
        const input = $('#pw-item-art-file');
        input.value = '';
        input.click();
      });
      body.appendChild(row);
      if (mlInfoRow) body.appendChild(mlInfoRow);
    });
    updateTotal();
    refreshOrderSaveState();
  }

  function updateTotal() {
    const subtotal = orderItemTotals(items, $('#pw-order-client-origin') ? $('#pw-order-client-origin').value : 'Normal').net;
    const discount = parseMoney($('#pw-discount-value') && $('#pw-discount-value').value);
    const surcharge = parseMoney($('#pw-surcharge-value') && $('#pw-surcharge-value').value);
    const paid = parseMoney($('#pw-paid-value') && $('#pw-paid-value').value);
    const total = Math.max(0, subtotal - discount + surcharge);
    $('#pw-order-total').textContent = money.format(total);
    if ($('#pw-products-subtotal')) $('#pw-products-subtotal').textContent = money.format(subtotal);
    if ($('#pw-payment-method-view')) $('#pw-payment-method-view').textContent = ($('#pw-payment-method').value || 'Não informada');
    if ($('#pw-payment-status-view')) $('#pw-payment-status-view').textContent = ($('#pw-payment-status').value || 'Pendente');
    if ($('#pw-discount-total')) $('#pw-discount-total').textContent = money.format(discount);
    if ($('#pw-surcharge-total')) $('#pw-surcharge-total').textContent = money.format(surcharge);
    if ($('#pw-adjusted-total')) $('#pw-adjusted-total').textContent = money.format(total);
    if ($('#pw-paid-total')) $('#pw-paid-total').textContent = money.format(paid);
    if ($('#pw-balance-total')) $('#pw-balance-total').textContent = money.format(Math.max(0, total - paid));
    const financialSection = $('#pw-financial-readonly');
    if (financialSection) financialSection.hidden = !(($('#pw-payment-method').value || '').trim() || discount > 0 || surcharge > 0 || paid > 0);
  }

  function setupDeliveryDateQuickMenu() {
    const field = $('#pw-requested-delivery');
    if (!field) return;
    const menu = document.createElement('div');
    menu.className = 'pw-date-quick-menu';
    menu.innerHTML =
      '<button type="button" data-date-option="today">📅 Hoje</button>' +
      '<button type="button" data-date-option="tomorrow">📅 Amanhã</button>' +
      '<button type="button" data-date-option="next-business-day">📅 Próximo dia útil</button>' +
      '<hr>' +
      '<button type="button" data-date-option="pick">🗓️ Selecionar data</button>';
    // O menu precisa permanecer dentro do app para receber as regras CSS
    // escopadas em #pw-personalizados-app.
    root.appendChild(menu);
    const closeMenu = () => menu.classList.remove('pw-open');
    const openMenuAt = (clientX, clientY) => {
      if (field.readOnly || field.disabled) return;
      menu.classList.add('pw-open');
      const margin = 8;
      const rect = menu.getBoundingClientRect();
      const left = Math.max(margin, Math.min(Number(clientX) || 0, window.innerWidth - rect.width - margin));
      const top = Math.max(margin, Math.min(Number(clientY) || 0, window.innerHeight - rect.height - margin));
      menu.style.left = Math.round(left) + 'px';
      menu.style.top = Math.round(top) + 'px';
    };
    const nextBusinessDay = () => {
      const date = new Date();
      date.setDate(date.getDate() + 1);
      while (date.getDay() === 0 || date.getDay() === 6) date.setDate(date.getDate() + 1);
      return date;
    };
    field.addEventListener('click', () => {
      if (field.readOnly || field.disabled) return;
      if (typeof field.showPicker === 'function') { try { field.showPicker(); } catch (error) { /* navegador sem suporte ao seletor nativo */ } }
    });
    field.addEventListener('contextmenu', event => {
      if (field.readOnly || field.disabled) return;
      event.preventDefault();
      openMenuAt(event.clientX, event.clientY);
    });
    // Alguns navegadores tratam <input type="date"> como controle nativo e
    // não encaminham o contextmenu de forma consistente. O botão direito no
    // pointerdown garante a mesma experiência nesses casos.
    field.addEventListener('pointerdown', event => {
      if (event.button !== 2 || field.readOnly || field.disabled) return;
      event.preventDefault();
      openMenuAt(event.clientX, event.clientY);
    });
    menu.addEventListener('click', event => {
      const button = event.target.closest('[data-date-option]');
      if (!button) return;
      closeMenu();
      const option = button.dataset.dateOption;
      if (option === 'pick') {
        field.focus();
        if (typeof field.showPicker === 'function') { try { field.showPicker(); } catch (error) { /* navegador sem suporte ao seletor nativo */ } }
        return;
      }
      let date = new Date();
      if (option === 'tomorrow') date.setDate(date.getDate() + 1);
      else if (option === 'next-business-day') date = nextBusinessDay();
      field.value = localDateValue(date);
      field.dispatchEvent(new Event('input', { bubbles: true }));
      field.dispatchEvent(new Event('change', { bubbles: true }));
      const clientField = $('#pw-client-search');
      if (clientField) clientField.focus();
    });
    document.addEventListener('click', event => { if (!menu.contains(event.target)) closeMenu(); });
    document.addEventListener('keydown', event => { if (event.key === 'Escape') closeMenu(); });
    window.addEventListener('scroll', closeMenu, true);
  }

  function updateDeadlineStatus() {
    const requested = $('#pw-requested-delivery').value;
    const actual = $('#pw-actual-delivery').value;
    const badge = $('#pw-deadline-status');
    badge.className = 'pw-deadline-status pw-status-neutral';

    if (!requested) {
      badge.textContent = 'Prazo não informado';
      return;
    }

    const requestedDate = new Date(requested + 'T12:00:00');
    const comparisonDate = actual ? new Date(actual + 'T12:00:00') : new Date();
    const days = Math.round((comparisonDate - requestedDate) / 86400000);

    if (actual) {
      if (days > 0) {
        badge.className = 'pw-deadline-status pw-status-late';
        badge.textContent = 'Entregue com ' + days + ' dia(s) de atraso';
      } else {
        badge.className = 'pw-deadline-status pw-status-ok';
        badge.textContent = 'Entregue no prazo';
      }
      return;
    }

    if (days > 0) {
      badge.className = 'pw-deadline-status pw-status-late';
      badge.textContent = 'Em atraso há ' + days + ' dia(s)';
    } else if (days >= -2) {
      badge.className = 'pw-deadline-status pw-status-warning';
      badge.textContent = days === 0 ? 'Entrega prevista para hoje' : 'Prazo próximo';
    } else {
      badge.className = 'pw-deadline-status pw-status-ok';
      badge.textContent = 'Dentro do prazo';
    }
  }

  function validateOrder() {
    const today = localDateValue(new Date());
    const requestedDelivery = $('#pw-requested-delivery').value;
    const savedOrder = editingOrderNumber && getOrders().find(order => String(order.orderNumber) === String(editingOrderNumber));
    const savedRequestedDelivery = String(savedOrder && savedOrder.requestedDelivery || '');
    if (!$('#pw-client-id').value) return 'Selecione ou cadastre um cliente.';
    if (!requestedDelivery) return 'Informe a previsão de entrega.';
    if (!savedRequestedDelivery && requestedDelivery < today) return 'A previsão de entrega não pode ser anterior à data atual.';
    if (!items.length) return 'Inclua pelo menos um produto no pedido.';
    if (items.some(item => !item.description.trim())) return 'Todos os produtos precisam ter uma descrição.';
    if (items.some(item => item.quantity <= 0)) return 'A quantidade dos produtos deve ser maior que zero.';
    if ($('#pw-actual-delivery').value && $('#pw-status').value !== 'Entregue') {
      return 'Ao informar a data em que o pedido foi entregue, altere a situação para Entregue.';
    }
    return '';
  }

