    // clique no caso comum — mas continua editável depois: só troca o array,
    // não trava nada, o usuário pode desmarcar/marcar qualquer uma na hora.
    const value = event.target.value;
    const allStatuses = ORDER_STATUS_FLOW.map(status => status.value);
    if (value === 'finalized') ordersSituationFilters = ['Entregue'];
    else if (value === 'open') ordersSituationFilters = allStatuses.filter(status => status !== 'Entregue');
    else if (value === 'all') ordersSituationFilters = allStatuses.slice();
