  // Menu de contexto (botão direito) na tabela de artes
  let artContextMenu = null;
  function removeArtContextMenu() {
    if (artContextMenu) { artContextMenu.remove(); artContextMenu = null; }
    document.removeEventListener('click', removeArtContextMenu);
    document.removeEventListener('keydown', removeArtContextMenuOnEsc);
  }
  function removeArtContextMenuOnEsc(event) { if (event.key === 'Escape') removeArtContextMenu(); }
  $('#pw-arts-body') && $('#pw-arts-body').addEventListener('contextmenu', event => {
    const row = event.target.closest('[data-art-record]');
    if (!row) return;
    event.preventDefault();
    removeArtContextMenu();
    const recordId = row.dataset.artRecord;
    const isMounted = row.dataset.artMounted === '1';
    const menu = document.createElement('div');
    menu.className = 'pw-context-menu';
    menu.style.cssText = 'position:fixed;z-index:10100;top:' + event.clientY + 'px;left:' + event.clientX + 'px;';
    const isChecked = (() => { const cb = row.querySelector('input[data-row-select]'); return cb && cb.checked; })();
    const cbDisabled = (() => { const cb = row.querySelector('input[data-row-select]'); return !cb || cb.disabled; })();
    menu.innerHTML =
      (!cbDisabled && !isChecked ? '<button class="pw-context-menu-item" data-context-action="select"><span>☑ Marcar</span></button>' : '') +
      (!cbDisabled && isChecked  ? '<button class="pw-context-menu-item" data-context-action="deselect"><span>☐ Desmarcar</span></button>' : '') +
      (!cbDisabled ? '<div class="pw-context-menu-divider"></div>' : '') +
      (!isMounted ? '<button class="pw-context-menu-item pw-context-menu-item-active" data-context-action="mount"><span>✓ Marcar como já montado</span></button>' : '') +
      (isMounted  ? '<button class="pw-context-menu-item pw-context-menu-item-active" data-context-action="unmount"><span>— Marcar como NÃO montado</span></button>' : '');
    menu.addEventListener('click', async event => {
      const btn = event.target.closest('[data-context-action]');
      if (!btn) return;
      removeArtContextMenu();
      if (btn.dataset.contextAction === 'select' || btn.dataset.contextAction === 'deselect') {
        const checkbox = row.querySelector('input[data-row-select]');
        if (checkbox && !checkbox.disabled) {
          checkbox.checked = btn.dataset.contextAction === 'select';
          checkbox.dispatchEvent(new Event('change', { bubbles: true }));
        }
        return;
      }
      await setArtMountedStatus(recordId, btn.dataset.contextAction === 'mount');
      showMessage(btn.dataset.contextAction === 'mount' ? 'Arte marcada como montada.' : 'Arte marcada como NÃO montada.', 'success');
    });
    root.appendChild(menu);
    artContextMenu = menu;
    // Reposiciona se sair da tela
    requestAnimationFrame(() => {
      if (!artContextMenu) return;
      const rect = menu.getBoundingClientRect();
      if (rect.right > window.innerWidth - 8) menu.style.left = Math.max(8, event.clientX - rect.width) + 'px';
      if (rect.bottom > window.innerHeight - 8) menu.style.top = Math.max(8, event.clientY - rect.height) + 'px';
    });
    setTimeout(() => {
      document.addEventListener('click', removeArtContextMenu);
      document.addEventListener('keydown', removeArtContextMenuOnEsc);
    }, 0);
  });
