  $('#pw-dtf-cost-form').addEventListener('submit', async event => {
    event.preventDefault();
    if (!userIsAdministrator(currentUser)) return showMessage('Apenas administradores podem registrar despesas.', 'error');
    const isAd = dtfCostFormMode === 'ads';
    if (isAd && !await ensureAnnouncementCategory()) return showMessage('Não foi possível preparar a categoria Anúncio.', 'error');
    const category = isAd ? 'Anúncio' : $('#pw-dtf-cost-category').value;
    const catalogItem = getDtfCatalog().find(record => record.id === $('#pw-dtf-cost-item').value) || null;
    const item = isAd ? 'Anúncio' : (!$('#pw-dtf-custom-item-wrap').hidden ? $('#pw-dtf-custom-item').value.trim() : (catalogItem && catalogItem.name || ''));
    const itemCode = isAd ? 'ADS' : (category === 'Outro' ? 'OUT' : (catalogItem && catalogItem.code || ''));
    const date = $('#pw-dtf-cost-date').value;
    const quantity = isAd ? 1 : Number($('#pw-dtf-cost-quantity').value || 0);
    const value = parseMoney($('#pw-dtf-cost-value').value);
    if (!date) return showMessage('Informe a data da movimentação.', 'error');
    if (!item) return showMessage('Informe o insumo, peça ou serviço.', 'error');
    if (!(quantity > 0)) return showMessage('Informe uma quantidade maior que zero.', 'error');
    if (!(value > 0)) return showMessage('Informe o valor total pago.', 'error');
    const records = getDtfCosts().map(record => ({ ...record }));
    const existingIndex = records.findIndex(record => record.id === editingDtfCostId);
    const existing = existingIndex >= 0 ? records[existingIndex] : null;
    const supplier = $('#pw-dtf-cost-supplier').value === '__new__' ? $('#pw-dtf-custom-supplier').value.trim() : $('#pw-dtf-cost-supplier').value.trim();
    if ($('#pw-dtf-cost-supplier').value === '__new__' && !supplier) return showMessage('Informe o nome do novo fornecedor ou técnico.', 'error');
    const entry = {
      ...existing,
      id: existing ? existing.id : 'dtf-cost-' + Date.now() + '-' + Math.random().toString(36).slice(2, 7), date, category, item, itemCode,
      itemId: catalogItem && $('#pw-dtf-custom-item-wrap').hidden ? catalogItem.id : '',
      action: isAd ? 'Anúncio' : $('#pw-dtf-cost-action').value, quantity, unit: isAd ? 'unidade' : $('#pw-dtf-cost-unit').value, value,
      supplier, supplierId:(getSuppliers().find(record => record.name === supplier) || {}).id || '', notes: $('#pw-dtf-cost-notes').value.trim(),
      createdAt: existing ? existing.createdAt : new Date().toISOString(),
      updatedAt: new Date().toISOString(),
      actor: existing ? existing.actor : currentActor(),
      updatedBy: currentActor(),
      userId: existing ? existing.userId : Number(currentUser && currentUser.id || 0)
    };
    if (existingIndex >= 0) records[existingIndex] = entry;
    else records.push(entry);
    const saveButton = $('#pw-save-dtf-cost');
    if (saveButton.disabled) return;
    if (!category || (!isAd && (!entry.unit || !entry.action))) return showMessage('Selecione a categoria, a movimentação e a unidade da despesa.', 'error');
    saveButton.disabled = true;
    let saved;
    try { saved = await saveExpenseCollection(STORAGE.dtfCosts, records); } finally { saveButton.disabled = false; }
    if (!saved) return;
    recordAudit('dtfCost', entry.id, existing ? 'Despesa alterada' : 'Despesa registrada', entry.item + ' · ' + money.format(entry.value));
    refreshExpenseViews();
    if (keepBulkEditorOpen('dtfCost', entry.id)) { editDtfCost(entry); markModalClean('pw-dtf-cost-modal'); setTimeout(() => $('#pw-save-dtf-cost').classList.add('pw-saved'), 0); }
    else if ($('#pw-dtf-cost-modal').classList.contains('pw-open')) closeModal('pw-dtf-cost-modal', true);
    else resetDtfCostForm(isAd ? 'ads' : 'materials');
    showMessage('Despesa de ' + entry.item + (existing ? ' atualizada' : ' registrada') + ' com sucesso.', 'success');
  });
