  $('#pw-item-art-file').addEventListener('change', async event => {
    const file = event.currentTarget.files && event.currentTarget.files[0];
    const item = itemWaitingForArt;
    itemWaitingForArt = null;
    if (!file || !item) return;
    const artCode = item.art && item.art.code ? item.art.code : nextArtCode($('#pw-order-number').value, items);
    if (!artCode) return showMessage('Este pedido já atingiu o limite de 26 artes identificadas por letras.', 'error');
    try {
      const isDtfUv = analyticsIsDtfUvItem(item);
      item.art = await uploadOrderArtPdf(file, artCode, isDtfUv, itemCategoryId(item));
      missingApprovedArtRowIds.delete(String(item.rowId || ''));
      const preservedOrigin = ($('#pw-order-client-origin') ? $('#pw-order-client-origin').value : 'Normal') || 'Normal';
      syncOrderItemsForOrigin(preservedOrigin);
      renderItems(preservedOrigin);
      maybeAdvanceStatusAfterArtAttach();
      if (isDtfUv) {
        await openDtfUvModal({ item, art:item.art });
      } else {
        showMessage('Arte em PDF anexada ao produto. Salve o pedido para confirmar o vínculo.', 'success');
      }
    } catch (error) {
      showMessage(error.message || 'Não foi possível enviar a arte aprovada.', 'error');
    }
  });

