  applySmartNameCase('pw-new-client-name');
  applySmartNameCase('pw-registry-contact');
  applySmartNameCase('pw-nfe-tech-name');

  $('#pw-save-client').addEventListener('click', async () => {
    const saveButton = $('#pw-save-client');
    if (saveButton.disabled) return;
    const autoSave = aiClientAutoSaveInProgress;
    const name = $('#pw-new-client-name').value.trim();
    const phone = formatPhone($('#pw-new-client-phone').value);
    const email = $('#pw-new-client-email').value.trim();
    const document = $('#pw-new-client-document').value.trim();
    const personType = documentType(document);
    const cep = digits($('#pw-new-client-cep').value);
    const code = $('#pw-new-client-code').value.trim();
    const monthlyClosing = $('#pw-new-client-monthly-closing').checked;
    const waNotifyEl = $('#pw-new-client-whatsapp-notify');
    const whatsappNotify = waNotifyEl ? waNotifyEl.checked : true;
    const customerType = $('#pw-new-client-customer-type').value === 'revenda' ? 'revenda' : 'direto';
    const closingDay = Number($('#pw-new-client-closing-day').value || 0);
    const orderOrigin = $('#pw-order-client-origin') ? $('#pw-order-client-origin').value : '';
    const orderViewActive = !!$('#pw-order-form') && $('#pw-order-form').classList.contains('pw-active');
    const marketplacePhoneOptional = (orderViewActive && orderOriginIsMarketplace(orderOrigin)) || (!!editingClientId && clientHasMarketplaceOrder(editingClientId));
    if (!code) return showMessage('O código do cliente é obrigatório.', 'error');
    if (!name) return showMessage('O nome do cliente é obrigatório.', 'error');
    if (!phone && !marketplacePhoneOptional) return showMessage('O telefone/WhatsApp do cliente é obrigatório.', 'error');
    if (phone && !isValidPhone(phone)) return showMessage('O telefone/WhatsApp informado não é válido.', 'error');
    if (monthlyClosing && (!Number.isInteger(closingDay) || closingDay < 1 || closingDay > 31)) return showMessage('Informe um dia de fechamento mensal entre 1 e 31.', 'error');
    if (email && !isValidEmail(email)) return showMessage('O endereço de e-mail informado não é válido.', 'error');
    if (document && !personType) {
      activateClientTab('contact');
      return showMessage('O CPF ou CNPJ informado não é válido.', 'error');
    }
    if (cep && cep.length !== 8) {
      activateClientTab('address');
      return showMessage('O CEP deve conter 8 números.', 'error');
    }

    const clients = getClients();
    if (editingClientId) {
      const currentClient = clients.find(record => record.id === editingClientId);
      if (currentClient && currentClient.monthlyClosing === true && monthlyClosing !== true && clientHasPendingMonthlyBilling(editingClientId)) {
        return showMessage('Este cliente tem pedidos com saldo pendente no fechamento mensal (vencidos ou a vencer). Quite o faturamento em aberto antes de alterar a forma de pagamento.', 'error');
      }
    }
    const candidateAddress = {
      cep: $('#pw-new-client-cep').value.trim(),
      street: $('#pw-new-client-street').value.trim(),
      number: $('#pw-new-client-number').value.trim(),
      complement: $('#pw-new-client-complement').value.trim(),
      neighborhood: $('#pw-new-client-neighborhood').value.trim(),
      city: $('#pw-new-client-city').value.trim(),
      cityCode: digits($('#pw-new-client-city-code').value).slice(0, 7),
      state: $('#pw-new-client-state').value.trim().toUpperCase()
    };
    const duplicateMatch = findPossibleDuplicateClient(clients, editingClientId, { name, document, phone, email, address: candidateAddress });
    if (duplicateMatch && !(await confirmPossibleDuplicateClient(duplicateMatch))) {
      aiClientAutoSaveInProgress = false;
      return;
    }
    const savedClientId = editingClientId || 'client-' + Date.now();
    if (clients.some(record => record.id !== editingClientId && normalize(record.code) === normalize(code))) return showMessage('Já existe um cliente com esse código.', 'error');
    const keepEditor = keepBulkEditorOpen('client', savedClientId);
    const existingClient = clients.find(record => record.id === savedClientId);
    if (existingClient && !userIsAdministrator(currentUser) && code !== existingClient.code) return showMessage('Apenas administradores podem alterar códigos já cadastrados.', 'error');
    const acceptsCorreiosEl = $('#pw-new-client-accepts-correios');
    const acceptsTranspEl   = $('#pw-new-client-accepts-transportadoras');
    const client = {
      id: savedClientId,
      code,
      position: existingClient && Number.isFinite(Number(existingClient.position)) ? Number(existingClient.position) : nextRecordPosition(clients),
      name,
      phone,
      email,
      document: formatDocument(document),
      personType,
      monthlyClosing,
      whatsappNotify,
      acceptsCorreios: acceptsCorreiosEl ? acceptsCorreiosEl.checked : true,
      acceptsTransportadoras: acceptsTranspEl ? acceptsTranspEl.checked : true,
      customerType,
      closingDay: monthlyClosing ? closingDay : 0,
      address: candidateAddress
    };
    const existingClientIndex = clients.findIndex(record => record.id === client.id);
    if (existingClientIndex >= 0) clients[existingClientIndex] = client;
    else clients.push(client);
    if (autoSave) showProcessing('Cadastrando cliente…', 'Salvando o cadastro identificado pela IA em segundo plano.', false, false);
    saveButton.disabled = true;
    const saved = await persistStorage(STORAGE.clients, clients);
    saveButton.disabled = false;
    if (!saved) {
      aiClientAutoSaveInProgress = false;
      if (autoSave) hideProcessing();
      return;
    }
    aiClientAutoSaveInProgress = false;
    SERVER_STORAGE[STORAGE.clients] = clients;
    syncCustomerTypeToWordPressUser(client);
    if (existingClientIndex < 0) consumeRegistryCode('client', code);
    selectClient(client);
    if (!keepEditor) {
      [
        'pw-new-client-code', 'pw-new-client-name', 'pw-new-client-phone', 'pw-new-client-email',
        'pw-new-client-document', 'pw-new-client-person-type', 'pw-new-client-cep', 'pw-new-client-street', 'pw-new-client-number',
        'pw-new-client-complement', 'pw-new-client-neighborhood', 'pw-new-client-city', 'pw-new-client-city-code', 'pw-new-client-state',
        'pw-find-state', 'pw-find-city', 'pw-find-street'
      ]
        .forEach(id => { $('#' + id).value = ''; });
      $('#pw-address-results').innerHTML = '';
      $('#pw-address-finder').classList.remove('pw-open');
      closeModal('pw-client-modal', true);
    }
    renderClientsConsultation();
    if (keepEditor) { renderBulkNavigation(); markModalClean('pw-client-modal'); saveButton.classList.add('pw-saved'); }
    if (autoSave) hideProcessing();
    showMessage(autoSave ? 'Cliente cadastrado com sucesso.' : (existingClientIndex >= 0 ? 'Cliente atualizado com sucesso.' : 'Cliente cadastrado e selecionado.'), 'success');
    if (existingClient) {
      const nameChanged = existingClient.name !== client.name;
      const otherChanged = existingClient.phone !== client.phone || existingClient.email !== client.email || existingClient.document !== client.document || JSON.stringify(existingClient.address || {}) !== JSON.stringify(client.address || {});
      if (nameChanged || otherChanged) {
        const affectedOrders = getOrders().filter(order => order.client && String(order.client.id) === String(client.id));
        const applyUpdate = () => getOrders().map(order => (order.client && String(order.client.id) === String(client.id)) ? { ...order, client: { ...order.client, name: client.name, phone: client.phone, email: client.email, document: client.document, address: client.address } } : order);
        if (nameChanged) {
          await confirmAndPropagateRename(existingClient.name, client.name, [{ label: 'Pedidos', items: affectedOrders, storageKey: STORAGE.orders, apply: applyUpdate }]);
        } else if (affectedOrders.length) {
          await writeStorage(STORAGE.orders, applyUpdate(), { immediate: true });
        }
      }
    }
    if (autoSave) focusOrderProducts();
  });

  $('#pw-save-product').addEventListener('click', async () => {
    const saveButton = $('#pw-save-product');
    if (saveButton.disabled) return;
    const code = $('#pw-new-product-code').value.trim();
    const description = $('#pw-new-product-description').value.trim();
    const categoryId = $('#pw-new-product-category').value;
    const unitId = $('#pw-new-product-unit').value;
    const supplierId = $('#pw-new-product-supplier').value;
    const cost = parseMoney($('#pw-new-product-cost').value);
    const price = parseMoney($('#pw-new-product-price').value);
    if (!code) return showMessage('Não foi possível gerar o código automático do produto.', 'error');
    if (!description) return showMessage('Informe a descrição do produto.', 'error');
    if (!categoryId) return showMessage('Selecione a categoria do produto.', 'error');
    if (!unitId) return showMessage('Selecione a unidade de venda.', 'error');

    syncVariationRows();
    const normalizedVariations = productVariations.map((variation, index) => ({
      id: variation.id || 'variation-' + Date.now() + '-' + index,
      description: String(variation.description || '').trim(),
      minQuantity: Math.max(1, Math.trunc(Number(variation.minQuantity) || 1)),
      maxQuantity: variation.maxQuantity == null || variation.maxQuantity === '' ? null : Math.max(1, Math.trunc(Number(variation.maxQuantity) || 1)),
      unitId: String(variation.unitId || ''),
      cost: Math.max(0, Number(variation.cost) || 0),
      price: Math.max(0, Number(variation.price) || 0)
    }));
    if (normalizedVariations.some(variation => !variation.description)) return showMessage('Informe a descrição de todas as variações.', 'error');
    if (normalizedVariations.some(variation => !variation.unitId)) return showMessage('Selecione a unidade de todas as variações.', 'error');
    if (normalizedVariations.some(variation => variation.price <= 0)) return showMessage('O preço de venda de cada variação deve ser maior que zero.', 'error');
    if (normalizedVariations.some(variation => variation.maxQuantity !== null && variation.maxQuantity <= variation.minQuantity)) {
      activateProductTab('variations');
      return showMessage('Em cada faixa, a quantidade máxima deve ser maior que a quantidade mínima.', 'error');
    }
    for (let index = 0; index < normalizedVariations.length; index += 1) {
      const current = normalizedVariations[index];
      const isLast = index === normalizedVariations.length - 1;
      if (!isLast && current.maxQuantity === null) {
        activateProductTab('variations');
        return showMessage('Preencha a quantidade máxima de todas as faixas, exceto da última.', 'error');
      }
      if (index > 0) {
        const previous = normalizedVariations[index - 1];
        const expectedMinimum = Number(previous.maxQuantity) + 1;
        if (current.minQuantity !== expectedMinimum) {
          activateProductTab('variations');
          return showMessage('As faixas devem ser contínuas: a próxima quantidade mínima precisa ser o máximo anterior + 1.', 'error');
        }
      }
    }

    const products = getProducts();
    if (products.some(product => product.id !== editingProductId && normalize(product.code) === normalize(code))) {
      return showMessage('Já existe um produto com esse código.', 'error');
    }
    const duplicateProduct = products.find(product => product.id !== editingProductId && normalize(product.description) === normalize(description));
    if (duplicateProduct && !confirm('Já existe um produto com descrição igual ou muito semelhante: ' + duplicateProduct.code + ' — ' + duplicateProduct.description + '. Deseja salvar mesmo assim?')) return;
    const existingProduct = products.find(record => record.id === editingProductId);
    if (existingProduct && !userIsAdministrator(currentUser) && code !== existingProduct.code) return showMessage('Apenas administradores podem alterar códigos já cadastrados.', 'error');
    const product = {
      id: editingProductId || 'product-' + Date.now(), code, description,
      position: existingProduct && Number.isFinite(Number(existingProduct.position)) ? Number(existingProduct.position) : nextRecordPosition(products),
      active: $('#pw-new-product-active').checked,
      categoryId, unitId, supplierId, cost, price,
      variations: normalizedVariations,
      notes: $('#pw-new-product-notes').value.trim()
    };
    const keepEditor = keepBulkEditorOpen('product', product.id);
    const existingProductIndex = products.findIndex(record => record.id === product.id);
    if (existingProductIndex >= 0) products[existingProductIndex] = product;
    else products.push(product);
    saveButton.disabled = true;
    const saved = await persistStorage(STORAGE.products, products);
    saveButton.disabled = false;
    if (!saved) return;
    SERVER_STORAGE[STORAGE.products] = products;
    if (existingProductIndex < 0) {
      consumeRegistryCode('product', code);
      chooseProductVariation(product);
    }
    if (!keepEditor) {
      clearProductModal();
      closeModal('pw-product-modal', true);
    }
    renderProductsConsultation();
    if (keepEditor) { renderBulkNavigation(); markModalClean('pw-product-modal'); saveButton.classList.add('pw-saved'); }
    showMessage(existingProductIndex >= 0 ? 'Produto atualizado com sucesso.' : 'Produto cadastrado e incluído no pedido.', 'success');
  });

  $('#pw-registry-modal').addEventListener('input', () => $('#pw-save-registry').classList.remove('pw-saved'));
  $('#pw-registry-modal').addEventListener('change', () => $('#pw-save-registry').classList.remove('pw-saved'));
  $('#pw-client-modal').addEventListener('input', () => $('#pw-save-client').classList.remove('pw-saved'));
  $('#pw-client-modal').addEventListener('change', () => $('#pw-save-client').classList.remove('pw-saved'));
  $('#pw-product-modal').addEventListener('input', () => $('#pw-save-product').classList.remove('pw-saved'));
  $('#pw-product-modal').addEventListener('change', () => $('#pw-save-product').classList.remove('pw-saved'));
  $('#pw-payment-modal').addEventListener('input', () => $('#pw-payment-entry-save').classList.remove('pw-saved'));
  $('#pw-payment-modal').addEventListener('change', () => $('#pw-payment-entry-save').classList.remove('pw-saved'));
  $('#pw-dtf-cost-modal').addEventListener('input', () => $('#pw-save-dtf-cost').classList.remove('pw-saved'));
  $('#pw-dtf-cost-modal').addEventListener('change', () => $('#pw-save-dtf-cost').classList.remove('pw-saved'));
  function markCfgDirty() {
    const btn = $('#pw-save-settings');
    if (!btn) return;
    btn.classList.remove('pw-cfg-save-clean');
    btn.classList.add('pw-cfg-save-dirty');
    btn.classList.remove('pw-saved');
  }
  function markCfgClean() {
    const btn = $('#pw-save-settings');
    if (!btn) return;
    btn.classList.remove('pw-cfg-save-dirty');
    btn.classList.add('pw-cfg-save-clean');
    btn.classList.add('pw-saved');
  }
  document.querySelector('[data-view="settings"]').addEventListener('input', markCfgDirty);
  document.querySelector('[data-view="settings"]').addEventListener('change', markCfgDirty);

  $('#pw-save-registry').addEventListener('click', async () => {
    const kind = $('#pw-registry-kind').value;
    const config = registryConfig(kind);
    if (!config) return showMessage('Tipo de cadastro inválido.', 'error');
    const name = $('#pw-registry-name').value.trim();
    const code = $('#pw-registry-code').value.trim();
    const phone = formatPhone($('#pw-registry-phone').value);
    const email = $('#pw-registry-email').value.trim();
    const document = $('#pw-registry-document').value.trim();
    if (!name) return showMessage('Informe o nome do cadastro.', 'error');
    if (kind === 'dtfCategory') {
      if (!code) return showMessage('Informe o código da categoria.', 'error');
      const id = $('#pw-registry-id').value || 'dtf-category-' + Date.now();
      const button = $('#pw-save-registry');
      if (button.disabled) return;
      button.disabled = true;
      let saved;
      try { saved = await saveDtfExpenseCategory({ id, code, name, active: $('#pw-registry-active').checked }); }
      finally { button.disabled = false; }
      if (!saved) return;
      if (keepBulkEditorOpen(kind, id)) { markModalClean('pw-registry-modal'); renderBulkNavigation(); $('#pw-save-registry').classList.add('pw-saved'); }
      else closeModal('pw-registry-modal', true);
      selectNewExpenseRegistry(kind, { id, name });
      showMessage('Categoria de despesa salva.', 'success'); return;
    }
    if (kind === 'dtfItem' || kind === 'dtfMovement') {
      if (!code) return showMessage('Informe o código do cadastro.', 'error');
      const record = { id:$('#pw-registry-id').value || kind + '-' + Date.now(), code, name, active:$('#pw-registry-active').checked };
      if (kind === 'dtfItem') {
        record.category = $('#pw-registry-expense-category').value;
        record.unit = $('#pw-registry-expense-unit').value;
        if (!record.category || !record.unit) return showMessage('Selecione a categoria e a unidade sugerida.', 'error');
      }
      const button = $('#pw-save-registry');
      if (button.disabled) return;
      button.disabled = true;
      let saved;
      try { saved = await saveExpenseMaster(kind, record); } finally { button.disabled = false; }
      if (!saved) return;
      if (keepBulkEditorOpen(kind, record.id)) { openRegistryEditor(kind, saved); renderBulkNavigation(); markModalClean('pw-registry-modal'); $('#pw-save-registry').classList.add('pw-saved'); }
      else closeModal('pw-registry-modal', true);
      selectNewExpenseRegistry(kind, saved);
      showMessage('Cadastro salvo e relatório atualizado.', 'success');
      return;
    }
    if (kind === 'unit' && !$('#pw-registry-symbol').value.trim()) return showMessage('Informe a sigla da unidade.', 'error');
    if (kind === 'supplier' && phone && !isValidPhone(phone)) return showMessage('O telefone do fornecedor não é válido.', 'error');
    if (kind === 'supplier' && email && !isValidEmail(email)) return showMessage('O e-mail do fornecedor não é válido.', 'error');
    if (kind === 'supplier' && document && !documentType(document)) return showMessage('O CPF/CNPJ do fornecedor não é válido.', 'error');
    const records = config.records();
    const id = $('#pw-registry-id').value || kind + '-' + Date.now();
    if (records.some(item => item.id !== id && normalize(item.code) === normalize(code))) return showMessage('Já existe um registro com esse código.', 'error');
    if (kind === 'orderOrigin' && records.some(item => item.id !== id && normalize(item.name) === normalize(name))) return showMessage('Já existe uma origem com esse nome.', 'error');
    const keepEditor = keepBulkEditorOpen(kind, id);
    const existingRecord = records.find(item => item.id === id);
    if (existingRecord && !userIsAdministrator(currentUser) && code !== existingRecord.code) return showMessage('Apenas administradores podem alterar códigos já cadastrados.', 'error');
    const record = {
      ...existingRecord,
      id, code, name, active: kind === 'paymentMethod' || (kind === 'orderOrigin' && existingRecord && existingRecord.protected) ? true : $('#pw-registry-active').checked,
      position: existingRecord && Number.isFinite(Number(existingRecord.position)) ? Number(existingRecord.position) : nextRecordPosition(records),
      symbol: $('#pw-registry-symbol').value.trim(),
      contact: $('#pw-registry-contact').value.trim(), phone, email,
      document: formatDocument(document), notes: $('#pw-registry-notes').value.trim()
    };
    if (kind === 'orderOrigin') record.marketplace = $('#pw-registry-marketplace').checked;
    if (kind === 'supplier') record.supplierType = $('#pw-registry-supplier-type').value;
    if (kind === 'unit' || kind === 'supplier') {
      record.aliases = [...new Set([...(existingRecord && existingRecord.aliases || []), ...(existingRecord ? [existingRecord.name, existingRecord.symbol] : [])].filter(Boolean))];
      if (kind === 'unit' && records.some(item => item.id !== id && [item.name, item.symbol, ...(item.aliases || [])].some(value => normalize(value) === normalize(record.name) || normalize(value) === normalize(record.symbol)))) return showMessage('Já existe uma unidade com esse nome ou sigla.', 'error');
    }
    const index = records.findIndex(item => item.id === id);
    const next = index >= 0 ? records.map(item => item.id === id ? record : item) : [...records, record];
    const button = $('#pw-save-registry');
    if (button.disabled) return;
    button.disabled = true;
    let saved;
    try {
      window.clearTimeout(serverSaveTimers[config.storage]); delete serverSaveTimers[config.storage];
      saved = await persistStorage(config.storage, next);
      if (saved) SERVER_STORAGE[config.storage] = next;
    } finally { button.disabled = false; }
    if (!saved) return;
    if (index < 0) consumeRegistryCode(kind, code);
    if (!keepEditor) closeModal('pw-registry-modal', true);
    renderRegistryConsultation(kind);
    const currentProductSelection = {
      categoryId: $('#pw-new-product-category').value,
      unitId: $('#pw-new-product-unit').value,
      supplierId: $('#pw-new-product-supplier').value
    };
    if (quickRegistryKind === kind) currentProductSelection[kind + 'Id'] = id;
    populateProductRegistrySelects(currentProductSelection);
    if (kind === 'paymentMethod') {
      populatePaymentMethodSelects($('#pw-payment-method').value, '');
    }
    if (quickRegistryKind === kind) {
      const targetLabels = { category: 'Categoria', unit: 'Unidade de venda', supplier: 'Fornecedor' };
      showMessage(targetLabels[kind] + ' cadastrado e selecionado no produto.', 'success');
      quickRegistryKind = '';
    } else {
      showMessage(index >= 0 ? 'Cadastro atualizado com sucesso.' : 'Cadastro realizado com sucesso.', 'success');
    }
    renderProductsConsultation();
    refreshExpenseViews();
    if (kind === 'supplier') syncDtfSupplierOptions($('#pw-dtf-cost-supplier').value);
    if (existingRecord && normalize(existingRecord.name) !== normalize(name)) {
      if (kind === 'supplier') {
        const affected = getDtfCosts().filter(expense => (expense.supplierId && expense.supplierId === id) || (!expense.supplierId && normalize(expense.supplier || '') === normalize(existingRecord.name)));
        await confirmAndPropagateRename(existingRecord.name, name, [{ label: 'Despesas', items: affected, storageKey: STORAGE.dtfCosts, apply: () => getDtfCosts().map(expense => affected.includes(expense) ? { ...expense, supplier: name, supplierId: id } : expense) }]);
      } else if (kind === 'paymentMethod') {
        const affectedOrders = getOrders().filter(order => order.paymentMethod === existingRecord.name || (order.payments || []).some(payment => payment.method === existingRecord.name));
        await confirmAndPropagateRename(existingRecord.name, name, [{
          label: 'Pedidos', items: affectedOrders, storageKey: STORAGE.orders,
          apply: () => getOrders().map(order => {
            if (order.paymentMethod !== existingRecord.name && !(order.payments || []).some(payment => payment.method === existingRecord.name)) return order;
            return { ...order, paymentMethod: order.paymentMethod === existingRecord.name ? name : order.paymentMethod, payments: (order.payments || []).map(payment => payment.method === existingRecord.name ? { ...payment, method: name } : payment) };
          })
        }]);
      } else if (kind === 'orderOrigin') {
        const affectedOrders = getOrders().filter(order => order.origin === existingRecord.name || (order.client && order.client.origin === existingRecord.name));
        await confirmAndPropagateRename(existingRecord.name, name, [{
          label: 'Pedidos', items: affectedOrders, storageKey: STORAGE.orders,
          apply: () => getOrders().map(order => {
            if (order.origin !== existingRecord.name && !(order.client && order.client.origin === existingRecord.name)) return order;
            return { ...order, origin: order.origin === existingRecord.name ? name : order.origin, client: order.client && order.client.origin === existingRecord.name ? { ...order.client, origin: name } : order.client };
          })
        }]);
      }
    }
    if (kind === 'orderOrigin') syncOrderOriginOptions(record.name);
    selectNewExpenseRegistry(kind, record);
    if (keepEditor) { renderBulkNavigation(); markModalClean('pw-registry-modal'); $('#pw-save-registry').classList.add('pw-saved'); }
  });

