  ['pw-actual-delivery'].forEach(id => {
    $('#' + id).addEventListener('change', updateDeadlineStatus);
  });
  /** Quem anexa a arte de um produto está, por definição, aprovando ela —
   * então avança a situação pra "Arte aprovada" sozinho, sem precisar o
   * usuário mudar o campo manualmente. Só dispara se a situação atual for
   * exatamente a etapa anterior ("Criação da arte"): se já estiver mais
   * adiante (ou for um pedido de marketplace com fluxo próprio), não mexe
   * em nada — reaproveita o MESMO fluxo do campo "Situação" (dispara
   * 'change' nele), então a confirmação de data/hora e todas as travas de
   * pedido finalizado/arte pendente continuam valendo normalmente. */
  function maybeAdvanceStatusAfterArtAttach() {
    const select = $('#pw-status');
    if (!select) return;
    const current = select.dataset.previousStatus || select.value;
    if (current !== 'Criação da arte') return;
    select.value = 'Arte aprovada';
    select.dispatchEvent(new Event('change', { bubbles: true }));
  }

  $('#pw-status').addEventListener('change', event => {
    const select = event.currentTarget;
    const previous = select.dataset.previousStatus || 'Criação da arte';
    const next = select.value;
    select.value = previous;
    if (!isImmediateNextStatus(previous, next) && !orderOriginIsMarketplace(orderOriginForArtsCheck($('#pw-order-number').value))) return showMessage('A situação só pode avançar uma etapa por vez.', 'error');
    const existing = getOrders().find(order => order.orderNumber === $('#pw-order-number').value) || {
      orderNumber: $('#pw-order-number').value,
      status: previous,
      createdDate: $('#pw-created-date').value,
      timeline: []
    };
    if (isOrderFinalized(existing)) return showMessage('Este pedido já está finalizado e não pode mais ser alterado.', 'error');
    if (!requireApprovedPdfArts(next, items, existing.orderNumber, false)) return;
    pendingStatusChange = { source: 'form', orderNumber: existing.orderNumber, status: next, previous };
    if (next === 'Entregue') {
      pendingStatusChange.at = new Date().toISOString();
      $('#pw-finalize-modal-title').textContent = 'Alterar situação para "' + statusDefinition(next).label + '"';
      renderStatusChangeHistory(existing, '#pw-finalize-status-history');
      prepareFinalizationModal(existing, $('#pw-actual-delivery').value || localDateValue(new Date()));
      openModal('pw-finalize-modal', true);
      return;
    }
    $('#pw-status-date-title').textContent = 'Alterar situação para "' + statusDefinition(next).label + '"';
    renderStatusChangeHistory(existing);
    $('#pw-status-date-now').click();
    openModal('pw-status-date-modal', true);
  });

  $('#pw-order-form').addEventListener('submit', async event => {
    event.preventDefault();
    if (orderSaveInProgress) return;
    const storedOrder = getOrders().find(saved => saved.orderNumber === $('#pw-order-number').value);
    if (isOrderFinalized(storedOrder)) return showMessage('Este pedido já está finalizado e não pode mais ser alterado.', 'error');
    if (orderIsLockedForCollaborator(storedOrder)) return showMessage('Este pedido já teve a situação alterada. Colaboradores podem apenas consultar, imprimir e registrar pagamentos.', 'error');
    const error = validateOrder();
    if (error) return showMessage(error, 'error');
    if (!requireApprovedPdfArts($('#pw-status').value, items, $('#pw-order-number').value, false)) return;

    const now = new Date();
    const selectedClientRecord = getClients().find(client => client.id === $('#pw-client-id').value) || {};
    const orderOrigin = $('#pw-order-client-origin').value || 'Normal';
    const marketplace = orderOriginIsMarketplace(orderOrigin);
    const marketplaceOrderNumber = $('#pw-order-marketplace-number').value.trim();
    $('#pw-last-change').value = dateTime.format(now);
    const oldOrder = getOrders().find(saved => saved.orderNumber === $('#pw-order-number').value) || null;
    // Valida campos de NF-e ao cadastrar novo pedido de marketplace
    if (marketplace && !oldOrder) {
      const nfeIssues = validateMarketplaceNfe(selectedClientRecord, items);
      if (nfeIssues.length) {
        const nfeChoice = await promptNfeValidation(nfeIssues);
        if (nfeChoice === 'cancel') return;
      }
    }
    const newStatus = $('#pw-status').value;
    const autoAiPaymentRequested = aiOrderPaymentPending && !oldOrder && !formFinalizationPayment;
    let autoAiPaymentRecorded = false;
    let autoAiPaymentAmount = 0;
    const timeline = oldOrder ? orderStatusHistory(oldOrder).map(item => ({ ...item })) : [];
    if (!oldOrder) {
      const createdAt = $('#pw-created-date').value ? $('#pw-created-date').value + 'T' + ($('#pw-order-time').value || '00:00') : now.toISOString();
      timeline.push({ status: 'Criação da arte', previous: '', at: createdAt, actor: currentActor(), note: 'Pedido cadastrado' });
      if (newStatus !== 'Criação da arte') timeline.push({ status: newStatus, previous: 'Criação da arte', at: formStatusChangeAt || now.toISOString(), actor: currentActor(), note: '' });
    }
    else if (oldOrder.status !== newStatus) timeline.push({ status: newStatus, previous: oldOrder.status, at: formStatusChangeAt || now.toISOString(), actor: currentActor(), note: '' });
    let order = {
      orderNumber: $('#pw-order-number').value,
      createdDate: $('#pw-created-date').value,
      orderTime: $('#pw-order-time').value,
      lastChange: now.toISOString(),
      requestedDelivery: $('#pw-requested-delivery').value,
      actualDelivery: $('#pw-actual-delivery').value,
      status: $('#pw-status').value,
      origin: orderOrigin,
      marketplaceOrderNumber: marketplace ? marketplaceOrderNumber : '',
      registrationSource: (oldOrder && oldOrder.registrationSource) || 'system',
      createdBy: loadedOrderCreator || {
        id: Number(currentUser && currentUser.id) || 0,
        name: String(currentUser && (currentUser.full_name || currentUser.display) || '').trim(),
        login: String(currentUser && currentUser.login || ''),
        role: userIsAdministrator(currentUser) ? 'Administrador' : String(currentUser && currentUser.role || 'Colaborador'),
        summary: $('#pw-created-by').value
      },
      client: {
        id: $('#pw-client-id').value,
        code: selectedClientRecord.code || '',
        name: $('#pw-client-name').value,
        phone: $('#pw-client-phone').value,
        email: $('#pw-client-email').value,
        document: $('#pw-client-document').value,
        address: selectedClientRecord.address || {},
        origin: orderOrigin,
        marketplaceOrderNumber: marketplace ? marketplaceOrderNumber : '',
        monthlyClosing: selectedClientRecord.monthlyClosing === true,
        closingDay: Number(selectedClientRecord.closingDay || 0)
      },
      items: items.map(item => ({ ...item })),
      personalizationNotes: $('#pw-personalization-notes').value.trim(),
      total: orderItemTotals(items, orderOrigin).net,
      discount: parseMoney($('#pw-discount-value').value),
      surcharge: parseMoney($('#pw-surcharge-value').value),
      paid: parseMoney($('#pw-paid-value').value),
      paymentMethod: $('#pw-payment-method').value,
      paymentType: formFinalizationPayment ? formFinalizationPayment.type : (oldOrder && oldOrder.paymentType || ''),
      paymentDate: formFinalizationPayment ? formFinalizationPayment.date : (oldOrder && oldOrder.paymentDate || ''),
      paymentStatus: $('#pw-payment-status').value,
      payments: (() => {
        const history = oldOrder && Array.isArray(oldOrder.payments) ? oldOrder.payments.slice() : [];
        if (formFinalizationPayment) history.push(formFinalizationPayment);
        return history;
      })(),
      timeline
    };
    if (autoAiPaymentRequested) {
      const pendingBalance = Math.max(0, adjustedOrderTotal(order) - Number(order.paid || 0));
      if (pendingBalance > 0.005) {
        const pixRecord = getPaymentMethods().find(method => normalize(method.name) === 'pix');
        const paymentMethod = pixRecord && pixRecord.name || 'Pix';
        const paymentDate = localDateValue(now);
        const payment = {
          method: paymentMethod,
          type: 'Total',
          value: pendingBalance,
          date: paymentDate,
          note: 'Pagamento registrado automaticamente pelo Cadastro IA por imagem',
          registeredAt: now.toISOString(),
          actor: currentActor()
        };
        order.payments.push(payment);
        order.paid = Math.max(0, Number(order.paid || 0)) + pendingBalance;
        order.paymentMethod = paymentMethod;
        order.paymentType = 'Total';
        order.paymentDate = paymentDate;
        order.paymentStatus = 'Pago';
        autoAiPaymentRecorded = true;
        autoAiPaymentAmount = pendingBalance;
      }
    }
    if (order.status === 'Entregue' && !order.client.monthlyClosing) {
      const balance = Math.max(0, adjustedOrderTotal(order) - Number(order.paid || 0));
      if (balance > 0.005) {
        return showMessage('O pedido não pode ser marcado como "Entregue" pois ainda há saldo pendente de ' + money.format(balance) + '. Quite o pagamento antes de alterar a situação.', 'error');
      }
    }

    syncOrderFinalization(order);

    const orders = readStorage(STORAGE.orders, []).slice();
    const currentIndex = orders.findIndex(saved => saved.orderNumber === order.orderNumber);
    orderSaveInProgress = true;
    $$('[data-order-save]').forEach(button => { button.disabled = true; });
    let saved = false;
    try {
      if (currentIndex < 0 && SERVER.ajaxUrl && SERVER.nonce) {
        // O servidor aloca o sequencial dentro de uma transação e grava apenas
        // este pedido, evitando colisões e sobrescritas entre usuários.
        const created = await createOrderOnServer(order);
        if (created) order = created;
        $('#pw-order-number').value = order.orderNumber || '';
        $('#pw-order-number-view').textContent = order.orderNumber || '—';
        await refreshSharedStorageSnapshot();
        const latestOrders = getOrders();
        if (!latestOrders.some(record => String(record.orderNumber) === String(order.orderNumber))) latestOrders.push(order);
        SERVER_STORAGE[STORAGE.orders] = latestOrders;
        saved = true;
      } else {
        if (currentIndex >= 0) orders[currentIndex] = order;
        else orders.push(order);
        saved = await persistStorage(STORAGE.orders, orders);
        if (saved) {
          SERVER_STORAGE[STORAGE.orders] = orders;
          if (currentIndex < 0) advanceOrderSequence(order.orderNumber);
        }
      }
    } catch (saveError) {
      console.error('Falha ao cadastrar o pedido.', saveError);
      showMessage(saveError && saveError.message || 'Não foi possível cadastrar o pedido.', 'error');
    } finally {
      orderSaveInProgress = false;
      $$('[data-order-save]').forEach(button => { button.disabled = false; });
    }
    if (!saved) return;
    aiOrderPaymentPending = false;
    recordAudit('order', order.orderNumber, currentIndex >= 0 ? 'Pedido atualizado' : 'Pedido cadastrado', 'Total: ' + money.format(adjustedOrderTotal(order)));
    if (autoAiPaymentRecorded) {
      recordAudit('order', order.orderNumber, 'Faturamento registrado automaticamente', 'Pix · Total · ' + money.format(autoAiPaymentAmount));
    }
    editingOrderNumber = order.orderNumber;
    $('#pw-status').dataset.previousStatus = order.status;
    formFinalizationPayment = null;
    formStatusChangeAt = null;
    loadedOrderCreator = order.createdBy;
    if (autoAiPaymentRecorded) {
      $('#pw-paid-value').value = Number(order.paid || 0).toFixed(2).replace('.', ',');
      $('#pw-payment-method').value = order.paymentMethod || 'Pix';
      $('#pw-payment-status').value = order.paymentStatus || 'Pago';
      updateTotal();
    }
    const note = $('#pw-editing-note');
    note.textContent = 'Editando o pedido ' + order.orderNumber + '. Ao salvar, o registro existente será atualizado.';
    note.classList.add('pw-visible');
    updateSystemViewContext('order');
    syncOrderEditLock(order);
    refreshAllViews();
    captureOrderSavedState(true);
    showMessage('Pedido ' + order.orderNumber + ' salvo com sucesso.' + (autoAiPaymentRecorded
      ? ' Faturamento registrado automaticamente: Pix · Total · ' + money.format(autoAiPaymentAmount) + '.'
      : ''), 'success');
  });

  ['pw-discount-value', 'pw-surcharge-value', 'pw-paid-value'].forEach(id => $('#' + id).addEventListener('input', updateTotal));

  $('#pw-dashboard-apply-filters').addEventListener('click', renderDashboard);
